@Test
public void testMiniClusterState() throws Exception {
    System.setProperty("workBaseDir", createTempDir("work").toString());
    System.setProperty("random.counts", "true");
    MiniClusterState.MiniClusterBenchState miniBenchState = new MiniClusterState.MiniClusterBenchState();
    BenchmarkParams benchParams = new BenchmarkParams("benchmark", "generatedTarget", true, 1, new int[] { 1 }, Collections.singletonList("label"), 0, 0, new IterationParams(IterationType.WARMUP, 1, TimeValue.milliseconds(10), 1), new IterationParams(IterationType.MEASUREMENT, 1, TimeValue.milliseconds(10), 1), Mode.Throughput, new WorkloadParams(), TimeUnit.SECONDS, 1, "jvm", Collections.singletonList("jvmArg"), "jdkVersion", "vmName", "vmVersion", "jmhVersion", TimeValue.seconds(10));
    BaseBenchState baseBenchState = new BaseBenchState();
    baseBenchState.doSetup(benchParams);
    miniBenchState.doSetup(benchParams, baseBenchState);
    int nodeCount = 3;
    miniBenchState.startMiniCluster(nodeCount);
    String collection = "collection1";
    int numShards = 1;
    int numReplicas = 1;
    miniBenchState.createCollection(collection, numShards, numReplicas);
    Docs docs = docs().field("id", integers().incrementing()).field(strings().basicLatinAlphabet().multi(312).ofLengthBetween(30, 64)).field(strings().basicLatinAlphabet().multi(312).ofLengthBetween(30, 64)).field(integers().all()).field(integers().all()).field(integers().all()).field(longs().all()).field(longs().all()).field(floats().all()).field(floats().all()).field(booleans().all()).field(booleans().all()).field(dates().all()).field(dates().all()).field(doubles().all()).field(doubles().all());
    int numDocs = 50;
    Iterator<SolrInputDocument> docIt = docs.preGenerate(numDocs);
    miniBenchState.index(collection, docs, numDocs);
    miniBenchState.forceMerge(collection, 15);
    ModifiableSolrParams params = MiniClusterState.params("q", "*:*");
    QueryRequest queryRequest = new QueryRequest(params);
    QueryResponse result = queryRequest.process(miniBenchState.client, collection);
    BaseBenchState.log("match all query result=" + result);
    assertEquals(numDocs, result.getResults().getNumFound());
    BaseBenchState.doTearDown(benchParams);
    miniBenchState.tearDown(benchParams);
    miniBenchState.shutdownMiniCluster(benchParams, baseBenchState);
}

