@Test
public void testClusterPluginsEditApi() throws Exception {
    PluginMeta meta = SingletonNoConfig.pluginMeta();
    V2Request req = new V2Request.Builder("/cluster/plugin").POST().withPayload(Collections.singletonMap("add", meta)).build();
    try {
        req.process(cluster.getSolrClient());
        fail("Expected a 404 response code because the Edit Apis are not registered");
    } catch (BaseHttpSolrClient.RemoteExecutionException e) {
        assertEquals("Expected a HTTP 404 response code because the /cluster/plugin API should not be registered", 404, e.code());
