@Test
public void testPackageTool() throws Exception {
    ToolRuntime runtime = new CLITestHelper.TestingRuntime(false);
    PackageTool tool = new PackageTool(runtime);
    String solrUrl = cluster.getJettySolrRunner(0).getBaseUrl().toString();
    run(tool, new String[] { "--solr-url", solrUrl, "list-installed", "--credentials", SecurityJson.USER_PASS });
    run(tool, new String[] { "--solr-url", solrUrl, "add-repo", "fullstory", "http://localhost:" + repositoryServer.getPort(), "--credentials", SecurityJson.USER_PASS });
    run(tool, new String[] { "--solr-url", solrUrl, "list-available", "--credentials", SecurityJson.USER_PASS });
    run(tool, new String[] { "--solr-url", solrUrl, "install", "question-answer:1.0.0", "--credentials", SecurityJson.USER_PASS });
    run(tool, new String[] { "--solr-url", solrUrl, "list-installed", "--credentials", SecurityJson.USER_PASS });
    withBasicAuth(CollectionAdminRequest.createCollection("abc", "conf1", 1, 1)).processAndWait(cluster.getSolrClient(), 10);
    withBasicAuth(CollectionAdminRequest.createCollection("def", "conf3", 1, 1)).processAndWait(cluster.getSolrClient(), 10);
    String rhPath = "/mypath2";
    run(tool, new String[] { "--solr-url", solrUrl, "list-deployed", "question-answer", "--credentials", SecurityJson.USER_PASS });
    // Leaving -p in for --param to test the deprecated value continues to work.
    run(tool, new String[] { "--solr-url", solrUrl, "deploy", "question-answer", "-y", "--collections", "abc", "--param", "RH-HANDLER-PATH=" + rhPath, "--credentials", SecurityJson.USER_PASS });
    assertPackageVersion("abc", "question-answer", "1.0.0", rhPath, "1.0.0", SecurityJson.USER_PASS);
    run(tool, new String[] { "--solr-url", solrUrl, "list-deployed", "question-answer", "--credentials", SecurityJson.USER_PASS });
    run(tool, new String[] { "--solr-url", solrUrl, "list-deployed", "-c", "abc", "--credentials", SecurityJson.USER_PASS });
    // Should we test the "auto-update to latest" functionality or the default explicit deploy
    // functionality
    boolean autoUpdateToLatest = random().nextBoolean();
    if (autoUpdateToLatest) {
        log.info("Testing auto-update to latest installed");
        // This command pegs the version to the latest available
        run(tool, new String[] { "--solr-url", solrUrl, "deploy", "question-answer:latest", "-y", "--collections", "abc", "--credentials", SecurityJson.USER_PASS });
        assertPackageVersion("abc", "question-answer", "$LATEST", rhPath, "1.0.0", SecurityJson.USER_PASS);
        run(tool, new String[] { "--solr-url", solrUrl, "install", "question-answer", "--credentials", SecurityJson.USER_PASS });
        assertPackageVersion("abc", "question-answer", "$LATEST", rhPath, "1.1.0", SecurityJson.USER_PASS);
    } else {
        log.info("Testing explicit deployment to a different/newer version");
        run(tool, new String[] { "--solr-url", solrUrl, "install", "question-answer", "--credentials", SecurityJson.USER_PASS });
        assertPackageVersion("abc", "question-answer", "1.0.0", rhPath, "1.0.0", SecurityJson.USER_PASS);
        // even if parameters are not passed in, they should be picked up from previous deployment
        if (random().nextBoolean()) {
            run(tool, new String[] { "--solr-url", solrUrl, "deploy", "--update", "-y", "question-answer", "--collections", "abc", "--param", "RH-HANDLER-PATH=" + rhPath, "--credentials", SecurityJson.USER_PASS });
        } else {
            run(tool, new String[] { "--solr-url", solrUrl, "deploy", "--update", "-y", "question-answer", "--collections", "abc", "--credentials", SecurityJson.USER_PASS });
        }
        assertPackageVersion("abc", "question-answer", "1.1.0", rhPath, "1.1.0", SecurityJson.USER_PASS);
    }
    log.info("Running undeploy...");
    run(tool, new String[] { "--solr-url", solrUrl, "undeploy", "question-answer", "--collections", "abc", "--credentials", SecurityJson.USER_PASS });
    run(tool, new String[] { "--solr-url", solrUrl, "list-deployed", "question-answer", "--credentials", SecurityJson.USER_PASS });
}

