@Test
public void testUpConfigLinkConfigClearZk() throws Exception {
    Path tmpDir = createTempDir();
    // test upconfig
    String confsetname = "confsetone";
    String[] args = new String[] { "upconfig", "--conf-name", confsetname, "--conf-dir", ExternalPaths.TECHPRODUCTS_CONFIGSET.toString(), "-z", zkServer.getZkAddress() };
    assertEquals(0, CLITestHelper.runTool(args, ConfigSetUploadTool.class));
    assertTrue(zkClient.exists(ZkConfigSetService.CONFIGS_ZKNODE + "/" + confsetname, true));
    final Path confDir = ExternalPaths.TECHPRODUCTS_CONFIGSET;
    List<String> zkFiles = zkClient.getChildren(ZkConfigSetService.CONFIGS_ZKNODE + "/" + confsetname, null, true);
    try (Stream<Path> filesStream = Files.list(confDir)) {
        assertEquals("Verify that all local files are uploaded to ZK", filesStream.count(), zkFiles.size());
    }
    // test linkconfig
    args = new String[] { "linkconfig", "--conf-name", confsetname, "-c", "collection1", "-z", zkServer.getZkAddress() };
    assertEquals(0, CLITestHelper.runTool(args, LinkConfigTool.class));
    ZkNodeProps collectionProps = ZkNodeProps.load(zkClient.getData(ZkStateReader.COLLECTIONS_ZKNODE + "/collection1", null, null, true));
    assertTrue(collectionProps.containsKey("configName"));
    assertEquals(confsetname, collectionProps.getStr("configName"));
    // test down config
    Path destDir = FilterPath.unwrap(tmpDir.resolve("solrtest-confdropspot-" + this.getClass().getName() + "-" + System.nanoTime()));
    assertFalse(Files.exists(destDir));
    args = new String[] { "downconfig", "--conf-name", confsetname, "--conf-dir", destDir.toString(), "-z", zkServer.getZkAddress() };
    assertEquals(0, CLITestHelper.runTool(args, ConfigSetDownloadTool.class));
    try (Stream<Path> filesStream = Files.list(destDir.resolve("conf"))) {
        List<Path> files = filesStream.toList();
        zkFiles = zkClient.getChildren(ZkConfigSetService.CONFIGS_ZKNODE + "/" + confsetname, null, true);
        assertEquals("Comparing original conf files that were to be uploaded to what is in ZK", files.size(), zkFiles.size());
        assertEquals("Comparing downloaded files to what is in ZK", files.size(), zkFiles.size());
    }
    // compare the original source with the downloaded destination
    try (Stream<Path> stream = Files.walk(ExternalPaths.TECHPRODUCTS_CONFIGSET)) {
        stream.filter(Files::isRegularFile).forEach((sourceFile) -> {
            Path sourceFileRelative = ExternalPaths.TECHPRODUCTS_CONFIGSET.relativize(sourceFile);
            Path downloadedFile = destDir.resolve("conf").resolve(sourceFileRelative);
            if (ConfigSetService.UPLOAD_FILENAME_EXCLUDE_PATTERN.matcher(sourceFileRelative.toString()).matches()) {
                assertFalse(sourceFile + " exists in ZK, downloaded:" + downloadedFile, Files.exists(downloadedFile));
            } else {
                assertTrue(downloadedFile + " does not exist source:" + sourceFile, Files.exists(downloadedFile));
                try {
                    assertEquals(sourceFileRelative + " content changed", -1, Files.mismatch(sourceFile, downloadedFile));
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
        });
    }
    // test reset zk
    args = new String[] { "rm", "-r", "-z", zkServer.getZkAddress(), "zk:/configs/confsetone" };
    assertEquals(0, CLITestHelper.runTool(args, ZkRmTool.class));
    assertEquals(0, zkClient.getChildren("/configs", null, true).size());
}

