    long start = timeSource.getTimeNs();
    at.minimumWaitBetweenActions();
    // should be no wait
    assertTrue(TimeUnit.MILLISECONDS.convert(timeSource.getTimeNs() - start, TimeUnit.NANOSECONDS) < 1000);
