@Test
@ShardsFixed(num = 1)
public void testDeleteDoesNotDeleteSharedAutocreatedConfigSet() throws Exception {
    String collectionNameInitial = "SimpleCollectionCreateDeleteTest.initialCollection";
    CollectionAdminRequest.Create createInitial = CollectionAdminRequest.createCollection(collectionNameInitial, 1, 1);
    NamedList<Object> requestInitial = createInitial.process(cloudClient).getResponse();
    if (requestInitial.get("success") != null) {
        // collection exists now
        assertTrue(getZkClient().exists(ZkStateReader.COLLECTIONS_ZKNODE + "/" + collectionNameInitial, false));
        String configName = cloudClient.getClusterStateProvider().getCollection(collectionNameInitial).getConfigName();
        // config for this collection is '.AUTOCREATED', and exists globally
        assertTrue(configName.endsWith(".AUTOCREATED"));
        assertTrue(getZkClient().exists(ZkStateReader.CONFIGS_ZKNODE + "/" + configName, true));
        // create a second collection, sharing the same configSet
        String collectionNameWithSharedConfig = "SimpleCollectionCreateDeleteTest.collectionSharingAutocreatedConfigSet";
        CollectionAdminRequest.Create createWithSharedConfig = CollectionAdminRequest.createCollection(collectionNameWithSharedConfig, configName, 1, 1);
        NamedList<Object> requestWithSharedConfig = createWithSharedConfig.process(cloudClient).getResponse();
        assertNotNull("The collection with shared config set should have been created", requestWithSharedConfig.get("success"));
        assertTrue("The new collection should exist after a successful creation", getZkClient().exists(ZkStateReader.COLLECTIONS_ZKNODE + "/" + collectionNameWithSharedConfig, false));
        String configNameOfSecondCollection = cloudClient.getClusterStateProvider().getCollection(collectionNameWithSharedConfig).getConfigName();
        assertEquals("Both collections should be using the same config", configName, configNameOfSecondCollection);
        // delete the initial collection - the config set should stay, since it is shared with the
        // other collection
        CollectionAdminRequest.Delete deleteInitialCollection = CollectionAdminRequest.deleteCollection(collectionNameInitial);
        cloudClient.request(deleteInitialCollection);
        // initial collection has been deleted
        assertFalse(getZkClient().exists(ZkStateReader.COLLECTIONS_ZKNODE + "/" + collectionNameInitial, false));
        // ... but not its autocreated config set, since it is shared with another collection
        assertTrue("The auto-created config set should NOT have been deleted. Another collection is using it.", getZkClient().exists(ZkStateReader.CONFIGS_ZKNODE + "/" + configName, true));
        // delete the second collection - the config set should now be deleted, since it is no longer
        // shared any other collection
        CollectionAdminRequest.Delete deleteSecondCollection = CollectionAdminRequest.deleteCollection(collectionNameWithSharedConfig);
        cloudClient.request(deleteSecondCollection);
        // the collection has been deleted
        assertFalse(getZkClient().exists(ZkStateReader.COLLECTIONS_ZKNODE + "/" + collectionNameWithSharedConfig, false));
        // ... and the config set is now also deleted - once it doesn't get referenced by any
        // collection
        assertFalse("The auto-created config set should have been deleted now. No collection is referencing it.", getZkClient().exists(ZkStateReader.CONFIGS_ZKNODE + "/" + configName, true));
    }
}

@Test
public void doTest() throws IOException, SolrServerException {
    // SPLITSHARD is recommended to be run in async mode, so we default to that.
    // Also, autoscale triggers use async with splits as well.
    boolean doAsync = true;
    CollectionAdminRequest.createCollection(COLLECTION_NAME, "conf", 1, 1).process(cluster.getSolrClient());
    cluster.waitForActiveCollection(COLLECTION_NAME, 1, 1);
    CloudSolrClient client = cluster.getSolrClient(COLLECTION_NAME);
    // splitting an empty collection by prefix should still work (i.e. fall back to old method of
    // just dividing the hash range
    CollectionAdminRequest.SplitShard splitShard = CollectionAdminRequest.splitShard(COLLECTION_NAME).setNumSubShards(2).setSplitByPrefix(true).setShardName("shard1");
    if (doAsync) {
        splitShard.setAsyncId("SPLIT1");
    }
    splitShard.process(client);
    // expectedReplicas==2 because original replica still exists and active but its shard is
    // inactive
    waitForState("Timed out waiting for sub shards to be active.", COLLECTION_NAME, activeClusterShape(2, 2));
    List<Prefix> prefixes = findPrefixes(20, 0, 0x00ffffff);
    List<Prefix> uniquePrefixes = removeDups(prefixes);
    // make it an even sized list, so we can split it exactly in two
    if (uniquePrefixes.size() % 2 == 1) {
        uniquePrefixes.remove(uniquePrefixes.size() - 1);
    }
    log.info("Unique prefixes: {}", uniquePrefixes);
    for (Prefix prefix : uniquePrefixes) {
        client.add(getDoc(prefix.key, "doc1"));
        client.add(getDoc(prefix.key, "doc2"));
    }
    client.commit();
    splitShard = CollectionAdminRequest.splitShard(COLLECTION_NAME).setSplitByPrefix(true).setShardName(// should start out with the range of 0-7fffffff
    "shard1_1");
    if (doAsync) {
        splitShard.setAsyncId("SPLIT2");
    }
    splitShard.process(client);
    waitForState("Timed out waiting for sub shards to be active.", COLLECTION_NAME, activeClusterShape(3, 3));
    // OK, now let's check that the correct split point was chosen
    // We can use the router to find the shards for the middle prefixes, and they should be
    // different.
    DocCollection collection = client.getClusterState().getCollection(COLLECTION_NAME);
    Collection<Slice> slices1 = collection.getRouter().getSearchSlicesSingle(uniquePrefixes.get(uniquePrefixes.size() / 2 - 1).key, null, collection);
    Collection<Slice> slices2 = collection.getRouter().getSearchSlicesSingle(uniquePrefixes.get(uniquePrefixes.size() / 2).key, null, collection);
    Slice slice1 = slices1.iterator().next();
    Slice slice2 = slices2.iterator().next();
    assertTrue(slices1.size() == 1 && slices2.size() == 1);
    assertNotSame(slice1, slice2);
    //
    // now let's add enough documents to the first prefix to get it split out on its own
    //
    for (int i = 0; i < uniquePrefixes.size(); i++) {
        client.add(getDoc(uniquePrefixes.get(0).key, "doc" + (i + 100)));
    }
    client.commit();
    splitShard = CollectionAdminRequest.splitShard(COLLECTION_NAME).setSplitByPrefix(true).setShardName(slice1.getName());
    if (doAsync) {
        splitShard.setAsyncId("SPLIT3");
    }
    splitShard.process(client);
    waitForState("Timed out waiting for sub shards to be active.", COLLECTION_NAME, activeClusterShape(4, 4));
    collection = client.getClusterState().getCollection(COLLECTION_NAME);
    slices1 = collection.getRouter().getSearchSlicesSingle(uniquePrefixes.get(0).key, null, collection);
    slices2 = collection.getRouter().getSearchSlicesSingle(uniquePrefixes.get(1).key, null, collection);
    slice1 = slices1.iterator().next();
    slice2 = slices2.iterator().next();
    assertTrue(slices1.size() == 1 && slices2.size() == 1);
    assertNotSame(slice1, slice2);
    // Now if we call split (with splitByPrefix) on a shard that has a single prefix, it should
    // split it in half
    splitShard = CollectionAdminRequest.splitShard(COLLECTION_NAME).setSplitByPrefix(true).setShardName(slice1.getName());
    if (doAsync) {
        splitShard.setAsyncId("SPLIT4");
    }
    splitShard.process(client);
    waitForState("Timed out waiting for sub shards to be active.", COLLECTION_NAME, activeClusterShape(5, 5));
    collection = client.getClusterState().getCollection(COLLECTION_NAME);
    slices1 = collection.getRouter().getSearchSlicesSingle(uniquePrefixes.get(0).key, null, collection);
    slice1 = slices1.iterator().next();
    assertEquals(2, slices1.size());
    //
    // split one more time, this time on a partial prefix/bucket
    //
    splitShard = CollectionAdminRequest.splitShard(COLLECTION_NAME).setSplitByPrefix(true).setShardName(slice1.getName());
    if (doAsync) {
        splitShard.setAsyncId("SPLIT5");
    }
    splitShard.process(client);
    waitForState("Timed out waiting for sub shards to be active.", COLLECTION_NAME, activeClusterShape(6, 6));
    collection = client.getClusterState().getCollection(COLLECTION_NAME);
    slices1 = collection.getRouter().getSearchSlicesSingle(uniquePrefixes.get(0).key, null, collection);
    assertEquals(3, slices1.size());
    // System.err.println("### STATE=" +
    // cluster.getSolrClient().getZkStateReader().getClusterState().getCollection(COLLECTION_NAME));
    // System.err.println("### getActiveSlices()=" +
    // cluster.getSolrClient().getZkStateReader().getClusterState().getCollection(COLLECTION_NAME).getActiveSlices());
}

