@Test
public void testStoreAndRead() {
    Map<String, DocCollection> collectionStates = new HashMap<>();
    Set<String> liveNodes = new HashSet<>();
    liveNodes.add("node1");
    liveNodes.add("node2");
    Map<String, Slice> slices = new HashMap<>();
    Map<String, Replica> sliceToProps = new HashMap<>();
    Map<String, Object> props = new HashMap<>();
    String nodeName = "node1:10000_solr";
    props.put(ZkStateReader.NODE_NAME_PROP, nodeName);
    props.put(ZkStateReader.BASE_URL_PROP, Utils.getBaseUrlForNodeName(nodeName, "http"));
    props.put(ZkStateReader.CORE_NAME_PROP, "core1");
    props.put("prop1", "value");
    props.put("prop2", "value2");
    props.put(ZkStateReader.CONFIGNAME_PROP, ConfigSetsHandler.DEFAULT_CONFIGSET_NAME);
    Replica replica = new Replica("node1", props, "collection1", "shard1");
    sliceToProps.put("node1", replica);
    Slice slice = new Slice("shard1", sliceToProps, null, "collection1");
    slices.put("shard1", slice);
    Slice slice2 = new Slice("shard2", sliceToProps, null, "collection1");
    slices.put("shard2", slice2);
    collectionStates.put("collection1", DocCollection.create("collection1", slices, props, DocRouter.DEFAULT, 0, Instant.EPOCH, null));
    collectionStates.put("collection2", DocCollection.create("collection2", slices, props, DocRouter.DEFAULT, 0, Instant.EPOCH, null));
    ClusterState clusterState = new ClusterState(liveNodes, collectionStates);
    assertFalse(clusterState.getCollection("collection1").getProperties().containsKey("shards"));
    byte[] bytes = Utils.toJSON(clusterState);
    Instant creationTime = Instant.now();
    ClusterState loadedClusterState = ClusterState.createFromJson(-1, bytes, liveNodes, creationTime, null);
    assertFalse(loadedClusterState.getCollection("collection1").getProperties().containsKey("shards"));
    assertEquals("Provided liveNodes not used properly", 2, loadedClusterState.getLiveNodes().size());
    assertEquals("No collections found", 2, loadedClusterState.size());
    assertEquals("Properties not copied properly", replica.getStr("prop1"), loadedClusterState.getCollection("collection1").getSlice("shard1").getReplicasMap().get("node1").getStr("prop1"));
    assertEquals("Properties not copied properly", replica.getStr("prop2"), loadedClusterState.getCollection("collection1").getSlice("shard1").getReplicasMap().get("node1").getStr("prop2"));
    assertEquals(creationTime, loadedClusterState.getCollection("collection1").getCreationTime());
    assertEquals(creationTime, loadedClusterState.getCollection("collection2").getCreationTime());
    loadedClusterState = ClusterState.createFromJson(-1, new byte[0], liveNodes, Instant.now(), null);
    assertEquals("Provided liveNodes not used properly", 2, loadedClusterState.getLiveNodes().size());
    assertEquals("Should not have collections", 0, loadedClusterState.size());
    loadedClusterState = ClusterState.createFromJson(-1, (byte[]) null, liveNodes, Instant.now(), null);
    assertEquals("Provided liveNodes not used properly", 2, loadedClusterState.getLiveNodes().size());
    assertEquals("Should not have collections", 0, loadedClusterState.size());
}

