@Test
public void testCreateCollWithDefaultClusterPropertiesNewFormat() throws Exception {
    String COLL_NAME = "CollWithDefaultClusterProperties";
    try {
        V2Response rsp = new V2Request.Builder("/cluster/properties").withMethod(SolrRequest.METHOD.PUT).withPayload("{\"defaults\": {\"collection\": {\"numShards\": 2, \"nrtReplicas\": 2}}}").build().process(cluster.getSolrClient());
        for (int i = 0; i < 300; i++) {
            Map<?, ?> m = cluster.getZkStateReader().getClusterProperty(DEFAULTS, null);
            if (m != null)
                break;
            Thread.sleep(10);
        }
        Object clusterProperty = cluster.getZkStateReader().getClusterProperty(List.of(DEFAULTS, COLLECTION, NUM_SHARDS_PROP), null);
        assertEquals("2", String.valueOf(clusterProperty));
        clusterProperty = cluster.getZkStateReader().getClusterProperty(List.of(DEFAULTS, COLLECTION, NRT_REPLICAS), null);
        assertEquals("2", String.valueOf(clusterProperty));
        CollectionAdminResponse response = CollectionAdminRequest.createCollection(COLL_NAME, "conf", null, null, null, null).process(cluster.getSolrClient());
        assertEquals(0, response.getStatus());
        assertTrue(response.isSuccess());
        cluster.waitForActiveCollection(COLL_NAME, 2, 4);
        DocCollection coll = cluster.getSolrClient().getClusterState().getCollection(COLL_NAME);
        Map<String, Slice> slices = coll.getSlicesMap();
        assertEquals(2, slices.size());
        for (Slice slice : slices.values()) {
            assertEquals(2, slice.getReplicas().size());
        }
        CollectionAdminRequest.deleteCollection(COLL_NAME).process(cluster.getSolrClient());
        // unset only a single value
        rsp = new V2Request.Builder("/cluster/properties").withMethod(SolrRequest.METHOD.PUT).withPayload("{\n" + "  \"defaults\" : {\n" + "    \"collection\": {\n" + "      \"nrtReplicas\": null\n" + "    }\n" + "  }\n" + "}").build().process(cluster.getSolrClient());
        // we use a timeout so that the change made in ZK is reflected in the watched copy inside
        // ZkStateReader
        TimeOut timeOut = new TimeOut(5, TimeUnit.SECONDS, new TimeSource.NanoTimeSource());
        while (!timeOut.hasTimedOut()) {
            clusterProperty = cluster.getZkStateReader().getClusterProperty(List.of(DEFAULTS, COLLECTION, NRT_REPLICAS), null);
            if (clusterProperty == null)
                break;
        }
        assertNull(clusterProperty);
        rsp = new V2Request.Builder("/cluster/properties").withMethod(SolrRequest.METHOD.PUT).withPayload("{\"defaults\": {\"collection\": null}}").build().process(cluster.getSolrClient());
        // assert that it is really gone in both old and new paths
        timeOut = new TimeOut(5, TimeUnit.SECONDS, new TimeSource.NanoTimeSource());
        while (!timeOut.hasTimedOut()) {
            clusterProperty = cluster.getZkStateReader().getClusterProperty(List.of(DEFAULTS, COLLECTION, NUM_SHARDS_PROP), null);
            if (clusterProperty == null)
                break;
        }
        assertNull(clusterProperty);
    } finally {
        V2Response rsp = new V2Request.Builder("/cluster/properties").withMethod(SolrRequest.METHOD.PUT).withPayload("{\"defaults\": null}").build().process(cluster.getSolrClient());
    }
}

