@Test
public void test() throws Exception {
    CloudSolrClient cloudClient = cluster.getSolrClient();
    String coll = "deletenodetest_coll";
    ClusterState state = cloudClient.getClusterState();
    Set<String> liveNodes = state.getLiveNodes();
    ArrayList<String> l = new ArrayList<>(liveNodes);
    Collections.shuffle(l, random());
    CollectionAdminRequest.Create create = pickRandom(CollectionAdminRequest.createCollection(coll, "conf1", 5, 2, 0, 0), CollectionAdminRequest.createCollection(coll, "conf1", 5, 1, 1, 0), CollectionAdminRequest.createCollection(coll, "conf1", 5, 0, 1, 1), // check RF=1
    CollectionAdminRequest.createCollection(coll, "conf1", 5, 1, 0, 0), CollectionAdminRequest.createCollection(coll, "conf1", 5, 0, 1, 0));
    create.setCreateNodeSet(StrUtils.join(l, ','));
    cloudClient.request(create);
    state = cloudClient.getClusterState();
    String nodeToBeDecommissioned = l.get(0);
    // check what replicas are on the node, and whether the call should fail
    boolean shouldFail = false;
    DocCollection docColl = state.getCollection(coll);
    log.info("#### DocCollection: {}", docColl);
    List<Replica> replicas = docColl.getReplicasOnNode(nodeToBeDecommissioned);
    if (replicas != null) {
        for (Replica replica : replicas) {
            String shard = docColl.getShardId(nodeToBeDecommissioned, replica.getStr(ZkStateReader.CORE_NAME_PROP));
            Slice slice = docColl.getSlice(shard);
            boolean hasOtherNonPullReplicas = false;
            for (Replica r : slice.getReplicas()) {
                if (!r.getName().equals(replica.getName()) && !r.getNodeName().equals(nodeToBeDecommissioned) && r.getType() != Replica.Type.PULL) {
                    hasOtherNonPullReplicas = true;
                    break;
                }
            }
            if (!hasOtherNonPullReplicas) {
                shouldFail = true;
                break;
            }
        }
    }
    new CollectionAdminRequest.DeleteNode(nodeToBeDecommissioned).processAsync("003", cloudClient);
    CollectionAdminRequest.RequestStatus requestStatus = CollectionAdminRequest.requestStatus("003");
    CollectionAdminRequest.RequestStatusResponse rsp = null;
    for (int i = 0; i < 200; i++) {
        rsp = requestStatus.process(cloudClient);
        if (rsp.getRequestStatus() == RequestStatusState.FAILED || rsp.getRequestStatus() == RequestStatusState.COMPLETED) {
            break;
        }
        Thread.sleep(50);
    }
    if (log.isInfoEnabled()) {
        log.info("####### DocCollection after: {}", cloudClient.getClusterState().getCollection(coll));
    }
    if (shouldFail) {
        assertSame(String.valueOf(rsp), rsp.getRequestStatus(), RequestStatusState.FAILED);
    } else {
        assertNotSame(String.valueOf(rsp), rsp.getRequestStatus(), RequestStatusState.FAILED);
    }
}

@Test
public void deleteLiveReplicaTest() throws Exception {
    final String collectionName = "delLiveColl";
    Create req = CollectionAdminRequest.createCollection(collectionName, "conf", 2, 2);
    req.process(cluster.getSolrClient());
    cluster.waitForActiveCollection(collectionName, 2, 4);
    DocCollection state = getCollectionState(collectionName);
    Slice shard = getRandomShard(state);
    // don't choose the leader to shutdown, it just complicates things unnecessarily
    Replica replica = getRandomReplica(shard, (r) -> (r.getState() == Replica.State.ACTIVE && !r.equals(shard.getLeader())));
    final var coreStatus = getCoreStatus(replica);
    Path dataDir = Path.of(coreStatus.dataDir);
    Exception e = expectThrows(Exception.class, () -> {
        CollectionAdminRequest.deleteReplica(collectionName, shard.getName(), replica.getName()).setOnlyIfDown(true).process(cluster.getSolrClient());
    });
    assertTrue("Unexpected error message: " + e.getMessage(), e.getMessage().contains("state is 'active'"));
    assertTrue("Data directory for " + replica.getName() + " should not have been deleted", Files.exists(dataDir));
    JettySolrRunner replicaJetty = cluster.getReplicaJetty(replica);
    ZkStateReaderAccessor accessor = new ZkStateReaderAccessor(replicaJetty.getCoreContainer().getZkController().getZkStateReader());
    final long preDeleteWatcherCount = countUnloadCoreOnDeletedWatchers(accessor.getStateWatchers(collectionName));
    CollectionAdminRequest.deleteReplica(collectionName, shard.getName(), replica.getName()).process(cluster.getSolrClient());
    waitForState("Expected replica " + replica.getName() + " to have been removed", collectionName, c -> {
        Slice testShard = c.getSlice(shard.getName());
        return testShard.getReplica(replica.getName()) == null;
    });
    // the core should no longer have a watch collection state since it was removed
    // the core should no longer have a watch collection state since it was removed
    TimeOut timeOut = new TimeOut(60, TimeUnit.SECONDS, TimeSource.NANO_TIME);
    timeOut.waitFor("Waiting for core's watcher to be removed", () -> {
        final long postDeleteWatcherCount = countUnloadCoreOnDeletedWatchers(accessor.getStateWatchers(collectionName));
        log.info("preDeleteWatcherCount={} vs postDeleteWatcherCount={}", preDeleteWatcherCount, postDeleteWatcherCount);
        return (preDeleteWatcherCount - 1L == postDeleteWatcherCount);
    });
    assertFalse("Data directory for " + replica.getName() + " should have been removed", Files.exists(dataDir));
}

@Test
public void deleteReplicaAndVerifyDirectoryCleanup() throws Exception {
    final String collectionName = "deletereplica_test";
    CollectionAdminRequest.createCollection(collectionName, "conf", 1, 2).process(cluster.getSolrClient());
    Replica leader = cluster.getZkStateReader().getLeaderRetry(collectionName, "shard1");
    // Confirm that the instance and data directory exist
    final var coreStatus = getCoreStatus(leader);
    assertTrue("Instance directory doesn't exist", Files.exists(Path.of(coreStatus.instanceDir)));
    assertTrue("DataDirectory doesn't exist", Files.exists(Path.of(coreStatus.dataDir)));
    CollectionAdminRequest.deleteReplica(collectionName, "shard1", leader.getName()).process(cluster.getSolrClient());
    Replica newLeader = cluster.getZkStateReader().getLeaderRetry(collectionName, "shard1");
    assertNotEquals(leader, newLeader);
    // Confirm that the instance and data directory were deleted by default
    assertFalse("Instance directory still exists", Files.exists(Path.of(coreStatus.instanceDir)));
    assertFalse("DataDirectory still exists", Files.exists(Path.of(coreStatus.dataDir)));
}

