    final long preDeleteWatcherCount = countUnloadCoreOnDeletedWatchers(accessor.getStateWatchers(collectionName));
    ZkNodeProps m = new ZkNodeProps(Overseer.QUEUE_OPERATION, OverseerAction.DELETECORE.toLower(), ZkStateReader.CORE_NAME_PROP, replica.getCoreName(), ZkStateReader.NODE_NAME_PROP, replica.getNodeName(), ZkStateReader.BASE_URL_PROP, replicaZkController.getZkStateReader().getBaseUrlForNodeName(replica.getNodeName()), ZkStateReader.COLLECTION_PROP, collectionName, ZkStateReader.CORE_NODE_NAME_PROP, replica.getName());
    if (replicaZkController.getDistributedClusterStateUpdater().isDistributedStateUpdate()) {
        cluster.getOpenOverseer().getDistributedClusterStateUpdater().doSingleStateUpdate(DistributedClusterStateUpdater.MutatingCommand.SliceRemoveReplica, m, cluster.getOpenOverseer().getSolrCloudManager(), cluster.getOpenOverseer().getZkStateReader());
    } else {
        cluster.getOpenOverseer().getStateUpdateQueue().offer(m);
    }
    waitForState("Timeout waiting for replica get deleted", collectionName, collectionState -> collectionState.getSlice("shard1").getReplicas().size() == 2);
    TimeOut timeOut = new TimeOut(60, TimeUnit.SECONDS, TimeSource.NANO_TIME);
    timeOut.waitFor("Waiting for replica get unloaded", () -> replicaJetty.getCoreContainer().getCoreDescriptor(replica.getCoreName()) == null);
    // the core should no longer have a watch collection state since it was removed
    timeOut = new TimeOut(60, TimeUnit.SECONDS, TimeSource.NANO_TIME);
    timeOut.waitFor("Waiting for core's watcher to be removed", () -> {
        final long postDeleteWatcherCount = countUnloadCoreOnDeletedWatchers(accessor.getStateWatchers(collectionName));
        log.info("preDeleteWatcherCount={} vs postDeleteWatcherCount={}", preDeleteWatcherCount, postDeleteWatcherCount);
        return (preDeleteWatcherCount - 1L == postDeleteWatcherCount);
    });
    CollectionAdminRequest.deleteCollection(collectionName).process(cluster.getSolrClient());
}

@Test
public void raceConditionOnDeleteAndRegisterReplica() throws Exception {
    final String collectionName = "raceDeleteReplicaCollection";
    CollectionAdminRequest.createCollection(collectionName, "conf", 1, 2).process(cluster.getSolrClient());
    cluster.waitForActiveCollection(collectionName, 1, 2);
    waitForState("Expected 1x2 collections", collectionName, clusterShape(1, 2));
    Slice shard1 = getCollectionState(collectionName).getSlice("shard1");
    Replica leader = shard1.getLeader();
    JettySolrRunner leaderJetty = getJettyForReplica(leader);
    Replica replica1 = shard1.getReplicas(replica -> !replica.getName().equals(leader.getName())).get(0);
    assertNotEquals(replica1.getName(), leader.getName());
    JettySolrRunner replica1Jetty = getJettyForReplica(replica1);
    String replica1JettyNodeName = replica1Jetty.getNodeName();
    Semaphore waitingForReplicaGetDeleted = new Semaphore(0);
    // for safety, we only want this hook get triggered one time
    AtomicInteger times = new AtomicInteger(0);
    ZkContainer.testing_beforeRegisterInZk = cd -> {
        if (cd.getCloudDescriptor() == null)
            return false;
        if (replica1.getName().equals(cd.getCloudDescriptor().getCoreNodeName()) && collectionName.equals(cd.getCloudDescriptor().getCollectionName())) {
            if (times.incrementAndGet() > 1) {
                return false;
            }
            log.info("Running delete core {}", cd);
            try {
                waitForJettyInit(replica1Jetty, replica1JettyNodeName);
                ZkController replica1ZkController = replica1Jetty.getCoreContainer().getZkController();
                ZkNodeProps m = new ZkNodeProps(Overseer.QUEUE_OPERATION, OverseerAction.DELETECORE.toLower(), ZkStateReader.CORE_NAME_PROP, replica1.getCoreName(), ZkStateReader.NODE_NAME_PROP, replica1.getNodeName(), ZkStateReader.BASE_URL_PROP, replica1ZkController.getZkStateReader().getBaseUrlForNodeName(replica1.getNodeName()), ZkStateReader.COLLECTION_PROP, collectionName, ZkStateReader.CORE_NODE_NAME_PROP, replica1.getName());
                if (replica1ZkController.getDistributedClusterStateUpdater().isDistributedStateUpdate()) {
                    cluster.getOpenOverseer().getDistributedClusterStateUpdater().doSingleStateUpdate(DistributedClusterStateUpdater.MutatingCommand.SliceRemoveReplica, m, cluster.getOpenOverseer().getSolrCloudManager(), cluster.getOpenOverseer().getZkStateReader());
                } else {
                    cluster.getOpenOverseer().getStateUpdateQueue().offer(m);
                }
                boolean replicaDeleted = false;
                TimeOut timeOut = new TimeOut(20, TimeUnit.SECONDS, TimeSource.NANO_TIME);
                while (!timeOut.hasTimedOut()) {
                    try {
                        ZkStateReader stateReader = replica1Jetty.getCoreContainer().getZkController().getZkStateReader();
                        stateReader.forceUpdateCollection(collectionName);
                        Slice shard = stateReader.getClusterState().getCollection(collectionName).getSlice("shard1");
                        if (shard.getReplicas().size() == 1) {
                            replicaDeleted = true;
                            waitingForReplicaGetDeleted.release();
                            break;
                        }
                        Thread.sleep(500);
                    } catch (NullPointerException | SolrException e) {
                        log.error("error deleting replica", e);
                        Thread.sleep(500);
                    }
                }
                if (!replicaDeleted) {
                    fail("Timeout for waiting replica get deleted");
                }
            } catch (Exception e) {
                log.error("Failed to delete replica", e);
                fail("Failed to delete replica");
            } finally {
                // avoiding deadlock
                waitingForReplicaGetDeleted.release();
            }
            return true;
        }
        return false;
    };
    try {
        replica1Jetty.stop();
        waitForNodeLeave(replica1JettyNodeName);
        // There is a race condition: the replica might be marked down before we get here, in which
        // case we never get notified. So we check before waiting... Not eliminating but significantly
        // reducing the race window - eliminating would require deeper changes in the code where the
        // watcher is set.
        if (getCollectionState(collectionName).getSlice("shard1").getReplica(replica1.getName()).getState() != DOWN) {
            waitForState("Expected replica:" + replica1 + " get down", collectionName, collectionState -> collectionState.getSlice("shard1").getReplica(replica1.getName()).getState() == DOWN);
        }
        replica1Jetty.start();
        waitingForReplicaGetDeleted.acquire();
    } finally {
        ZkContainer.testing_beforeRegisterInZk = null;
    }
    TimeOut timeOut = new TimeOut(30, TimeUnit.SECONDS, TimeSource.NANO_TIME);
    timeOut.waitFor("Timeout adding replica to shard", () -> {
        try {
            CollectionAdminRequest.addReplicaToShard(collectionName, "shard1").process(cluster.getSolrClient());
            return true;
        } catch (Exception e) {
            // expected, when the node is not fully started
            return false;
        }
    });
    waitForState("Expected 1x2 collections", collectionName, clusterShape(1, 2));
    shard1 = getCollectionState(collectionName).getSlice("shard1");
    Replica latestLeader = shard1.getLeader();
    leaderJetty = getJettyForReplica(latestLeader);
    String leaderJettyNodeName = leaderJetty.getNodeName();
    leaderJetty.stop();
    waitForNodeLeave(leaderJettyNodeName);
    waitForState("Expected new active leader", collectionName, collectionState -> {
        Slice shard = collectionState.getSlice("shard1");
        Replica newLeader = shard.getLeader();
        return newLeader != null && newLeader.getState() == Replica.State.ACTIVE && !newLeader.getName().equals(latestLeader.getName());
    });
    leaderJetty.start();
    cluster.waitForActiveCollection(collectionName, 1, 2);
    CollectionAdminRequest.deleteCollection(collectionName).process(cluster.getSolrClient());
}

@Test
public void deleteReplicaOnIndexing() throws Exception {
    final String collectionName = "deleteReplicaOnIndexing";
    CollectionAdminRequest.createCollection(collectionName, "conf", 1, 2).process(cluster.getSolrClient());
    waitForState("", collectionName, clusterShape(1, 2));
    AtomicBoolean closed = new AtomicBoolean(false);
    Thread[] threads = new Thread[100];
    for (int i = 0; i < threads.length; i++) {
        int finalI = i;
        threads[i] = new Thread(() -> {
            int doc = finalI * 10000;
            while (!closed.get()) {
                try {
                    cluster.getSolrClient().add(collectionName, new SolrInputDocument("id", String.valueOf(doc++)));
                } catch (Exception e) {
                    log.error("Failed on adding document to {}", collectionName, e);
                }
            }
        });
        threads[i].start();
    }
    Slice shard1 = getCollectionState(collectionName).getSlice("shard1");
    Replica nonLeader = shard1.getReplicas(rep -> !rep.getName().equals(shard1.getLeader().getName())).get(0);
    CollectionAdminRequest.deleteReplica(collectionName, "shard1", nonLeader.getName()).process(cluster.getSolrClient());
    closed.set(true);
    for (Thread thread : threads) {
        thread.join();
    }
    waitForState("Waiting for single replica in state", collectionName, collectionState -> collectionState.getReplicas().size() == 1);
}

