@Test
public void testDisconnect() throws Exception {
    final String TRACKER_ROOT = "/disconnect";
    DistributedApiAsyncTracker permanentDaat = new DistributedApiAsyncTracker(zkClient, TRACKER_ROOT);
    DistributedApiAsyncTracker permanentDaat2 = new DistributedApiAsyncTracker(zkClient, TRACKER_ROOT);
    final String asyncPermanent = "permanentAsync";
    final String asyncTransient = "transientAsync";
    assertTrue("Could not create async task " + asyncPermanent, permanentDaat.createNewAsyncJobTracker(asyncPermanent));
    try (SolrZkClient transientZkClient = new SolrZkClient.Builder().withUrl(zkServer.getZkHost()).withTimeout(AbstractZkTestCase.TIMEOUT, TimeUnit.MILLISECONDS).build()) {
        DistributedApiAsyncTracker transientDaat = new DistributedApiAsyncTracker(transientZkClient, TRACKER_ROOT);
        assertTrue("Could not create async task " + asyncTransient, transientDaat.createNewAsyncJobTracker(asyncTransient));
        assertEquals("permanentDaat can't see " + asyncPermanent, RequestStatusState.SUBMITTED, permanentDaat.getAsyncTaskRequestStatus(asyncPermanent).first());
        assertEquals("permanentDaat2 can't see " + asyncPermanent, RequestStatusState.SUBMITTED, permanentDaat2.getAsyncTaskRequestStatus(asyncPermanent).first());
        assertEquals("transientDaat can't see " + asyncPermanent, RequestStatusState.SUBMITTED, transientDaat.getAsyncTaskRequestStatus(asyncPermanent).first());
        assertEquals("permanentDaat can't see " + asyncTransient, RequestStatusState.SUBMITTED, permanentDaat.getAsyncTaskRequestStatus(asyncTransient).first());
        assertEquals("permanentDaat2 can't see " + asyncTransient, RequestStatusState.SUBMITTED, permanentDaat2.getAsyncTaskRequestStatus(asyncTransient).first());
        assertEquals("transientDaat can't see " + asyncTransient, RequestStatusState.SUBMITTED, transientDaat.getAsyncTaskRequestStatus(asyncTransient).first());
    }
    // transientDaat connection closed, doesn't change a thing for asyncPermanent...
    assertEquals("permanentDaat can't see " + asyncPermanent, RequestStatusState.SUBMITTED, permanentDaat.getAsyncTaskRequestStatus(asyncPermanent).first());
    assertEquals("permanentDaat2 can't see " + asyncPermanent, RequestStatusState.SUBMITTED, permanentDaat2.getAsyncTaskRequestStatus(asyncPermanent).first());
    // ...but asyncTransient is now failed.
    assertEquals("permanentDaat can't see " + asyncTransient, RequestStatusState.FAILED, permanentDaat.getAsyncTaskRequestStatus(asyncTransient).first());
    assertEquals("permanentDaat2 can't see " + asyncTransient, RequestStatusState.FAILED, permanentDaat2.getAsyncTaskRequestStatus(asyncTransient).first());
}

@Test
public void testDisconnectAfterCompletion() throws Exception {
    final String TRACKER_ROOT = "/multiConn";
    DistributedApiAsyncTracker daat = new DistributedApiAsyncTracker(zkClient, TRACKER_ROOT);
    final String asyncId = "theId";
    try (SolrZkClient transientZkClient = new SolrZkClient.Builder().withUrl(zkServer.getZkHost()).withTimeout(AbstractZkTestCase.TIMEOUT, TimeUnit.MILLISECONDS).build()) {
        DistributedApiAsyncTracker transientDaat = new DistributedApiAsyncTracker(transientZkClient, TRACKER_ROOT);
        assertTrue("Could not create async task " + asyncId, transientDaat.createNewAsyncJobTracker(asyncId));
        // The task completes, then connection lost
        NamedList<Object> nl = new NamedList<>();
        nl.add("status", "I made it");
        transientDaat.setTaskCompleted(asyncId, new OverseerSolrResponse(nl));
        assertEquals("transientDaat can't see " + asyncId, RequestStatusState.COMPLETED, transientDaat.getAsyncTaskRequestStatus(asyncId).first());
        assertEquals("transientDaat can't retrieve correct completed OverseerSolrResponse " + asyncId, "I made it", transientDaat.getAsyncTaskRequestStatus(asyncId).second().getResponse().get("status"));
        assertEquals("daat can't retrieve correct completed OverseerSolrResponse " + asyncId, "I made it", daat.getAsyncTaskRequestStatus(asyncId).second().getResponse().get("status"));
    }
    // Even though connection was closed, the task should still be completed, and we should be able
    // to retrieve its response
    assertEquals("daat can't see " + asyncId, RequestStatusState.COMPLETED, daat.getAsyncTaskRequestStatus(asyncId).first());
    assertEquals("Did not retrieve correct completed OverseerSolrResponse after other connection closes " + asyncId, "I made it", daat.getAsyncTaskRequestStatus(asyncId).second().getResponse().get("status"));
    // And given it completed, it should be deleted
    daat.deleteAllAsyncIds();
    assertEquals("task was not deleted " + asyncId, RequestStatusState.NOT_FOUND, daat.getAsyncTaskRequestStatus(asyncId).first());
}

@Test
public void testIdCleanup() throws Exception {
    // When cleaning up, 3 async id's will be removed
    final int maxTasks = 30;
    DistributedApiAsyncTracker daat = new DistributedApiAsyncTracker(zkClient, "/manyIds", maxTasks);
    for (int asyncId = 1; asyncId <= maxTasks; asyncId++) {
        assertTrue(daat.createNewAsyncJobTracker(Integer.toString(asyncId)));
    }
    // All ids should be tracked
    assertEquals(RequestStatusState.SUBMITTED, daat.getAsyncTaskRequestStatus(Integer.toString(1)).first());
    assertEquals(RequestStatusState.SUBMITTED, daat.getAsyncTaskRequestStatus(Integer.toString(maxTasks)).first());
    // Adding one more should trigger cleanup of earlier id's
    assertTrue(daat.createNewAsyncJobTracker("straw"));
    String cleanedUpId1 = Integer.toString(1);
    assertEquals("Cleanup should have been triggered and removed the first task", RequestStatusState.NOT_FOUND, daat.getAsyncTaskRequestStatus(cleanedUpId1).first());
    assertEquals("Last task should not have been cleaned up", RequestStatusState.SUBMITTED, daat.getAsyncTaskRequestStatus(Integer.toString(maxTasks)).first());
    assertEquals("Task having triggered cleanup should not have been cleaned up", RequestStatusState.SUBMITTED, daat.getAsyncTaskRequestStatus("straw").first());
    // Identical to the test 3 lines above but repeated to be considered in context
    assertEquals("Cleaned up ID (1) should no longer be visible", RequestStatusState.NOT_FOUND, daat.getAsyncTaskRequestStatus(cleanedUpId1).first());
    // Creating a new task with same id fails but "revives" the ID if the task is still in progress
    assertFalse("Should not be able to create a task with same id as task in progress", daat.createNewAsyncJobTracker(cleanedUpId1));
    assertEquals("Cleaned up ID now visible again", RequestStatusState.SUBMITTED, daat.getAsyncTaskRequestStatus(cleanedUpId1).first());
    // 2 is also in progress and was also cleaned up. It should be markable complete without issues
    // (since that's what will happen when it completed).
    String cleanedUpId2 = Integer.toString(2);
    assertEquals("Another cleaned up ID (2) should not be visible", RequestStatusState.NOT_FOUND, daat.getAsyncTaskRequestStatus(cleanedUpId2).first());
    NamedList<Object> nl = new NamedList<>();
    nl.add("code", "da vinci");
    daat.setTaskCompleted(cleanedUpId2, new OverseerSolrResponse(nl));
    assertEquals("task should now be completed " + cleanedUpId2, RequestStatusState.COMPLETED, daat.getAsyncTaskRequestStatus(cleanedUpId2).first());
    assertEquals("task should have correct OverseerSolrResponse " + cleanedUpId2, "da vinci", daat.getAsyncTaskRequestStatus(cleanedUpId2).second().getResponse().get("code"));
    // 3 is also in progress and was also cleaned up. It should be markable running without issues,
    // but that doesn't revive it (still not found).
    // (if we want setTaskRunning to revive a removed task, we'd have to check the persistent node
    // existence each time, which is likely not worth it)
    String cleanedUpId3 = Integer.toString(3);
    assertEquals("Another cleaned up ID (3) should not be visible", RequestStatusState.NOT_FOUND, daat.getAsyncTaskRequestStatus(cleanedUpId3).first());
    daat.setTaskRunning(cleanedUpId3);
    assertEquals("task should now be running " + cleanedUpId3, RequestStatusState.NOT_FOUND, daat.getAsyncTaskRequestStatus(cleanedUpId3).first());
}

@Test
public void testDistributedQueue() throws Exception {
    String dqZNode = "/distqueue/test";
    byte[] data = "hello world".getBytes(UTF8);
    DistributedQueue dq = makeDistributedQueue(dqZNode);
    // basic ops
    assertNull(dq.poll());
    try {
        dq.remove();
        fail("NoSuchElementException expected");
    } catch (NoSuchElementException expected) {
        // expected
    }
    dq.offer(data);
    assertArrayEquals(dq.peek(500), data);
    assertArrayEquals(dq.remove(), data);
    assertNull(dq.poll());
    dq.offer(data);
    // waits for data
    assertArrayEquals(dq.take(), data);
    assertNull(dq.poll());
    dq.offer(data);
    // wait until data is definitely there before calling remove
    dq.peek(true);
    assertArrayEquals(dq.remove(), data);
    assertNull(dq.poll());
    // should block until the background thread makes the offer
    (new QueueChangerThread(dq, 1000)).start();
    assertNotNull(dq.peek(true));
    assertNotNull(dq.remove());
    assertNull(dq.poll());
    // timeout scenario ... background thread won't offer until long after the peek times out
    QueueChangerThread qct = new QueueChangerThread(dq, 1000);
    qct.start();
    assertNull(dq.peek(500));
    qct.join();
}

@Test
public void testDistributedQueueCache() throws Exception {
    String dqZNode = "/distqueue/test";
    byte[] data = "hello world".getBytes(UTF8);
    ZkDistributedQueue consumer = makeDistributedQueue(dqZNode);
    DistributedQueue producer = makeDistributedQueue(dqZNode);
    DistributedQueue producer2 = makeDistributedQueue(dqZNode);
    producer2.offer(data);
    producer.offer(data);
    producer.offer(data);
    consumer.poll();
    assertEquals(2, consumer.getZkStats().getQueueLength());
    producer.offer(data);
    producer2.offer(data);
    consumer.poll();
    // Wait for watcher being kicked off
    while (!consumer.isDirty()) {
        Thread.sleep(20);
    }
    // DQ still have elements in their queue, so we should not fetch elements path from Zk
    assertEquals(1, consumer.getZkStats().getQueueLength());
    consumer.poll();
    consumer.peek();
    assertEquals(2, consumer.getZkStats().getQueueLength());
}

@Test
public void testDistributedQueueBlocking() throws Exception {
    String dqZNode = "/distqueue/test";
    String testData = "hello world";
    ZkDistributedQueue dq = makeDistributedQueue(dqZNode);
    assertNull(dq.peek());
    Future<String> future = executor.submit(() -> new String(dq.peek(true), UTF8));
    try {
        future.get(1000, TimeUnit.MILLISECONDS);
        fail("TimeoutException expected");
    } catch (TimeoutException expected) {
        assertFalse(future.isDone());
    }
    // Ultimately trips the watcher, triggering child refresh
    dq.offer(testData.getBytes(UTF8));
    assertEquals(testData, future.get(1000, TimeUnit.MILLISECONDS));
    assertNotNull(dq.poll());
    // After draining the queue, a watcher should be set.
    assertNull(dq.peek(100));
    TimeOut timeout = new TimeOut(30, TimeUnit.SECONDS, TimeSource.NANO_TIME);
    timeout.waitFor("Timeout waiting to see dirty=false", () -> {
        try {
            return !dq.isDirty();
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    });
    assertFalse(dq.isDirty());
    assertEquals(1, dq.watcherCount());
    forceSessionExpire();
    // Session expiry should have fired the watcher.
    Thread.sleep(100);
    assertTrue(dq.isDirty());
    assertEquals(0, dq.watcherCount());
    // Rerun the earlier test make sure updates are still seen, post reconnection.
    future = executor.submit(() -> new String(dq.peek(true), UTF8));
    try {
        future.get(1000, TimeUnit.MILLISECONDS);
        fail("TimeoutException expected");
    } catch (TimeoutException expected) {
        assertFalse(future.isDone());
    }
    // Ultimately trips the watcher, triggering child refresh
    dq.offer(testData.getBytes(UTF8));
    assertEquals(testData, future.get(1000, TimeUnit.MILLISECONDS));
    assertNotNull(dq.poll());
    assertNull(dq.poll());
}

@Test
public void testLeakChildWatcher() throws Exception {
    String dqZNode = "/distqueue/test";
    ZkDistributedQueue dq = makeDistributedQueue(dqZNode);
    assertTrue(dq.peekElements(1, 1, s1 -> true).isEmpty());
    assertEquals(1, dq.watcherCount());
    assertFalse(dq.isDirty());
    assertTrue(dq.peekElements(1, 1, s1 -> true).isEmpty());
    assertEquals(1, dq.watcherCount());
    assertFalse(dq.isDirty());
    assertNull(dq.peek());
    assertEquals(1, dq.watcherCount());
    assertFalse(dq.isDirty());
    assertNull(dq.peek(10));
    assertEquals(1, dq.watcherCount());
    assertFalse(dq.isDirty());
    dq.offer("hello world".getBytes(UTF8));
    // synchronously available
    assertNotNull(dq.peek());
    // dirty and watcher state indeterminate here, race with watcher
    // watcher should have fired now
    Thread.sleep(100);
    assertNotNull(dq.peek());
    // in case of race condition, childWatcher is kicked off after peek()
    if (dq.watcherCount() == 0) {
        assertTrue(dq.isDirty());
        dq.poll();
        dq.offer("hello world".getBytes(UTF8));
        dq.peek();
    }
    assertEquals(1, dq.watcherCount());
    assertFalse(dq.isDirty());
    assertFalse(dq.peekElements(1, 1, s -> true).isEmpty());
    assertEquals(1, dq.watcherCount());
    assertFalse(dq.isDirty());
}

