@Test
public void testStressElection() throws Exception {
    final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(15, new SolrNamedThreadFactory("stressElection"));
    final List<ClientThread> threads = Collections.synchronizedList(new ArrayList<ClientThread>());
    // start with a leader
    ClientThread thread1 = new ClientThread("shard1", 0);
    threads.add(thread1);
    scheduler.schedule(thread1, 0, TimeUnit.MILLISECONDS);
    Thread scheduleThread = new Thread() {

        @Override
        public void run() {
            int count = atLeast(5);
            for (int i = 1; i < count; i++) {
                int launchIn = random().nextInt(500);
                ClientThread thread = null;
                try {
                    thread = new ClientThread("shard1", i);
                } catch (Exception e) {
                    //
                }
                if (thread != null) {
                    threads.add(thread);
                    scheduler.schedule(thread, launchIn, TimeUnit.MILLISECONDS);
                }
            }
        }
    };
    Thread killThread = new Thread() {

        @Override
        public void run() {
            while (!stopStress) {
                try {
                    int j;
                    try {
                        // always 1 we won't kill...
                        j = random().nextInt(threads.size() - 2);
                    } catch (IllegalArgumentException e) {
                        continue;
                    }
                    try {
                        threads.get(j).close();
                    } catch (Exception e) {
                    }
                    Thread.sleep(10);
                } catch (Exception e) {
                }
            }
        }
    };
    Thread connLossThread = new Thread(() -> {
        while (!stopStress) {
            try {
                Thread.sleep(50);
                int j;
                j = random().nextInt(threads.size());
                try {
                    if (random().nextBoolean()) {
                        KillSession.kill(threads.get(j).es.zkClient.getCuratorFramework().getZookeeperClient().getZooKeeper());
                    }
                } catch (Exception e) {
                    log.error("error expiring session", e);
                }
                Thread.sleep(500);
            } catch (Exception e) {
                log.error("error expiring session", e);
            }
        }
    });
    try {
        scheduleThread.start();
        connLossThread.start();
        killThread.start();
        Thread.sleep(4000);
        stopStress = true;
        scheduleThread.interrupt();
        connLossThread.interrupt();
        killThread.interrupt();
        scheduleThread.join();
        scheduler.shutdownNow();
        connLossThread.join();
        killThread.join();
        int seq = threads.get(getLeaderThread()).getSeq();
        // we have a leader we know, TODO: lets check some other things
    } finally {
        // cleanup any threads still running
        for (ClientThread thread : threads) {
            thread.close();
        }
        // cleanup any threads still running
        for (ClientThread thread : threads) {
            thread.es.zkClient.close();
            thread.close();
        }
        for (Thread thread : threads) {
            thread.join();
        }
    }
}

