@Test
public void testMostInSyncReplicasCanWinElection() throws Exception {
    final String collectionName = "collection1";
    CollectionAdminRequest.createCollection(collectionName, 1, 3).setCreateNodeSet("").process(cluster.getSolrClient());
    CollectionAdminRequest.addReplicaToShard(collectionName, "shard1").setNode(cluster.getJettySolrRunner(0).getNodeName()).process(cluster.getSolrClient());
