    waitForState("Timeout waiting for shard leader", collectionName, clusterShape(1, 1));
    Replica leader = getCollectionState(collectionName).getSlice("shard1").getLeader();
    // this replica will ahead of election queue
    CollectionAdminRequest.addReplicaToShard(collectionName, "shard1").setNode(cluster.getJettySolrRunner(1).getNodeName()).process(cluster.getSolrClient());
    cluster.waitForActiveCollection(collectionName, 1, 2);
    waitForState("Timeout waiting for 1x2 collection", collectionName, clusterShape(1, 2));
    Replica replica1 = getCollectionState(collectionName).getSlice("shard1").getReplicas(replica -> replica.getNodeName().equals(cluster.getJettySolrRunner(1).getNodeName())).get(0);
    CollectionAdminRequest.addReplicaToShard(collectionName, "shard1").setNode(cluster.getJettySolrRunner(2).getNodeName()).process(cluster.getSolrClient());
    cluster.waitForActiveCollection(collectionName, 1, 3);
    waitForState("Timeout waiting for 1x3 collection", collectionName, clusterShape(1, 3));
    Replica replica2 = getCollectionState(collectionName).getSlice("shard1").getReplicas(replica -> replica.getNodeName().equals(cluster.getJettySolrRunner(2).getNodeName())).get(0);
    cluster.getSolrClient().add(collectionName, new SolrInputDocument("id", "1"));
    cluster.getSolrClient().add(collectionName, new SolrInputDocument("id", "2"));
    cluster.getSolrClient().commit(collectionName);
    // replica in node1 won't be able to do recovery
    proxies.get(cluster.getJettySolrRunner(0)).close();
    // leader won't be able to send request to replica in node1
    proxies.get(cluster.getJettySolrRunner(1)).close();
    addDoc(collectionName, 3, cluster.getJettySolrRunner(0));
    try (ZkShardTerms zkShardTerms = new ZkShardTerms(collectionName, "shard1", cluster.getZkClient())) {
        assertEquals(3, zkShardTerms.getTerms().size());
        assertEquals(zkShardTerms.getHighestTerm(), zkShardTerms.getTerm(leader.getName()));
        assertEquals(zkShardTerms.getHighestTerm(), zkShardTerms.getTerm(replica2.getName()));
        assertTrue(zkShardTerms.getHighestTerm() > zkShardTerms.getTerm(replica1.getName()));
    }
    proxies.get(cluster.getJettySolrRunner(2)).close();
    addDoc(collectionName, 4, cluster.getJettySolrRunner(0));
    try (ZkShardTerms zkShardTerms = new ZkShardTerms(collectionName, "shard1", cluster.getZkClient())) {
        assertEquals(3, zkShardTerms.getTerms().size());
        assertEquals(zkShardTerms.getHighestTerm(), zkShardTerms.getTerm(leader.getName()));
        assertTrue(zkShardTerms.getHighestTerm() > zkShardTerms.getTerm(replica2.getName()));
        assertTrue(zkShardTerms.getHighestTerm() > zkShardTerms.getTerm(replica1.getName()));
        assertTrue(zkShardTerms.getTerm(replica2.getName()) > zkShardTerms.getTerm(replica1.getName()));
    }
    proxies.get(cluster.getJettySolrRunner(1)).reopen();
    proxies.get(cluster.getJettySolrRunner(2)).reopen();
    JettySolrRunner j = cluster.getJettySolrRunner(0);
    j.stop();
    cluster.waitForJettyToStop(j);
    try {
        // even replica2 joined election at the end of the queue, but it is the one with the highest
        // term
        waitForState("Timeout waiting for new leader", collectionName, collectionState -> {
            Replica newLeader = collectionState.getSlice("shard1").getLeader();
            if (newLeader == null) {
                return false;
            }
            return newLeader.getName().equals(replica2.getName());
        });
    } catch (Exception e) {
        List<String> children = zkClient().getChildren("/collections/" + collectionName + "/leader_elect/shard1/election", null, true);
        log.info("{} election nodes:{}", collectionName, children);
        throw e;
    }
    cluster.getJettySolrRunner(0).start();
    proxies.get(cluster.getJettySolrRunner(0)).reopen();
    waitForState("Timeout waiting for 1x3 collection", collectionName, clusterShape(1, 3));
    assertDocsExistInAllReplicas(Arrays.asList(leader, replica1), collectionName, 1, 3);
    CollectionAdminRequest.deleteCollection(collectionName).process(cluster.getSolrClient());
}

@Test
public void test() throws Exception {
    configureCluster(6).addConfig("conf1", TEST_PATH().resolve("configsets").resolve("cloud-dynamic").resolve("conf")).configure();
    String coll = "replacenodetest_coll";
    if (log.isInfoEnabled()) {
        log.info("total_jettys: {}", cluster.getJettySolrRunners().size());
    }
    CloudSolrClient cloudClient = cluster.getSolrClient();
    Set<String> liveNodes = cloudClient.getClusterState().getLiveNodes();
    ArrayList<String> l = new ArrayList<>(liveNodes);
    Collections.shuffle(l, random());
    String emptyNode = l.remove(0);
    String nodeToBeDecommissioned = l.get(0);
    CollectionAdminRequest.Create create;
    // NOTE: always using the createCollection that takes in 'int' for all types of replicas, so we
    // never have to worry about null checking when comparing the Create command with the final
    // Slices
    // TODO: tlog replicas do not work correctly in tests due to fault
    // TestInjection#waitForInSyncWithLeader
    create = pickRandom(CollectionAdminRequest.createCollection(coll, "conf1", 5, 2, 0, 0), // CollectionAdminRequest.createCollection(coll, "conf1", 5, 1,1,0),
    // CollectionAdminRequest.createCollection(coll, "conf1", 5, 0,1,1),
    // CollectionAdminRequest.createCollection(coll, "conf1", 5, 1,0,1),
    // CollectionAdminRequest.createCollection(coll, "conf1", 5, 0,2,0),
    // check also replicationFactor 1
    CollectionAdminRequest.createCollection(coll, "conf1", 5, 1, 0, 0));
    create.setCreateNodeSet(StrUtils.join(l, ','));
    cloudClient.request(create);
    cluster.waitForActiveCollection(coll, 5, 5 * (create.getNumNrtReplicas() + create.getNumPullReplicas() + create.getNumTlogReplicas()));
    DocCollection collection = cloudClient.getClusterState().getCollection(coll);
    log.debug("### Before decommission: {}", collection);
    log.info("excluded_node : {}  ", emptyNode);
    Map<?, ?> response = callMigrateReplicas(cloudClient, new MigrateReplicasRequestBody(Set.of(nodeToBeDecommissioned), Set.of(emptyNode), true, null));
    assertEquals("MigrateReplicas request was unsuccessful", 0L, ((Map<?, ?>) response.get("responseHeader")).get("status"));
    ZkStateReader zkStateReader = ZkStateReader.from(cloudClient);
    try (SolrClient coreClient = getHttpSolrClient(zkStateReader.getBaseUrlForNodeName(nodeToBeDecommissioned))) {
        CoreAdminResponse status = CoreAdminRequest.getStatus(null, coreClient);
        assertEquals("There should not be any cores left on decommissioned node", 0, status.getCoreStatus().size());
    }
    Thread.sleep(5000);
    collection = cloudClient.getClusterState().getCollectionOrNull(coll, false);
    log.debug("### After decommission: {}", collection);
    // check what are replica states on the decommissioned node
    assertNull("There should not be any replicas left on decommissioned node", collection.getReplicasOnNode(nodeToBeDecommissioned));
    // let's do it back - this time wait for recoveries
    response = callMigrateReplicas(cloudClient, new MigrateReplicasRequestBody(Set.of(emptyNode), Set.of(nodeToBeDecommissioned), true, null));
    assertEquals("MigrateReplicas request was unsuccessful", 0L, ((Map<?, ?>) response.get("responseHeader")).get("status"));
    try (SolrClient coreClient = getHttpSolrClient(zkStateReader.getBaseUrlForNodeName(emptyNode))) {
        CoreAdminResponse status = CoreAdminRequest.getStatus(null, coreClient);
        assertEquals("Expecting no cores but found some: " + status.getCoreStatus(), 0, status.getCoreStatus().size());
    }
    collection = cluster.getSolrClient().getClusterState().getCollection(coll);
    assertEquals(create.getNumShards().intValue(), collection.getSlices().size());
    for (Slice s : collection.getSlices()) {
        assertEquals(create.getNumNrtReplicas().intValue(), s.getReplicas(EnumSet.of(Replica.Type.NRT)).size());
        assertEquals(create.getNumTlogReplicas().intValue(), s.getReplicas(EnumSet.of(Replica.Type.TLOG)).size());
        assertEquals(create.getNumPullReplicas().intValue(), s.getReplicas(EnumSet.of(Replica.Type.PULL)).size());
    }
    // make sure all newly created replicas on node are active
    List<Replica> newReplicas = collection.getReplicasOnNode(nodeToBeDecommissioned);
    assertNotNull("There should be replicas on the migrated-to node", newReplicas);
    assertFalse("There should be replicas on the migrated-to node", newReplicas.isEmpty());
    for (Replica r : newReplicas) {
        assertEquals(r.toString(), Replica.State.ACTIVE, r.getState());
    }
    // make sure all replicas on emptyNode are not active
    List<Replica> replicas = collection.getReplicasOnNode(emptyNode);
    if (replicas != null) {
        for (Replica r : replicas) {
            assertNotEquals(r.toString(), Replica.State.ACTIVE, r.getState());
        }
    }
    // check replication metrics on this jetty - see SOLR-14924
    for (JettySolrRunner jetty : cluster.getJettySolrRunners()) {
        if (jetty.getCoreContainer() == null) {
            continue;
        }
        SolrMetricManager metricManager = jetty.getCoreContainer().getMetricManager();
        String registryName = null;
        for (String name : metricManager.registryNames()) {
            if (name.startsWith("solr.core.")) {
                registryName = name;
            }
        }
        Map<String, Metric> metrics = metricManager.registry(registryName).getMetrics();
        if (!metrics.containsKey("REPLICATION./replication.fetcher")) {
            continue;
        }
        MetricsMap fetcherGauge = (MetricsMap) ((SolrMetricManager.GaugeWrapper<?>) metrics.get("REPLICATION./replication.fetcher")).getGauge();
        assertNotNull("no IndexFetcher gauge in metrics", fetcherGauge);
        Map<String, Object> value = fetcherGauge.getValue();
        if (value.isEmpty()) {
            continue;
        }
        assertNotNull("isReplicating missing: " + value, value.get("isReplicating"));
        assertTrue("isReplicating should be a boolean: " + value, value.get("isReplicating") instanceof Boolean);
        if (value.get("indexReplicatedAt") == null) {
            continue;
        }
        assertNotNull("timesIndexReplicated missing: " + value, value.get("timesIndexReplicated"));
        assertTrue("timesIndexReplicated should be a number: " + value, value.get("timesIndexReplicated") instanceof Number);
    }
}

@Test
public void testWithNoTarget() throws Exception {
    configureCluster(5).addConfig("conf1", TEST_PATH().resolve("configsets").resolve("cloud-dynamic").resolve("conf")).configure();
    String coll = "migratereplicastest_notarget_coll";
    if (log.isInfoEnabled()) {
        log.info("total_jettys: {}", cluster.getJettySolrRunners().size());
    }
    CloudSolrClient cloudClient = cluster.getSolrClient();
    Set<String> liveNodes = cloudClient.getClusterState().getLiveNodes();
    List<String> l = new ArrayList<>(liveNodes);
    Collections.shuffle(l, random());
    List<String> nodesToBeDecommissioned = l.subList(0, 2);
    List<String> eventualTargetNodes = l.subList(2, l.size());
    // TODO: tlog replicas do not work correctly in tests due to fault
    // TestInjection#waitForInSyncWithLeader
    CollectionAdminRequest.Create create = CollectionAdminRequest.createCollection(coll, "conf1", 3, 2, 0, 0);
    cloudClient.request(create);
    cluster.waitForActiveCollection(coll, create.getNumShards(), create.getNumShards() * (create.getNumNrtReplicas() + create.getNumPullReplicas() + create.getNumTlogReplicas()));
    DocCollection initialCollection = cloudClient.getClusterState().getCollection(coll);
    log.info("### Before decommission: {}", initialCollection);
    List<Integer> initialReplicaCounts = l.stream().map(node -> initialCollection.getReplicasOnNode(node).size()).collect(Collectors.toList());
    Map<?, ?> response = callMigrateReplicas(cloudClient, new MigrateReplicasRequestBody(new HashSet<>(nodesToBeDecommissioned), Collections.emptySet(), true, null));
    assertEquals("MigrateReplicas request was unsuccessful", 0L, ((Map<?, ?>) response.get("responseHeader")).get("status"));
    DocCollection collection = cloudClient.getClusterState().getCollectionOrNull(coll, false);
    assertNotNull("Collection cannot be null: " + coll, collection);
    log.info("### After decommission: {}", collection);
    // check what are replica states on the decommissioned nodes
    for (String nodeToBeDecommissioned : nodesToBeDecommissioned) {
        List<Replica> replicas = collection.getReplicasOnNode(nodeToBeDecommissioned);
        if (replicas == null) {
            replicas = Collections.emptyList();
        }
        assertEquals("There should be no more replicas on the sourceNode after a migrateReplicas request.", Collections.emptyList(), replicas);
    }
    for (String node : eventualTargetNodes) {
        assertNotEquals("The non-source node '" + node + "' should not receive all replicas from the migration", 4, collection.getReplicasOnNode(node).size());
    }
}

