@Test
public void downNodeReportsAllImpactedCollectionsAndNothingElse() {
    NodeMutator nm = new NodeMutator(null);
    // Collection1: 2 shards X 1 replica = replica1 on node1 and replica2 on node2
    // Collection2: 1 shard X 1 replica = replica1 on node2
    ZkStateReader reader = ClusterStateMockUtil.buildClusterState("csrr2rDcsr2", 1, NODE1, NODE2);
    ClusterState clusterState = reader.getClusterState();
    assertEquals(clusterState.getCollection("collection1").getReplica("replica1").getBaseUrl(), NODE1_URL);
    assertEquals(clusterState.getCollection("collection1").getReplica("replica2").getBaseUrl(), NODE2_URL);
    assertEquals(clusterState.getCollection("collection2").getReplica("replica4").getBaseUrl(), NODE2_URL);
    ZkNodeProps props = new ZkNodeProps(ZkStateReader.NODE_NAME_PROP, NODE1);
    List<ZkWriteCommand> writes = nm.downNode(clusterState, props);
    assertEquals(writes.size(), 1);
    assertEquals(writes.get(0).name, "collection1");
    assertEquals(writes.get(0).collection.getReplica("replica1").getState(), Replica.State.DOWN);
    assertEquals(writes.get(0).collection.getReplica("replica2").getState(), Replica.State.ACTIVE);
    reader.close();
    // Collection1: 2 shards X 1 replica = replica1 on node1 and replica2 on node2
    // Collection2: 1 shard X 1 replica = replica1 on node2
    // Collection3: 1 shard X 3 replica = replica1 on node1 , replica2 on node2, replica3 on node3
    reader = ClusterStateMockUtil.buildClusterState("csrr2rDcsr2csr1r2r3", 1, NODE1, NODE2, NODE3);
    clusterState = reader.getClusterState();
    assertEquals(clusterState.getCollection("collection1").getReplica("replica1").getBaseUrl(), NODE1_URL);
    assertEquals(clusterState.getCollection("collection1").getReplica("replica2").getBaseUrl(), NODE2_URL);
    assertEquals(clusterState.getCollection("collection2").getReplica("replica4").getBaseUrl(), NODE2_URL);
    assertEquals(clusterState.getCollection("collection3").getReplica("replica5").getBaseUrl(), NODE1_URL);
    assertEquals(clusterState.getCollection("collection3").getReplica("replica6").getBaseUrl(), NODE2_URL);
    assertEquals(clusterState.getCollection("collection3").getReplica("replica7").getBaseUrl(), NODE3_URL);
    writes = nm.downNode(clusterState, props);
    assertEquals(writes.size(), 2);
    for (ZkWriteCommand write : writes) {
        if (write.name.equals("collection1")) {
            assertEquals(write.collection.getReplica("replica1").getState(), Replica.State.DOWN);
            assertEquals(write.collection.getReplica("replica2").getState(), Replica.State.ACTIVE);
        } else if (write.name.equals("collection3")) {
            assertEquals(write.collection.getReplica("replica5").getState(), Replica.State.DOWN);
            assertEquals(write.collection.getReplica("replica6").getState(), Replica.State.ACTIVE);
            assertEquals(write.collection.getReplica("replica7").getState(), Replica.State.ACTIVE);
        } else {
            fail("No other collection needs to be changed");
        }
    }
    reader.close();
}

@Test
public void testRoleIntegration() throws Exception {
    JettySolrRunner j0 = cluster.getJettySolrRunner(0);
    testSupportedRolesAPI();
    // Start a dedicated overseer node
    JettySolrRunner j1 = startNodeWithRoles("overseer:preferred,data:off");
    validateNodeRoles(j1.getNodeName(), "node-roles/overseer/preferred", j1.getNodeName(), "node-roles/data/off");
    V2Response rsp;
    OverseerRolesTest.waitForNewOverseer(20, j1.getNodeName(), true);
    // Start another node that is allowed or preferred overseer but has data
    String overseerModeOnDataNode = random().nextBoolean() ? "preferred" : "allowed";
    JettySolrRunner j2 = startNodeWithRoles("overseer:" + overseerModeOnDataNode + ",data:on");
    validateNodeRoles(j2.getNodeName(), "node-roles/overseer/" + overseerModeOnDataNode, j2.getNodeName(), "node-roles/data/on");
    // validate the preferred overseers
    validateNodeRoles(j2.getNodeName(), "node-roles/overseer/" + overseerModeOnDataNode, j1.getNodeName(), "node-roles/overseer/preferred");
    String COLLECTION_NAME = "TEST_ROLES";
    CollectionAdminRequest.createCollection(COLLECTION_NAME, "conf", 3, 1).process(cluster.getSolrClient());
    cluster.waitForActiveCollection(COLLECTION_NAME, 3, 3);
    // Assert that no replica was placed on the dedicated overseer node
    String dedicatedOverseer = j1.getNodeName();
    cluster.getSolrClient().getClusterStateProvider().getCollection(COLLECTION_NAME).forEachReplica((s, replica) -> assertNotEquals(replica.node, dedicatedOverseer));
    // Shutdown the dedicated overseer, make sure that node disappears from the roles output
    j1.stop();
    // Wait and make sure that another node picks up overseer responsibilities
    OverseerRolesTest.waitForNewOverseer(20, it -> !dedicatedOverseer.equals(it), false);
    // Make sure the stopped node no longer has the role assigned
    rsp = new V2Request.Builder("/cluster/node-roles/role/overseer/" + overseerModeOnDataNode).GET().build().process(cluster.getSolrClient());
    assertFalse(((Collection) rsp._get("node-roles/overseer/" + overseerModeOnDataNode, null)).contains(j1.getNodeName()));
}

