            while (!timeout.hasTimedOut()) {
                try {
                    mockController.publishState(COLLECTION, "core1", "node1", "shard1", Replica.State.RECOVERING, 1, true, getOpenOverseer());
                    break;
                } catch (SolrException | IllegalStateException e) {
                    log.error("error publishing state", e);
                }
            }
            mockController2 = new MockZKController(server.getZkAddress(), "node2:8984_", overseers);
            timeout = new TimeOut(10, TimeUnit.SECONDS, TimeSource.NANO_TIME);
            while (!timeout.hasTimedOut()) {
                try {
                    mockController.publishState(COLLECTION, "core1", "node1", "shard1", Replica.State.ACTIVE, 1, true, getOpenOverseer());
                    break;
                } catch (SolrException | IllegalStateException e) {
                    log.error("error publishing state", e);
                }
            }
            verifyShardLeader(reader, COLLECTION, "shard1", "core1");
            timeout = new TimeOut(10, TimeUnit.SECONDS, TimeSource.NANO_TIME);
            while (!timeout.hasTimedOut()) {
                try {
                    mockController2.publishState(COLLECTION, "core4", "node2", "shard1", Replica.State.ACTIVE, 1, true, getOpenOverseer());
                    break;
                } catch (SolrException | IllegalStateException e) {
                    log.error("error publishing state", e);
                }
            }
            mockController.close();
            mockController = null;
            ZkController zkController = createMockZkController(server.getZkAddress(), null, reader);
            zkControllers.add(zkController);
            TimeOut timeOut = new TimeOut(10, TimeUnit.SECONDS, TimeSource.NANO_TIME);
            timeOut.waitFor("Timed out waiting to see core4 as leader", () -> {
                ZkCoreNodeProps leaderProps;
                try {
                    leaderProps = zkController.getLeaderProps(COLLECTION, "shard1", 1000, false);
                } catch (SolrException e) {
                    return false;
                } catch (InterruptedException e) {
                    throw new RuntimeException(e);
                } catch (SessionExpiredException e) {
                    return false;
                }
                if (leaderProps.getCoreName().equals("core4")) {
                    return true;
                }
                return false;
            });
        }
    } finally {
        if (killer != null) {
            killer.run = false;
            if (killerThread != null) {
                killerThread.join();
            }
        }
        close(mockController);
        close(mockController2);
        close(reader);
    }
}

