    // ok, now introduce a network partition between the leader and the replica
    SocketProxy proxy = getProxyForReplica(notLeader);
    proxy.close();
    // add more than ULOG_NUM_RECORDS_TO_KEEP docs so that peer sync cannot be used for recovery
    int MAX_DOCS = 2 + MAX_BUFFERED_DOCS + ULOG_NUM_RECORDS_TO_KEEP;
    for (; i < MAX_DOCS; i++) {
        SolrInputDocument document = new SolrInputDocument();
        document.addField("id", String.valueOf(i));
        document.addField("a_t", "text_" + i);
        cloudClient.add(document);
    }
    // Have the partition last at least 1 sec
    // While this gives the impression that recovery is timing related, this is
    // really only
    // to give time for the state to be written to ZK before the test completes.
    // In other words,
    // without a brief pause, the test finishes so quickly that it doesn't give
    // time for the recovery process to kick-in
    Thread.sleep(2000L);
    proxy.reopen();
    List<Replica> notLeaders = ensureAllReplicasAreActive(DEFAULT_COLLECTION, "shard1", 1, 2, 30);
}

@Test
public void stressTestRecovery() throws Exception {
    final String collection = "recoveryStressTest";
    CollectionAdminRequest.createCollection(collection, "conf", 1, 4).process(cluster.getSolrClient());
    waitForState("Expected a collection with one shard and two replicas", collection, clusterShape(1, 4));
    final var scheduledExecutorService = Executors.newScheduledThreadPool(1, new SolrNamedThreadFactory("stressTestRecovery"));
    try (SolrClient solrClient = cluster.basicSolrClientBuilder().withDefaultCollection(collection).build()) {
        final StoppableIndexingThread indexThread = new StoppableIndexingThread(null, solrClient, "1", true, 10, 1, true);
        final var startAndStopCount = new CountDownLatch(50);
        final Thread startAndStopRandomReplicas = new Thread(() -> {
            try {
                while (startAndStopCount.getCount() > 0) {
                    DocCollection state = getCollectionState(collection);
                    Replica leader = state.getLeader("shard1");
                    Replica replica = getRandomReplica(state.getSlice("shard1"), (r) -> !leader.equals(r));
                    JettySolrRunner jetty = cluster.getReplicaJetty(replica);
                    jetty.stop();
                    Thread.sleep(100);
                    jetty.start();
                    startAndStopCount.countDown();
                }
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
        startAndStopRandomReplicas.start();
        // index and commit doc after fixed interval of 10 sec
        scheduledExecutorService.scheduleWithFixedDelay(indexThread, 1000, 10000, TimeUnit.MILLISECONDS);
        scheduledExecutorService.scheduleWithFixedDelay(() -> {
            try {
                new UpdateRequest().commit(solrClient, collection);
            } catch (IOException e) {
                throw new RuntimeException(e);
            } catch (SolrServerException e) {
                throw new RuntimeException(e);
            }
        }, 100, 10000, TimeUnit.MILLISECONDS);
        startAndStopCount.await();
        scheduledExecutorService.shutdownNow();
        // final commit to make documents visible for replicas
        new UpdateRequest().commit(solrClient, collection);
    }
    cluster.getZkStateReader().waitForState(collection, 120, TimeUnit.SECONDS, clusterShape(1, 4));
    // test that leader and replica have same doc count
    DocCollection state = getCollectionState(collection);
    assertShardConsistency(state.getSlice("shard1"), true);
}

