public void test() throws Exception {
    CloudSolrClient solrClient = cluster.getSolrClient();
    for (int i = 0; i < 10; i++) {
        SolrInputDocument doc = new SolrInputDocument();
        doc.addField("id", String.valueOf(i));
        solrClient.add(COLLECTION_NAME, doc);
    }
    solrClient.commit(COLLECTION_NAME);
    // find the leader node
    Replica replica = cluster.getZkStateReader().getLeaderRetry(COLLECTION_NAME, "shard1");
    JettySolrRunner replicaJetty = null;
    List<JettySolrRunner> jettySolrRunners = cluster.getJettySolrRunners();
    for (JettySolrRunner jettySolrRunner : jettySolrRunners) {
        int port = jettySolrRunner.getBaseUrl().getPort();
        if (replica.getBaseUrl().contains(":" + port)) {
            replicaJetty = jettySolrRunner;
            break;
        }
    }
    // kill the leader
    replicaJetty.stop();
    // add a replica (asynchronously)
    CollectionAdminRequest.AddReplica addReplica = CollectionAdminRequest.addReplicaToShard(COLLECTION_NAME, "shard1");
    String asyncId = addReplica.processAsync(solrClient);
    // wait a bit
    Thread.sleep(1000);
    // bring the old leader node back up
    replicaJetty.start();
    // wait until everyone is active
    cluster.getZkStateReader().waitForState(COLLECTION_NAME, DEFAULT_TIMEOUT, TimeUnit.SECONDS, (n, c) -> DocCollection.isFullyActive(n, c, 1, 2));
    // now query each replica and check for consistency
    assertConsistentReplicas(solrClient, cluster.getSolrClient().getClusterState().getCollection(COLLECTION_NAME).getSlice("shard1"));
    // sanity check that documents still exist
    QueryResponse response = solrClient.query(COLLECTION_NAME, new SolrQuery("*:*"));
    assertEquals("Indexed documents not found", 10, response.getResults().getNumFound());
}

@Test
public void testLeaderElectionWithZkExpiry() throws Exception {
    Path zkDir = createTempDir("zkData");
    Path ccDir = createTempDir("testLeaderElectionWithZkExpiry-solr");
    final ZkTestServer server = new ZkTestServer(zkDir);
    server.setTheTickTime(1000);
    try {
        server.run();
        CloudConfig cloudConfig = new CloudConfig.CloudConfigBuilder("dummy.host.com", 8984).setLeaderConflictResolveWait(180000).setLeaderVoteWait(180000).build();
        CoreContainer cc = createCoreContainer(ccDir, SOLRXML);
        try {
            ExecutorService threadExecutor = ExecutorUtil.newMDCAwareSingleThreadExecutor(new SolrNamedThreadFactory(this.getTestName()));
            try (ZkController zkController = new ZkController(cc, server.getZkAddress(), 15000, cloudConfig)) {
                threadExecutor.execute(() -> {
                    TimeOut timeout = new TimeOut(10, TimeUnit.SECONDS, TimeSource.NANO_TIME);
                    while (!timeout.hasTimedOut()) {
                        long sessionId = zkController.getZkClient().getZkSessionId();
                        server.expire(sessionId);
                        try {
                            timeout.sleep(10);
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                            return;
                        }
                    }
                });
                try (SolrZkClient zc = new SolrZkClient.Builder().withUrl(server.getZkAddress()).withTimeout(LeaderElectionTest.TIMEOUT, TimeUnit.MILLISECONDS).build()) {
                    boolean found = false;
                    TimeOut timeout = new TimeOut(60, TimeUnit.SECONDS, TimeSource.NANO_TIME);
                    while (!timeout.hasTimedOut()) {
                        try {
                            String leaderNode = OverseerCollectionConfigSetProcessor.getLeaderNode(zc);
                            if (leaderNode != null && !leaderNode.trim().isEmpty()) {
                                if (log.isInfoEnabled()) {
                                    log.info("Time={} Overseer leader is = {}", System.nanoTime(), leaderNode);
                                }
                                found = true;
                                break;
                            }
                        } catch (KeeperException.NoNodeException nne) {
                            // ignore
                        }
                    }
                    assertTrue(found);
                }
            } finally {
                ExecutorUtil.shutdownNowAndAwaitTermination(threadExecutor);
            }
        } finally {
            cc.shutdown();
        }
    } finally {
        server.shutdown();
    }
}

