        UpdateRequest ureq = withBasicAuth(new UpdateRequest());
        ureq.add(new SolrInputDocument("id", String.valueOf(numDocs), "foo", "bar"));
        ureq.commit(solrClient, collectionName);
        Slice s = docCollection.getSlices().iterator().next();
        try (SolrClient leaderClient = getHttpSolrClient(s.getLeader())) {
            assertEquals(numDocs, queryWithBasicAuth(leaderClient, new SolrQuery("*:*")).getResults().getNumFound());
        }
        List<Replica> pullReplicas = s.getReplicas(EnumSet.of(Replica.Type.PULL));
        waitForNumDocsInAllReplicas(numDocs, pullReplicas, "*:*", SecurityJson.USER, SecurityJson.PASS);
        for (Replica r : pullReplicas) {
            try (SolrClient pullReplicaClient = getHttpSolrClient(r)) {
                QueryResponse statsResponse = queryWithBasicAuth(pullReplicaClient, new SolrQuery("qt", "/admin/plugins", "stats", "true"));
                // the 'adds' metric is a gauge, which is null for PULL replicas
                assertNull("Replicas shouldn't process the add document request: " + statsResponse, getUpdateHandlerMetric(statsResponse, "UPDATE.updateHandler.adds"));
                assertEquals("Replicas shouldn't process the add document request: " + statsResponse, 0L, getUpdateHandlerMetric(statsResponse, "UPDATE.updateHandler.cumulativeAdds.count"));
            }
        }
    }
    CollectionAdminResponse response = withBasicAuth(CollectionAdminRequest.reloadCollection(collectionName)).process(cluster.getSolrClient());
    assertEquals(0, response.getStatus());
    assertUlogPresence(docCollection);
    // add another pull replica to ensure it can pull the indexes
    Slice s = docCollection.getSlices().iterator().next();
    List<Replica> pullReplicas = s.getReplicas(EnumSet.of(Replica.Type.PULL));
    assertEquals(numPullReplicas, pullReplicas.size());
    response = withBasicAuth(CollectionAdminRequest.addReplicaToShard(collectionName, s.getName(), Replica.Type.PULL)).process(cluster.getSolrClient());
    assertEquals(0, response.getStatus());
    // added a PULL
    numPullReplicas = numPullReplicas + 1;
    waitForState("Expected collection to be created with 1 shard and " + (numPullReplicas + 1) + " replicas", collectionName, clusterShape(1, numPullReplicas + 1));
    docCollection = assertNumberOfReplicas(collectionName, 1, 0, numPullReplicas, false, true);
    s = docCollection.getSlices().iterator().next();
    pullReplicas = s.getReplicas(EnumSet.of(Replica.Type.PULL));
    assertEquals(numPullReplicas, pullReplicas.size());
    waitForNumDocsInAllReplicas(numDocs, pullReplicas, "*:*", SecurityJson.USER, SecurityJson.PASS);
    withBasicAuth(CollectionAdminRequest.deleteCollection(collectionName)).process(cluster.getSolrClient());
    waitForDeletion(collectionName);
}

/**
 * Assert that requests to "down collection", i.e. a collection which has all replicas in down
 * state (but are hosted on nodes that are live), fail fast and throw meaningful exceptions
 */
@Test
public void testQueryToDownCollectionShouldFailFast() throws Exception {
    CollectionAdminRequest.createCollection(COLLECTION_NAME, "conf", 2, 1).setBasicAuthCredentials(USERNAME, PASSWORD).process(cluster.getSolrClient());
    // Add some dummy documents
    UpdateRequest update = (UpdateRequest) new UpdateRequest().setBasicAuthCredentials(USERNAME, PASSWORD);
    for (int i = 0; i < 100; i++) {
        update.add("id", Integer.toString(i));
    }
    update.commit(cluster.getSolrClient(), COLLECTION_NAME);
    // Bring down replicas but keep nodes up. This could've been done by some combinations of
    // collections API operations; however to make it faster, altering cluster state directly!
    downAllReplicas();
    // assert all replicas are in down state
    List<Replica> replicas = getCollectionState(COLLECTION_NAME).getReplicas();
    for (Replica replica : replicas) {
        assertEquals(replica.getState(), Replica.State.DOWN);
    }
    // assert all nodes as active
    assertEquals(3, cluster.getSolrClient().getClusterStateProvider().getLiveNodes().size());
    SolrRequest<QueryResponse> req = new QueryRequest(new SolrQuery("*:*").setRows(0)).setBasicAuthCredentials(USERNAME, PASSWORD);
    try (SolrClient client = cluster.getJettySolrRunner(0).newClient()) {
        // Without the SOLR-13793 fix, this causes requests to "down collection" to pile up (until the
        // nodes run out of serviceable threads, and they crash, even for other collections hosted on
        // the
        // nodes).
        SolrException error = expectThrows(SolrException.class, "Request should fail after trying all replica nodes once", () -> client.request(req, COLLECTION_NAME));
        assertEquals(error.code(), SolrException.ErrorCode.INVALID_STATE.code);
        assertTrue(error.getMessage().contains("No active replicas found for collection: " + COLLECTION_NAME));
    }
    // run same set of tests on v2 client which uses V2HttpCall
    try (SolrClient v2Client = new Http2SolrClient.Builder(cluster.getJettySolrRunner(0).getBaseUrl().toString()).build()) {
        SolrException error = expectThrows(SolrException.class, "Request should fail after trying all replica nodes once", () -> v2Client.request(req, COLLECTION_NAME));
        assertEquals(error.code(), SolrException.ErrorCode.INVALID_STATE.code);
        assertTrue(error.getMessage().contains("No active replicas found for collection: " + COLLECTION_NAME));
    }
}

