@Override
public void test() throws Exception {
    super.test();
}

@Override
@AwaitsFix(bugUrl = "https://issues.apache.org/jira/browse/SOLR-13369")
@Test
public void test() throws Exception {
    boolean testFinished = false;
    try {
        handle.clear();
        handle.put("timestamp", SKIPVAL);
        // todo: do I have to do this here?
        waitForRecoveriesToFinish(true);
        // NOTE: we might randomly generate the same uniqueKey value multiple times,
        // (which is a valid test case, they should route to the same shard both times)
        // so we track each expectedId in a set for later sanity checking
        final Set<String> expectedUniqueKeys = new HashSet<>();
        for (int i = 0; i < NUM_ADDS; i++) {
            final int appId = r.nextInt(MAX_APP_ID) + 1;
            final int userId = r.nextInt(MAX_USER_ID) + 1;
            // skew the odds so half the time we have no mask, and half the time we
            // have an even distribution of 1-16 bits
            final int bitMask = Math.max(0, r.nextInt(32) - 15);
            String id = "app" + appId + (bitMask <= 0 ? "" : ("/" + bitMask)) + "!" + "user" + userId + "!" + "doc" + r.nextInt(MAX_DOC_ID);
            doAddDoc(id);
            expectedUniqueKeys.add(id);
        }
        commit();
        final Map<String, String> routePrefixMap = new HashMap<>();
        final Set<String> actualUniqueKeys = new HashSet<>();
        for (int i = 1; i <= sliceCount; i++) {
            final String shardId = "shard" + i;
            final Set<String> uniqueKeysInShard = fetchUniqueKeysFromShard(shardId);
            {
                // sanity check our uniqueKey values aren't duplicated across shards
                final Set<String> uniqueKeysOnDuplicateShards = new HashSet<>(uniqueKeysInShard);
                uniqueKeysOnDuplicateShards.retainAll(actualUniqueKeys);
                assertEquals(shardId + " contains some uniqueKeys that were already found on a previous shard", Collections.emptySet(), uniqueKeysOnDuplicateShards);
                actualUniqueKeys.addAll(uniqueKeysInShard);
            }
            // foreach uniqueKey, extract its route prefix and confirm those aren't spread across
            // multiple shards
            for (String uniqueKey : uniqueKeysInShard) {
                final String routePrefix = uniqueKey.substring(0, uniqueKey.lastIndexOf('!'));
                log.debug("shard( {} ) : uniqueKey( {} ) -> routePrefix( {} )", shardId, uniqueKey, routePrefix);
                assertNotNull("null prefix WTF? " + uniqueKey, routePrefix);
                final String otherShard = routePrefixMap.put(routePrefix, shardId);
                if (null != otherShard)
                    // if we already had a mapping, make sure it's an earlier doc from our current shard...
                    assertEquals("routePrefix " + routePrefix + " found in multiple shards", shardId, otherShard);
            }
        }
        assertEquals("Docs missing?", expectedUniqueKeys.size(), actualUniqueKeys.size());
        testFinished = true;
    } finally {
        if (!testFinished) {
            printLayoutOnTearDown = true;
        }
    }
}

@Test
public void testNodeNameUrlConversion() throws Exception {
    // nodeName from parts
    assertEquals("localhost:8888_solr", ZkController.generateNodeName("localhost", "8888"));
    // root context
    assertEquals("localhost:8888_solr", ZkController.generateNodeName("localhost", "8888"));
    // subdir
    assertEquals("foo-bar:77_solr", ZkController.generateNodeName("foo-bar", "77"));
    // setup a SolrZkClient to do some getBaseUrlForNodeName testing
    Path zkDir = createTempDir("zkData");
    ZkTestServer server = new ZkTestServer(zkDir);
    try {
        server.run();
        try (SolrZkClient client = new SolrZkClient.Builder().withUrl(server.getZkAddress()).withTimeout(TIMEOUT, TimeUnit.MILLISECONDS).build()) {
            ZkController.createClusterZkNodes(client);
            try (ZkStateReader zkStateReader = new ZkStateReader(client)) {
                zkStateReader.createClusterStateWatchersAndUpdate();
                assertEquals("http://zzz_xxx:1234/solr", zkStateReader.getBaseUrlForNodeName("zzz_xxx:1234_solr"));
                // test that no matter what you pass in, you end up with /solr.
                assertEquals("http://xxx:99/solr", zkStateReader.getBaseUrlForNodeName("xxx:99_"));
                // assertEquals("http://xxx:99/solr", result);
                assertEquals("http://foo-bar.baz.org:9999/solr", zkStateReader.getBaseUrlForNodeName("foo-bar.baz.org:9999_some_dir"));
                assertEquals("http://foo-bar.baz.org:9999/solr", zkStateReader.getBaseUrlForNodeName("foo-bar.baz.org:9999_solr%2Fsub_dir"));
                // generateNodeName + getBaseUrlForNodeName
                assertEquals("http://foo:9876/solr", zkStateReader.getBaseUrlForNodeName(ZkController.generateNodeName("foo", "9876")));
                assertEquals("http://foo.bar.com:9876/solr", zkStateReader.getBaseUrlForNodeName(ZkController.generateNodeName("foo.bar.com", "9876")));
                assertEquals("http://foo-bar:9876/solr", zkStateReader.getBaseUrlForNodeName(ZkController.generateNodeName("foo-bar", "9876")));
                assertEquals("http://foo-bar.com:80/solr", zkStateReader.getBaseUrlForNodeName(ZkController.generateNodeName("foo-bar.com", "80")));
            }
            ClusterProperties cp = new ClusterProperties(client);
            cp.setClusterProperty("urlScheme", "https");
            // Verify the URL Scheme is taken into account
            try (ZkStateReader zkStateReader = new ZkStateReader(client)) {
                zkStateReader.createClusterStateWatchersAndUpdate();
                assertEquals("https://zzz.xxx:1234/solr", zkStateReader.getBaseUrlForNodeName("zzz.xxx:1234_solr"));
                assertEquals("https://foo-bar.com:80/solr", zkStateReader.getBaseUrlForNodeName(ZkController.generateNodeName("foo-bar.com", "80")));
            }
        }
    } finally {
        server.shutdown();
    }
}

