@LogLevel(value = "org.apache.solr.cloud=DEBUG;org.apache.solr.cloud.overseer=DEBUG")
@Test
public void testPublishAndWaitForDownStates() throws Exception {
    /*
    This test asserts that if zkController.publishAndWaitForDownStates uses only core name to check if all local
    cores are down then the method will return immediately but if it uses coreNodeName (as it does after SOLR-6665 then
    the method will time out).
    We set up the cluster state in such a way that two replicas with same core name exist on non-existent nodes
    and core container also has a dummy core that has the same core name. The publishAndWaitForDownStates before SOLR-6665
    would only check the core names and therefore return immediately but after SOLR-6665 it should time out.
     */
    assumeWorkingMockito();
    final String collectionName = "testPublishAndWaitForDownStates";
    Path zkDir = createTempDir(collectionName);
    String nodeName = "127.0.0.1:8983_solr";
    try {
        cluster = configureCluster(1).configure();
        AtomicReference<ZkController> zkControllerRef = new AtomicReference<>();
        CoreContainer cc = new MockCoreContainer() {

            @Override
            public List<CoreDescriptor> getCoreDescriptors() {
                CoreDescriptor descriptor = new CoreDescriptor(collectionName, TEST_PATH(), Collections.emptyMap(), new Properties(), zkControllerRef.get());
                // non-existent coreNodeName, this will cause zkController.publishAndWaitForDownStates
                // to wait indefinitely when using coreNodeName but usage of core name alone will
                // return immediately
                descriptor.getCloudDescriptor().setCoreNodeName("core_node0");
                return Collections.singletonList(descriptor);
            }
        };
        ZkController zkController = null;
        try {
            CloudConfig cloudConfig = new CloudConfig.CloudConfigBuilder("127.0.0.1", 8983).setUseDistributedClusterStateUpdates(Boolean.getBoolean("solr.distributedClusterStateUpdates")).setUseDistributedCollectionConfigSetExecution(Boolean.getBoolean("solr.distributedCollectionConfigSetExecution")).build();
            zkController = new ZkController(cc, cluster.getZkServer().getZkAddress(), TIMEOUT, cloudConfig);
            zkControllerRef.set(zkController);
            zkController.getZkClient().makePath(DocCollection.getCollectionPathRoot(collectionName), new byte[0], CreateMode.PERSISTENT, true);
            ZkNodeProps m = new ZkNodeProps(Overseer.QUEUE_OPERATION, CollectionParams.CollectionAction.CREATE.toLower(), ZkStateReader.NODE_NAME_PROP, nodeName, ZkStateReader.NUM_SHARDS_PROP, "1", "name", collectionName);
            if (zkController.getDistributedClusterStateUpdater().isDistributedStateUpdate()) {
                zkController.getDistributedClusterStateUpdater().doSingleStateUpdate(DistributedClusterStateUpdater.MutatingCommand.ClusterCreateCollection, m, zkController.getSolrCloudManager(), zkController.getZkStateReader());
            } else {
                zkController.getOverseerJobQueue().offer(Utils.toJSON(m));
            }
            // Add an active replica that shares the same core name, but on a non existent host
            MapWriter propMap = ew -> ew.put(Overseer.QUEUE_OPERATION, ADDREPLICA.toLower()).put(COLLECTION_PROP, collectionName).put(SHARD_ID_PROP, "shard1").put(ZkStateReader.NODE_NAME_PROP, "non_existent_host:1_").put(ZkStateReader.CORE_NAME_PROP, collectionName).put(ZkStateReader.STATE_PROP, "active");
            if (zkController.getDistributedClusterStateUpdater().isDistributedStateUpdate()) {
                zkController.getDistributedClusterStateUpdater().doSingleStateUpdate(DistributedClusterStateUpdater.MutatingCommand.SliceAddReplica, new ZkNodeProps(propMap), zkController.getSolrCloudManager(), zkController.getZkStateReader());
            } else {
                zkController.getOverseerJobQueue().offer(propMap);
            }
            // Add an down replica that shares the same core name, also on a non existent host
            propMap = ew -> ew.put(Overseer.QUEUE_OPERATION, ADDREPLICA.toLower()).put(COLLECTION_PROP, collectionName).put(SHARD_ID_PROP, "shard1").put(ZkStateReader.NODE_NAME_PROP, "non_existent_host:2_").put(ZkStateReader.CORE_NAME_PROP, collectionName).put(ZkStateReader.STATE_PROP, "down");
            if (zkController.getDistributedClusterStateUpdater().isDistributedStateUpdate()) {
                zkController.getDistributedClusterStateUpdater().doSingleStateUpdate(DistributedClusterStateUpdater.MutatingCommand.SliceAddReplica, new ZkNodeProps(propMap), zkController.getSolrCloudManager(), zkController.getZkStateReader());
            } else {
                zkController.getOverseerJobQueue().offer(propMap);
            }
            // Add an active replica on the existing host. This replica will exist in the cluster state
            // but not
            // on the disk. We are testing that this replica is also put to "DOWN" even though it
            // doesn't exist locally.
            propMap = ew -> ew.put(Overseer.QUEUE_OPERATION, ADDREPLICA.toLower()).put(COLLECTION_PROP, collectionName).put(SHARD_ID_PROP, "shard1").put(ZkStateReader.NODE_NAME_PROP, nodeName).put(ZkStateReader.CORE_NAME_PROP, collectionName + "-not-on-disk").put(ZkStateReader.STATE_PROP, "active");
            if (zkController.getDistributedClusterStateUpdater().isDistributedStateUpdate()) {
                zkController.getDistributedClusterStateUpdater().doSingleStateUpdate(DistributedClusterStateUpdater.MutatingCommand.SliceAddReplica, new ZkNodeProps(propMap), zkController.getSolrCloudManager(), zkController.getZkStateReader());
            } else {
                zkController.getOverseerJobQueue().offer(propMap);
            }
            // Wait for the overseer to process all the replica additions
            if (!zkController.getDistributedClusterStateUpdater().isDistributedStateUpdate()) {
                zkController.getZkStateReader().waitForState(collectionName, 10, TimeUnit.SECONDS, collectionState -> Optional.ofNullable(collectionState).map(DocCollection::getReplicas).map(List::size).orElse(0) == 3);
            }
            Instant now = Instant.now();
            zkController.publishAndWaitForDownStates(5);
            assertThat("The ZkController.publishAndWaitForDownStates should not have timed out but it did", Duration.between(now, Instant.now()), Matchers.lessThanOrEqualTo(Duration.ofSeconds(5)));
            zkController.getZkStateReader().forciblyRefreshAllClusterStateSlow();
            ClusterState clusterState = zkController.getClusterState();
            Map<String, List<Replica>> replicasOnNode = clusterState.getReplicaNamesPerCollectionOnNode(nodeName);
            assertNotNull("There should be replicas on the existing node", replicasOnNode);
            List<Replica> replicas = replicasOnNode.get(collectionName);
            assertNotNull("There should be replicas for the collection on the existing node", replicas);
            assertEquals("Wrong number of replicas for the collection on the existing node", 1, replicas.size());
            for (Replica replica : replicas) {
                assertEquals("Replica " + replica.getName() + " is not DOWN, even though it is on the node that should be DOWN", Replica.State.DOWN, replica.getState());
            }
        } finally {
            if (zkController != null)
                zkController.close();
            cc.shutdown();
        }
    } finally {
        cluster.shutdown();
    }
}

@Test
public void testTouchConfDir() throws Exception {
    Path zkDir = createTempDir("zkData");
    ZkTestServer server = new ZkTestServer(zkDir);
    try {
        server.run();
        try (SolrZkClient zkClient = new SolrZkClient.Builder().withUrl(server.getZkAddress()).withTimeout(TIMEOUT, TimeUnit.MILLISECONDS).build()) {
            CoreContainer cc = getCoreContainer();
            try {
                CloudConfig cloudConfig = new CloudConfig.CloudConfigBuilder("127.0.0.1", 8983).build();
                try (ZkController zkController = new ZkController(cc, server.getZkAddress(), TIMEOUT, cloudConfig)) {
                    final Path dir = createTempDir();
                    final String configsetName = "testconfigset";
                    try (ZkSolrResourceLoader loader = new ZkSolrResourceLoader(dir, configsetName, null, zkController)) {
                        String zkpath = "/configs/" + configsetName;
                        // touchConfDir doesn't make the znode
                        Stat s = new Stat();
                        assertFalse(zkClient.exists(zkpath, true));
                        zkClient.makePath(zkpath, true);
                        assertTrue(zkClient.exists(zkpath, true));
                        assertNull(zkClient.getData(zkpath, null, s, true));
                        assertEquals(0, s.getVersion());
                        // touchConfDir should only set the data to new byte[] {0}
                        ZkController.touchConfDir(loader);
                        assertTrue(zkClient.exists(zkpath, true));
                        assertArrayEquals(ZkController.TOUCHED_ZNODE_DATA, zkClient.getData(zkpath, null, s, true));
                        assertEquals(1, s.getVersion());
                        // set new data to check if touchConfDir overwrites later
                        byte[] data = "{\"key\", \"new data\"".getBytes(StandardCharsets.UTF_8);
                        s = zkClient.setData(zkpath, data, true);
                        assertEquals(2, s.getVersion());
                        // make sure touchConfDir doesn't overwrite existing data.
                        // touchConfDir should update version.
                        assertTrue(zkClient.exists(zkpath, true));
                        ZkController.touchConfDir(loader);
                        assertTrue(zkClient.exists(zkpath, true));
                        assertArrayEquals(data, zkClient.getData(zkpath, null, s, true));
                        assertEquals(3, s.getVersion());
                    }
                }
            } finally {
                cc.shutdown();
            }
        }
    } finally {
        server.shutdown();
    }
}

