@Test
public void testRaceConditionOnUpdates() throws InterruptedException {
    String collection = "raceConditionOnUpdates";
    List<String> replicas = Arrays.asList("rep1", "rep2", "rep3", "rep4");
    for (String replica : replicas) {
        try (ZkShardTerms zkShardTerms = new ZkShardTerms(collection, "shard1", cluster.getZkClient())) {
            zkShardTerms.registerTerm(replica);
        }
    }
    List<String> failedReplicas = new ArrayList<>(replicas);
    Collections.shuffle(failedReplicas, random());
    while (failedReplicas.size() > 2) {
        failedReplicas.remove(0);
    }
    AtomicBoolean stop = new AtomicBoolean(false);
    Thread[] threads = new Thread[failedReplicas.size()];
    for (int i = 0; i < failedReplicas.size(); i++) {
        String replica = failedReplicas.get(i);
        threads[i] = new Thread(() -> {
            try (ZkShardTerms zkShardTerms = new ZkShardTerms(collection, "shard1", cluster.getZkClient())) {
                while (!stop.get()) {
                    try {
                        Thread.sleep(random().nextInt(200));
                        zkShardTerms.setTermEqualsToLeader(replica);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        log.error("interrupted", e);
                    }
                }
            }
        });
        threads[i].start();
    }
    long maxTerm = 0;
    try (ZkShardTerms shardTerms = new ZkShardTerms(collection, "shard1", cluster.getZkClient())) {
        shardTerms.registerTerm("leader");
        TimeOut timeOut = new TimeOut(10, TimeUnit.SECONDS, new TimeSource.CurrentTimeSource());
        while (!timeOut.hasTimedOut()) {
            maxTerm++;
            assertEquals(shardTerms.getTerms().get("leader"), Collections.max(shardTerms.getTerms().values()));
            Thread.sleep(100);
        }
        assertTrue(maxTerm >= Collections.max(shardTerms.getTerms().values()));
    }
    stop.set(true);
    for (Thread thread : threads) {
        thread.join();
    }
}

@Test
@SuppressWarnings({ "try" })
public void testMultipleWatchesAsync() throws Exception {
    try (ZkConnection conn = new ZkConnection()) {
        final SolrZkClient zkClient = conn.getClient();
        zkClient.makePath("/collections", true);
        final int numColls = random().nextInt(100);
        final CountDownLatch latch = new CountDownLatch(numColls);
        final CountDownLatch watchesDone = new CountDownLatch(numColls);
        final Set<String> collectionsInProgress = new HashSet<>(numColls);
        AtomicInteger maxCollectionsInProgress = new AtomicInteger();
        for (int i = 1; i <= numColls; i++) {
            String collPath = "/collections/collection" + i;
            zkClient.makePath(collPath, true);
            zkClient.getChildren(collPath, new Watcher() {

                @Override
                public void process(WatchedEvent event) {
                    synchronized (collectionsInProgress) {
                        collectionsInProgress.add(// Will be something like /collections/collection##
                        event.getPath());
                        maxCollectionsInProgress.set(Math.max(maxCollectionsInProgress.get(), collectionsInProgress.size()));
                    }
                    latch.countDown();
                    try {
                        latch.await(10000, TimeUnit.MILLISECONDS);
                    } catch (InterruptedException e) {
                    }
                    synchronized (collectionsInProgress) {
                        collectionsInProgress.remove(event.getPath());
                    }
                    watchesDone.countDown();
                }
            }, true);
        }
        for (int i = 1; i <= numColls; i++) {
            String shardsPath = "/collections/collection" + i + "/shards";
            zkClient.makePath(shardsPath, true);
        }
        assertTrue(latch.await(10000, TimeUnit.MILLISECONDS));
        assertEquals("All collections should have been processed in parallel", numColls, maxCollectionsInProgress.get());
        // just as sanity check for the test:
        assertTrue(watchesDone.await(10000, TimeUnit.MILLISECONDS));
        synchronized (collectionsInProgress) {
            assertEquals(0, collectionsInProgress.size());
        }
    }
}

