        waitForState("Expected shard " + sliceName + " to be in state " + Slice.State.INACTIVE, collectionName, c -> c.getSlice(sliceName).getState() == Slice.State.INACTIVE);
        final long ttlStart = timeSource.getTimeNs();
        waitForState("Waiting for InactiveShardRemover to delete inactive shard", collectionName, ttlSeconds + 5, TimeUnit.SECONDS, clusterShape(0, 0));
        final long ttlEnd = timeSource.getTimeNs();
        final long ttlPeriodSeconds = TimeUnit.NANOSECONDS.toSeconds(ttlEnd - ttlStart);
        assertTrue(ttlPeriodSeconds >= ttlSeconds);
    } finally {
        removePlugin();
    }
}

