    attributeFetcher.fetchFrom(cluster.getLiveNodes()).requestNodeMetric(NodeMetricImpl.HEAP_USAGE).requestNodeMetric(NodeMetricImpl.SYSLOAD_AVG).requestNodeMetric(NodeMetricImpl.NUM_CORES).requestNodeMetric(NodeMetricImpl.FREE_DISK_GB).requestNodeMetric(NodeMetricImpl.TOTAL_DISK_GB).requestNodeMetric(NodeMetricImpl.AVAILABLE_PROCESSORS).requestNodeMetric(someMetricKey).requestNodeSystemProperty(sysprop).requestCollectionMetrics(collection, Set.of(ReplicaMetricImpl.INDEX_SIZE_GB, ReplicaMetricImpl.QUERY_RATE_1MIN, ReplicaMetricImpl.UPDATE_RATE_1MIN));
    AttributeValues attributeValues = attributeFetcher.fetchAttributes();
    String userName = System.getProperty("user.name");
