            assertEquals("number of groups", 1, groupCounts.size());
            groupCounts.forEach((group, count) -> {
                assertTrue("too few replicas shard=" + shard + ", type=" + type + ", group=" + group, count.get() >= 1);
            });
        });
    });
}

