 * replica per shard to be placed on any node.
 */
@Test
public void testMultiplePlacementsWithExistingReplicas() throws Exception {
    String collectionName = "existingCollection";
    // Cluster nodes and their attributes
    Builders.ClusterBuilder clusterBuilder = Builders.newClusterBuilder().initializeLiveNodes(3);
    // The collection already exists with shards and replicas
    Builders.CollectionBuilder collectionBuilder = Builders.newCollectionBuilder(collectionName);
    // Note that the collection as defined below is in a state that would NOT be returned by the
    // placement plugin: shard 1 has two replicas on node 0. The plugin should still be able to
    // place additional replicas as long as they don't break the rules.
    List<List<String>> shardsReplicas = List.of(// shard 1
    List.of("NRT 0"), // shard 2
    List.of("NRT 1"), // shard 3
    List.of("NRT 2"));
    collectionBuilder.customCollectionSetup(shardsReplicas, clusterBuilder.getLiveNodeBuilders());
    clusterBuilder.addCollection(collectionBuilder);
    SolrCollection solrCollection = collectionBuilder.build();
    List<Node> liveNodes = clusterBuilder.buildLiveNodes();
    // Place an additional NRT and an additional TLOG replica for each shard
    PlacementRequestImpl placementRequest = new PlacementRequestImpl(solrCollection, solrCollection.getShardNames(), new HashSet<>(liveNodes), ReplicaCount.of(1, 0, 0));
    List<PlacementRequest> placementRequests = solrCollection.getShardNames().stream().map(shard -> new PlacementRequestImpl(solrCollection, Collections.singleton(shard), new HashSet<>(liveNodes), ReplicaCount.of(1, 0, 0))).collect(Collectors.toList());
    // Randomize the order of the requests
    Collections.shuffle(placementRequests, random());
    // The replicas must be placed on the most appropriate nodes, i.e. those that do not already
    // have a replica for the shard and then on the node with the lowest number of cores. NRT are
    // placed first and given the cluster state here the placement is deterministic (easier to test,
    // only one good placement).
    List<PlacementPlan> pps = plugin.computePlacements(placementRequests, clusterBuilder.buildPlacementContext());
    List<ReplicaPlacement> replicaPlacements = pps.stream().flatMap(pp -> pp.getReplicaPlacements().stream()).collect(Collectors.toList());
    replicaPlacements.forEach(rp -> assertNotEquals("Two replicas of the same shard on the same node", solrCollection.getShard(rp.getShardName()).iterator().next().getNode(), rp.getNode()));
    Map<Node, List<ReplicaPlacement>> placementsByNode = replicaPlacements.stream().collect(Collectors.groupingBy(ReplicaPlacement::getNode, Collectors.toList()));
    for (Map.Entry<Node, List<ReplicaPlacement>> entry : placementsByNode.entrySet()) {
        assertEquals(String.format(Locale.ROOT, "Node %s has multiple replicas placed on it, when each node should have 1 placement: [%s]", entry.getKey().getName(), entry.getValue().stream().map(ReplicaPlacement::getShardName).collect(Collectors.joining(", "))), 1, entry.getValue().size());
    }
}

