@Test
public void testAsyncTracking() throws InterruptedException, ExecutionException {
    ExecutorService es = ExecutorUtil.newMDCAwareSingleThreadExecutor(new SolrNamedThreadFactory("TestExec"));
    Object trackable = new Object();
    Future<?> result = es.submit(() -> {
        ObjectReleaseTracker.track(trackable);
    });
    // make sure that track has been called
    result.get();
    String message = ObjectReleaseTracker.clearObjectTrackerAndCheckEmpty();
    assertThat(message, stringContainsInOrder(ObjectReleaseTracker.ObjectTrackerException.class.getName(), "Exception: Submitter stack trace", getClassName() + "." + getTestName()));
    // Test the grandparent submitter case
    AtomicReference<Future<?>> indirectResult = new AtomicReference<>();
    result = es.submit(() -> indirectResult.set(es.submit(() -> {
        ObjectReleaseTracker.track(trackable);
    })));
    result.get();
    indirectResult.get().get();
    message = ObjectReleaseTracker.clearObjectTrackerAndCheckEmpty();
    assertThat(message, stringContainsInOrder(ObjectReleaseTracker.ObjectTrackerException.class.getName(), "Exception: Submitter stack trace", "Exception: Submitter stack trace", getClassName() + "." + getTestName()));
    // Now test great-grandparent, which we don't explicitly account for, but should have been
    // recursively set
    AtomicReference<Future<?>> indirectIndirect = new AtomicReference<>();
    result = es.submit(() -> indirectResult.set(es.submit(() -> indirectIndirect.set(es.submit(() -> {
        ObjectReleaseTracker.track(trackable);
    })))));
    result.get();
    indirectResult.get().get();
    indirectIndirect.get().get();
    message = ObjectReleaseTracker.clearObjectTrackerAndCheckEmpty();
    assertThat(message, stringContainsInOrder(ObjectReleaseTracker.ObjectTrackerException.class.getName(), "Exception: Submitter stack trace", "Exception: Submitter stack trace", "Exception: Submitter stack trace", getClassName() + "." + getTestName()));
    es.shutdown();
    assertTrue(es.awaitTermination(1, TimeUnit.SECONDS));
}

