@Test
public void testCoreAdminHandler() throws Exception {
    final Path workDir = createTempDir();
    final CoreContainer cores = h.getCoreContainer();
    cores.getAllowPaths().add(workDir);
    final CoreAdminHandler admin = new CoreAdminHandler(cores);
    Path instDir;
    try (SolrCore template = cores.getCore("collection1")) {
        assertNotNull(template);
        instDir = template.getCoreDescriptor().getInstanceDir();
    }
    assertTrue("instDir doesn't exist: " + instDir, Files.exists(instDir));
    final Path instProp = workDir.resolve("instProp");
    PathUtils.copyDirectory(instDir, instProp);
    SolrQueryResponse resp = new SolrQueryResponse();
    // Sneaking in a test for using a bad core name
    SolrException se = expectThrows(SolrException.class, () -> {
        admin.handleRequestBody(req(CoreAdminParams.ACTION, CoreAdminParams.CoreAdminAction.CREATE.toString(), CoreAdminParams.INSTANCE_DIR, instProp.toAbsolutePath().toString(), CoreAdminParams.NAME, "ugly$core=name"), new SolrQueryResponse());
    });
    assertTrue("Expected error message for bad core name.", se.toString().contains("Invalid core"));
    CoreDescriptor cd = cores.getCoreDescriptor("ugly$core=name");
    assertNull("Should NOT have added this core!", cd);
    // create a new core (using CoreAdminHandler) w/ properties
    admin.handleRequestBody(req(CoreAdminParams.ACTION, CoreAdminParams.CoreAdminAction.CREATE.toString(), CoreAdminParams.INSTANCE_DIR, instProp.toAbsolutePath().toString(), CoreAdminParams.NAME, "props", CoreAdminParams.PROPERTY_PREFIX + "hoss", "man", CoreAdminParams.PROPERTY_PREFIX + "foo", "baz"), resp);
    assertNull("Exception on create", resp.getException());
    cd = cores.getCoreDescriptor("props");
    assertNotNull("Core not added!", cd);
    assertEquals(cd.getCoreProperty("hoss", null), "man");
    assertEquals(cd.getCoreProperty("foo", null), "baz");
    // attempt to create a bogus core and confirm failure
    ignoreException("Could not load config");
    se = expectThrows(SolrException.class, () -> {
        admin.handleRequestBody(req(CoreAdminParams.ACTION, CoreAdminParams.CoreAdminAction.CREATE.toString(), CoreAdminParams.NAME, "bogus_dir_core", CoreAdminParams.INSTANCE_DIR, "dir_does_not_exist_127896"), new SolrQueryResponse());
    });
    // :NOOP:
    // :TODO: CoreAdminHandler's exception messages are terrible, otherwise we could assert
    // something useful here
    unIgnoreException("Could not load config");
    // check specifically for status of the failed core name
    resp = new SolrQueryResponse();
    admin.handleRequestBody(req(CoreAdminParams.ACTION, CoreAdminParams.CoreAdminAction.STATUS.toString(), CoreAdminParams.CORE, "bogus_dir_core"), resp);
    @SuppressWarnings("unchecked")
    Map<String, Exception> failures = (Map<String, Exception>) resp.getValues().get("initFailures");
    assertNotNull("core failures is null", failures);
    final var statusByCore = JacksonContentWriter.DEFAULT_MAPPER.convertValue(resp.getValues().get("status"), new TypeReference<Map<String, CoreStatusResponse.SingleCoreData>>() {
    });
    assertNotNull("core status is null", statusByCore);
    assertEquals("wrong number of core failures", 1, failures.size());
    Exception fail = failures.get("bogus_dir_core");
    assertNotNull("null failure for test core", fail);
    assertTrue("init failure doesn't mention problem: " + fail.getCause().getMessage(), 0 < fail.getCause().getMessage().indexOf("dir_does_not_exist"));
    assertTrue("bogus_dir_core status isn't empty", statusByCore.containsKey("bogus_dir_core"));
    final var bogusDirCoreStatus = statusByCore.get("bogus_dir_core");
    assertNull(bogusDirCoreStatus.name);
    assertNull(bogusDirCoreStatus.config);
    // Try renaming the core, we should fail
    // First assert that the props core exists
    cd = cores.getCoreDescriptor("props");
    assertNotNull("Core disappeared!", cd);
    // now rename it something else just for kicks since we don't actually test this that I could
    // find.
    admin.handleRequestBody(req(CoreAdminParams.ACTION, CoreAdminParams.CoreAdminAction.RENAME.toString(), CoreAdminParams.CORE, "props", CoreAdminParams.OTHER, "rename_me"), resp);
    cd = cores.getCoreDescriptor("rename_me");
    assertNotNull("Core should have been renamed!", cd);
    // Rename it something bogus and see if you get an exception, the old core is still there and
    // the bogus one isn't
    se = expectThrows(SolrException.class, () -> {
        admin.handleRequestBody(req(CoreAdminParams.ACTION, CoreAdminParams.CoreAdminAction.RENAME.toString(), CoreAdminParams.CORE, "rename_me", CoreAdminParams.OTHER, "bad$name"), new SolrQueryResponse());
    });
    assertTrue("Expected error message for bad core name.", se.getMessage().contains("Invalid core"));
    cd = cores.getCoreDescriptor("bad$name");
    assertNull("Core should NOT exist!", cd);
    cd = cores.getCoreDescriptor("rename_me");
    assertNotNull("Core should have been renamed!", cd);
    // :TODO: because of SOLR-3665 we can't ask for status from all cores
    admin.close();
}

@Test
public void testDeleteInstanceDir() throws Exception {
    Path solrHomeDirectory = createTempDir("solr-home");
    copySolrHomeToTemp(solrHomeDirectory, "corex");
    Path corex = solrHomeDirectory.resolve("corex");
    Files.writeString(corex.resolve("core.properties"), "", StandardCharsets.UTF_8);
    copySolrHomeToTemp(solrHomeDirectory, "corerename");
    Path coreRename = solrHomeDirectory.resolve("corerename");
    Path renamePropFile = coreRename.resolve("core.properties");
    Files.writeString(renamePropFile, "", StandardCharsets.UTF_8);
    JettySolrRunner runner = new JettySolrRunner(solrHomeDirectory.toAbsolutePath().toString(), JettyConfig.builder().build());
    runner.start();
    try (SolrClient client = new HttpSolrClient.Builder(runner.getBaseUrl().toString()).withDefaultCollection("corex").withConnectionTimeout(DEFAULT_CONNECTION_TIMEOUT, TimeUnit.MILLISECONDS).withSocketTimeout(DEFAULT_CONNECTION_TIMEOUT, TimeUnit.MILLISECONDS).build()) {
        SolrInputDocument doc = new SolrInputDocument();
        doc.addField("id", "123");
        client.add(doc);
        client.commit();
    }
    try (SolrClient client = new HttpSolrClient.Builder(runner.getBaseUrl().toString()).withConnectionTimeout(DEFAULT_CONNECTION_TIMEOUT, TimeUnit.MILLISECONDS).withSocketTimeout(DEFAULT_CONNECTION_TIMEOUT, TimeUnit.MILLISECONDS).build()) {
        CoreAdminRequest.Unload req = new CoreAdminRequest.Unload(false);
        req.setDeleteInstanceDir(true);
        req.setCoreName("corex");
        req.process(client);
    }
    // Make sure a renamed core
    // 1> has the property persisted (SOLR-11783)
    // 2> is deleted after rename properly.
    try (SolrClient client = new HttpSolrClient.Builder(runner.getBaseUrl().toString()).withConnectionTimeout(DEFAULT_CONNECTION_TIMEOUT, TimeUnit.MILLISECONDS).withSocketTimeout(DEFAULT_CONNECTION_TIMEOUT, TimeUnit.MILLISECONDS).build()) {
        CoreAdminRequest.renameCore("corerename", "brand_new_core_name", client);
        Properties props = new Properties();
        try (Reader is = Files.newBufferedReader(renamePropFile, StandardCharsets.UTF_8)) {
            props.load(is);
        }
        assertEquals("Name should have been persisted!", "brand_new_core_name", props.getProperty("name"));
    }
    try (SolrClient client = new HttpSolrClient.Builder(runner.getBaseUrl().toString()).withConnectionTimeout(DEFAULT_CONNECTION_TIMEOUT, TimeUnit.MILLISECONDS).withSocketTimeout(DEFAULT_CONNECTION_TIMEOUT, TimeUnit.MILLISECONDS).build()) {
        CoreAdminRequest.Unload req = new CoreAdminRequest.Unload(false);
        req.setDeleteInstanceDir(true);
        req.setCoreName("brand_new_core_name");
        req.process(client);
    }
    runner.stop();
    assertFalse("Instance directory exists after core unload with deleteInstanceDir=true : " + corex, Files.exists(corex));
    assertFalse("Instance directory exists after core unload with deleteInstanceDir=true : " + coreRename, Files.exists(coreRename));
}

