@Test
public void testAPIs() throws IOException, SolrServerException, InterruptedException {
    // test no daemon defined
    checkCmdsNoDaemon(daemonOfInterest);
    // Now create all our daemons.
    for (String name : daemonNames) {
        createDaemon(DAEMON_DEF.replace("DAEMON_NAME", name), name);
    }
    List<Tuple> tuples = getTuples(params("qt", "/stream", "action", "list"));
    assertEquals("Should have all daemons listed", numDaemons, tuples.size());
    for (int idx = 0; idx < numDaemons; ++idx) {
        assertEquals("Daemon should be running ", tuples.get(idx).getString("id"), daemonNames.get(idx));
    }
    // Are all the daemons in a good state?
    for (String daemon : daemonNames) {
        checkAlive(daemon);
    }
    // We shouldn't be able to open a daemon twice without closing., leads to thread leeks.
    Tuple tupleOfInterest = getTupleOfInterest(params("qt", "/stream", "action", "start", "id", daemonOfInterest), DAEMON_OP);
    assertTrue("Should not open twice without closing", tupleOfInterest.getString(DAEMON_OP).contains("There is already an open daemon named"));
    // Try stopping and check return.
    tupleOfInterest = getTupleOfInterest(params("qt", "/stream", "action", "stop", "id", daemonOfInterest), DAEMON_OP);
    assertTrue("Should have been able to stop the daemon", tupleOfInterest.getString(DAEMON_OP).contains(daemonOfInterest + " stopped"));
    checkStopped();
    // Are all the daemons alive? NOTE: a stopped daemon is still there, but in a TERMINATED state
    for (String daemon : daemonNames) {
        if (daemon.equals(daemonOfInterest) == false) {
            checkAlive(daemon);
        }
    }
    // Try starting and check return.
    tupleOfInterest = getTupleOfInterest(params("qt", "/stream", "action", "start", "id", daemonOfInterest), DAEMON_OP);
    assertTrue("Should have been able to start the daemon", tupleOfInterest.getString(DAEMON_OP).contains(daemonOfInterest + " started"));
    // Are all the daemons alive?
    for (String daemon : daemonNames) {
        checkAlive(daemon);
    }
    // Try killing a daemon, it should be removed from lists.
    tupleOfInterest = getTupleOfInterest(params("qt", "/stream", "action", "kill", "id", daemonOfInterest), DAEMON_OP);
    assertTrue("Daemon should have been killed", tupleOfInterest.getString(DAEMON_OP).contains(daemonOfInterest + " killed"));
    // Loop for a bit, waiting for the daemon to be removed from the list of possible entries.
    checkDaemonKilled(daemonOfInterest);
    // Should not be able to start a killed daemon
    tupleOfInterest = getTupleOfInterest(params("qt", "/stream", "action", "start", "id", daemonOfInterest), DAEMON_OP);
    assertTrue("Daemon should not be found", tupleOfInterest.getString(DAEMON_OP).contains(daemonOfInterest + " not found"));
    // Should not be able to sop a killed daemon
    tupleOfInterest = getTupleOfInterest(params("qt", "/stream", "action", "stop", "id", daemonOfInterest), DAEMON_OP);
    assertTrue("Daemon should not be found", tupleOfInterest.getString(DAEMON_OP).contains(daemonOfInterest + " not found"));
    // Should not be able to kill a killed daemon
    tupleOfInterest = getTupleOfInterest(params("qt", "/stream", "action", "kill", "id", daemonOfInterest), DAEMON_OP);
    assertTrue("Daemon should not be found", tupleOfInterest.getString(DAEMON_OP).contains(daemonOfInterest + " not found"));
    // Let's bring the killed daemon back and see if it returns in our lists. Use the method that
    // loops a bit to check in case there's a delay.
    createDaemon(DAEMON_DEF.replace("DAEMON_NAME", daemonOfInterest), daemonOfInterest);
    checkAlive(daemonOfInterest);
    // Now kill them all so the threads disappear.
    for (String daemon : daemonNames) {
        getTuples(params("qt", "/stream", "action", "kill", "id", daemon));
        checkDaemonKilled(daemon);
    }
}

@Test
public void testHealthCheckHandler() throws Exception {
    // positive check that our only existing "healthy" node works with cloud client
    // NOTE: this is using GenericSolrRequest, not HealthCheckRequest which is why it passes
    // as compared with testHealthCheckHandlerWithCloudClient
    // (Not sure if that's actually a good thing -- but it's how the existing test worked)
    final var genericHealthcheck = new GenericSolrRequest(SolrRequest.METHOD.GET, HEALTH_CHECK_HANDLER_PATH, SolrRequest.SolrRequestType.ADMIN);
    assertEquals(CommonParams.OK, genericHealthcheck.process(cluster.getSolrClient()).getResponse().get(CommonParams.STATUS));
    // positive check that our exiting "healthy" node works with direct http client
    try (SolrClient solrClient = getHttpSolrClient(cluster.getJettySolrRunner(0).getBaseUrl().toString())) {
        assertEquals(CommonParams.OK, runHealthcheckWithClient(solrClient).getNodeStatus());
    }
    // successfully create a dummy collection
    try (SolrClient solrClient = getHttpSolrClient(cluster.getJettySolrRunner(0).getBaseUrl().toString())) {
        CollectionAdminResponse collectionAdminResponse = CollectionAdminRequest.createCollection("test", "_default", 1, 1).withProperty("solr.directoryFactory", "solr.StandardDirectoryFactory").process(solrClient);
        assertEquals(0, collectionAdminResponse.getStatus());
        assertEquals(CommonParams.OK, runHealthcheckWithClient(solrClient).getNodeStatus());
    } finally {
        cluster.deleteAllCollections();
        cluster.deleteAllConfigSets();
    }
    // add a new node for the purpose of negative testing
    JettySolrRunner newJetty = cluster.startJettySolrRunner();
    try (SolrClient solrClient = getHttpSolrClient(newJetty.getBaseUrl().toString())) {
        // positive check that our (new) "healthy" node works with direct http client
        final var response = runHealthcheckWithClient(solrClient);
        assertEquals(CommonParams.OK, response.getNodeStatus());
        // now "break" our (new) node
        newJetty.getCoreContainer().getZkController().getZkClient().close();
        // negative check of our (new) "broken" node that we deliberately put into an unhealthy state
        SolrClient.RemoteSolrException e = expectThrows(SolrClient.RemoteSolrException.class, () -> {
            runHealthcheckWithClient(solrClient);
        });
        assertTrue(e.getMessage(), e.getMessage().contains("Host Unavailable"));
        assertEquals(SolrException.ErrorCode.SERVICE_UNAVAILABLE.code, e.code());
    } finally {
        newJetty.stop();
    }
    // (redundant) positive check that our (previously) exiting "healthy" node (still) works
    // after getting negative results from our broken node and failed core container
    try (SolrClient solrClient = getHttpSolrClient(cluster.getJettySolrRunner(0).getBaseUrl().toString())) {
        assertEquals(CommonParams.OK, runHealthcheckWithClient(solrClient).getNodeStatus());
    }
}

