    // let's query by specifying multiple mlt.fl as comma-separated values
    QueryResponse response = query("q", "lowerfilt:moon", "fl", id, MoreLikeThisParams.MIN_TERM_FREQ, 2, MoreLikeThisParams.MIN_DOC_FREQ, 1, "sort", "id_i1 desc", "mlt", "true", "mlt.fl", "lowerfilt1,lowerfilt", "qt", requestHandlerName, "shards.qt", requestHandlerName, "mlt.count", "20");
    NamedList<Object> moreLikeThis = (NamedList<Object>) response.getResponse().get("moreLikeThis");
    Map<String, Long> idVsMLTCount = new HashMap<>();
    for (Map.Entry<String, Object> entry : moreLikeThis) {
        SolrDocumentList docList = (SolrDocumentList) entry.getValue();
        idVsMLTCount.put(entry.getKey(), docList.getNumFound());
    }
    // let's query by specifying multiple mlt.fl as multiple request parameters
    response = query("q", "lowerfilt:moon", "fl", id, MoreLikeThisParams.MIN_TERM_FREQ, 2, MoreLikeThisParams.MIN_DOC_FREQ, 1, "sort", "id_i1 desc", "mlt", "true", "mlt.fl", "lowerfilt1", "mlt.fl", "lowerfilt", "qt", requestHandlerName, "shards.qt", requestHandlerName, "mlt.count", "20");
    moreLikeThis = (NamedList<Object>) response.getResponse().get("moreLikeThis");
    for (Map.Entry<String, Object> entry : moreLikeThis) {
        String key = entry.getKey();
        Long expected = idVsMLTCount.get(key);
        Long actual = ((SolrDocumentList) entry.getValue()).getNumFound();
        assertEquals("MLT mismatch for id=" + key, expected, actual);
    }
    // test boost mlt.qf
    query("q", "lowerfilt:moon", "fl", id, MoreLikeThisParams.MIN_TERM_FREQ, 2, MoreLikeThisParams.MIN_DOC_FREQ, 1, "sort", "id_i1 desc", "mlt", "true", "mlt.fl", "lowerfilt1,lowerfilt", "mlt.qf", "lowerfilt1^1.2 lowerfilt^3.4", "qt", requestHandlerName, "shards.qt", requestHandlerName, "mlt.count", "20");
}

