        assertU(adoc("id", "x", "title", "boosted", "str_s1", "group1"));
        assertU(adoc("id", "y", "title", "boosted boosted", "str_s1", "group2"));
        assertU(adoc("id", "z", "title", "boosted boosted boosted", "str_s1", "group2"));
        assertU(commit());
        final SolrParams baseParams = params("qt", "/elevate", "q", "title:ipod", "sort", "score desc, id asc", "fl", "id", "elevateIds", "x,y,z", "excludeIds", "b");
        // sanity check everything returned w/these elevation options...
        assertJQ(req(baseParams), "/response/numFound==5", "/response/start==0", "/response/docs==[{'id':'x'},{'id':'y'},{'id':'z'},{'id':'c'},{'id':'a'}]");
        // same query using CURSOR_MARK_START should produce a 'next' cursor...
        assertCursorJQ(req(baseParams, CURSOR_MARK_PARAM, CURSOR_MARK_START), "/response/numFound==5", "/response/start==0", "/response/docs==[{'id':'x'},{'id':'y'},{'id':'z'},{'id':'c'},{'id':'a'}]");
        // use a cursor w/rows < 5, then fetch next cursor...
        String nextCursor = null;
        nextCursor = assertCursorJQ(req(baseParams, CURSOR_MARK_PARAM, CURSOR_MARK_START, "rows", "2"), "/response/numFound==5", "/response/start==0", "/response/docs==[{'id':'x'},{'id':'y'}]");
        nextCursor = assertCursorJQ(req(baseParams, CURSOR_MARK_PARAM, nextCursor, "rows", "2"), "/response/numFound==5", "/response/start==0", "/response/docs==[{'id':'z'},{'id':'c'}]");
        nextCursor = assertCursorJQ(req(baseParams, CURSOR_MARK_PARAM, nextCursor, "rows", "2"), "/response/numFound==5", "/response/start==0", "/response/docs==[{'id':'a'}]");
        final String lastCursor = nextCursor;
        nextCursor = assertCursorJQ(req(baseParams, CURSOR_MARK_PARAM, nextCursor, "rows", "2"), "/response/numFound==5", "/response/start==0", "/response/docs==[]");
        assertEquals(lastCursor, nextCursor);
    } finally {
        delete();
    }
}

