@Test
public void test() throws Exception {
    // field names
    final String id = "id";
    final String bee_t = "bee_t";
    final String forage_t = "forage_t";
    // add custom handlers (the exact custom handler names should not matter)
    final String[] searchHandlerNames = new String[] { null, "/custom_select" + random().nextInt(), "/custom_select" + random().nextInt() };
    final String[] searchHandlerAppends = new String[] { null, "    'appends' : { 'fq' : '-" + forage_t + ":pollen' }, \n", "    'appends' : { 'fq' : '-" + forage_t + ":nectar' }, \n" };
    for (int ii = 0; ii < searchHandlerNames.length; ++ii) {
        if (searchHandlerNames[ii] != null) {
            cluster.getSolrClient().request(new ConfigRequest("{\n" + "  'add-requesthandler': {\n" + "    'name' : '" + searchHandlerNames[ii] + "',\n" + "    'class' : 'org.apache.solr.handler.component.SearchHandler',\n" + searchHandlerAppends[ii] + "  }\n" + "}"), COLLECTION);
        }
    }
    // add some documents
    {
        new UpdateRequest().add(sdoc(id, 1, bee_t, "bumble bee", forage_t, "nectar")).add(sdoc(id, 2, bee_t, "honey bee", forage_t, "propolis")).add(sdoc(id, 3, bee_t, "solitary bee", forage_t, "pollen")).commit(cluster.getSolrClient(), COLLECTION);
    }
    // search (with all possible search handler combinations)
    for (boolean shortCircuit : new boolean[] { false, true }) {
        for (boolean withFilterQuery : new boolean[] { false, true }) {
            for (int ii = 0; ii < searchHandlerNames.length; ++ii) {
                for (int jj = 0; jj < searchHandlerNames.length; ++jj) {
                    final int numAppendedFilterQueries;
                    if (searchHandlerNames[ii] != null && searchHandlerNames[jj] != null && !searchHandlerNames[ii].equals(searchHandlerNames[jj])) {
                        // both handlers appended their filter query
                        numAppendedFilterQueries = 2;
                    } else if (searchHandlerNames[ii] != null || searchHandlerNames[jj] != null) {
                        numAppendedFilterQueries = // one filter query from one handler or the same filter query from both
                        1;
                        // handlers
                    } else {
                        // no custom handlers, no appended filter queries
                        numAppendedFilterQueries = 0;
                    }
                    // compose the query
                    final SolrQuery solrQuery = new SolrQuery(bee_t + ":bee");
                    if (searchHandlerNames[ii] != null) {
                        solrQuery.setParam(CommonParams.QT, searchHandlerNames[ii]);
                    }
                    if (searchHandlerNames[jj] != null) {
                        solrQuery.setParam(ShardParams.SHARDS_QT, searchHandlerNames[jj]);
                    }
                    if (withFilterQuery) {
                        solrQuery.setFilterQueries("-" + forage_t + ":water");
                    }
                    solrQuery.setParam("shortCircuit", shortCircuit);
                    solrQuery.setParam(CommonParams.DEBUG, CommonParams.QUERY);
                    // make the query
                    final QueryResponse queryResponse = new QueryRequest(solrQuery).process(cluster.getSolrClient(), COLLECTION);
                    // analyse the response
                    final StringBuilder contextInfo = new StringBuilder();
                    contextInfo.append("COLLECTION=" + COLLECTION);
                    contextInfo.append(",NUM_SHARDS=" + NUM_SHARDS);
                    contextInfo.append(",NUM_REPLICAS=" + NUM_REPLICAS);
                    contextInfo.append(",shortCircuit=" + shortCircuit);
                    contextInfo.append(",withFilterQuery=" + withFilterQuery);
                    contextInfo.append(",ii=" + ii);
                    contextInfo.append(",jj=" + jj);
                    final int expectedNumFilterQueries = (withFilterQuery ? 1 : 0) + numAppendedFilterQueries;
                    assertNotNull(queryResponse);
                    final Map<String, Object> debugMap = queryResponse.getDebugMap();
                    assertNotNull(debugMap);
                    final List<?> filterQueriesList = (List<?>) debugMap.getOrDefault("filter_queries", Collections.EMPTY_LIST);
                    final Set<?> filterQueriesSet = new HashSet<>(filterQueriesList);
                    contextInfo.append(",filterQueriesList=" + filterQueriesList.toString());
                    if (searchHandlerNames[ii] != null && (searchHandlerNames[jj] == null || searchHandlerNames[jj].equals(searchHandlerNames[ii]))) {
                        assertEquals(contextInfo.toString(), expectedNumFilterQueries, filterQueriesSet.size());
                        // SOLR-10059: sometimes (but not always) filterQueriesList contains duplicates
                        continue;
                    }
                    assertEquals(contextInfo.toString(), expectedNumFilterQueries, filterQueriesList.size());
                    assertEquals(contextInfo.toString(), filterQueriesSet.size(), filterQueriesList.size());
                }
            }
        }
    }
}

@Test
public void testInitialization() {
    SolrCore core = h.getCore();
    // Build an explicit list
    // -----------------------------------------------
    List<String> names0 = new ArrayList<>();
    names0.add(MoreLikeThisComponent.COMPONENT_NAME);
    NamedList<List<String>> args = new NamedList<>();
    args.add(SearchHandler.INIT_COMPONENTS, names0);
    try (SearchHandler handler = new SearchHandler()) {
        handler.init(args);
        handler.inform(core);
        assertEquals(1, handler.getComponents().size());
        assertEquals(core.getSearchComponent(MoreLikeThisComponent.COMPONENT_NAME), handler.getComponents().get(0));
    } catch (IOException e) {
        fail("IOException closing SearchHandler");
    }
    // Build an explicit list that includes the debug comp.
    // -----------------------------------------------
    names0 = new ArrayList<>();
    names0.add(FacetComponent.COMPONENT_NAME);
    names0.add(DebugComponent.COMPONENT_NAME);
    names0.add(MoreLikeThisComponent.COMPONENT_NAME);
    args = new NamedList<>();
    args.add(SearchHandler.INIT_COMPONENTS, names0);
    try (SearchHandler handler = new SearchHandler()) {
        handler.init(args);
        handler.inform(core);
        assertEquals(3, handler.getComponents().size());
        assertEquals(core.getSearchComponent(FacetComponent.COMPONENT_NAME), handler.getComponents().get(0));
        assertEquals(core.getSearchComponent(DebugComponent.COMPONENT_NAME), handler.getComponents().get(1));
        assertEquals(core.getSearchComponent(MoreLikeThisComponent.COMPONENT_NAME), handler.getComponents().get(2));
    } catch (IOException e) {
        fail("Exception when closing SearchHandler");
    }
    // First/Last list
    // -----------------------------------------------
    names0 = new ArrayList<>();
    names0.add(MoreLikeThisComponent.COMPONENT_NAME);
    List<String> names1 = new ArrayList<>();
    names1.add(FacetComponent.COMPONENT_NAME);
    args = new NamedList<>();
    args.add(SearchHandler.INIT_FIRST_COMPONENTS, names0);
    args.add(SearchHandler.INIT_LAST_COMPONENTS, names1);
    try (SearchHandler handler = new SearchHandler()) {
        handler.init(args);
        handler.inform(core);
        List<SearchComponent> comps = handler.getComponents();
        assertEquals(2 + handler.getDefaultComponents().size(), comps.size());
        assertEquals(core.getSearchComponent(MoreLikeThisComponent.COMPONENT_NAME), comps.get(0));
        assertEquals(core.getSearchComponent(FacetComponent.COMPONENT_NAME), comps.get(comps.size() - 2));
        // Debug component is always last in this case
        assertEquals(core.getSearchComponent(DebugComponent.COMPONENT_NAME), comps.get(comps.size() - 1));
    } catch (IOException e) {
        fail("Exception when closing SearchHandler");
    }
}

@Test
public void testZkConnected() throws Exception {
    MiniSolrCloudCluster miniCluster = new MiniSolrCloudCluster(5, createTempDir(), JettyConfig.builder().build());
    final CloudSolrClient cloudSolrClient = miniCluster.getSolrClient();
    try {
        assertNotNull(miniCluster.getZkServer());
        List<JettySolrRunner> jettys = miniCluster.getJettySolrRunners();
        assertEquals(5, jettys.size());
        for (JettySolrRunner jetty : jettys) {
            assertTrue(jetty.isRunning());
        }
        // create collection
        String collectionName = "testSolrCloudCollection";
        String configName = "solrCloudCollectionConfig";
        miniCluster.uploadConfigSet(SolrTestCaseJ4.TEST_PATH().resolve("collection1/conf"), configName);
        CollectionAdminRequest.createCollection(collectionName, configName, 2, 2).setPerReplicaState(SolrCloudTestCase.isPRS()).process(miniCluster.getSolrClient());
        QueryRequest req = new QueryRequest();
        QueryResponse rsp = req.process(cloudSolrClient, collectionName);
        assertTrue(rsp.getResponseHeader().getBooleanArg("zkConnected"));
        Collection<Slice> slices = cloudSolrClient.getClusterState().getCollection(collectionName).getSlices();
        Slice slice = getRandomEntry(slices);
        Replica replica = getRandomEntry(slice.getReplicas());
        JettySolrRunner jetty = miniCluster.getReplicaJetty(replica);
        // Use the replica's core URL to avoid ZK communication
        try (SolrClient client = new HttpSolrClient.Builder(replica.getBaseUrl()).withDefaultCollection(replica.getCoreName()).build()) {
            jetty.getCoreContainer().getZkController().getZkClient().close();
            rsp = req.process(client);
            assertFalse(rsp.getResponseHeader().getBooleanArg("zkConnected"));
        }
    } finally {
        miniCluster.shutdown();
    }
}

