@Test
public void testDefaultBuildOnStartupNotStoredDict() throws Exception {
    final String suggester = "suggest_doc_default_startup_no_store";
    // validate that this suggester is not storing the lookup
    assertEquals(suggester, h.getCore().getSolrConfig().get("searchComponent", n -> "suggest".equals(n.attr("name"))).get("lst", 7).get("str", n -> "name".equals(n.attr("name"))).txt());
    assertNull(h.getCore().getSolrConfig().get("searchComponent", n -> "suggest".equals(n.attr("name"))).get("lst", 7).get("str", n -> "storeDir".equals(n.attr("name"))).txt());
    // validate that this suggester only builds manually and has not buildOnStartup parameter
    assertEquals("false", h.getCore().getSolrConfig().get("searchComponent", n -> "suggest".equals(n.attr("name"))).get("lst", 7).get("str", n -> "buildOnCommit".equals(n.attr("name"))).txt());
    assertNull(h.getCore().getSolrConfig().get("searchComponent", n -> "suggest".equals(n.attr("name"))).get("lst", 7).get("str", n -> "buildOnStartup".equals(n.attr("name"))).txt());
    reloadCore(random().nextBoolean());
    // Validate that the suggester was built on new/reload core
    assertQ(req("qt", rh, SuggesterParams.SUGGEST_DICT, suggester, SuggesterParams.SUGGEST_Q, "example", SuggesterParams.SUGGEST_COUNT, "5"), "//lst[@name='suggest']/lst[@name='" + suggester + "']/lst[@name='example']/int[@name='numFound'][.='2']");
    // add one more doc, should be visible after core reload
    assertU(adoc("id", "10", "cat", "example data extra ", "price", "40", "weight", "35"));
    assertU((commit()));
    waitForWarming();
    // buildOnCommit=false, this doc should not be in the suggester yet
    assertQ(req("qt", rh, SuggesterParams.SUGGEST_DICT, suggester, SuggesterParams.SUGGEST_Q, "example", SuggesterParams.SUGGEST_COUNT, "5"), "//lst[@name='suggest']/lst[@name='" + suggester + "']/lst[@name='example']/int[@name='numFound'][.='2']");
    reloadCore(random().nextBoolean());
    assertQ(req("qt", rh, SuggesterParams.SUGGEST_DICT, suggester, SuggesterParams.SUGGEST_Q, "example", SuggesterParams.SUGGEST_COUNT, "5"), "//lst[@name='suggest']/lst[@name='" + suggester + "']/lst[@name='example']/int[@name='numFound'][.='3']");
}

@Test
public void testDefaultBuildOnStartupStoredDict() throws Exception {
    final String suggester = "suggest_doc_default_startup";
    // validate that this suggester is storing the lookup
    assertEquals(suggester, h.getCore().getSolrConfig().get("searchComponent", n -> "suggest".equals(n.attr("name"))).get("lst", 6).get("str", n -> "name".equals(n.attr("name"))).txt());
    assertEquals(suggester, h.getCore().getSolrConfig().get("searchComponent", n -> "suggest".equals(n.attr("name"))).get("lst", 6).get("str", n -> "storeDir".equals(n.attr("name"))).txt());
    // validate that this suggester only builds manually and has not buildOnStartup parameter
    assertEquals("false", h.getCore().getSolrConfig().get("searchComponent", n -> "suggest".equals(n.attr("name"))).get("lst", 6).get("str", n -> "buildOnCommit".equals(n.attr("name"))).txt());
    assertNull(h.getCore().getSolrConfig().get("searchComponent", n -> "suggest".equals(n.attr("name"))).get("lst", 6).get("str", n -> "buildOnStartup".equals(n.attr("name"))).txt());
    assertQ(req("qt", rh, SuggesterParams.SUGGEST_DICT, suggester, SuggesterParams.SUGGEST_Q, "example", SuggesterParams.SUGGEST_COUNT, "5"), "//lst[@name='suggest']/lst[@name='" + suggester + "']/lst[@name='example']/int[@name='numFound'][.='0']");
    // build the suggester manually
    assertQ(req("qt", rh, SuggesterParams.SUGGEST_DICT, suggester, SuggesterParams.SUGGEST_BUILD, "true"), "//str[@name='command'][.='build']");
    assertQ(req("qt", rh, SuggesterParams.SUGGEST_DICT, suggester, SuggesterParams.SUGGEST_Q, "example", SuggesterParams.SUGGEST_COUNT, "5"), "//lst[@name='suggest']/lst[@name='" + suggester + "']/lst[@name='example']/int[@name='numFound'][.='2']");
    reloadCore(random().nextBoolean());
    // Validate that the suggester was loaded on new/reload core
    assertQ(req("qt", rh, SuggesterParams.SUGGEST_DICT, suggester, SuggesterParams.SUGGEST_Q, "example", SuggesterParams.SUGGEST_COUNT, "5"), "//lst[@name='suggest']/lst[@name='" + suggester + "']/lst[@name='example']/int[@name='numFound'][.='2']");
    // add one more doc, this should not be seen after a core reload (not until the suggester is
    // manually rebuilt)
    assertU(adoc("id", "10", "cat", "example data extra ", "price", "40", "weight", "35"));
    assertU((commit()));
    waitForWarming();
    // buildOnCommit=false, this doc should not be in the suggester yet
    assertQ(req("qt", rh, SuggesterParams.SUGGEST_DICT, suggester, SuggesterParams.SUGGEST_Q, "example", SuggesterParams.SUGGEST_COUNT, "5"), "//lst[@name='suggest']/lst[@name='" + suggester + "']/lst[@name='example']/int[@name='numFound'][.='2']");
    reloadCore(random().nextBoolean());
    assertQ(req("qt", rh, SuggesterParams.SUGGEST_DICT, suggester, SuggesterParams.SUGGEST_Q, "example", SuggesterParams.SUGGEST_COUNT, "5"), "//lst[@name='suggest']/lst[@name='" + suggester + "']/lst[@name='example']/int[@name='numFound'][.='2']");
    // build the suggester manually
    assertQ(req("qt", rh, SuggesterParams.SUGGEST_DICT, suggester, SuggesterParams.SUGGEST_BUILD, "true"), "//str[@name='command'][.='build']");
    assertQ(req("qt", rh, SuggesterParams.SUGGEST_DICT, suggester, SuggesterParams.SUGGEST_Q, "example", SuggesterParams.SUGGEST_COUNT, "5"), "//lst[@name='suggest']/lst[@name='" + suggester + "']/lst[@name='example']/int[@name='numFound'][.='3']");
}

