@Test
public void testErrorCases() {
    String[] doc = { "id", "1", "term_s", "YYYY", "text_t", "bleh bleh", "test_i", "5000", "test_l", "100", "test_f", "200" };
    assertU(adoc(doc));
    assertU(commit());
    String[] doc1 = { "id", "2", "term_s", "YYYY", "text_t", "bleh bleh", "test_i", "500", "test_l", "1000", "test_f", "2000" };
    assertU(adoc(doc1));
    ignoreException("missing expand field");
    ignoreException("Expected identifier at pos 2");
    ignoreException("Can't determine a Sort Order");
    ignoreException("Expand not supported for fieldType:'text'");
    // expand with grouping
    SolrException e = expectThrows(SolrException.class, () -> {
        h.query(req("q", "*:*", "expand", "true", "expand.field", "id", "group", "true", "group.field", "id"));
    });
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, e.code());
    assertEquals("Can not use expand with Grouping enabled", e.getMessage());
    // no expand field
    e = expectThrows(SolrException.class, () -> h.query(req("q", "*:*", "expand", "true")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, e.code());
    assertEquals("missing expand field", e.getMessage());
    // query and filter syntax errors
    e = expectThrows(SolrException.class, () -> h.query(req("q", "*:*", "expand", "true", "expand.field", "term_s", "expand.q", "{!")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, e.code());
    assertTrue(e.getMessage().contains("Expected identifier at pos 2 str='{!'"));
    e = expectThrows(SolrException.class, () -> h.query(req("q", "*:*", "expand", "true", "expand.field", "term_s", "expand.q", "*:*", "expand.fq", "{!")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, e.code());
    assertTrue(e.getMessage().contains("Expected identifier at pos 2 str='{!'"));
    e = expectThrows(SolrException.class, () -> h.query(req("q", "*:*", "expand", "true", "expand.field", "term_s", "expand.q", "*:*", "expand.fq", "{!")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, e.code());
    assertTrue(e.getMessage().contains("Expected identifier at pos 2 str='{!'"));
    e = expectThrows(SolrException.class, () -> h.query(req("q", "*:*", "expand", "true", "expand.field", "term_s", "expand.q", "*:*", "expand.sort", "bleh")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, e.code());
    assertTrue(e.getMessage().contains("Can't determine a Sort Order (asc or desc) in sort spec 'bleh'"));
    e = expectThrows(SolrException.class, () -> h.query(req("q", "*:*", "expand", "true", "expand.field", "text_t", "expand.q", "*:*")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, e.code());
    assertEquals("Expand not supported for fieldType:'text'", e.getMessage());
    resetExceptionIgnores();
}

@Test
public void testLoadBalancerRequestsMinMax() throws ClassNotFoundException {
    final Path home = TEST_PATH();
    CoreContainer cc = null;
    ShardHandlerFactory factory = null;
    try {
        cc = CoreContainer.createAndLoad(home, home.resolve("solr-shardhandler-loadBalancerRequests.xml"));
        factory = cc.getShardHandlerFactory();
        assertThat(factory, instanceOf(Class.forName(expectedShardHandlerFactory)));
        // All SHF's currently extend HttpShardFactory, so this case is safe
        @SuppressWarnings("resource")
        final HttpShardHandlerFactory httpShardHandlerFactory = ((HttpShardHandlerFactory) factory);
        assertEquals(expectedLoadBalancerRequestsMinimumAbsolute, httpShardHandlerFactory.permittedLoadBalancerRequestsMinimumAbsolute, 0.0);
        assertEquals(expectedLoadBalancerRequestsMaximumFraction, httpShardHandlerFactory.permittedLoadBalancerRequestsMaximumFraction, 0.0);
        // create a dummy request and dummy url list
        final QueryRequest queryRequest = null;
        final List<String> urls = new ArrayList<>();
        for (int ii = 0; ii < 10; ++ii) {
            urls.add("http://localhost" + ii + ":8983/solr");
        }
        // create LBHttpSolrClient request
        final LBSolrClient.Req req = httpShardHandlerFactory.newLBHttpSolrClientReq(queryRequest, urls);
        // actual vs. expected test
        final int actualNumServersToTry = req.getNumServersToTry();
        int expectedNumServersToTry = (int) Math.floor(urls.size() * expectedLoadBalancerRequestsMaximumFraction);
        if (expectedNumServersToTry < expectedLoadBalancerRequestsMinimumAbsolute) {
            expectedNumServersToTry = expectedLoadBalancerRequestsMinimumAbsolute;
        }
        assertEquals("wrong numServersToTry for" + " urls.size=" + urls.size() + " expectedLoadBalancerRequestsMinimumAbsolute=" + expectedLoadBalancerRequestsMinimumAbsolute + " expectedLoadBalancerRequestsMaximumFraction=" + expectedLoadBalancerRequestsMaximumFraction, expectedNumServersToTry, actualNumServersToTry);
    } finally {
        if (factory != null)
            factory.close();
        if (cc != null)
            cc.shutdown();
    }
}

