    }
    float[] float_vals = new float[10];
    float_vals[0] = 0.0f;
    float_vals[1] = +0.0f;
    float_vals[2] = -0.0f;
    float_vals[3] = +0.00001f;
    float_vals[4] = +0.000011f;
    float_vals[5] = Float.MAX_VALUE;
    float_vals[6] = Float.MIN_VALUE;
    // 0.33333334
