/**
 * Tests WordDelimiterGraphFilter, stacked/synonymous tokens at index time (catenate options)
 */
@Test
public void testWDF() throws Exception {
    baseParams.set("field", "name_tagWDF");
    // hyphen
    final String WINSTONSALEM = "City of Winston-Salem";
    // space
    final String BOSTONHARBOR = "Boston Harbor";
    buildNames(WINSTONSALEM, BOSTONHARBOR);
    // round-trip works
    assertTags(reqDoc(WINSTONSALEM), new TestTag(0, WINSTONSALEM.length(), WINSTONSALEM, lookupByName(WINSTONSALEM)));
    // space separated works
    final String WS_SPACE = WINSTONSALEM.replace('-', ' ');
    assertTags(reqDoc(WS_SPACE), new TestTag(0, WS_SPACE.length(), WS_SPACE, lookupByName(WINSTONSALEM)));
    // must be full match
    // match nothing
    assertTags(reqDoc("Winston"));
    // match nothing
    assertTags(reqDoc("Salem"));
    // round-trip works
    assertTags(reqDoc(BOSTONHARBOR), new TestTag(0, BOSTONHARBOR.length(), BOSTONHARBOR, lookupByName(BOSTONHARBOR)));
    // hyphen separated works
    final String BH_HYPHEN = BOSTONHARBOR.replace(' ', '-');
    assertTags(reqDoc(BH_HYPHEN), new TestTag(0, BH_HYPHEN.length(), BH_HYPHEN, lookupByName(BOSTONHARBOR)));
    // must be full match
    // match nothing
    assertTags(reqDoc("Boston"));
    // match nothing
