    assertQ(req("id:101"), "//arr[@name='str_s']/str[3][.='c']");
    assertQ(req("id:102"), "//arr[@name='str_s']/str[2][.='EMPTY']");
    assertQ(req("id:103"), "//arr[@name='str_s']/str[.='EMPTY']");
    // test alternate values for delimiters
    makeFile("id|str_s\n" + "100|^quoted^\n" + "101|a;'b';c\n" + "102|a;;b\n" + "103|\n" + // no backslash escaping should be done by default
    "104|a\\\\b\n");
    loadLocal("commit", "true", "separator", "|", "encapsulator", "^", "f.str_s.map", ":EMPTY", "f.str_s.split", "true", "f.str_s.separator", ";", "f.str_s.encapsulator", "'");
