        pullFromTo(leaderJetty, repeaterJetty);
        rQuery(3, "*:*", repeaterClient);
        pullFromTo(repeaterJetty, followerJetty);
        rQuery(3, "*:*", followerClient);
        for (int i = 3; i < 6; i++) index(leaderClient, "id", i, "name", "name = " + i);
