        pullFromTo(leaderJetty, repeaterJetty);
        rQuery(6, "*:*", repeaterClient);
        pullFromTo(repeaterJetty, followerJetty);
        rQuery(6, "*:*", followerClient);
    } finally {
        if (repeater != null) {
            repeaterJetty.stop();
