@Test
public void doTestBackup() throws Exception {
    final BackupStatusChecker backupStatus = new BackupStatusChecker(leaderClient, "/" + DEFAULT_TEST_CORENAME + "/replication");
    String lastBackupDir = backupStatus.checkBackupSuccess();
    assertNull("Already have a successful backup", lastBackupDir);
    // One extra for the backup on commit
    final Path[] snapDir = new Path[5];
    // First snapshot location
    int nDocs = BackupRestoreUtils.indexDocs(leaderClient, DEFAULT_TEST_COLLECTION_NAME, docsSeed);
    lastBackupDir = backupStatus.waitForDifferentBackupDir(lastBackupDir, 30);
    snapDir[0] = Path.of(leader.getDataDir(), lastBackupDir);
    final boolean namedBackup = random().nextBoolean();
    String[] backupNames = null;
    if (namedBackup) {
        backupNames = new String[4];
    }
    for (int i = 0; i < 4; i++) {
        final String backupName = TestUtil.randomSimpleString(random(), 1, 20) + "_" + i;
        if (!namedBackup) {
            if (addNumberToKeepInRequest) {
                runBackupCommand(leaderJetty, ReplicationHandler.CMD_BACKUP, "&" + backupKeepParamName + "=2");
            } else {
                runBackupCommand(leaderJetty, ReplicationHandler.CMD_BACKUP, "");
            }
            lastBackupDir = backupStatus.waitForDifferentBackupDir(lastBackupDir, 30);
        } else {
            runBackupCommand(leaderJetty, ReplicationHandler.CMD_BACKUP, "&name=" + backupName);
            lastBackupDir = backupStatus.waitForBackupSuccess(backupName, 30);
            backupNames[i] = backupName;
        }
        snapDir[i + 1] = Path.of(leader.getDataDir(), lastBackupDir);
        verify(snapDir[i + 1], nDocs);
    }
    // Test Deletion of named backup
    if (namedBackup) {
        testDeleteNamedBackup(backupNames);
    } else {
        // 5 backups got created. 4 explicitly and one because a commit was called.
        // Only the last two should still exist.
        final List<String> remainingBackups = new ArrayList<>();
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(Path.of(leader.getDataDir()), "snapshot*")) {
            Iterator<Path> iter = stream.iterator();
            while (iter.hasNext()) {
                remainingBackups.add(iter.next().getFileName().toString());
            }
        }
        // Depending on the use of backupKeepParamName there should either be 2 or 1 backups remaining
        if (backupKeepParamName.equals(ReplicationHandler.NUMBER_BACKUPS_TO_KEEP_REQUEST_PARAM)) {
            assertEquals(remainingBackups.toString(), 2, remainingBackups.size());
            if (Files.exists(snapDir[0]) || Files.exists(snapDir[1]) || Files.exists(snapDir[2])) {
                fail("Backup should have been cleaned up because " + backupKeepParamName + " was set to 2.");
            }
        } else {
            assertEquals(remainingBackups.toString(), 1, remainingBackups.size());
            if (Files.exists(snapDir[0]) || Files.exists(snapDir[1]) || Files.exists(snapDir[2]) || Files.exists(snapDir[3])) {
                fail("Backup should have been cleaned up because " + backupKeepParamName + " was set to 1.");
            }
        }
    }
}

@Test
public void testDiskOverFlow() throws Exception {
    invokeReplicationCommand(TestReplicationHandler.buildUrl(followerJetty.getLocalPort()) + "/" + DEFAULT_TEST_CORENAME, "disablepoll");
    // index docs
    log.info("Indexing to LEADER");
    int docsInLeader = 1000;
    long szLeader = indexDocs(leaderClient, docsInLeader, 0);
    log.info("Indexing to FOLLOWER");
    long szFollower = indexDocs(followerClient, 1200, 1000);
    IndexFetcher.usableDiskSpaceProvider = new Function<String, Long>() {

        @Override
        public Long apply(String s) {
            return szLeader;
        }
    };
    // we don't need/want the barrier to be cyclic, so we use a ref that our barrier action will
    // null out to prevent it from being triggered multiple times (which shouldn't happen anyway)
    final AtomicReference<CyclicBarrier> commonBarrier = new AtomicReference<>();
    commonBarrier.set(new CyclicBarrier(2, () -> {
        commonBarrier.set(null);
    }));
    final List<Throwable> threadFailures = new ArrayList<>(7);
    IndexFetcher.testWait = new BooleanSupplier() {

        @Override
        public boolean getAsBoolean() {
            try {
                final CyclicBarrier barrier = commonBarrier.get();
                if (null != barrier) {
                    barrier.await(60, TimeUnit.SECONDS);
                }
            } catch (Exception e) {
                log.error("IndexFetcher Thread Failure", e);
                threadFailures.add(e);
            }
            return true;
        }
    };
    new Thread(() -> {
        try {
            for (int i = 0; i < 100; i++) {
                final CyclicBarrier barrier = commonBarrier.get();
                assertNotNull("why is query thread still looping if barrier has already been cleared?", barrier);
                try {
                    QueryResponse rsp = followerClient.query(new SolrQuery().setQuery("*:*").setRows(0));
                    Thread.sleep(200);
                } catch (SolrException e) {
                    if (e.code() == SolrException.ErrorCode.SERVICE_UNAVAILABLE.code && e.getMessage().contains(expectedErr)) {
                        log.info("Got expected exception", e);
                        // now let the barrier complete & clear itself, and we're done
                        barrier.await(60, TimeUnit.SECONDS);
                        // break out
                        return;
                    }
                    // else...
                    // not our expected exception, re-throw to fail fast...
                    throw e;
                }
            }
            // if we made it this far, something is wrong...
            throw new RuntimeException("Query thread gave up waiting for expected error: " + expectedErr);
        } catch (Exception e) {
            log.error("Query Thread Failure", e);
            threadFailures.add(e);
        }
    }).start();
    QueryResponse response = followerClient.query(new SolrQuery().add("qt", "/replication").add("command", CMD_FETCH_INDEX).add("wait", "true"));
    assertEquals("Replication command status", "OK", response._getStr("status", null));
    assertEquals("threads encountered failures (see logs for when)", Collections.emptyList(), threadFailures);
    response = followerClient.query(new SolrQuery().setQuery("*:*").setRows(0));
    assertEquals("docs in follower", docsInLeader, response.getResults().getNumFound());
    response = followerClient.query(new SolrQuery().add("qt", "/replication").add("command", ReplicationHandler.CMD_DETAILS));
    if (log.isInfoEnabled()) {
        log.info("DETAILS {}", Utils.writeJson(response, new StringWriter(), true));
    }
    assertEquals("follower's clearedLocalIndexFirst (from rep details)", "true", response._getStr("details/follower/clearedLocalIndexFirst", null));
}

