    Map<?, ?> caches = (Map<?, ?>) editable_prop_map.get("query");
    setupRestTestHarnesses();
    List<Thread> threads = new ArrayList<>(caches.size());
    final List<List<String>> collectErrors = new ArrayList<>();
    for (Map.Entry<?, ?> e : caches.entrySet()) {
        if (e.getValue() instanceof Map) {
            List<String> errs = new ArrayList<>();
            collectErrors.add(errs);
            Thread t = new Thread(() -> {
                try {
                    invokeBulkCall((String) e.getKey(), errs);
                } catch (Exception e1) {
                    log.error("error invoking bulk call", e1);
                }
            });
            threads.add(t);
            t.start();
        }
    }
    for (Thread thread : threads) thread.join();
    boolean success = true;
    for (List<?> e : collectErrors) {
        if (!e.isEmpty()) {
            success = false;
            log.error("{}", e);
        }
    }
    assertTrue(collectErrors.toString(), success);
}

