    try {
        JettySolrRunner j = cluster.getRandomJetty(random());
        String url = j.getBaseUrl() + "/admin/metrics?key=solr.node:CONTAINER.zkClient&wt=json";
        try (SolrClient solrClient = j.newClient()) {
            HttpClient httpClient = ((HttpSolrClient) solrClient).getHttpClient();
            @SuppressWarnings("unchecked")
            Map<String, Object> zkMmetrics = (Map<String, Object>) Utils.getObjectByPath(Utils.executeGET(httpClient, url, Utils.JSONCONSUMER), false, List.of("metrics", "solr.node:CONTAINER.zkClient"));
            Set<String> allKeys = Set.of("watchesFired", "reads", "writes", "bytesRead", "bytesWritten", "multiOps", "cumulativeMultiOps", "childFetches", "cumulativeChildrenFetched", "existsChecks", "deletes");
            for (String k : allKeys) {
                assertNotNull(zkMmetrics.get(k));
            }
            Utils.executeGET(httpClient, j.getBaseURLV2() + "/cluster/zookeeper/children/live_nodes", Utils.JSONCONSUMER);
            @SuppressWarnings("unchecked")
            Map<String, Object> zkMmetricsNew = (Map<String, Object>) Utils.getObjectByPath(Utils.executeGET(httpClient, url, Utils.JSONCONSUMER), false, List.of("metrics", "solr.node:CONTAINER.zkClient"));
