 * some simple params) to verify that they don't generate an error against the minimal schema
 */
@Test
public void testAllConfiguredHandlers() {
    Set<String> handlerNames = h.getCore().getRequestHandlers().keySet();
    for (String handler : handlerNames) {
        try {
            if (handler.startsWith("/update") || handler.startsWith("/admin") || handler.startsWith("/schema") || handler.startsWith("/config") || handler.startsWith("/mlt") || handler.startsWith("/export") || handler.startsWith("/graph") || handler.startsWith("/sql") || handler.startsWith("/stream") || handler.startsWith("/terms") || handler.startsWith("/analysis/") || handler.startsWith("/debug/") || handler.startsWith("/replication") || handler.startsWith("/tasks")) {
                continue;
            }
            assertQ("failure w/handler: '" + handler + "'", req("qt", handler, // this should be fairly innocuous for any type of query
            "q", "foo:bar", "omitHeader", "false"), "//lst[@name='responseHeader']");
        } catch (Exception e) {
            throw new RuntimeException("exception w/handler: '" + handler + "'", e);
        }
    }
}

