    delVersion.pkg = "test_pkg";
    req = new V2Request.Builder("/cluster/package").forceV2(true).withMethod(SolrRequest.METHOD.POST).withPayload(Collections.singletonMap("delete", delVersion)).build();
    // we are expecting an error
