    assertQ(req("q", "*:*", "facet", "true", "facet.interval", "test_s_dv", "facet.interval", "test_l_dv", "facet.interval.set", "[1,2]", "facet.interval.set", "[2,3]", "facet.interval.set", "[3,4]"), "count(//lst[@name='facet_intervals']/lst)=2", "//lst[@name='facet_intervals']/lst[@name='test_s_dv']/int[@name='[1,2]'][.=0]", "//lst[@name='facet_intervals']/lst[@name='test_s_dv']/int[@name='[2,3]'][.=0]", "//lst[@name='facet_intervals']/lst[@name='test_s_dv']/int[@name='[3,4]'][.=0]", "//lst[@name='facet_intervals']/lst[@name='test_l_dv']/int[@name='[1,2]'][.=2]", "//lst[@name='facet_intervals']/lst[@name='test_l_dv']/int[@name='[2,3]'][.=2]", "//lst[@name='facet_intervals']/lst[@name='test_l_dv']/int[@name='[3,4]'][.=2]");
    // use of facet.interval.set and override
    assertQ(req("q", "*:*", "facet", "true", "facet.interval", "test_s_dv", "facet.interval", "test_l_dv", "facet.interval.set", "[1,2]", "f.test_l_dv.facet.interval.set", "[3,4]", "f.test_l_dv.facet.interval.set", "[4,5]"), "count(//lst[@name='facet_intervals']/lst)=2", "//lst[@name='facet_intervals']/lst[@name='test_s_dv']/int[@name='[1,2]'][.=0]", // interval [1,2] not
    "count(//lst[@name='facet_intervals']/lst[@name='test_l_dv']/int)=2", // present
    "//lst[@name='facet_intervals']/lst[@name='test_l_dv']/int[@name='[3,4]'][.=2]", "//lst[@name='facet_intervals']/lst[@name='test_l_dv']/int[@name='[4,5]'][.=2]");
    assertQ(req("q", "*:*", "facet", "true", "facet.interval", "test_s_dv", "facet.interval", "test_l_dv", "facet.interval.set", "[1,2]", "facet.interval.set", "[2,3]", "facet.interval.set", "[3,4]", "f.test_s_dv.facet.interval.set", "[cat,dog]"), "count(//lst[@name='facet_intervals']/lst)=2", // only [cat,dog] in
    "count(//lst[@name='facet_intervals']/lst[@name='test_s_dv']/int)=1", // test_s_dv
    "//lst[@name='facet_intervals']/lst[@name='test_s_dv']/int[@name='[cat,dog]'][.=5]", "count(//lst[@name='facet_intervals']/lst[@name='test_l_dv']/int)=3", "//lst[@name='facet_intervals']/lst[@name='test_l_dv']/int[@name='[1,2]'][.=2]", "//lst[@name='facet_intervals']/lst[@name='test_l_dv']/int[@name='[2,3]'][.=2]", "//lst[@name='facet_intervals']/lst[@name='test_l_dv']/int[@name='[3,4]'][.=2]");
    // use of facet.interval.set with wrong field type
    assertQEx("Unexpected Exception", "Invalid start interval", req("q", "*:*", "facet", "true", "facet.interval", "test_l_dv", "f.test_l_dv.facet.interval.set", "[cat,dog]"), SolrException.ErrorCode.BAD_REQUEST);
}

