@Test
public void testPrometheusStructureOutput() throws Exception {
    ModifiableSolrParams params = new ModifiableSolrParams();
    params.set("wt", "prometheus");
    var req = new GenericSolrRequest(METHOD.GET, "/admin/metrics", SolrRequestType.ADMIN, params);
    req.setResponseParser(new NoOpResponseParser("prometheus"));
    try (SolrClient adminClient = getHttpSolrClient(solrClientTestRule.getBaseUrl())) {
        NamedList<Object> res = adminClient.request(req);
        assertNotNull("null response from server", res);
        String output = (String) res.get("response");
        Set<String> seenTypeInfo = new HashSet<>();
        List<String> filteredResponse = output.lines().filter(line -> {
            if (!line.startsWith("#")) {
                return true;
            }
            assertTrue("Prometheus exposition format cannot have duplicate TYPE information", seenTypeInfo.add(line));
            return false;
        }).collect(Collectors.toList());
        filteredResponse.forEach((actualMetric) -> {
            String actualValue;
            if (actualMetric.contains("}")) {
                actualValue = actualMetric.substring(actualMetric.lastIndexOf("} ") + 1);
            } else {
                actualValue = actualMetric.split(" ")[1];
            }
            assertTrue("All metrics should start with 'solr_metrics_'", actualMetric.startsWith("solr_metrics_"));
            try {
                Float.parseFloat(actualValue);
            } catch (NumberFormatException e) {
                log.warn("Prometheus value not a parsable float");
                assertTrue(VALID_PROMETHEUS_VALUES.contains(actualValue));
            }
        });
    }
}

@Test
public void testXmlTransformer() throws Exception {
    QueryRequest req = new QueryRequest(new ModifiableSolrParams(Map.of("q", new String[] { "*:*" }, "fl", new String[] { "author:[xml],content_type:[xml]" }, "wt", new String[] { "xml" })));
    req.setResponseParser(XML_NOOP_RESPONSE_PARSER);
    String strResponse = (String) CLIENT.request(req, "collection1").get("response");
    assertTrue("response does not contain raw XML encoding: " + strResponse, strResponse.contains("<raw name=\"author\"><root><child1>some</child1><child2>trivial</child2><child3>xml</child3></root></raw>"));
    assertTrue("response (multiValued) does not contain raw XML encoding: " + strResponse, Pattern.compile("<arr name=\"content_type\">\\s*<raw><root>one</root></raw>\\s*<raw><root>two</root></raw>\\s*</arr>").matcher(strResponse).find());
    req = new QueryRequest(new ModifiableSolrParams(Map.of("q", new String[] { "*:*" }, "fl", new String[] { "author,content_type" }, "wt", new String[] { "xml" })));
    req.setResponseParser(XML_NOOP_RESPONSE_PARSER);
    strResponse = (String) CLIENT.request(req, "collection1").get("response");
    assertTrue("response does not contain escaped XML encoding: " + strResponse, strResponse.contains("<str name=\"author\">&lt;root&gt;&lt;child1"));
    assertTrue("response (multiValued) does not contain escaped XML encoding: " + strResponse, Pattern.compile("<arr name=\"content_type\">\\s*<str>&lt;root&gt;").matcher(strResponse).find());
    req = new QueryRequest(new ModifiableSolrParams(Map.of("q", new String[] { "*:*" }, "fl", new String[] { "author:[xml],content_type:[xml]" }, "wt", new String[] { "json" })));
    req.setResponseParser(JSON_NOOP_RESPONSE_PARSER);
    strResponse = (String) CLIENT.request(req, "collection1").get("response");
    assertTrue("unexpected serialization of XML field value in JSON response: " + strResponse, strResponse.contains("\"author\":\"<root><child1>some</child1>"));
    assertTrue("unexpected (multiValued) serialization of XML field value in JSON response: " + strResponse, strResponse.contains("\"content_type\":[\"<root>one</root>"));
}

