@Test
public void parseVector_NotAList_shouldThrowException() {
    RuntimeException thrown = assertThrows("Single string value should throw an exception", SolrException.class, () -> {
        toTestFloatEncoding.getVectorBuilder("string", DenseVectorParser.BuilderPhase.INDEX).getFloatVector();
    });
    assertThat(thrown.getMessage(), is("incorrect vector format. The expected format is:'[f1,f2..f3]' where each element f is a float"));
    thrown = assertThrows("Single string value should throw an exception", SolrException.class, () -> {
        toTestByteEncoding.getVectorBuilder("string", DenseVectorParser.BuilderPhase.INDEX).getByteVector();
    });
    assertThat(thrown.getMessage(), is("incorrect vector format. The expected format is:'[b1,b2..b3]' where each element b is a byte (-128 to 127)"));
    thrown = assertThrows("Single float value should throw an exception", SolrException.class, () -> {
        toTestFloatEncoding.getVectorBuilder(1.5f, DenseVectorParser.BuilderPhase.INDEX).getFloatVector();
    });
    assertThat(thrown.getMessage(), is("incorrect vector format. The expected format is:'[f1,f2..f3]' where each element f is a float"));
    thrown = assertThrows("Single string value should throw an exception", SolrException.class, () -> {
        toTestByteEncoding.getVectorBuilder("1", DenseVectorParser.BuilderPhase.INDEX).getByteVector();
    });
    assertThat(thrown.getMessage(), is("incorrect vector format. The expected format is:'[b1,b2..b3]' where each element b is a byte (-128 to 127)"));
}

