public void denseVectorFieldOnAtomicUpdate_shouldBeUpdatedCorrectly() throws Exception {
    assumeTrue("update log must be enabled for atomic update", Boolean.getBoolean(System.getProperty("enable.update.log")));
    try {
        initCore("solrconfig.xml", "schema-densevector.xml");
        SolrInputDocument doc = new SolrInputDocument();
        doc.addField("id", "0");
        doc.addField("vector", Arrays.asList(1.1, 2.2, 3.3, 4.4));
        doc.addField("vector_byte_encoding", Arrays.asList(5, 6, 7, 8));
        doc.addField("string_field", "test");
        assertU(adoc(doc));
        assertU(commit());
        assertJQ(req("q", "id:0", "fl", "*"), "/response/docs/[0]/vector==[1.1,2.2,3.3,4.4]", "/response/docs/[0]/vector_byte_encoding==[5,6,7,8]", "/response/docs/[0]/string_field==test");
        SolrInputDocument updateDoc = new SolrInputDocument();
        updateDoc.addField("id", "0");
        updateDoc.addField("vector", Map.of("set", Arrays.asList(9.2, 2.2, 3.3, 5.2)));
        updateDoc.addField("vector_byte_encoding", Map.of("set", Arrays.asList(8, 3, 1, 3)));
        assertU(adoc(updateDoc));
        assertU(commit());
        assertJQ(req("q", "id:0", "fl", "*"), "/response/docs/[0]/vector==[9.2,2.2,3.3,5.2]", "/response/docs/[0]/vector_byte_encoding==[8,3,1,3]", "/response/docs/[0]/string_field=='test'");
    } finally {
        deleteCore();
    }
}

@Test
public void denseVectorByteEncoding_shouldRaiseExceptionWithValuesOutsideBoundaries() throws Exception {
    try {
        initCore("solrconfig.xml", "schema-densevector.xml");
        SolrInputDocument doc = new SolrInputDocument();
        doc.addField("id", "0");
        doc.addField("vector_byte_encoding", Arrays.asList(128, 6, 7, 8));
        RuntimeException thrown = assertThrows("Incorrect elements should throw an exception", SolrException.class, () -> {
            assertU(adoc(doc));
        });
        assertThat(thrown.getCause().getMessage(), is("Error while creating field 'vector_byte_encoding{type=knn_vector_byte_encoding,properties=indexed,stored}' from value '[128, 6, 7, 8]'"));
        assertThat(thrown.getCause().getCause().getMessage(), is("incorrect vector element: '128'. The expected format is:'[b1,b2..b3]' where each element b is a byte (-128 to 127)"));
        SolrInputDocument doc1 = new SolrInputDocument();
        doc1.addField("id", "1");
        doc1.addField("vector_byte_encoding", Arrays.asList(1, -129, 7, 8));
        thrown = assertThrows("Incorrect elements should throw an exception", SolrException.class, () -> {
            assertU(adoc(doc1));
        });
        assertThat(thrown.getCause().getMessage(), is("Error while creating field 'vector_byte_encoding{type=knn_vector_byte_encoding,properties=indexed,stored}' from value '[1, -129, 7, 8]'"));
        assertThat(thrown.getCause().getCause().getMessage(), is("incorrect vector element: '-129'. The expected format is:'[b1,b2..b3]' where each element b is a byte (-128 to 127)"));
    } finally {
        deleteCore();
    }
}

