@Test
public void testDocValues() throws IOException {
    final DocValuesType expectedNumericDvType = Boolean.getBoolean(NUMERIC_POINTS_SYSPROP) ? DocValuesType.SORTED_NUMERIC : DocValuesType.SORTED_SET;
    assertU(adoc("id", "1", "floatdv", "4.5", "intdv", "-1", "intdv", "3", "stringdv", "value1", "stringdv", "value2", "booldv", "false", "booldv", "true"));
    assertU(commit());
    try (SolrCore core = h.getCoreInc()) {
        final RefCounted<SolrIndexSearcher> searcherRef = core.openNewSearcher(true, true);
        final SolrIndexSearcher searcher = searcherRef.get();
        try {
            final LeafReader reader = searcher.getSlowAtomicReader();
            assertEquals(1, reader.numDocs());
            final FieldInfos infos = reader.getFieldInfos();
            assertEquals(DocValuesType.SORTED_SET, infos.fieldInfo("stringdv").getDocValuesType());
            assertEquals(DocValuesType.SORTED_SET, infos.fieldInfo("booldv").getDocValuesType());
            assertEquals(expectedNumericDvType, infos.fieldInfo("floatdv").getDocValuesType());
            assertEquals(expectedNumericDvType, infos.fieldInfo("intdv").getDocValuesType());
            SortedSetDocValues dv = reader.getSortedSetDocValues("stringdv");
            assertEquals(0, dv.nextDoc());
            assertEquals(0, dv.nextOrd());
            assertEquals(1, dv.nextOrd());
            assertEquals(SortedSetDocValues.NO_MORE_ORDS, dv.nextOrd());
            dv = reader.getSortedSetDocValues("booldv");
            assertEquals(0, dv.nextDoc());
            assertEquals(0, dv.nextOrd());
            assertEquals(1, dv.nextOrd());
            assertEquals(SortedSetDocValues.NO_MORE_ORDS, dv.nextOrd());
        } finally {
            searcherRef.decref();
        }
    }
}

/**
 * Tests the ability to do basic queries (without scoring, just match-only) on string docvalues
 * fields that are not inverted (indexed "forward" only)
 */
@Test
public void testStringDocValuesMatch() {
    assertU(adoc("id", "1", "stringdv", "b"));
    assertU(adoc("id", "2", "stringdv", "a"));
    assertU(adoc("id", "3", "stringdv", "c"));
    assertU(adoc("id", "4", "stringdv", "car"));
    assertU(adoc("id", "5", "stringdv", "dog", "stringdv", "cat"));
    assertU(commit());
    // string: termquery
    assertQ(req("q", "stringdv:car", "sort", "id asc"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=4]");
    // string: range query
    assertQ(req("q", "stringdv:[b TO d]", "sort", "id asc"), "//*[@numFound='4']", "//result/doc[1]/str[@name='id'][.=1]", "//result/doc[2]/str[@name='id'][.=3]", "//result/doc[3]/str[@name='id'][.=4]", "//result/doc[4]/str[@name='id'][.=5]");
    // string: prefix query
    assertQ(req("q", "stringdv:c*", "sort", "id asc"), "//*[@numFound='3']", "//result/doc[1]/str[@name='id'][.=3]", "//result/doc[2]/str[@name='id'][.=4]", "//result/doc[3]/str[@name='id'][.=5]");
    // string: wildcard query
    assertQ(req("q", "stringdv:c?r", "sort", "id asc"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=4]");
    // string: regexp query
    assertQ(req("q", "stringdv:/c[a-b]r/", "sort", "id asc"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=4]");
}

