@Test
public void testDatePointFieldRangeFacet() {
    String docValuesField = "number_p_dt_dv";
    String nonDocValuesField = "number_p_dt";
    int numValues = 10 * RANDOM_MULTIPLIER;
    int numBuckets = numValues / 2;
    List<Long> values, sortedValues;
    long min, max;
    DateGapCeiling gap;
    do {
        values = getRandomLongs(numValues, false, MAX_DATE_EPOCH_MILLIS);
        sortedValues = values.stream().sorted().collect(Collectors.toList());
        min = sortedValues.get(0);
        max = sortedValues.get(sortedValues.size() - 1);
    } while (max > MAX_DATE_EPOCH_MILLIS || min < MIN_DATE_EPOCH_MILLIS);
    long initialGap = BigInteger.valueOf(max).subtract(BigInteger.valueOf(min)).divide(BigInteger.valueOf(numBuckets)).longValueExact();
    gap = new DateGapCeiling(BigInteger.valueOf(max + initialGap).subtract(// padding for rounding
    BigInteger.valueOf(min)).divide(BigInteger.valueOf(numBuckets)).longValueExact());
    int[] bucketCount = new int[numBuckets];
    int bucketNum = 0;
    long minBucketVal = min;
    // System.err.println("min:" + Instant.ofEpochMilli(min) + "   max: " +
    // Instant.ofEpochMilli(max) + "   gap: " + gap);
    // System.err.println("bucketNum: " + bucketNum + "   minBucketVal: " +
    // Instant.ofEpochMilli(minBucketVal));
    for (long value : sortedValues) {
        // System.err.println("value: " + Instant.ofEpochMilli(value));
        while (value >= gap.addTo(minBucketVal)) {
            ++bucketNum;
            minBucketVal = gap.addTo(minBucketVal);
            // System.err.println("bucketNum: " + bucketNum + "   minBucketVal: " +
            // Instant.ofEpochMilli(minBucketVal));
        }
        ++bucketCount[bucketNum];
    }
    for (int i = 0; i < numValues; i++) {
        assertU(adoc("id", String.valueOf(i), docValuesField, Instant.ofEpochMilli(values.get(i)).toString(), nonDocValuesField, Instant.ofEpochMilli(values.get(i)).toString()));
    }
    assertU(commit());
    assertTrue(h.getCore().getLatestSchema().getField(docValuesField).hasDocValues());
    assertTrue(h.getCore().getLatestSchema().getField(docValuesField).getType() instanceof PointField);
    String[] testStrings = new String[numBuckets + 1];
    testStrings[numBuckets] = "//*[@numFound='" + numValues + "']";
    minBucketVal = min;
    for (int i = 0; i < numBuckets; ++i) {
        testStrings[i] = "//lst[@name='facet_counts']/lst[@name='facet_ranges']/lst[@name='" + docValuesField + "']/lst[@name='counts']/int[@name='" + Instant.ofEpochMilli(minBucketVal) + "'][.='" + bucketCount[i] + "']";
        minBucketVal = gap.addTo(minBucketVal);
    }
    long maxPlusGap = gap.addTo(max);
    assertQ(req("q", "*:*", "facet", "true", "facet.range", docValuesField, "facet.range.start", Instant.ofEpochMilli(min).toString(), "facet.range.end", Instant.ofEpochMilli(maxPlusGap).toString(), "facet.range.gap", gap.toString()), testStrings);
    assertQ(req("q", "*:*", "facet", "true", "facet.range", docValuesField, "facet.range.start", Instant.ofEpochMilli(min).toString(), "facet.range.end", Instant.ofEpochMilli(maxPlusGap).toString(), "facet.range.gap", gap.toString(), "facet.range.method", "dv"), testStrings);
    assertFalse(h.getCore().getLatestSchema().getField(nonDocValuesField).hasDocValues());
    assertTrue(h.getCore().getLatestSchema().getField(nonDocValuesField).getType() instanceof PointField);
    minBucketVal = min;
    for (int i = 0; i < numBuckets; ++i) {
        testStrings[i] = "//lst[@name='facet_counts']/lst[@name='facet_ranges']/lst[@name='" + nonDocValuesField + "']/lst[@name='counts']/int[@name='" + Instant.ofEpochMilli(minBucketVal).toString() + "'][.='" + bucketCount[i] + "']";
        minBucketVal = gap.addTo(minBucketVal);
    }
    maxPlusGap = gap.addTo(max);
    // Range Faceting with method = filter should work
    assertQ(req("q", "*:*", "facet", "true", "facet.range", nonDocValuesField, "facet.range.start", Instant.ofEpochMilli(min).toString(), "facet.range.end", Instant.ofEpochMilli(maxPlusGap).toString(), "facet.range.gap", gap.toString(), "facet.range.method", "filter"), testStrings);
    // this should actually use filter method instead of dv
    assertQ(req("q", "*:*", "facet", "true", "facet.range", nonDocValuesField, "facet.range.start", Instant.ofEpochMilli(min).toString(), "facet.range.end", Instant.ofEpochMilli(maxPlusGap).toString(), "facet.range.gap", gap.toString(), "facet.range.method", "dv"), testStrings);
}

