    assertQEx("Should fail as queries is not of type map", "Expected Map for 'queries', received [{}]", req("q", "*:*", "rows", "0", "json.queries", "[{}]"), SolrException.ErrorCode.BAD_REQUEST);
    assertQEx("Should fail as queries are null in JSON", "Expected Map for 'queries', received null", req("json", "{query:\"*:*\", queries:null}"), SolrException.ErrorCode.BAD_REQUEST);
    // range facets
    assertQEx("Should fail as 'other' is of type Map", "Expected list of string or comma separated string values for 'other', " + "received LinkedHashMap={} , path=facet/f", req("q", "*:*", "json.facet", "{f:{type:range, field:num_d, start:10, end:12, gap:1, other:{}}}"), SolrException.ErrorCode.BAD_REQUEST);
    assertQEx("Should fail as 'include' is of type Map", "Expected list of string or comma separated string values for 'include', " + "received LinkedHashMap={} , path=facet/f", req("q", "*:*", "json.facet", "{f:{type:range, field:num_d, start:10, end:12, gap:1, include:{}}}"), SolrException.ErrorCode.BAD_REQUEST);
    // missing start parameter
    assertQEx("Should Fail with missing field error", "Missing required parameter: 'start' , path=facet/f", req("q", "*:*", "json.facet", "{f:{type:range, field:num_d}}"), SolrException.ErrorCode.BAD_REQUEST);
    // missing end parameter
    assertQEx("Should Fail with missing field error", "Missing required parameter: 'end' , path=facet/f", req("q", "*:*", "json.facet", "{f:{type:range, field:num_d, start:10}}"), SolrException.ErrorCode.BAD_REQUEST);
    // missing gap parameter
    assertQEx("Should Fail with missing field error", "Missing required parameter: 'gap' , path=facet/f", req("q", "*:*", "json.facet", "{f:{type:range, field:num_d, start:10, end:12}}"), SolrException.ErrorCode.BAD_REQUEST);
    // invalid value for facet field
    assertQEx("Should Fail as args is of type long", "Expected string/map for facet field, received Long=2 , path=facet/facet", req("q", "*:*", "rows", "0", "json.facet.facet.field", "2"), SolrException.ErrorCode.BAD_REQUEST);
    // invalid value for facet query
    assertQEx("Should Fail as args is of type long for query", "Expected string/map for facet query, received Long=2 , path=facet/facet", req("q", "*:*", "rows", "0", "json.facet.facet.query", "2"), SolrException.ErrorCode.BAD_REQUEST);
    // valid facet field
    assertQ("Should pass as this is valid query", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s}}"));
    // invalid perSeg
    assertQEx("Should fail as perSeg is not of type boolean", "Expected boolean type for param 'perSeg' but got Long = 2 , path=facet/cat_s", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,perSeg:2}}"), SolrException.ErrorCode.BAD_REQUEST);
    assertQEx("Should fail as sort is invalid", "Invalid sort option 'bleh' for field 'cat_s'", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,sort:bleh}}"), SolrException.ErrorCode.BAD_REQUEST);
    assertQEx("Should fail as sort order is invalid", "Unknown Sort direction 'bleh'", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,sort:{count: bleh}}}"), SolrException.ErrorCode.BAD_REQUEST);
    // test for prelim_sort
    assertQEx("Should fail as prelim_sort is invalid", "Invalid prelim_sort option 'bleh' for field 'cat_s'", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,prelim_sort:bleh}}"), SolrException.ErrorCode.BAD_REQUEST);
    assertQEx("Should fail as prelim_sort map is invalid", "Invalid prelim_sort option '{bleh=desc}' for field 'cat_s'", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,prelim_sort:{bleh:desc}}}"), SolrException.ErrorCode.BAD_REQUEST);
    // with nested facet
    assertQEx("Should fail as prelim_sort is invalid", "Invalid sort option 'bleh' for field 'id'", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,sort:bleh,facet:" + "{bleh:\"unique(cat_s)\",id:{type:terms,field:id,sort:bleh}}}}"), SolrException.ErrorCode.BAD_REQUEST);
    assertQ("Should pass as sort is proper", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,sort:bleh,facet:" + "{bleh:\"unique(cat_s)\",id:{type:terms,field:id,sort:{bleh:desc},facet:{bleh:\"unique(id)\"}}}}}"));
}

@Test
public void testAggErrors() {
    ignoreException("aggregation");
    SolrException e = expectThrows(SolrException.class, () -> {
        h.query(req("q", "*:*", "json.facet", "{bleh:'div(2,4)'}"));
    });
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, e.code());
    assertThat(e.getMessage(), containsString("Expected multi-doc aggregation from 'div' but got per-doc function in input ('div(2,4)"));
    e = expectThrows(SolrException.class, () -> {
        h.query(req("q", "*:*", "json.facet", "{b:'agg(div(2,4))'}"));
    });
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, e.code());
    assertThat(e.getMessage(), containsString("Expected multi-doc aggregation from 'div' but got per-doc function in input ('agg(div(2,4))"));
    e = expectThrows(SolrException.class, () -> {
        h.query(req("q", "*:*", "json.facet", "{b:'agg(bleh(2,4))'}"));
    });
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, e.code());
    assertThat(e.getMessage(), containsString("Unknown aggregation 'bleh' in input ('agg(bleh(2,4))"));
    e = expectThrows(SolrException.class, () -> {
        h.query(req("q", "*:*", "json.facet", "{b:'bleh(2,4)'}"));
    });
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, e.code());
    assertThat(e.getMessage(), containsString("Unknown aggregation 'bleh' in input ('bleh(2,4)"));
    resetExceptionIgnores();
}

@Test
public void testMerge() throws Exception {
    doTestRefine(// the facet request
    "{x : {type:terms, field:X, limit:2, refine:true} }", // shard0 response
    "{x: {buckets:[{val:x1, count:5}, {val:x2, count:3}], more:true } }", // shard1 response
    "{x: {buckets:[{val:x2, count:4}, {val:x3, count:2}], more:true } }", // shard0 expected refinement info
    null, // shard1 expected refinement info
    "=={x:{_l:[x1]}}");
    // same test as above, but shard1 indicates it doesn't have any more results, so there shouldn't
    // be any refinement
    doTestRefine(// the facet request
    "{x : {type:terms, field:X, limit:2, refine:true} }", // shard0 response
    "{x: {buckets:[{val:x1, count:5}, {val:x2, count:3}],more:true } }", // shard1 response
    "{x: {buckets:[{val:x2, count:4}, {val:x3, count:2}] } }", // shard0 expected refinement info
    null, // shard1 expected refinement info  // without more:true, we should not attempt to get
    null);
    // same but with processEmpty:true we should check for refinement even if there isn't "more"
    doTestRefine("{x : {type:terms, field:X, limit:2, refine:true, facet: { processEmpty:true } } }", // shard0 response
    "{x: {buckets:[{val:x1, count:5}, {val:x2, count:3}],more:true } }", // shard1 response -- NO "more"
    "{x: {buckets:[{val:x2, count:4}] } }", // shard0 expected refinement info
    null, // shard1 expected refinement info
    "=={x:{_l:[x1]}}");
    // same test w/o refinement turned on (even though shards say they have more)
    doTestRefine(// the facet request
    "{x : {type:terms, field:X, limit:2} }", // shard0 response
    "{x: {buckets:[{val:x1, count:5}, {val:x2, count:3}], more:true } }", // shard1 response
    "{x: {buckets:[{val:x2, count:4}, {val:x3, count:2}], more:true } }", // shard0 expected refinement info
    null, // shard1 expected refinement info
    null);
    // same test, but nested in query facet
    doTestRefine(// the facet request
    "{top:{type:query, q:'foo_s:myquery', facet:{x : {type:terms, field:X, limit:2, refine:true} } } }", // shard0
    "{top: {x: {buckets:[{val:x1, count:5}, {val:x2, count:3}], more:true } } }", // response
    // shard1
    "{top: {x: {buckets:[{val:x2, count:4}, {val:x3, count:2}], more:true } } }", // response
    // shard0 expected refinement info
    null, // shard1 expected refinement info
    "=={top:{x:{_l:[x1]}}}");
    // same test w/o refinement turned on
    doTestRefine("{top:{type:query, q:'foo_s:myquery', facet:{x : {type:terms, field:X, limit:2, refine:false} } } }", // shard0 response
    "{top: {x: {buckets:[{val:x1, count:5}, {val:x2, count:3}] } } }", // shard1 response
    "{top: {x: {buckets:[{val:x2, count:4}, {val:x3, count:2}] } } }", null, null);
    // same test, but nested in a terms facet
    doTestRefine("{top:{type:terms, field:Afield, facet:{x : {type:terms, field:X, limit:2, refine:true} } } }", "{top: {buckets:[{val:'A', count:2, x:{buckets:[{val:x1, count:5},{val:x2, count:3}], more:true} } ] } }", "{top: {buckets:[{val:'A', count:1, x:{buckets:[{val:x2, count:4},{val:x3, count:2}], more:true} } ] } }", null, "=={top: {" + "_s:[  ['A' , {x:{_l:[x1]}} ]  ]" + "    }  " + "}");
    // same test, but nested in range facet
    doTestRefine("{top:{type:range, field:R, start:0, end:1, gap:1, facet:{x : {type:terms, field:X, limit:2, refine:true} } } }", "{top: {buckets:[{val:0, count:2, x:{buckets:[{val:x1, count:5},{val:x2, count:3}],more:true} } ] } }", "{top: {buckets:[{val:0, count:1, x:{buckets:[{val:x2, count:4},{val:x3, count:2}],more:true} } ] } }", null, "=={top: {" + "_s:[  [0 , {x:{_l:[x1]}} ]  ]" + "    }  " + "}");
    // same test, but now the range facet includes "other" buckets
    // (so we also verify that the "_actual_end" is echoed back)
    doTestRefine("{top:{type:range, other:all, field:R, start:0, end:1, gap:1, " + "      facet:{x : {type:terms, field:X, limit:2, refine:true} } } }", // phase #1
    "{top: {buckets:[{val:0, count:2, x:{more:true,buckets:[{val:x1, count:5},{val:x2, count:3}]} } ]," + "       before:{count:0},after:{count:0}," + "       between:{count:2,x:{more:true,buckets:[{val:x1, count:5},{val:x2, count:3}]} }," + "       '_actual_end':'does_not_matter_must_be_echoed_back' } }", "{top: {buckets:[{val:0, count:1, x:{more:true,buckets:[{val:x2, count:4},{val:x3, count:2}]} } ]," + "       before:{count:0},after:{count:0}," + "       between:{count:1,x:{more:true,buckets:[{val:x2, count:4},{val:x3, count:2}]} }," + "       '_actual_end':'does_not_matter_must_be_echoed_back' } }", // refinement...
    null, "=={top: {" + "    _s:[  [0 , {x:{_l:[x1]}} ]  ]," + "    between:{ x:{_l : [x1]} }," + "    '_actual_end':'does_not_matter_must_be_echoed_back'" + "} } ");
    // imagine that all the nodes we query in phase#1 are running "old" versions of solr that
    // don't know they are supposed to compute _actual_end. our merger should not fail or freak out
    // trust that in the phase#2 refinement request either:
    //  - the processor will re-compute it (if refine request goes to "new" version of solr)
    //  - the processor wouldn't know what to do with an _actual_end sent by the merger anyway
    doTestRefine("{top:{type:range, other:all, field:R, start:0, end:1, gap:1, " + "      facet:{x : {type:terms, field:X, limit:2, refine:true} } } }", // phase #1
    "{top: {buckets:[{val:0, count:2, x:{more:true,buckets:[{val:x1, count:5},{val:x2, count:3}]} } ]," + "       before:{count:0},after:{count:0}," + "       between:{count:2,x:{more:true,buckets:[{val:x1, count:5},{val:x2, count:3}]} }," + // no actual_end
    "       } }", "{top: {buckets:[{val:0, count:1, x:{more:true,buckets:[{val:x2, count:4},{val:x3, count:2}]} } ]," + "       before:{count:0},after:{count:0}," + "       between:{count:1,x:{more:true,buckets:[{val:x2, count:4},{val:x3, count:2}]} }," + // no actual_end
    "       } }", // refinement...
    null, "=={top: {" + "    _s:[  [0 , {x:{_l:[x1]}} ]  ]," + "    between:{ x:{_l : [x1]} }" + "} } ");
    // a range face w/o any sub facets shouldn't require any refinement
    doTestRefine("{top:{type:range, other:all, field:R, start:0, end:3, gap:2 } }", // phase #1
    "{top: {buckets:[{val:0, count:2}, {val:2, count:2}]," + "       before:{count:3},after:{count:47}," + "       between:{count:5}," + "       } }", "{top: {buckets:[{val:0, count:2}, {val:2, count:19}]," + "       before:{count:22},after:{count:0}," + "       between:{count:21}," + "       } }", // refinement...
    null, null);
    // same test, but nested in range facet with ranges
    doTestRefine("{top:{type:range, field:R, ranges:[{from:0, to:1}], facet:{x : {type:terms, field:X, limit:2, refine:true} } } }", "{top: {buckets:[{val:\"[0,1)\", count:2, x:{buckets:[{val:x1, count:5},{val:x2, count:3}],more:true} } ] } }", "{top: {buckets:[{val:\"[0,1)\", count:1, x:{buckets:[{val:x2, count:4},{val:x3, count:2}],more:true} } ] } }", null, "=={top: {" + "_s:[  [\"[0,1)\" , {x:{_l:[x1]}} ]  ]" + "    }  " + "}");
    doTestRefine("{top:{type:range, field:R, ranges:[{from:\"*\", to:1}], facet:{x : {type:terms, field:X, limit:2, refine:true} } } }", "{top: {buckets:[{val:\"[*,1)\", count:2, x:{buckets:[{val:x1, count:5},{val:x2, count:3}],more:true} } ] } }", "{top: {buckets:[{val:\"[*,1)\", count:1, x:{buckets:[{val:x2, count:4},{val:x3, count:2}],more:true} } ] } }", null, "=={top: {" + "_s:[  [\"[*,1)\" , {x:{_l:[x1]}} ]  ]" + "    }  " + "}");
    // a range facet w/o any sub facets shouldn't require any refinement
    // other and include ignored for ranges
    doTestRefine("{top:{type:range, other:all, field:R, ranges:[{from:0, to:2},{from:2, to:3}] } }", // phase #1
    "{top: {buckets:[{val:\"[0,2)\", count:2}, {val:\"[2,3)\", count:2}]," + "       } }", "{top: {buckets:[{val:\"[0,2)\", count:2}, {val:\"[2,3)\", count:19}]," + "       } }", // refinement...
    null, null);
    // for testing partial _p, we need a partial facet within a partial facet
    doTestRefine("{top:{type:terms, field:Afield, refine:true, limit:1, facet:{x : {type:terms, field:X, limit:1, refine:true} } } }", "{top: {buckets:[{val:'A', count:2, x:{buckets:[{val:x1, count:5},{val:x2, count:3}],more:true} } ],more:true } }", "{top: {buckets:[{val:'B', count:1, x:{buckets:[{val:x2, count:4},{val:x3, count:2}],more:true} } ],more:true } }", null, "=={top: {" + "_p:[  ['A' , {x:{_l:[x1]}} ]  ]" + "    }  " + "}");
    // test partial _p under a missing bucket
    doTestRefine("{top:{type:terms, field:Afield, refine:true, limit:1, missing:true, facet:{x : {type:terms, field:X, limit:1, refine:true} } } }", "{top: {buckets:[], missing:{count:12, x:{buckets:[{val:x2, count:4},{val:x3, count:2}],more:true} }  } }", "{top: {buckets:[], missing:{count:10, x:{buckets:[{val:x1, count:5},{val:x4, count:3}],more:true} }  } }", "=={top: {" + "missing:{x:{_l:[x1]}}" + "    }  " + "}", null);
}

@Test
public void testMergeWithOverrefine() throws Exception {
    // overrefine heuristic should use explicit overrequest as default
    doTestRefine("{x : {type:terms, field:X, limit:1, overrequest:1, sort:'count asc', refine:true} }", //
    "{x: {buckets:[{val:x1, count:3}, {val:x2, count:5}, {val:x9, count:42}, {val:x0, count:42}], more:true } }", "{x: {buckets:[{val:x2, count:2}, {val:x3, count:4}, {val:x7, count:66}, {val:x8, count:66}], more:true } }", //
    "=={x:{_l:[x3]}}", "=={x:{_l:[x1]}}");
    doTestRefine("{x : {type:terms, field:X, limit:1, overrequest:0, sort:'count asc', refine:true} }", //
    "{x: {buckets:[{val:x1, count:3}, {val:x2, count:5}, {val:x9, count:42}, {val:x0, count:42}], more:true } }", "{x: {buckets:[{val:x2, count:2}, {val:x3, count:4}, {val:x7, count:66}, {val:x8, count:66}], more:true } }", //
    null, "=={x:{_l:[x1]}}");
    // completely implicit heuristic when no explicit overrequest
    // limit=1 + 10% + 4 =~ 5 total, but x2 is fully populated so only the other 4 "lowest" should
    // be refined
    doTestRefine("{x : {type:terms, field:X, limit:1, sort:'count asc', refine:true} }", //
    "{x: {buckets:[{val:x1, count:3}, {val:x2, count:5}, {val:x9, count:42}, {val:x0, count:42}], more:true } }", "{x: {buckets:[{val:x2, count:2}, {val:x3, count:4}, {val:x7, count:66}, {val:x8, count:66}], more:true } }", //
    "=={x:{_l:[x3]}}", "=={x:{_l:[x1,x0,x9]}}");
    // when using (default) mincount (or mincount=0) sort="count desc" should eliminate need for
    // overrefine (regardless of whether any explicit overrequest is specified)
    for (String extra : Arrays.asList("", ", mincount:0", ", mincount:1", ", overrequest:3", ", overrequest:3, mincount:0")) {
        // w/o any overrefinement, we should only need to backfill x1 & x3 (x2 already fully
        // populated)
        doTestRefine("{x : {type:terms, field:X, limit:3, sort:'count desc', refine:true" + extra + " } }", //
        "{x: {buckets:[{val:x1, count:29}, {val:x2, count:15}, {val:x9, count:7}, {val:x0, count:7}], more:true } }", "{x: {buckets:[{val:x2, count:20}, {val:x3, count:12}, {val:x7, count:7}, {val:x8, count:7}], more:true } }", //
        "=={x:{_l:[x3]}}", "=={x:{_l:[x1]}}");
    }
    // with 1<mincount, even sort="count desc" should trigger heuristic overrefinement
    // limit=1 + 10% + 4 =~ 5 total, but x2 is fully populated so only the other 4 "highest" should
    // be refined
    doTestRefine("{x : {type:terms, field:X, limit:1, mincount:5, sort:'count desc', refine:true } }", //
    "{x: {buckets:[{val:x1, count:29}, {val:x2, count:15}, {val:x9, count:5}, {val:x0, count:3}], more:true } }", "{x: {buckets:[{val:x2, count:20}, {val:x3, count:12}, {val:x7, count:7}, {val:x8, count:4}], more:true } }", //
    "=={x:{_l:[x3,x7]}}", "=={x:{_l:[x1,x9]}}");
    // explicit overrefine
    // limit=1 + overrefine=2 == 3 total, but x2 is fully populated, so only x1 & x3 need refined
    doTestRefine("{x : {type:terms, field:X, limit:1, overrequest:1, overrefine:2, sort:'count asc', refine:true} }", //
    "{x: {buckets:[{val:x1, count:3}, {val:x2, count:5}, {val:x9, count:42}, {val:x0, count:42}], more:true } }", "{x: {buckets:[{val:x2, count:2}, {val:x3, count:9}, {val:x7, count:66}, {val:x8, count:66}], more:true } }", //
    "=={x:{_l:[x3]}}", "=={x:{_l:[x1]}}");
    // explicit overrefine with 0<offset
    // offset=1 + limit=1 + overrefine=2 == 4 total, but x2 is fully populated, so only x1,x3,x9
    // need refined
    doTestRefine("{x : {type:terms, field:X, limit:1, offset:1, overrequest:1, overrefine:2, sort:'count asc', refine:true} }", //
    "{x: {buckets:[{val:x1, count:3}, {val:x2, count:5}, {val:x9, count:42}, {val:x0, count:43}], more:true } }", "{x: {buckets:[{val:x2, count:2}, {val:x3, count:9}, {val:x7, count:66}, {val:x8, count:67}], more:true } }", //
    "=={x:{_l:[x3]}}", "=={x:{_l:[x1,x9]}}");
    // heuristic refinement of nested facets
    // limit=1 + 10% + 4 =~ 5 total (at each level)
    // -> x2 is fully populated and child buckets are consistent - no refinement needed at all
    // -> x4 has counts from both shards, but child buckets don't align perfectly
    //
    // For (test) simplicity, only x3 and x4 have enough (total) y buckets to prove that the
    // sub-facet
    // overrefine heuristic is finite...
    // -> x3 has 6 total sub-facet buckets, only "lowest 5" should be refined on missing shard
    // -> x4 also has 6 total sub-facet buckets, but only 3 need refined since 2 already fully
    // populated
    doTestRefine("{x:{type:terms, field:X, limit:1, sort:'count asc', refine:true, " + "    facet:{y : {type:terms, field:X, limit:1, sort:'count asc', refine:true} } } }", //
    "{x: {buckets:[" + "       {val:'x1', count:1, y:{buckets:[{val:y11, count:1},{val:y12, count:3}], more:true} }, " + "       {val:'x2', count:2, y:{buckets:[{val:y21, count:1},{val:y22, count:3}], more:true} }, " + "       {val:'x4', count:3, y:{buckets:[{val:y41, count:1},{val:y4a, count:3},     " + "                                       {val:y42, count:4},{val:y4d, count:5}], more:true} }, " + "       {val:'x5', count:4, y:{buckets:[{val:y51, count:1},{val:y52, count:3}], more:true} }, " + "    ], more:true } }", "{x: {buckets:[" + "       {val:'x3', count:1, y:{buckets:[{val:y31, count:1},{val:y32, count:2},     " + "                                       {val:y33, count:3},{val:y34, count:4}, " + "                                       {val:y35, count:5},{val:y36, count:6}], more:true} }, " + "       {val:'x2', count:2, y:{buckets:[{val:y21, count:1},{val:y22, count:3}], more:true} }, " + "       {val:'x4', count:3, y:{buckets:[{val:y41, count:1},{val:y4b, count:3},     " + "                                       {val:y42, count:4},{val:y4c, count:9}], more:true} }, " + "       {val:'x9', count:9, y:{buckets:[{val:y91, count:1},{val:y92, count:3}], more:true} }, " + "    ], more:true } }", //
