// attempt to reproduce https://github.com/Heliosearch/heliosearch/issues/33
@Test
public void testComplex() throws Exception {
    Random r = random();
    Client client = Client.localClient;
    double price_low = 11000;
    double price_high = 100000;
    ModifiableSolrParams p = params("make_s", "make_s", "model_s", "model_s", "price_low", Double.toString(price_low), "price_high", Double.toString(price_high));
    MacroExpander m = new MacroExpander(p.getMap());
    String make_s = m.expand("${make_s}");
    String model_s = m.expand("${model_s}");
    client.deleteByQuery("*:*", null);
    int nDocs = 99;
    String[] makes = { "honda", "toyota", "ford", null };
    Double[] prices = { 10000.0, 30000.0, 50000.0, 0.0, null };
    String[] honda_models = { "accord", "civic", "fit", "pilot", null };
    // make sure this is alphabetized to match tiebreaks in index
    String[] other_models = { "z1", "z2", "z3", "z4", "z5", "z6", null };
    int nHonda = 0;
    final int[] honda_model_counts = new int[honda_models.length];
    for (int i = 0; i < nDocs; i++) {
        SolrInputDocument doc = sdoc("id", Integer.toString(i));
        Double price = rand(prices);
        if (price != null) {
            doc.addField("cost_f", price);
        }
        boolean matches_price = price != null && price >= price_low && price <= price_high;
        String make = rand(makes);
        if (make != null) {
            doc.addField(make_s, make);
        }
        if ("honda".equals(make)) {
            int modelNum = r.nextInt(honda_models.length);
            String model = honda_models[modelNum];
            if (model != null) {
                doc.addField(model_s, model);
            }
            if (matches_price) {
                nHonda++;
                honda_model_counts[modelNum]++;
            }
        } else if (make == null) {
            // add some docs w/ model but w/o make
            doc.addField(model_s, rand(honda_models));
        } else {
            // other makes
            // add some docs w/ model but w/o make
            doc.addField(model_s, rand(other_models));
        }
        client.add(doc, null);
        if (r.nextInt(10) == 0) {
            // dup, causing a delete
            client.add(doc, null);
        }
        if (r.nextInt(20) == 0) {
            // force new seg
            client.commit();
        }
    }
    client.commit();
    // now figure out top counts
    List<Integer> idx = new ArrayList<>();
    for (int i = 0; i < honda_model_counts.length - 1; i++) {
        idx.add(i);
    }
    idx.sort((o1, o2) -> {
        int cmp = honda_model_counts[o2] - honda_model_counts[o1];
        return cmp == 0 ? o1 - o2 : cmp;
    });
    // straight query facets
    client.testJQ(params(p, "q", "*:*", "rows", "0", "fq", "+${make_s}:honda +cost_f:[${price_low} TO ${price_high}]", "json.facet", "{makes:{terms:{field:${make_s}, facet:{models:{terms:{field:${model_s}, limit:2, mincount:0}}}}" + "}}", "facet", "true", "facet.pivot", "make_s,model_s", "facet.limit", "2"), "facets=={count:" + nHonda + ", makes:{buckets:[{val:honda, count:" + nHonda + ", models:{buckets:[" + "{val:" + honda_models[idx.get(0)] + ", count:" + honda_model_counts[idx.get(0)] + "}," + "{val:" + honda_models[idx.get(1)] + ", count:" + honda_model_counts[idx.get(1)] + "}]}" + "}]}}");
}

@Test
public void testExplicitQueryDomain() throws Exception {
    Client client = Client.localClient();
    indexSimple(client);
    {
        // simple 'query' domain
        // the facet buckets for all the requests below should be identical
        // only the numFound & top level facet count should differ
        final String expectedFacets = "facets/w=={ buckets:[" + "  { val:'NJ', count:2}, " + "  { val:'NY', count:1} ] }";
        assertJQ(req("rows", "0", "q", "cat_s:B", "json.facet", "{w: {type:terms, field:'where_s'}}"), "response/numFound==3", "facets/count==3", expectedFacets);
        assertJQ(req("rows", "0", "q", "id:3", "json.facet", "{w: {type:terms, field:'where_s', domain: { query:'cat_s:B' }}}"), "response/numFound==1", "facets/count==1", expectedFacets);
        assertJQ(req("rows", "0", "q", "*:*", "fq", "-*:*", "json.facet", "{w: {type:terms, field:'where_s', domain: { query:'cat_s:B' }}}"), "response/numFound==0", "facets/count==0", expectedFacets);
        assertJQ(req("rows", "0", "q", "*:*", "fq", "-*:*", "domain_q", "cat_s:B", "json.facet", "{w: {type:terms, field:'where_s', domain: { query:{param:domain_q} }}}"), "response/numFound==0", "facets/count==0", expectedFacets);
    }
    {
        // a nested explicit query domain
        // for all the "top" buckets, the subfacet should have identical sub-buckets
        final String expectedSubBuckets = "{ buckets:[ { val:'B', count:3}, { val:'A', count:2} ] }";
        assertJQ(req("rows", "0", "q", "num_i:[0 TO *]", "json.facet", "{w: {type:terms, field:'where_s', " + "     facet: { c: { type:terms, field:'cat_s', domain: { query:'*:*' }}}}}"), "facets/w=={ buckets:[" + "  { val:'NJ', count:2, c: " + expectedSubBuckets + "}, " + "  { val:'NY', count:1, c: " + expectedSubBuckets + "} " + "] }");
    }
    {
        // an (effectively) empty query should produce an error
        ignoreException("'query' domain can not be null");
        ignoreException("'query' domain must not evaluate to an empty list");
        for (String raw : Arrays.asList("null", "[ ]", "{param:bogus}")) {
            expectThrows(SolrException.class, () -> {
                assertJQ(req("rows", "0", "q", "num_i:[0 TO *]", "json.facet", "{w: {type:terms, field:'where_s', " + "     facet: { c: { type:terms, field:'cat_s', domain: { query: " + raw + " }}}}}"));
            });
        }
    }
}

@Test
public void testSimpleSKG() throws Exception {
    Client client = Client.localClient();
    indexSimple(client);
    // using relatedness() as a top level stat, not nested under any facet
    // (not particularly useful, but shouldn't error either)
    assertJQ(req("q", "cat_s:[* TO *]", "rows", "0", "fore", "where_s:NY", "back", "*:*", "json.facet", " { skg: 'relatedness($fore,$back)' }"), "facets=={" + "   count:5, " + "   skg : { relatedness: 0.00699," + "           foreground_popularity: 0.33333," + "           background_popularity: 0.83333," + "   } }");
    // simple single level facet w/skg stat & (re)sorting
    for (String sort : Arrays.asList("sort:'index asc'", "sort:'y desc'", "sort:'z desc'", "sort:'skg desc'", "prelim_sort:'count desc', sort:'index asc'", "prelim_sort:'count desc', sort:'y desc'", "prelim_sort:'count desc', sort:'z desc'", "prelim_sort:'count desc', sort:'skg desc'")) {
        // the relatedness score of each of our cat_s values is (conveniently) also alphabetical
        // order, (and the same order as 'sum(num_i) desc' & 'min(num_i) desc')
        //
        // So all of these re/sort options should produce identical output (since the num buckets is <
        // limit)
        // - Testing "index" sort allows the randomized use of "stream" processor as default to be
        // tested.
        // - Testing (re)sorts on other stats sanity checks code paths where relatedness() is a
        // "deferred" Agg
