            // results shouldn't change regardless of our limit param
            assertJQ(req("q", "cat_s:[* TO *]", "rows", "0", "fore", "where_s:NY", "back", "*:*", "json.facet", "" + "{x: { type: terms, field: 'cat_s', " + sort + limit + "      facet: { skg: 'relatedness($fore,$back)', y:'sum(num_i)', z:'min(num_i)' } } }"), "facets=={count:5, x:{ buckets:[" + "   { val:'A', count:2, y:5.0, z:2, " + "     skg : { relatedness: 0.00554, " + // + "             foreground_count: 1, "
