            "             foreground_popularity: 0.16667," + "             background_popularity: 0.33333, }," + "   }, " + "   { val:'B', count:3, y:-3.0, z:-5, " + // perfectly average and uncorrelated
            "     skg : { relatedness: 0.0, " + // + "             foreground_count: 1, "
            // + "             foreground_size: 2, "
            // + "             background_count: 3, "
            // + "             background_size: 6,"
            "             foreground_popularity: 0.16667," + "             background_popularity: 0.5 }," + "   } ] } } ");
            // same query with a prefix of 'B' should produce only a single bucket with exact same
