            assertJQ(req("q", "cat_s:[* TO *]", "rows", "0", "fore", "where_s:NY", "back", "*:*", "json.facet", "" + "{x: { type: terms, field: 'cat_s', prefix:'B', " + sort + limit + "      facet: { skg: 'relatedness($fore,$back)', y:'sum(num_i)', z:'min(num_i)' } } }"), "facets=={count:5, x:{ buckets:[" + "   { val:'B', count:3, y:-3.0, z:-5, " + // perfectly average and uncorrelated
