    assertQ(req("fl", "*,score", "q", "{!func}payload(vals_dpf,x,0.0,min)"), "//float[@name='score']='19.0'");
    assertQ(req("fl", "*,score", "q", "{!func}payload(vals_dpf,x,0.0,max)"), "//float[@name='score']='37.0'");
