    assertQ(req("q", random().nextBoolean() ? "{!filters param=$child.fq excludeTags=firstTag,secondTag v=$gchq}" : random().nextBoolean() ? "{!filters param=$thereAreNoLikeThese v=$gchq}" : "{!filters v=$gchq}", "child.fq", "{!tag=firstTag}childparent_s:e", "child.fq", "{!tag=secondTag}child_s:l", "gchq", "child_s:[* TO *]"), "//*[@numFound='18']");
    /*
    The below is admittedly a weird request; but QParser param dereferencing provides no way to
    distinguish between `{!filters param=}` and `{!filters param=$fqs}` where `fqs` param is
    absent. Because we want to support the latter case, we must also support the former, even it
    would arguably make sense to throw a syntax error in the former case.
     */
    assertQ("should support weird absent param spec", req("q", "{!filters v=$gchq param=}\"", "gchq", "child_s:[* TO *]"), "//*[@numFound='18']");
    // omit main query
    assertQ(req("q", "{!filters param=$child.fq}", "child.fq", "{!tag=firstTag}childparent_s:(e f)", "child.fq", "{!tag=secondTag}child_s:l"), "//*[@numFound='2']");
    // all excluded, matching all
    assertQ(req("q", "{!filters param=$child.fq excludeTags=firstTag,secondTag}", "child.fq", "{!tag=firstTag}childparent_s:(e f)", "child.fq", "{!tag=secondTag}child_s:l"), "//*[@numFound='42']");
    assertQ(req(// excluding top level
    "q", "{!filters param=$child.fq excludeTags=bot,top v=$gchq}", "child.fq", // 6 ls remains
    "{!tag=secondTag}child_s:l", "gchq", "{!tag=top}childparent_s:e"), "//*[@numFound='6']");
    assertQ(req(// top and filter are excluded, got all results
    "q", "{!filters excludeTags=bot,secondTag,top v=$gchq}", "child.fq", "{!tag=secondTag}child_s:l", "gchq", "{!tag=top}childparent_s:e"), "//*[@numFound='42']");
}

@Test
public void testFiltersCache() throws SyntaxError, IOException {
    final String[] elFilterQuery = new String[] { "q", "{!filters param=$child.fq v=$gchq}", "child.fq", "childparent_s:e", "child.fq", "child_s:l", "gchq", "child_s:[* TO *]" };
    assertQ("precondition: single doc match", req(elFilterQuery), elChild);
    final Query query;
    try (final SolrQueryRequest req = req(elFilterQuery)) {
        QParser parser = QParser.getParser(req.getParams().get("q"), null, req);
        query = parser.getQuery();
        final TopDocs topDocs = req.getSearcher().search(query, 10);
        assertEquals(1, topDocs.totalHits.value);
    }
    assertU(adoc("id", "12275", "child_s", "l", "childparent_s", "e"));
    assertU(commit());
    assertQ(// cache=false
    "here we rely on autowarming for catching cache leak", req(elFilterQuery), "//*[@numFound='2']");
    try (final SolrQueryRequest req = req()) {
        final int count = req.getSearcher().count(query);
        assertEquals("expecting new doc is visible to old query", 2, count);
    }
}

