@Test
public void test() throws Exception {
    // add just one document (docid 0)
    StringWriter w = new StringWriter();
    XML.escapeCharData(randomXmlUsableUnicodeString(), w);
    String bigFieldValue = w.toString();
    assertU(adoc(ID_FLD, "101", LAZY_FIELD, "lzy", BIG_FIELD, bigFieldValue));
    assertU(commit());
    // trigger the ID_FLD to get into the doc cache; don't reference other fields
    // eager load ID_FLD; rest are lazy
    assertQ(req("q", "101", "df", ID_FLD, "fl", ID_FLD));
    // fetch the document; we know it will be from the documentCache, docId 0
    final Document d = h.getCore().withSearcher(searcher -> searcher.getDocFetcher().doc(0));
    assertEager(d, ID_FLD);
    assertLazyNotLoaded(d, LAZY_FIELD);
    assertLazyNotLoaded(d, BIG_FIELD);
    // trigger load of LAZY_FIELD
    assertQ(req("q", "101", "df", ID_FLD, "fl", LAZY_FIELD));
    assertEager(d, ID_FLD);
    // loaded now
    assertLazyLoaded(d, LAZY_FIELD);
    // because big fields are handled separately
    assertLazyNotLoaded(d, BIG_FIELD);
    // trigger load of BIG_FIELD
    assertQ(req("q", "101", "df", ID_FLD, "fl", BIG_FIELD));
    assertEager(d, ID_FLD);
    assertLazyLoaded(d, LAZY_FIELD);
    // loaded now
    assertLazyLoaded(d, BIG_FIELD);
    assertEquals(bigFieldValue, d.getField(BIG_FIELD).stringValue());
}

