@Test
public void knnQueryAsSubQuery() {
    final SolrParams common = params("fl", "id", "vec", "[1.0, 2.0, 3.0, 4.0]");
    final String filt = "id:(2 4 7 9 8 20 3)";
    // When knn parser is a subquery, it should not pre-filter on any global fq params
    // topK -> 1,4,2,10,3 -> fq -> 4,2,3
    assertQ(req(common, "fq", filt, "q", "*:* AND {!knn f=vector topK=5 v=$vec}"), "//result[@numFound='3']", "//result/doc[1]/str[@name='id'][.='4']", "//result/doc[2]/str[@name='id'][.='2']", "//result/doc[3]/str[@name='id'][.='3']");
    // topK -> 1,4,2,10,3 + '8' -> fq -> 4,2,3,8
    assertQ(req(common, "fq", filt, "q", "id:8^=0.01 OR {!knn f=vector topK=5 v=$vec}"), "//result[@numFound='4']", "//result/doc[1]/str[@name='id'][.='4']", "//result/doc[2]/str[@name='id'][.='2']", "//result/doc[3]/str[@name='id'][.='3']", "//result/doc[4]/str[@name='id'][.='8']");
}

@Test
public void knnQueryAsSubQuery_withPreFilter() {
    final SolrParams common = params("fl", "id", "vec", "[1.0, 2.0, 3.0, 4.0]");
    final String filt = "id:(2 4 7 9 8 20 3)";
    // knn subquery should still accept `preFilter` local param
    // filt -> topK -> 4,2,3,7,9
    assertQ(req(common, "q", "*:* AND {!knn f=vector topK=5 preFilter='" + filt + "' v=$vec}"), "//result[@numFound='5']", "//result/doc[1]/str[@name='id'][.='4']", "//result/doc[2]/str[@name='id'][.='2']", "//result/doc[3]/str[@name='id'][.='3']", "//result/doc[4]/str[@name='id'][.='7']", "//result/doc[5]/str[@name='id'][.='9']");
    // it should not pre-filter on any global fq params
    // filt -> topK -> 4,2,3,7,9 -> fq -> 3,9
    assertQ(req(common, "fq", "id:(1 9 20 3 5 6 8)", "q", "*:* AND {!knn f=vector topK=5 preFilter='" + filt + "' v=$vec}"), "//result[@numFound='2']", "//result/doc[1]/str[@name='id'][.='3']", "//result/doc[2]/str[@name='id'][.='9']");
    // filt -> topK -> 4,2,3,7,9 + '8' -> fq -> 8,3,9
    assertQ(req(common, "fq", "id:(1 9 20 3 5 6 8)", "q", "id:8^=100 OR {!knn f=vector topK=5 preFilter='" + filt + "' v=$vec}"), "//result[@numFound='3']", "//result/doc[1]/str[@name='id'][.='8']", "//result/doc[2]/str[@name='id'][.='3']", "//result/doc[3]/str[@name='id'][.='9']");
}

