@Test
public void knnQueryWithMultiSelectFaceting_excludeTags() {
    // NOTE: faceting on id is not very realistic,
    // but it confirms what we care about re:filters w/o needing extra fields.
    final String facet_xpath = "//lst[@name='facet_fields']/lst[@name='id']/int";
    final String vectorToSearch = "[1.0, 2.0, 3.0, 4.0]";
    final SolrParams common = params("fl", "id", "indent", "true", "q", "{!knn f=vector topK=5 excludeTags=facet_click v=$vec}", "vec", vectorToSearch, // mimicing "inStock:true"
    "fq", "-id:(2 3)", "facet", "true", "facet.mincount", "1", "facet.field", "{!ex=facet_click}id");
    // initial query, with basic pre-filter and facet counts
    assertQ(req(common), "//result[@numFound='5']", "//result/doc[1]/str[@name='id'][.='1']", "//result/doc[2]/str[@name='id'][.='4']", "//result/doc[3]/str[@name='id'][.='10']", "//result/doc[4]/str[@name='id'][.='7']", "//result/doc[5]/str[@name='id'][.='5']", "*[count(" + facet_xpath + ")=5]", facet_xpath + "[@name='1'][.='1']", facet_xpath + "[@name='4'][.='1']", facet_xpath + "[@name='10'][.='1']", facet_xpath + "[@name='7'][.='1']", facet_xpath + "[@name='5'][.='1']");
    // drill down on a single facet constraint
    // multi-select means facet counts shouldn't change
    // (this proves the knn isn't pre-filtering on the 'facet_click' fq)
    assertQ(req(common, "fq", "{!tag=facet_click}id:(4)"), "//result[@numFound='1']", "//result/doc[1]/str[@name='id'][.='4']", "*[count(" + facet_xpath + ")=5]", facet_xpath + "[@name='1'][.='1']", facet_xpath + "[@name='4'][.='1']", facet_xpath + "[@name='10'][.='1']", facet_xpath + "[@name='7'][.='1']", facet_xpath + "[@name='5'][.='1']");
    // drill down on an additional facet constraint
    // multi-select means facet counts shouldn't change
    // (this proves the knn isn't pre-filtering on the 'facet_click' fq)
