@Test
public void vecSimQueryAsSubQuery() {
    final SolrParams common = params("fl", "id", "vec", "[1.0, 2.0, 3.0, 4.0]");
    final String filt = "id:(2 4 7 9 8 20)";
    // When vecSim parser is a subquery, it should not pre-filter on any global fq params
    // minReturn -> 1,4,2,10,3,7,5,6 -> fq -> 4,2,7
    assertQ(req(common, "fq", filt, "q", "*:* AND {!vectorSimilarity f=vector minReturn=0.8 v=$vec}"), "//result[@numFound='3']", "//result/doc[1]/str[@name='id'][.='4']", "//result/doc[2]/str[@name='id'][.='2']", "//result/doc[3]/str[@name='id'][.='7']");
    // minReturn -> 1,4,2,10,3,7,5,6 + '8' -> fq -> 4,2,7,8
    assertQ(req(common, "fq", filt, "q", "id:8^=0.01 OR {!vectorSimilarity f=vector minReturn=0.8 v=$vec}"), "//result[@numFound='4']", "//result/doc[1]/str[@name='id'][.='4']", "//result/doc[2]/str[@name='id'][.='2']", "//result/doc[3]/str[@name='id'][.='7']", "//result/doc[4]/str[@name='id'][.='8']");
}

