    assertQ(req(common, "q", "*:* AND {!vectorSimilarity f=vector minReturn=0.8 preFilter='" + filt + "' v=$vec}"), "//result[@numFound='4']", "//result/doc[1]/str[@name='id'][.='4']", "//result/doc[2]/str[@name='id'][.='2']", "//result/doc[3]/str[@name='id'][.='3']", "//result/doc[4]/str[@name='id'][.='7']");
    // it should not pre-filter on any global fq params
    // filt -> minReturn -> 4,2,3,7 -> fq -> 3,7
    assertQ(req(common, "fq", "id:(1 9 20 3 5 7 8)", "q", "*:* AND {!vectorSimilarity f=vector minReturn=0.8 preFilter='" + filt + "' v=$vec}"), "//result[@numFound='2']", "//result/doc[1]/str[@name='id'][.='3']", "//result/doc[2]/str[@name='id'][.='7']");
    // filt -> minReturn -> 4,2,3,7 + '8' -> fq -> 8,3,7
    assertQ(req(common, "fq", "id:(1 9 20 3 5 7 8)", "q", "id:8^=100 OR {!vectorSimilarity f=vector minReturn=0.8 preFilter='" + filt + "' v=$vec}"), "//result[@numFound='3']", "//result/doc[1]/str[@name='id'][.='8']", "//result/doc[2]/str[@name='id'][.='3']", "//result/doc[3]/str[@name='id'][.='7']");
