    final String filterTermQuery = "filter(" + termQuery + ")";
    final int expectNumFound = 1;
    final String expectNumFoundXPath = "/response/numFound==" + expectNumFound;
    h.reload();
    assertJQ(req("q", termQuery, "indent", "true"), expectNumFoundXPath);
    assertEquals(0, lookupFilterCacheInserts(h.getCore()));
    h.reload();
    assertJQ(req("q", filterTermQuery, "indent", "true"), expectNumFoundXPath);
    assertEquals(1, lookupFilterCacheInserts(h.getCore()));
    h.reload();
    assertJQ(req("q", "*:*", "indent", "true", "fq", "{!cache=false}field_s:d0"), expectNumFoundXPath);
    assertEquals(0, lookupFilterCacheInserts(h.getCore()));
    h.reload();
    assertJQ(req("q", "*:*", "indent", "true", "fq", "{!cache=true}field_s:d0"), expectNumFoundXPath);
    assertEquals(1, lookupFilterCacheInserts(h.getCore()));
    h.reload();
    assertJQ(req("q", "*:*", "indent", "true", "fq", "{!cache=false}filter(field_s:d0)"), expectNumFoundXPath);
    assertEquals(1, lookupFilterCacheInserts(h.getCore()));
    h.reload();
    assertJQ(req("q", "*:*", "indent", "true", "fq", "{!cache=true}filter(field_s:d0)"), expectNumFoundXPath);
    assertEquals(1, lookupFilterCacheInserts(h.getCore()));
    h.reload();
    assertJQ(req("q", "*:*", "indent", "true", "fq", termQuery), expectNumFoundXPath);
    assertEquals(1, lookupFilterCacheInserts(h.getCore()));
    h.reload();
    assertJQ(req("q", "*:*", "indent", "true", "fq", filterTermQuery), expectNumFoundXPath);
    assertEquals(1, lookupFilterCacheInserts(h.getCore()));
    h.reload();
    SolrCore core = h.getCore();
    Map<String, Object> filterCacheMetrics;
    final String termQuery2 = "{!term f=field_s v='d1'}";
    final String filterTermQuery2 = "filter(" + termQuery2 + ")";
    assertJQ(req("q", "*:*", "indent", "true", "fq", "{!bool cache=false should=$ftq should=$ftq2}", "ftq", filterTermQuery, "ftq2", filterTermQuery2), "/response/numFound==2");
    assertEquals(2, lookupFilterCacheInserts(core));
    JQ(req("q", "*:*", "indent", "true", "fq", random().nextBoolean() ? termQuery : filterTermQuery));
    filterCacheMetrics = lookupFilterCacheMetrics(core);
    // unchanged
    assertEquals(2, (long) filterCacheMetrics.get("inserts"));
    assertEquals(1, (long) filterCacheMetrics.get("hits"));
    JQ(req("q", "*:*", "indent", "true", "fq", random().nextBoolean() ? termQuery2 : filterTermQuery2));
    filterCacheMetrics = lookupFilterCacheMetrics(core);
    // unchanged
    assertEquals(2, (long) filterCacheMetrics.get("inserts"));
    assertEquals(2, (long) filterCacheMetrics.get("hits"));
    JQ(req("q", "*:*", "indent", "true", "fq", "{!bool cache=false should=$ftq should=$ftq2}", "ftq", filterTermQuery, "ftq2", filterTermQuery2, "cursorMark", "*", "sort", "id asc"));
    filterCacheMetrics = lookupFilterCacheMetrics(core);
    // unchanged
    assertEquals(2, (long) filterCacheMetrics.get("inserts"));
    assertEquals(4, (long) filterCacheMetrics.get("hits"));
    JQ(req("q", "*:*", "indent", "true", "fq", "{!bool should=$ftq should=$ftq2}", "ftq", filterTermQuery, "ftq2", filterTermQuery2, "cursorMark", "*", "sort", "id asc"));
    filterCacheMetrics = lookupFilterCacheMetrics(core);
    // added top-level
    assertEquals(3, (long) filterCacheMetrics.get("inserts"));
    assertEquals(6, (long) filterCacheMetrics.get("hits"));
}

