        if (results == null) {
            set2.add(s);
        }
    }
    assertTrue(set1.size() > 0);
    assertTrue(set2.size() > 0);
    assertEquals(set1.size() + set2.size(), set.size());
    assertNoOverLap(set1, set2);
}

