@Test
public void testBoost() {
    // Simple term query
    q = parse("foo^3.0");
    assertTrue(q instanceof BoostQuery);
    assertEquals(3.0, ((BoostQuery) q).getBoost(), 1e-15);
    // Some DMQ and one plain required
    q = parse("foo^5.0 bar^6.0 +baz^7");
    clauses = clauses(q);
    assertEquals(2, clauses.length);
    assertTrue(clauses[0].getQuery() instanceof DisjunctionMaxQuery);
    DisjunctionMaxQuery dmq = ((DisjunctionMaxQuery) clauses[0].getQuery());
    Query fooClause = ((BooleanQuery) dmq.getDisjuncts().stream().filter(q -> q.toString().contains("foo")).findFirst().get()).clauses().iterator().next().getQuery();
    assertEquals(5.0, ((BoostQuery) fooClause).getBoost(), 1e-15);
    Query barClause = ((BooleanQuery) dmq.getDisjuncts().stream().filter(q -> q.toString().contains("bar")).findFirst().get()).clauses().iterator().next().getQuery();
    assertEquals(6.0, ((BoostQuery) barClause).getBoost(), 1e-15);
    assertEquals(7.0, ((BoostQuery) clauses[1].getQuery()).getBoost(), 1e-15);
    assertFalse(q instanceof BoostQuery);
    // Grouped with parens on top level
    q = parse("(foo^2.0 bar)^3.0");
    clauses = clauses(q);
    assertEquals(1, clauses.length);
    assertTrue(clauses[0].getQuery() instanceof DisjunctionMaxQuery);
    dmq = ((DisjunctionMaxQuery) clauses[0].getQuery());
    fooClause = ((BooleanQuery) dmq.getDisjuncts().stream().filter(q -> q.toString().contains("foo")).findFirst().get()).clauses().iterator().next().getQuery();
    assertEquals(2.0, ((BoostQuery) fooClause).getBoost(), 1e-15);
    barClause = ((BooleanQuery) dmq.getDisjuncts().stream().filter(q -> q.toString().contains("bar")).findFirst().get()).clauses().iterator().next().getQuery();
    assertFalse(barClause instanceof BoostQuery);
    assertEquals(3.0, ((BoostQuery) q).getBoost(), 1e-15);
}

@Test
public void testLimit() throws Exception {
    Assume.assumeTrue("Thread memory monitoring is not available", MemAllowedLimit.isSupported());
    long limitMs = 100000;
    // 1 MiB
    MemAllowedLimit memLimit = new MemAllowedLimit(1f);
    ArrayList<byte[]> data = new ArrayList<>();
    long startNs = System.nanoTime();
    int wakeups = 0;
    while (!memLimit.shouldExit()) {
        Thread.sleep(100);
        // allocate memory
        for (int i = 0; i < 20; i++) {
            data.add(new byte[5000]);
        }
        wakeups++;
    }
    long endNs = System.nanoTime();
    assertTrue(data.size() > 1);
    long wallTimeDeltaMs = TimeUnit.MILLISECONDS.convert(endNs - startNs, TimeUnit.NANOSECONDS);
    log.info("Time limit: {} ms, elapsed wall-clock: {} ms, wakeups: {}", limitMs, wallTimeDeltaMs, wakeups);
    assertTrue("Number of wakeups should be smaller than 100 but was " + wakeups, wakeups < 100);
    assertTrue("Elapsed wall-clock time expected much smaller than 100ms but was " + wallTimeDeltaMs, limitMs > wallTimeDeltaMs);
}

@Test
public void testDistribLimit() throws Exception {
    Assume.assumeTrue("Thread memory monitoring is not available", MemAllowedLimit.isSupported());
    SolrClient solrClient = cluster.getSolrClient();
    // no limits set - should complete
    // 150 KiB
    long dataSize = 150;
    QueryResponse rsp = solrClient.query(COLLECTION, params("q", "id:*", "sort", "id desc", "dataSize", String.valueOf(dataSize)));
    assertEquals(rsp.getHeader().get("status"), 0);
    assertNull("should not have partial results", rsp.getHeader().get("partialResults"));
    // memAllowed set with large value, should return full results
    rsp = solrClient.query(COLLECTION, params("q", "id:*", "sort", "id asc", "memLoadCount", String.valueOf(dataSize), "stages", "prepare,process", "memAllowed", "1.5"));
    assertNull("should have full results", rsp.getHeader().get("partialResults"));
    // memAllowed set, should return partial results
    rsp = solrClient.query(COLLECTION, params("q", "id:*", "sort", "id asc", "memLoadCount", String.valueOf(dataSize), "stages", "prepare,process", "memAllowed", "0.2"));
    assertNotNull("should have partial results", rsp.getHeader().get("partialResults"));
    // multi-threaded search
    // memAllowed set, should return partial results
    rsp = solrClient.query(COLLECTION, params("q", "id:*", "sort", "id asc", "memLoadCount", String.valueOf(dataSize), "stages", "prepare,process", "multiThreaded", "true", "memAllowed", "0.2"));
    assertNotNull("should have partial results", rsp.getHeader().get("partialResults"));
}

