    verbose("ndocs=", ndocs);
    verbose("nWriteThreads=", nWriteThreads);
    verbose("nReadThreads=", nReadThreads);
    verbose("percentRealtimeQuery=", percentRealtimeQuery);
    verbose("maxConcurrentCommits=", maxConcurrentCommits);
    verbose("operations=", operations);
    initModel(ndocs);
    final AtomicInteger numCommitting = new AtomicInteger();
    List<Thread> threads = new ArrayList<>();
    for (int i = 0; i < nWriteThreads; i++) {
        Thread thread = new Thread("WRITER" + i) {

            Random rand = new Random(random().nextInt());

            @Override
            public void run() {
                try {
                    while (operations.get() > 0) {
                        int oper = rand.nextInt(100);
                        if (oper < commitPercent) {
                            if (numCommitting.incrementAndGet() <= maxConcurrentCommits) {
                                Map<Integer, DocInfo> newCommittedModel;
                                long version;
                                synchronized (TestRealTimeGet.this) {
                                    // take a snapshot
                                    newCommittedModel = new HashMap<>(model);
                                    version = snapshotCount++;
                                    verbose("took snapshot version=", version);
                                }
                                if (rand.nextInt(100) < softCommitPercent) {
                                    verbose("softCommit start");
                                    assertU(TestHarness.commit("softCommit", "true"));
                                    verbose("softCommit end");
                                } else {
                                    verbose("hardCommit start");
                                    assertU(commit());
                                    verbose("hardCommit end");
                                }
                                synchronized (TestRealTimeGet.this) {
                                    // install this model snapshot only if it's newer than the current one
                                    if (version >= committedModelClock) {
                                        if (VERBOSE) {
                                            verbose("installing new committedModel version=" + committedModelClock);
                                        }
                                        committedModel = newCommittedModel;
                                        committedModelClock = version;
                                    }
                                }
                            }
                            numCommitting.decrementAndGet();
                            continue;
                        }
                        int id = rand.nextInt(ndocs);
                        Object sync = syncArr[id];
                        // set the lastId before we actually change it sometimes to try and
                        // uncover more race conditions between writing and reading
                        boolean before = rand.nextBoolean();
                        if (before) {
                            lastId = id;
                        }
                        // We can't concurrently update the same document and retain our invariants of
                        // increasing values since we can't guarantee what order the updates will be
                        // executed. Even with versions, we can't remove the sync because increasing
                        // versions does not mean increasing vals.
                        synchronized (sync) {
                            DocInfo info = model.get(id);
                            long val = info.val;
                            long nextVal = Math.abs(val) + 1;
                            if (oper < commitPercent + deletePercent) {
                                boolean opt = rand.nextInt() < optimisticPercent;
                                boolean correct = opt ? rand.nextInt() < optimisticCorrectPercent : false;
                                long badVersion = correct ? 0 : badVersion(rand, info.version);
                                if (VERBOSE) {
                                    if (!opt) {
                                        verbose("deleting id", id, "val=", nextVal);
                                    } else {
                                        verbose("deleting id", id, "val=", nextVal, "existing_version=", info.version, (correct ? "" : (" bad_version=" + badVersion)));
                                    }
                                }
                                // assertU("<delete><id>" + id + "</id></delete>");
                                Long version = null;
                                if (opt) {
                                    if (correct) {
                                        version = deleteAndGetVersion(Integer.toString(id), params("_version_", Long.toString(info.version)));
                                    } else {
                                        SolrException se = expectThrows(SolrException.class, "should not get random version", () -> deleteAndGetVersion(Integer.toString(id), params("_version_", Long.toString(badVersion))));
                                        assertEquals(409, se.code());
                                    }
                                } else {
                                    version = deleteAndGetVersion(Integer.toString(id), null);
                                }
                                if (version != null) {
                                    model.put(id, new DocInfo(version, -nextVal));
                                }
                                if (VERBOSE) {
                                    verbose("deleting id", id, "val=", nextVal, "DONE");
                                }
                            } else if (oper < commitPercent + deletePercent + deleteByQueryPercent) {
                                if (VERBOSE) {
                                    verbose("deleteByQuery id ", id, "val=", nextVal);
                                }
                                assertU("<delete><query>id:" + id + "</query></delete>");
                                model.put(id, new DocInfo(-1L, -nextVal));
                                if (VERBOSE) {
                                    verbose("deleteByQuery id", id, "val=", nextVal, "DONE");
                                }
                            } else {
                                boolean opt = rand.nextInt() < optimisticPercent;
                                boolean correct = opt ? rand.nextInt() < optimisticCorrectPercent : false;
                                long badVersion = correct ? 0 : badVersion(rand, info.version);
                                if (VERBOSE) {
                                    if (!opt) {
                                        verbose("adding id", id, "val=", nextVal);
                                    } else {
                                        verbose("adding id", id, "val=", nextVal, "existing_version=", info.version, (correct ? "" : (" bad_version=" + badVersion)));
                                    }
                                }
                                Long version = null;
                                SolrInputDocument sd = sdoc("id", Integer.toString(id), FIELD, Long.toString(nextVal));
                                if (opt) {
                                    if (correct) {
                                        version = addAndGetVersion(sd, params("_version_", Long.toString(info.version)));
                                    } else {
                                        SolrException se = expectThrows(SolrException.class, "should not get bad version", () -> addAndGetVersion(sd, params("_version_", Long.toString(badVersion))));
                                        assertEquals(409, se.code());
                                    }
                                } else {
                                    version = addAndGetVersion(sd, null);
                                }
                                if (version != null) {
                                    model.put(id, new DocInfo(version, nextVal));
                                }
                                if (VERBOSE) {
                                    verbose("adding id", id, "val=", nextVal, "DONE");
                                }
                            }
                        }
                        // end sync
                        if (!before) {
                            lastId = id;
                        }
                    }
                } catch (Throwable e) {
                    operations.set(-1L);
                    throw new RuntimeException(e);
                }
            }
        };
        threads.add(thread);
    }
    for (int i = 0; i < nReadThreads; i++) {
        Thread thread = new Thread("READER" + i) {

            Random rand = new Random(random().nextInt());

            @Override
            public void run() {
                try {
                    while (operations.decrementAndGet() >= 0) {
                        // bias toward a recently changed doc
                        int id = rand.nextInt(100) < 25 ? lastId : rand.nextInt(ndocs);
                        // when indexing, we update the index, then the model
                        // so when querying, we should first check the model, and then the index
                        boolean realTime = rand.nextInt(100) < percentRealtimeQuery;
                        DocInfo info;
                        if (realTime) {
                            info = model.get(id);
                        } else {
                            synchronized (TestRealTimeGet.this) {
                                info = committedModel.get(id);
                            }
                        }
                        if (VERBOSE) {
                            verbose("querying id", id);
                        }
                        boolean filteredOut = false;
                        SolrQueryRequest sreq;
                        if (realTime) {
                            ModifiableSolrParams p = params("wt", "json", "qt", "/get", "ids", Integer.toString(id));
                            if (rand.nextInt(100) < filteredGetPercent) {
                                int idToFilter = rand.nextBoolean() ? id : rand.nextInt(ndocs);
                                filteredOut = idToFilter != id;
                                p.add("fq", "id:" + idToFilter);
                            }
                            sreq = req(p);
                        } else {
                            sreq = req("wt", "json", "q", "id:" + Integer.toString(id), "omitHeader", "true");
                        }
                        String response = h.query(sreq);
                        @SuppressWarnings({ "rawtypes" })
                        Map rsp = (Map) Utils.fromJSONString(response);
                        @SuppressWarnings({ "rawtypes" })
                        List doclist = (List) (((Map) rsp.get("response")).get("docs"));
                        if (doclist.size() == 0) {
                            // there's no info we can get back with a delete operation, so not much we can
                            // check
                            // without further synchronization. This is also correct when filteredOut==true
                        } else {
                            assertEquals(1, doclist.size());
                            long foundVal = (Long) (((Map) doclist.get(0)).get(FIELD));
                            long foundVer = (Long) (((Map) doclist.get(0)).get("_version_"));
                            if (filteredOut || foundVal < Math.abs(info.val) || (foundVer == info.version && foundVal != info.val)) {
                                // if the version matches, the val must
                                verbose("ERROR, id=", id, "found=", response, "model", info);
                                fail();
                            }
                        }
                    }
                } catch (Throwable e) {
                    operations.set(-1L);
                    throw new RuntimeException(e);
                }
            }
        };
        threads.add(thread);
    }
    for (Thread thread : threads) {
        thread.start();
    }
    for (Thread thread : threads) {
        thread.join();
    }
}

@Test
public void stressLogReplay() throws Exception {
    final int NUM_UPDATES = 150;
    try {
        TestInjection.skipIndexWriterCommitOnClose = true;
        final Semaphore logReplay = new Semaphore(0);
        final Semaphore logReplayFinish = new Semaphore(0);
        UpdateLog.testing_logReplayHook = () -> {
            try {
                assertTrue(logReplay.tryAcquire(timeout, TimeUnit.SECONDS));
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        };
        UpdateLog.testing_logReplayFinishHook = logReplayFinish::release;
        clearIndex();
        assertU(commit());
        Map<Integer, Integer> docIdToVal = new HashMap<>();
        for (int i = 0; i < NUM_UPDATES; i++) {
            int kindOfUpdate = random().nextInt(100);
            if (docIdToVal.size() < 10)
                kindOfUpdate = 0;
            if (kindOfUpdate <= 50) {
                // add a new document update, may be a duplicate with the current one
                int val = random().nextInt(1000);
                int docId = random().nextInt(10000);
                addAndGetVersion(sdoc("id", String.valueOf(docId), "val_i_dvo", val), null);
                docIdToVal.put(docId, val);
            } else if (kindOfUpdate <= 80) {
                // inc val of a document
                ArrayList<Integer> ids = new ArrayList<>(docIdToVal.keySet());
                int docId = ids.get(random().nextInt(ids.size()));
                int delta = random().nextInt(10);
                addAndGetVersion(sdoc("id", String.valueOf(docId), "val_i_dvo", map("inc", delta)), null);
                docIdToVal.put(docId, docIdToVal.get(docId) + delta);
            } else if (kindOfUpdate <= 85) {
                // set val of a document
                ArrayList<Integer> ids = new ArrayList<>(docIdToVal.keySet());
                int docId = ids.get(random().nextInt(ids.size()));
                int val = random().nextInt(1000);
                addAndGetVersion(sdoc("id", String.valueOf(docId), "val_i_dvo", map("set", val)), null);
                docIdToVal.put(docId, val);
            } else if (kindOfUpdate <= 90) {
                // delete by id
                ArrayList<Integer> vals = new ArrayList<>(docIdToVal.values());
                int val = vals.get(random().nextInt(vals.size()));
                deleteByQueryAndGetVersion("val_i_dvo:" + val, null);
                docIdToVal.entrySet().removeIf(integerIntegerEntry -> integerIntegerEntry.getValue() == val);
            } else {
                // delete by query
                ArrayList<Integer> ids = new ArrayList<>(docIdToVal.keySet());
                int docId = ids.get(random().nextInt(ids.size()));
                deleteAndGetVersion(String.valueOf(docId), null);
                docIdToVal.remove(docId);
            }
        }
        h.close();
        createCore();
        assertJQ(req("q", "*:*"), "/response/numFound==0");
        // unblock recovery
        logReplay.release(Integer.MAX_VALUE);
        assertTrue(logReplayFinish.tryAcquire(timeout, TimeUnit.SECONDS));
        assertU(commit());
        assertJQ(req("q", "*:*"), "/response/numFound==" + docIdToVal.size());
        for (Map.Entry<Integer, Integer> entry : docIdToVal.entrySet()) {
            assertJQ(req("q", "id:" + entry.getKey(), "fl", "val_i_dvo"), "/response/numFound==1", "/response/docs==[{'val_i_dvo':" + entry.getValue() + "}]");
        }
    } finally {
        UpdateLog.testing_logReplayHook = null;
        UpdateLog.testing_logReplayFinishHook = null;
    }
}

@Test
public void testLogReplay() throws Exception {
    try {
        TestInjection.skipIndexWriterCommitOnClose = true;
        final Semaphore logReplay = new Semaphore(0);
        final Semaphore logReplayFinish = new Semaphore(0);
        UpdateLog.testing_logReplayHook = () -> {
            try {
                assertTrue(logReplay.tryAcquire(timeout, TimeUnit.SECONDS));
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        };
        UpdateLog.testing_logReplayFinishHook = () -> logReplayFinish.release();
        clearIndex();
        assertU(commit());
        Deque<Long> versions = new ArrayDeque<>();
        versions.addFirst(addAndGetVersion(sdoc("id", "A1"), null));
        versions.addFirst(addAndGetVersion(sdoc("id", "A11"), null));
        versions.addFirst(addAndGetVersion(sdoc("id", "A12"), null));
        versions.addFirst(deleteByQueryAndGetVersion("id:A11", null));
        versions.addFirst(addAndGetVersion(sdoc("id", "A13"), null));
        versions.addFirst(// atomic update
        addAndGetVersion(sdoc("id", "A12", "val_i_dvo", map("set", 1)), null));
        versions.addFirst(// in-place update
        addAndGetVersion(sdoc("id", "A12", "val_i_dvo", map("set", 2)), null));
        assertJQ(req("q", "*:*"), "/response/numFound==0");
        assertJQ(req("qt", "/get", "getVersions", "" + versions.size()), "/versions==" + versions);
        h.close();
        createCore();
        // live map view
        Map<String, Metric> metrics = getMetrics();
        // Solr should kick this off now
        // h.getCore().getUpdateHandler().getUpdateLog().recoverFromLog();
        // verify that previous close didn't do a commit
        // recovery should be blocked by our hook
        assertJQ(req("q", "*:*"), "/response/numFound==0");
        // make sure we can still access versions after a restart
        assertJQ(req("qt", "/get", "getVersions", "" + versions.size()), "/versions==" + versions);
        assertEquals(UpdateLog.State.REPLAYING, h.getCore().getUpdateHandler().getUpdateLog().getState());
        // check metrics
        @SuppressWarnings({ "unchecked" })
        Gauge<Integer> state = (Gauge<Integer>) metrics.get("TLOG.state");
        assertEquals(UpdateLog.State.REPLAYING.ordinal(), state.getValue().intValue());
        @SuppressWarnings({ "unchecked" })
        Gauge<Integer> replayingLogs = (Gauge<Integer>) metrics.get("TLOG.replay.remaining.logs");
        assertTrue(replayingLogs.getValue() > 0);
        @SuppressWarnings({ "unchecked" })
        Gauge<Long> replayingDocs = (Gauge<Long>) metrics.get("TLOG.replay.remaining.bytes");
        assertTrue(replayingDocs.getValue() > 0);
        Meter replayDocs = (Meter) metrics.get("TLOG.replay.ops");
        long initialOps = replayDocs.getCount();
        // unblock recovery
        logReplay.release(1000);
        // make sure we can still access versions during recovery
        assertJQ(req("qt", "/get", "getVersions", "" + versions.size()), "/versions==" + versions);
        // wait until recovery has finished
        assertTrue(logReplayFinish.tryAcquire(timeout, TimeUnit.SECONDS));
        assertJQ(req("q", "val_i_dvo:2"), // assert that in-place update is retained
        "/response/numFound==1");
        assertJQ(req("q", "*:*"), "/response/numFound==3");
        assertEquals(7L, replayDocs.getCount() - initialOps);
        assertEquals(UpdateLog.State.ACTIVE.ordinal(), state.getValue().intValue());
        // make sure we can still access versions after recovery
        assertJQ(req("qt", "/get", "getVersions", "" + versions.size()), "/versions==" + versions);
        assertU(adoc("id", "A2"));
        assertU(adoc("id", "A3"));
        assertU(delI("A2"));
        assertU(adoc("id", "A4"));
        assertJQ(req("q", "*:*"), "/response/numFound==3");
        assertJQ(req("q", "val_i_dvo:2"), // assert that in-place update is retained
        "/response/numFound==1");
        h.close();
        createCore();
        // Solr should kick this off now
        // h.getCore().getUpdateHandler().getUpdateLog().recoverFromLog();
        // wait until recovery has finished
        assertTrue(logReplayFinish.tryAcquire(timeout, TimeUnit.SECONDS));
        assertJQ(req("q", "*:*"), "/response/numFound==5");
        assertJQ(req("q", "id:A2"), "/response/numFound==0");
        // no updates, so ensure that recovery does not run
        h.close();
        int permits = logReplay.availablePermits();
        createCore();
        // Solr should kick this off now
        // h.getCore().getUpdateHandler().getUpdateLog().recoverFromLog();
        assertJQ(req("q", "*:*"), "/response/numFound==5");
        assertJQ(req("q", "val_i_dvo:2"), // assert that in-place update is retained
        "/response/numFound==1");
        Thread.sleep(100);
        assertEquals(permits, // no updates, so ensure that recovery didn't run
        logReplay.availablePermits());
        assertEquals(UpdateLog.State.ACTIVE, h.getCore().getUpdateHandler().getUpdateLog().getState());
    } finally {
        UpdateLog.testing_logReplayHook = null;
        UpdateLog.testing_logReplayFinishHook = null;
    }
}

@Test
public void testNewDBQAndDocMatchingOldDBQDuringLogReplay() throws Exception {
    try {
        TestInjection.skipIndexWriterCommitOnClose = true;
        final Semaphore logReplay = new Semaphore(0);
        final Semaphore logReplayFinish = new Semaphore(0);
        UpdateLog.testing_logReplayHook = () -> {
            try {
                assertTrue(logReplay.tryAcquire(timeout, TimeUnit.SECONDS));
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        };
        UpdateLog.testing_logReplayFinishHook = () -> logReplayFinish.release();
        clearIndex();
        assertU(commit());
        // because we're sending updates during log replay, we can't emulate replica logic -- we need
        // to use normal updates like a leader / single-node instance would get.
        //
        // (In SolrCloud mode, when a replica run recoverFromLog, replica in this time period will
        // have state = DOWN, so It won't receive any updates.)
        updateJ(jsonAdd(sdoc("id", "B0")), params());
        // should be deleted by subsequent DBQ in tlog
        updateJ(jsonAdd(sdoc("id", "B1")), params());
        updateJ(jsonAdd(sdoc("id", "B2")), // should be deleted by DBQ that arrives during tlog replay
        params());
        updateJ(jsonDelQ("id:B1 OR id:B3 OR id:B6"), params());
        updateJ(jsonAdd(sdoc("id", "B3")), // should *NOT* be deleted by previous DBQ in tlog
        params());
        updateJ(jsonAdd(sdoc("id", "B4")), // should be deleted by DBQ that arrives during tlog replay
        params());
        updateJ(jsonAdd(sdoc("id", "B5")), params());
        // sanity check no updates have been applied yet (just in tlog)
        assertJQ(req("q", "*:*"), "/response/numFound==0");
        h.close();
        // (Attempts to) kick off recovery (which is currently blocked by semaphore)
        createCore();
        // verify that previous close didn't do a commit & that recovery should be blocked by our hook
        assertJQ(req("q", "*:*"), "/response/numFound==0");
        // begin recovery (first few items)
        logReplay.release(TestUtil.nextInt(random(), 1, 6));
        // ... but before recover is completely unblocked/finished, have a *new* DBQ arrive
        // that should delete some items we either have just replayed, or are about to replay (or
        // maybe both)...
        updateJ(jsonDelQ("id:B2 OR id:B4"), params());
        // ...and re-add a doc that would have matched a DBQ already in the tlog
        // (which may/may-not have been replayed yet)
        // should *NOT* be deleted by DBQ from tlog
        updateJ(jsonAdd(sdoc("id", "B6")), params());
        assertU(commit());
        // now completely unblock recovery
        logReplay.release(1000);
        // wait until recovery has finished
        assertTrue(logReplayFinish.tryAcquire(timeout, TimeUnit.SECONDS));
        // verify only the expected docs are found, even with out-of-order DBQ and DBQ that arrived
        // during recovery
        assertJQ(req("q", "*:*", "fl", "id", "sort", "id asc"), "/response/docs==[{'id':'B0'}, {'id':'B3'}, {'id':'B5'}, {'id':'B6'}]");
    } finally {
        UpdateLog.testing_logReplayHook = null;
        UpdateLog.testing_logReplayFinishHook = null;
    }
}

