        timeout.waitFor("Timeout waiting for finish replay updates", () -> h.getCore().getUpdateHandler().getUpdateLog().getState() == UpdateLog.State.ACTIVE);
        updateJ(jsonAdd(sdoc("id", "Q7", "_version_", v117)), params(DISTRIB_UPDATE_PARAM, // do another add to make sure flags are back to normal
        FROM_LEADER));
        req.close();
        h.close();
        createCore();
        req = req();
        uhandler = req.getCore().getUpdateHandler();
        UpdateLog updateLog = uhandler.getUpdateLog();
        // TODO this can fail
        // assertFalse(updateLog.existOldBufferLog());
        // Timeout for Q7 get replayed, because it was added on tlog, therefore it will be replayed on
        // restart
        timeout = new TimeOut(10, TimeUnit.SECONDS, TimeSource.NANO_TIME);
        timeout.waitFor("Timeout waiting for finish replay updates", () -> h.getCore().getUpdateHandler().getUpdateLog().getState() == UpdateLog.State.ACTIVE);
        assertJQ(req("qt", "/get", "id", "Q7"), "/doc/id==Q7");
    } finally {
