@Test
@Repeat(iterations = 10)
public void testLLPDecodeIsStableAndPrecise() throws Exception {
    // test that LatLonPointSpatialField decode of docValue will round-trip (re-index then
    // re-decode) to the same value
    @SuppressWarnings({ "resource", "IOResourceOpenedButNotSafelyClosed" })
    SolrClient // do NOT close it; it will close Solr
    client = new EmbeddedSolrServer(h.getCore());
    final String fld = "llp_1_dv_dvasst";
    String ptOrig = GeoTestUtil.nextLatitude() + "," + GeoTestUtil.nextLongitude();
    assertU(adoc("id", "0", fld, ptOrig));
    assertU(commit());
    // retrieve it (probably less precision)
    String ptDecoded1 = (String) client.query(params("q", "id:0")).getResults().get(0).get(fld);
    // now write it back
    assertU(adoc("id", "0", fld, ptDecoded1));
    assertU(commit());
    // retrieve it; assert that it's the same as written
    String ptDecoded2 = (String) client.query(params("q", "id:0")).getResults().get(0).get(fld);
    assertEquals("orig:" + ptOrig, ptDecoded1, ptDecoded2);
    // test that the representation is pretty accurate
    final Point ptOrigObj = SpatialUtils.parsePoint(ptOrig, SpatialContext.GEO);
    final Point ptDecodedObj = SpatialUtils.parsePoint(ptDecoded1, SpatialContext.GEO);
    double deltaCentimeters = SpatialContext.GEO.calcDistance(ptOrigObj, ptDecodedObj) * DistanceUtils.DEG_TO_KM * 1000.0 * 100.0;
    // See javadocs of LatLonDocValuesField for these constants
    final Point absErrorPt = SpatialContext.GEO.getShapeFactory().pointXY(8.381903171539307E-8, 4.190951585769653E-8);
    double deltaCentimetersMax = SpatialContext.GEO.calcDistance(absErrorPt, 0, 0) * DistanceUtils.DEG_TO_KM * 1000.0 * 100.0;
    assertEquals(1.0420371840922256, deltaCentimetersMax, // just so that we see it in black & white in the test
    0.0);
    // max found by trial & error.  If we used 8 decimal places then we could get down to 1.04 cm
    // accuracy, but then we lose the ability to round-trip -- 40 would become 39.99999997  (ugh).
    assertTrue("deltaCm too high: " + deltaCentimeters, deltaCentimeters < 1.41);
    // Pt(x=105.29894270124083,y=-0.4371673760042398) to  Pt(x=105.2989428,y=-0.4371673) is 1.38568
}

@Test
public void testLatLonRetrieval() throws Exception {
    final String ptHighPrecision = "40.2996543270,-74.0824956673";
    final String ptLossOfPrecision = // rounded version of the one above, losing precision
    "40.2996544,-74.0824957";
    // "_1" is single, "_N" is multiValued
    // "_dv" is docValues (otherwise not),  "_dvasst" is useDocValuesAsStored (otherwise not)
    // "_st" is stored" (otherwise not)
    // a random point using the number of decimal places we support for round-tripping.
    String randPointStr = new BigDecimal(GeoTestUtil.nextLatitude()).setScale(7, RoundingMode.HALF_UP).stripTrailingZeros().toPlainString() + "," + new BigDecimal(GeoTestUtil.nextLongitude()).setScale(7, RoundingMode.HALF_UP).stripTrailingZeros().toPlainString();
    List<RetrievalCombo> combos = Arrays.asList(new RetrievalCombo("llp_1_dv_st", ptHighPrecision), new RetrievalCombo("llp_N_dv_st", Arrays.asList("-40,40", "-45,45")), // multiValued but 1 value
    new RetrievalCombo("llp_N_dv_st", Arrays.asList("-40,40")), new RetrievalCombo("llp_1_dv_dvasst", ptHighPrecision, ptLossOfPrecision), // this one comes back in a different order since it gets sorted low to high
    new RetrievalCombo("llp_N_dv_dvasst", Arrays.asList("-40,40", "-45,45"), Arrays.asList("-45,45", "-40,40")), new RetrievalCombo("llp_N_dv_dvasst", // multiValued but 1 value
    Arrays.asList(randPointStr)), // edge cases.  (note we sorted it as Lucene will internally)
    new RetrievalCombo("llp_N_dv_dvasst", Arrays.asList("-90,180", "-90,-180", "0,0", "0,180", "0,-180", "90,0", "90,180", "90,-180")), new RetrievalCombo("llp_1_dv", ptHighPrecision, ptLossOfPrecision), new RetrievalCombo("llp_N_dv", Arrays.asList("-45,45", "-40,40")));
    Collections.shuffle(combos, random());
    // add and commit
    for (RetrievalCombo combo : combos) {
        SolrInputDocument doc = new SolrInputDocument();
        doc.addField("id", "" + combo.id);
        for (String indexValue : combo.indexValues) {
            doc.addField(combo.fieldName, indexValue);
        }
        assertU(adoc(doc));
        if (TestUtils.rarely()) {
            // induce segments to potentially change internal behavior
            assertU(commit());
        }
    }
    assertU(commit());
    // create an assertJQ assertion string, once for fl=*, another for when the field is listed
    List<String> assertJQsFlListed = new ArrayList<>();
    List<String> assertJQsFlStar = new ArrayList<>();
    for (RetrievalCombo combo : combos) {
        String expect = "response/docs/[" + combo.id + "]/" + combo.fieldName + "==" + combo.expectReturnJSON;
        assertJQsFlListed.add(expect);
        if (combo.fieldName.endsWith("_dv")) {
            expect = "response/docs/[" + combo.id + "]=={'id':'" + combo.id + // only the id, nothing else
            "'}";
        }
        assertJQsFlStar.add(expect);
    }
    // check
    assertJQ(req("q", "*:*", "sort", "id asc", "fl", "*"), assertJQsFlStar.toArray(new String[0]));
    assertJQ(req("q", "*:*", "sort", "id asc", "fl", "id," + combos.stream().map(c -> c.fieldName).collect(Collectors.joining(","))), assertJQsFlListed.toArray(new String[0]));
}

