@Test
public void testTermsMethodEquivalency() {
    // Run queries with a variety of 'method' and postfilter options.
    final TermsParams[] methods = new TermsParams[] { new TermsParams("termsFilter", true), new TermsParams("termsFilter", false), new TermsParams("booleanQuery", true), new TermsParams("booleanQuery", false), new TermsParams("automaton", true), new TermsParams("automaton", false), new TermsParams("docValuesTermsFilter", true), new TermsParams("docValuesTermsFilter", false), new TermsParams("docValuesTermsFilterTopLevel", true), new TermsParams("docValuesTermsFilterTopLevel", false), new TermsParams("docValuesTermsFilterPerSegment", true), new TermsParams("docValuesTermsFilterPerSegment", false) };
    for (TermsParams method : methods) {
        // Single-valued field, single term value
        ModifiableSolrParams params = new ModifiableSolrParams();
        params.add("q", method.buildQuery("author_s1", "Robert Jordan"));
        params.add("sort", "id asc");
        assertQ(req(params, "indent", "on"), "*[count(//doc)=2]", "//result/doc[1]/str[@name='id'][.='2']", "//result/doc[2]/str[@name='id'][.='3']");
        // Single-valued field, multiple term values
        params = new ModifiableSolrParams();
        params.add("q", method.buildQuery("author_s1", "Robert Jordan,Isaac Asimov"));
        params.add("sort", "id asc");
        assertQ(req(params, "indent", "on"), "*[count(//doc)=3]", "//result/doc[1]/str[@name='id'][.='2']", "//result/doc[2]/str[@name='id'][.='3']", "//result/doc[3]/str[@name='id'][.='7']");
        // Multi-valued field, single term value
        params = new ModifiableSolrParams();
        params.add("q", method.buildQuery("cat_s", "childrens"));
        params.add("sort", "id asc");
        assertQ(req(params, "indent", "on"), "*[count(//doc)=2]", "//result/doc[1]/str[@name='id'][.='2']", "//result/doc[2]/str[@name='id'][.='3']");
        // Multi-valued field, multiple term values
        params = new ModifiableSolrParams();
        params.add("q", method.buildQuery("cat_s", "childrens,scifi"));
        params.add("sort", "id asc");
        assertQ(req(params, "indent", "on"), "*[count(//doc)=5]", "//result/doc[1]/str[@name='id'][.='2']", "//result/doc[2]/str[@name='id'][.='3']", "//result/doc[3]/str[@name='id'][.='5']", "//result/doc[4]/str[@name='id'][.='6']", "//result/doc[5]/str[@name='id'][.='7']");
        // Numeric field
        params = new ModifiableSolrParams();
        params.add("q", method.buildQuery("pubyear_i", "2009"));
        params.add("sort", "id asc");
        // Test schema randomizes between Trie and Point.  "terms" is supported for "trie" but not
        // "Point"
        final String numericFieldType = System.getProperty("solr.tests.IntegerFieldType");
        if (numericFieldType.contains("Point")) {
            assertQEx("Expected 'terms' query on PointField to fail", req(params, "indent", "on"), 400);
        } else {
            assertQ(req(params, "indent", "on"), "*[count(//doc)=1]", "//result/doc[1]/str[@name='id'][.='1']");
        }
    }
}

@Test
public void testSimple() {
    Object cacheScope = new Object();
    ThinCache.NodeLevelCache<Object, Integer, String> backing = new ThinCache.NodeLevelCache<>();
    ThinCache<Object, Integer, String> lfuCache = new ThinCache<>();
    lfuCache.setBacking(cacheScope, backing);
    SolrMetricsContext solrMetricsContext = new SolrMetricsContext(metricManager, registry, "foo");
    lfuCache.initializeMetrics(solrMetricsContext, scope + "-1");
    Object cacheScope2 = new Object();
    ThinCache<Object, Integer, String> newLFUCache = new ThinCache<>();
    newLFUCache.setBacking(cacheScope2, backing);
    newLFUCache.initializeMetrics(solrMetricsContext, scope + "-2");
    Map<String, String> params = new HashMap<>();
    params.put("size", "100");
    params.put("initialSize", "10");
    NoOpRegenerator regenerator = new NoOpRegenerator();
    backing.init(params, null, null);
    Object initObj = lfuCache.init(Collections.singletonMap("autowarmCount", "25"), null, regenerator);
    lfuCache.setState(SolrCache.State.LIVE);
    for (int i = 0; i < 101; i++) {
        lfuCache.put(i + 1, Integer.toString(i + 1));
    }
    assertEquals("15", lfuCache.get(15));
    assertEquals("75", lfuCache.get(75));
    assertNull(lfuCache.get(110));
    Map<String, Object> nl = lfuCache.getMetricsMap().getValue();
    assertEquals(3L, nl.get("lookups"));
    assertEquals(2L, nl.get("hits"));
    assertEquals(101L, nl.get("inserts"));
    // first item put in should be the first out
    assertNull(lfuCache.get(1));
    // Test autowarming
    newLFUCache.init(Collections.singletonMap("autowarmCount", "25"), initObj, regenerator);
    newLFUCache.warm(null, lfuCache);
    newLFUCache.setState(SolrCache.State.LIVE);
    newLFUCache.put(103, "103");
    assertEquals("15", newLFUCache.get(15));
    assertEquals("75", newLFUCache.get(75));
    assertNull(newLFUCache.get(50));
    nl = newLFUCache.getMetricsMap().getValue();
    assertEquals(3L, nl.get("lookups"));
    assertEquals(2L, nl.get("hits"));
    assertEquals(1L, nl.get("inserts"));
    assertEquals(0L, nl.get("evictions"));
    assertEquals(7L, nl.get("cumulative_lookups"));
    assertEquals(4L, nl.get("cumulative_hits"));
    assertEquals(102L, nl.get("cumulative_inserts"));
}

@Test
public void testInitCore() throws Exception {
    for (int i = 0; i < 20; i++) {
        assertU(adoc("id", Integer.toString(i)));
    }
    assertU(commit());
    assertQ(req("q", "*:*", "fq", "id:0"));
    assertQ(req("q", "*:*", "fq", "id:0"));
    assertQ(req("q", "*:*", "fq", "id:1"));
    Map<String, Object> nodeMetricsSnapshot = MetricUtils.convertMetrics(h.getCoreContainer().getMetricManager().registry("solr.node"), List.of("CACHE.nodeLevelCache/myNodeLevelCacheThin", "CACHE.nodeLevelCache/myNodeLevelCache"));
    Map<String, Object> coreMetricsSnapshot = MetricUtils.convertMetrics(h.getCore().getCoreMetricManager().getRegistry(), List.of("CACHE.searcher.filterCache"));
    // check that metrics are accessible, and the core cache writes through to the node-level cache
    Map<String, Number> assertions = Map.of("lookups", 3L, "hits", 1L, "inserts", 2L, "size", 2);
    for (Map.Entry<String, Number> e : assertions.entrySet()) {
        String key = e.getKey();
        Number val = e.getValue();
        assertEquals(val, nodeMetricsSnapshot.get("CACHE.nodeLevelCache/myNodeLevelCacheThin.".concat(key)));
        assertEquals(val, coreMetricsSnapshot.get("CACHE.searcher.filterCache.".concat(key)));
    }
    // for the other node-level cache, simply check that metrics are accessible
    assertEquals(0, nodeMetricsSnapshot.get("CACHE.nodeLevelCache/myNodeLevelCache.size"));
}

