public void testReportErrorIfFieldMissmatch() throws SyntaxError {
    DenseVectorField vectorField1 = new DenseVectorField(5, VectorSimilarityFunction.COSINE, VectorEncoding.BYTE);
    SchemaField field1 = new SchemaField("field1", vectorField1);
    DenseVectorField vectorField2 = new DenseVectorField(5, VectorSimilarityFunction.COSINE, VectorEncoding.FLOAT32);
