@Test
public void testDeleteSecurityJsonZnode() throws Exception {
    try (SolrClient client = new Http2SolrClient.Builder(cluster.getJettySolrRunner(0).getBaseUrl().toString()).build()) {
        try {
            new QueryRequest(params("q", "*:*")).process(client, COLLECTION);
            fail("Should throw exception due to authentication needed");
        } catch (Exception e) {
            /* Ignore */
        }
        // Deleting security.json will disable security - before SOLR-9679 it would instead cause an
        // exception
        cluster.getZkClient().delete("/security.json", -1, false);
        int count = 0;
        boolean done = false;
        // Assert that security is turned off. This is async, so we retry up to 5s before failing the
        // test
        while (!done) {
            try {
                Thread.sleep(500);
                count += 1;
                new QueryRequest(params("q", "*:*")).process(client, COLLECTION);
                done = true;
            } catch (Exception e) {
                if (count >= 10) {
                    fail("Failed 10 times to query without credentials after removing security.json");
                }
            }
        }
    }
}

@Test
public void testBasicAuth() throws Exception {
    String authcPrefix = "/admin/authentication";
    String authzPrefix = "/admin/authorization";
    HttpClient httpClient = null;
    SolrClient solrClient = null;
    try {
        httpClient = HttpClientUtil.createClient(null);
        String baseUrl = buildUrl(jetty.getLocalPort());
        solrClient = getHttpSolrClient(baseUrl);
        verifySecurityStatus(httpClient, baseUrl + authcPrefix, "/errorMessages", null, 20);
        // Write security.json locally. Should cause security to be initialized
        securityConfHandler.persistConf(new SecurityConfHandler.SecurityConfig().setData(Utils.fromJSONString(STD_CONF.replace("'", "\""))));
        securityConfHandler.securityConfEdited();
        verifySecurityStatus(httpClient, baseUrl + authcPrefix, "authentication/class", "solr.BasicAuthPlugin", 20);
        String command = "{\n" + "'set-user': {'harry':'HarryIsCool'}\n" + "}";
        doHttpPost(httpClient, baseUrl + authcPrefix, command, null, null, 401);
        verifySecurityStatus(httpClient, baseUrl + authcPrefix, "authentication.enabled", "true", 20);
        command = "{\n" + "'set-user': {'harry':'HarryIsUberCool'}\n" + "}";
        doHttpPost(httpClient, baseUrl + authcPrefix, command, "solr", "SolrRocks");
        verifySecurityStatus(httpClient, baseUrl + authcPrefix, "authentication/credentials/harry", NOT_NULL_PREDICATE, 20);
        // Read file from SOLR_HOME and verify that it contains our new user
        assertTrue(new String(Utils.toJSON(securityConfHandler.getSecurityConfig(false).getData()), UTF_8).contains("harry"));
        // Edit authorization
        verifySecurityStatus(httpClient, baseUrl + authzPrefix, "authorization/permissions[1]/role", null, 20);
        doHttpPost(httpClient, baseUrl + authzPrefix, "{'set-permission': {'name': 'update', 'role':'updaterole'}}", "solr", "SolrRocks");
        command = "{\n" + "'set-permission': {'name': 'read', 'role':'solr'}\n" + "}";
        doHttpPost(httpClient, baseUrl + authzPrefix, command, "solr", "SolrRocks");
        try {
            solrClient.query("collection1", new MapSolrParams(Collections.singletonMap("q", "foo")));
            fail("Should return a 401 response");
        } catch (Exception e) {
            // Test that the second doPost request to /security/authorization went through
            verifySecurityStatus(httpClient, baseUrl + authzPrefix, "authorization/permissions[2]/role", "solr", 20);
        }
    } finally {
        if (httpClient != null) {
            HttpClientUtil.close(httpClient);
            solrClient.close();
        }
    }
}

