@Test
public void testMultiAuthEditAPI() throws Exception {
    final String user = "admin";
    final String pass = "SolrRocks";
    HttpClient httpClient = null;
    SolrClient solrClient = null;
    try {
        httpClient = HttpClientUtil.createClient(null);
        String baseUrl = buildUrl(jetty.getLocalPort());
        solrClient = getHttpSolrClient(baseUrl);
        verifySecurityStatus(httpClient, baseUrl + authcPrefix, "/errorMessages", null, 5);
        // Initialize security.json with multiple auth plugins configured
        String multiAuthPluginSecurityJson = Files.readString(TEST_PATH().resolve("security").resolve("multi_auth_plugin_security.json"), StandardCharsets.UTF_8);
        securityConfHandler.persistConf(new SecurityConfHandler.SecurityConfig().setData(Utils.fromJSONString(multiAuthPluginSecurityJson)));
        securityConfHandler.securityConfEdited();
        // verify "WWW-Authenticate" headers are returned
        verifyWWWAuthenticateHeaders(httpClient, baseUrl);
        verifySecurityStatus(httpClient, baseUrl + authcPrefix, "authentication/class", "solr.MultiAuthPlugin", 5, user, pass);
        verifySecurityStatus(httpClient, baseUrl + authzPrefix, "authorization/class", "solr.MultiAuthRuleBasedAuthorizationPlugin", 5, user, pass);
        // anonymous requests are blocked by all plugins
        int statusCode = doHttpGetAnonymous(httpClient, baseUrl + "/admin/info/system");
        assertEquals("anonymous get succeeded but should not have", 401, statusCode);
        // update blockUnknown to allow anonymous for the basic plugin
        String command = "{\n" + "'set-property': { 'basic': {'blockUnknown':false} }\n" + "}";
        doHttpPost(httpClient, baseUrl + authcPrefix, command, user, pass, 200);
        statusCode = doHttpGetAnonymous(httpClient, baseUrl + "/admin/info/system");
        assertEquals("anonymous get failed but should have succeeded", 200, statusCode);
        // For the multi-auth plugin, every command is wrapped with an object that identifies the
        // "scheme"
        command = "{\n" + "'set-user': {'harry':'HarryIsCool'}\n" + "}";
        // no scheme identified!
        doHttpPost(httpClient, baseUrl + authcPrefix, command, user, pass, 400);
        command = "{\n" + "'set-user': { 'foo': {'harry':'HarryIsCool'} }\n" + "}";
        // no "foo" scheme configured
        doHttpPost(httpClient, baseUrl + authcPrefix, command, user, pass, 400);
        command = "{\n" + "'set-user': { 'basic': {'harry':'HarryIsCool'} }\n" + "}";
        // no creds, should fail ...
        doHttpPost(httpClient, baseUrl + authcPrefix, command, null, null, 401);
        // with basic creds, should pass ...
        doHttpPost(httpClient, baseUrl + authcPrefix, command, user, pass, 200);
        verifySecurityStatus(httpClient, baseUrl + authcPrefix, "authentication/schemes[0]/credentials/harry", NOT_NULL_PREDICATE, 5, user, pass);
        // authz command but missing the "scheme" wrapper
        command = "{\n" + "'set-user-role': {'harry':['users']}\n" + "}";
        doHttpPost(httpClient, baseUrl + authzPrefix, command, user, pass, 400);
        // add "harry" to the "users" role ...
        command = "{\n" + "'set-user-role': { 'basic': {'harry':['users']} }\n" + "}";
        doHttpPost(httpClient, baseUrl + authzPrefix, command, user, pass, 200);
        verifySecurityStatus(httpClient, baseUrl + authzPrefix, "authorization/schemes[0]/user-role/harry", NOT_NULL_PREDICATE, 5, user, pass);
        // give the users role a custom permission
        verifySecurityStatus(httpClient, baseUrl + authzPrefix, "authorization/permissions[6]", NULL_PREDICATE, 5, user, pass);
        command = "{\n" + "'set-permission': { 'name':'k8s-zk', 'role':'users', 'collection':null, 'path':'/admin/zookeeper/status' }\n" + "}";
        doHttpPost(httpClient, baseUrl + authzPrefix, command, user, pass, 200);
        verifySecurityStatus(httpClient, baseUrl + authzPrefix, "authorization/permissions[6]/path", new ExpectedValuePredicate("/admin/zookeeper/status"), 5, user, pass);
        command = "{\n" + "'update-permission': { 'index':'7', 'name':'k8s-zk', 'role':'users', 'collection':null, 'path':'/admin/zookeeper/status2' }\n" + "}";
        doHttpPost(httpClient, baseUrl + authzPrefix, command, user, pass, 200);
        verifySecurityStatus(httpClient, baseUrl + authzPrefix, "authorization/permissions[6]/path", new ExpectedValuePredicate("/admin/zookeeper/status2"), 5, user, pass);
        // delete the permission
        command = "{\n" + "'delete-permission': 7\n" + "}";
        doHttpPost(httpClient, baseUrl + authzPrefix, command, user, pass, 200);
        verifySecurityStatus(httpClient, baseUrl + authzPrefix, "authorization/permissions[6]", NULL_PREDICATE, 5, user, pass);
        // delete the user
        command = "{\n" + "'delete-user': { 'basic': 'harry' }\n" + "}";
        doHttpPost(httpClient, baseUrl + authcPrefix, command, user, pass, 200);
        verifySecurityStatus(httpClient, baseUrl + authcPrefix, "authentication/schemes[0]/credentials/harry", NULL_PREDICATE, 5, user, pass);
        // update the property on the mock (just to test routing to the mock plugin)
        command = "{\n" + "'set-property': { 'mock': { 'blockUnknown':false } }\n" + "}";
        doHttpPostWithHeader(httpClient, baseUrl + authcPrefix, command, new BasicHeader("Authorization", "mock foo"), 200);
        verifySecurityStatus(httpClient, baseUrl + authcPrefix, "authentication/schemes[1]/blockUnknown", new ExpectedValuePredicate(Boolean.FALSE), 5, user, pass);
    } finally {
        if (httpClient != null) {
            HttpClientUtil.close(httpClient);
        }
        if (solrClient != null) {
            solrClient.close();
        }
    }
}

@Test
public void init() throws IOException {
    MultiDestinationAuditLogger al = new MultiDestinationAuditLogger();
    Map<String, Object> config = new HashMap<>();
    config.put("class", "solr.MultiDestinationAuditLogger");
    config.put("async", false);
    config.put("eventTypes", Arrays.asList(AuditEvent.EventType.COMPLETED.name()));
    ArrayList<Map<String, Object>> plugins = new ArrayList<>();
    Map<String, Object> conf1 = new HashMap<>();
    conf1.put("class", "solr.SolrLogAuditLoggerPlugin");
    conf1.put("async", false);
    conf1.put("eventTypes", Arrays.asList(AuditEvent.EventType.ANONYMOUS.name()));
    plugins.add(conf1);
    Map<String, Object> conf2 = new HashMap<>();
    conf2.put("class", "solr.MockAuditLoggerPlugin");
    conf2.put("async", false);
    conf2.put("eventTypes", Arrays.asList(AuditEvent.EventType.AUTHENTICATED.name()));
    plugins.add(conf2);
    config.put("plugins", plugins);
    SolrResourceLoader loader = new SolrResourceLoader(Path.of(""));
    al.inform(loader);
    al.init(config);
    al.doAudit(new AuditEvent(AuditEvent.EventType.ANONYMOUS).setUsername("me"));
    assertEquals(0, // not configured for ANONYMOUS
    ((MockAuditLoggerPlugin) al.plugins.get(1)).events.size());
    al.doAudit(new AuditEvent(AuditEvent.EventType.AUTHENTICATED).setUsername("me"));
    assertEquals(1, // configured for authenticated
    ((MockAuditLoggerPlugin) al.plugins.get(1)).events.size());
    assertFalse(al.shouldLog(AuditEvent.EventType.ERROR));
    assertFalse(al.shouldLog(AuditEvent.EventType.UNAUTHORIZED));
    assertTrue(al.shouldLog(AuditEvent.EventType.COMPLETED));
    assertTrue(al.shouldLog(AuditEvent.EventType.ANONYMOUS));
    assertTrue(al.shouldLog(AuditEvent.EventType.AUTHENTICATED));
    assertEquals(0, config.size());
    al.close();
    loader.close();
}

