@Test
public void testSan() {
    // Email
    testCertificateCases(List.of(List.of(SANType.EMAIL.getValue(), "user1@example.com"), List.of(SANType.EMAIL.getValue(), "user2@example.com")), "san.email", "user1@example.com");
    // Email with 'extract'
    testCertificateCases(List.of(List.of(SANType.EMAIL.getValue(), "user@example.com")), null, "san.email", List.of("user@example.com"), "startsWith", Map.of("after", "@", "before", ".com"), "example");
    testCertificateCases(List.of(List.of(SANType.EMAIL.getValue(), "user@example.com")), null, "san.email", List.of("user@example.com"), "equals", Map.of("before", "@"), "user");
    // DNS
    testCertificateCases(List.of(List.of(SANType.DNS.getValue(), "value1.example.com"), List.of(SANType.DNS.getValue(), "value2.example.com")), "san.dns", "value1.example.com");
    // URI
    testCertificateCases(List.of(List.of(SANType.URI.getValue(), "http://example.com"), List.of(SANType.URI.getValue(), "http://example2.org")), "san.uri", List.of("http://example.com"), "equals", "http://example.com");
    // IP Address
    testCertificateCases(List.of(List.of(SANType.IP_ADDRESS.getValue(), "192.168.1.1"), List.of(SANType.IP_ADDRESS.getValue(), "10.0.0.1")), "san.IP_ADDRESS", "192.168.1.1");
    // OTHER_NAME
    testCertificateCases(List.of(List.of(SANType.OTHER_NAME.getValue(), "1.2.3.4")), "san.OTHER_NAME", "1.2.3.4");
    // X400_ADDRESS
    testCertificateCases(List.of(List.of(SANType.X400_ADDRESS.getValue(), "X400AddressValue")), "san.X400_ADDRESS", "X400AddressValue");
    // DIRECTORY_NAME
    testCertificateCases(List.of(List.of(SANType.DIRECTORY_NAME.getValue(), "DirectoryNameValue")), "san.DIRECTORY_NAME", "DirectoryNameValue");
    // EDI_PARTY_NAME
    testCertificateCases(List.of(List.of(SANType.EDI_PARTY_NAME.getValue(), "EdiPartyNameValue")), "san.EDI_PARTY_NAME", "EdiPartyNameValue");
    // REGISTERED_ID
    testCertificateCases(List.of(List.of(SANType.REGISTERED_ID.getValue(), "RegisteredIdValue")), "san.REGISTERED_ID", "RegisteredIdValue");
    //  CheckType tests
    testCertificateCases(List.of(List.of(SANType.EMAIL.getValue(), "user1@example.com"), List.of(SANType.EMAIL.getValue(), "user2@example.com")), "san.email", List.of("user2@example.com"), "equals", "user2@example.com");
    testCertificateCases(List.of(List.of(SANType.EMAIL.getValue(), "user1@example.com"), List.of(SANType.EMAIL.getValue(), "user2@example.com")), "san.email", List.of("user2"), "contains", "user2@example.com");
    testCertificateCases(List.of(List.of(SANType.EMAIL.getValue(), "user1@example.com"), List.of(SANType.EMAIL.getValue(), "user2@example.com")), "san.email", List.of("user2"), "startsWith", "user2@example.com");
    testCertificateCases(List.of(List.of(SANType.EMAIL.getValue(), "user@example1.com"), List.of(SANType.EMAIL.getValue(), "user@example2.com")), "san.email", List.of("example2.com"), "endsWith", "user@example2.com");
    testCertificateCases(List.of(List.of(SANType.EMAIL.getValue(), "user1@example.com"), List.of(SANType.EMAIL.getValue(), "user2@example.com")), "san.email", Collections.emptyList(), "*", "user1@example.com");
}

