@Test
public void testResolverWithExtractPatternMissing() throws SSLPeerUnverifiedException, CertificateParsingException {
    when(mockCertificate.getSubjectAlternativeNames()).thenReturn(List.of(List.of(SANType.EMAIL.getValue(), "info@example.com")));
    // Both 'after' and 'before' patterns are missing
    final Map<String, Object> params = new HashMap<>();
    params.put("path", "SAN.email");
    params.put("filter", Map.of("checkType", "startsWith", "values", List.of("info@")));
    assertResolvedPrincipal(params, "info@example.com");
    // Only 'before' pattern is provided, 'after' is missing
    params.put("extract", Map.of("before", ".com"));
    assertResolvedPrincipal(params, "info@example");
    // Only 'after' pattern is provided, 'before' is missing
    params.put("extract", Map.of("after", "@"));
    assertResolvedPrincipal(params, "example.com");
    // Invalid 'after' pattern that doesn't exist in the SAN value
    params.put("extract", Map.of("after", "notfound"));
    assertResolvedPrincipal(params, // Expect the original value since the 'after' pattern was not found
    "info@example.com");
}

@Test
public void testPkiAuth() throws Exception {
    HttpClient httpClient = ((CloudLegacySolrClient) cluster.getSolrClient()).getHttpClient();
    for (JettySolrRunner jetty : cluster.getJettySolrRunners()) {
        String baseUrl = jetty.getBaseUrl().toString();
        verifySecurityStatus(httpClient, baseUrl + "/admin/authorization", "authorization/class", MockAuthorizationPlugin.class.getName(), 20);
        verifySecurityStatus(httpClient, baseUrl + "/admin/authentication", "authentication.enabled", "true", 20);
    }
    log.info("Starting test");
    ModifiableSolrParams params = new ModifiableSolrParams();
    params.add("q", "*:*");
    params.add("__user", "solr");
    params.add("__pwd", "SolrRocks");
    // This should work fine.
    final AtomicInteger count = new AtomicInteger();
    MockAuthorizationPlugin.predicate = context -> {
        if ("/select".equals(context.getResource())) {
            Principal principal = context.getUserPrincipal();
            log.info("principalIs : {}", principal);
            if (principal != null && principal.getName().equals("solr")) {
                count.incrementAndGet();
            }
        }
    };
    MockAuthenticationPlugin.predicate = servletRequest -> {
        String s = ((HttpServletRequest) servletRequest).getQueryString();
        if (s != null && s.contains("__user=solr") && s.contains("__pwd=SolrRocks")) {
            servletRequest.setAttribute(Principal.class.getName(), "solr");
        }
        return true;
    };
    QueryRequest query = new QueryRequest(params);
    query.process(cluster.getSolrClient(), COLLECTION);
    assertTrue("all nodes must get the user solr , no:of nodes got solr : " + count.get(), count.get() > 2);
    assertPkiAuthMetricsMinimums(2, 2, 0, 0, 0, 0);
}

