        doAutoDetect(curl, method, "  \t\n\r  <tag>hi</tag>  ", "text/xml", null, null);
        doAutoDetect(curl, method, "  \t\r\n  aaa=1&bbb=2&ccc=3", null, "bbb", // params with whitespace first
        "2");
