    MockSolrSpellChecker checker3 = new MockSolrSpellChecker(differentDistance);
    cssc.addChecker(checker1);
    cssc.addChecker(checker2);
    expectThrows(IllegalArgumentException.class, () -> cssc.addChecker(checker3));
