        assertNotNull("documemt is null and it shouldn't be", suggestions);
        assertEquals("documemt Size: " + suggestions.size() + " is not: " + 1, 1, suggestions.size());
        Map.Entry<String, Integer> entry = suggestions.entrySet().iterator().next();
        assertEquals(entry.getKey() + " is not equal to " + "document", "document", entry.getKey());
