@Test
public void testEstimatedHitCounts() {
    final String xpathPrefix = "//lst[@name='spellcheck']/lst[@name='collations']/lst[@name='collation']/";
    final SolrParams reusedParams = params(SpellCheckComponent.COMPONENT_NAME, "true", SpellCheckComponent.SPELLCHECK_DICT, "direct", SpellingParams.SPELLCHECK_COUNT, "1", SpellingParams.SPELLCHECK_COLLATE, "true", SpellingParams.SPELLCHECK_MAX_COLLATION_TRIES, "1", SpellingParams.SPELLCHECK_MAX_COLLATIONS, "1", SpellingParams.SPELLCHECK_COLLATE_EXTENDED_RESULTS, "true", "qt", "/spellCheckCompRH");
    // default case, no SPELLCHECK_COLLATE_MAX_COLLECT_DOCS should be exact num hits
    assertQ(req(reusedParams, CommonParams.Q, "teststop:metnoia"), xpathPrefix + "str[@name='collationQuery']='teststop:metanoia'", xpathPrefix + "long[@name='hits']=6");
    // specifying 0 means "exact" same as default, but specifying a value greater
    // than the total number of docs in the index should also result in it
    // "estimating" and getting exact number as well.
    for (String val : new String[] { "0", "30", "100", "10000" }) {
        assertQ(req(reusedParams, CommonParams.Q, "teststop:metnoia", SpellingParams.SPELLCHECK_COLLATE_MAX_COLLECT_DOCS, val), xpathPrefix + "str[@name='collationQuery']='teststop:metanoia'", xpathPrefix + "long[@name='hits']=6");
    }
    // values between 0 and the num docs in the index should not error, and should
    // produce an estimate no more than the total number of docs
    final int iters = atLeast(10);
    for (int iter = 0; iter < iters; iter++) {
        final int val = TestUtil.nextInt(random(), 1, 17);
        assertQ(req(reusedParams, CommonParams.Q, "teststop:metnoia", SpellingParams.SPELLCHECK_COLLATE_MAX_COLLECT_DOCS, "" + val), xpathPrefix + "str[@name='collationQuery']='teststop:metanoia'", xpathPrefix + "long[@name='hits' and . <= 17 and 0 < .]");
    }
    // "everYother" appears in every other doc in the index, so "everother"
    // should produce a "decent" approximation of the number of hits (8)
    // for any 5 <= SPELLCHECK_COLLATE_MAX_COLLECT_DOCS
    //
    // (we have to be kind of flexible with our definition of "decent"
    // since we're dealing with a fairly small index here)
    for (int val = 5; val <= 20; val++) {
        // we will append to this...
        String hitsXPath = xpathPrefix + "long[@name='hits']";
        if (val <= NUM_DOCS_WITH_TERM_EVERYOTHER) {
            // strongest assertions we can make given an arbitrary MergePolicy on such a small index
            // is based on the idea that the docs may all come *first* or all come *last*
            // and then do the math on what estimate should come from that if we collected *exactly*
            // 'val'...
            //
            // if they are all "first" we will overestimate and assume everything is a match...
            int max = NUM_DOCS;
            // if they are all "last" we will under-estimate based on how non-matches we had to skip...
            int min = (/* min collected */
            val) / (/* max docs possibly scanned */
            NUM_DOCS);
            hitsXPath += "[" + min + " <= . and . <= " + max + "]";
        } else {
            // we've asked for a number greater than what can possibly be found in our tiny index, which
            // should force it to scan all docs so our hits should be exact
            hitsXPath += "[.=" + NUM_DOCS_WITH_TERM_EVERYOTHER + "]";
        }
        assertQ(req(reusedParams, CommonParams.Q, "teststop:everother", SpellingParams.SPELLCHECK_COLLATE_MAX_COLLECT_DOCS, "" + val), xpathPrefix + "str[@name='collationQuery']='teststop:everyother'", hitsXPath);
    }
}

