@Test
public void testGroupAPI() throws Exception {
    createIndex();
    String filt = f + ":[* TO *]";
    assertQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f), "/response/lst[@name='grouped']/lst[@name='" + f + "']/arr[@name='groups']");
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id"), // exact match
    "/responseHeader/status==0", // partial match by skipping some elements
    "/responseHeader=={'_SKIP_':'QTime', 'status':0}", // partial match by only including some elements
    "/responseHeader=={'_MATCH_':'status', 'status':0}", "/grouped=={'" + f + "':{'matches':10,'groups':[\n" + "{'groupValue':1,'doclist':{'numFound':3,'start':0,numFoundExact:true,'docs':[{'id':'8'}]}}," + "{'groupValue':3,'doclist':{'numFound':2,'start':0,numFoundExact:true,'docs':[{'id':'3'}]}}," + "{'groupValue':2,'doclist':{'numFound':3,'start':0,numFoundExact:true,'docs':[{'id':'4'}]}}," + "{'groupValue':5,'doclist':{'numFound':1,'start':0,numFoundExact:true,'docs':[{'id':'1'}]}}," + "{'groupValue':4,'doclist':{'numFound':1,'start':0,numFoundExact:true,'docs':[{'id':'2'}]}}" + "]}}");
    // test that filtering cuts down the result set
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "fq", f + ":2"), "/grouped=={'" + f + "':{'matches':3,'groups':[" + "{'groupValue':2,'doclist':{'numFound':3,'start':0,numFoundExact:true,'docs':[{'id':'4'}]}}" + "]}}");
    // test limiting the number of groups returned
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "rows", "2"), "/grouped=={'" + f + "':{'matches':10,'groups':[" + "{'groupValue':1,'doclist':{'numFound':3,'start':0,numFoundExact:true,'docs':[{'id':'8'}]}}," + "{'groupValue':3,'doclist':{'numFound':2,'start':0,numFoundExact:true,'docs':[{'id':'3'}]}}" + "]}}");
    // test offset into group list
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "rows", "1", "start", "1"), "/grouped=={'" + f + "':{'matches':10,'groups':[" + "{'groupValue':3,'doclist':{'numFound':2,'start':0,numFoundExact:true,'docs':[{'id':'3'}]}}" + "]}}");
    // test big offset into group list
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "rows", "1", "start", "100"), "/grouped=={'" + f + "':{'matches':10,'groups':[" + "]}}");
    // test increasing the docs per group returned
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "rows", "2", "group.limit", "3"), "/grouped=={'" + f + "':{'matches':10,'groups':[" + "{'groupValue':1,'doclist':{'numFound':3,'start':0,numFoundExact:true,'docs':[{'id':'8'},{'id':'10'},{'id':'5'}]}}," + "{'groupValue':3,'doclist':{'numFound':2,'start':0,numFoundExact:true,'docs':[{'id':'3'},{'id':'6'}]}}" + "]}}");
    // test offset into each group
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "rows", "2", "group.limit", "3", "group.offset", "1"), "/grouped=={'" + f + "':{'matches':10,'groups':[" + "{'groupValue':1,'doclist':{'numFound':3,'start':1,'numFoundExact':true,'docs':[{'id':'10'},{'id':'5'}]}}," + "{'groupValue':3,'doclist':{'numFound':2,'start':1,'numFoundExact':true,'docs':[{'id':'6'}]}}" + "]}}");
    // test big offset into each group
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "rows", "2", "group.limit", "3", "group.offset", "10"), "/grouped=={'" + f + "':{'matches':10,'groups':[" + "{'groupValue':1,'doclist':{'numFound':3,'start':10,'numFoundExact':true,'docs':[]}}," + "{'groupValue':3,'doclist':{'numFound':2,'start':10,'numFoundExact':true,'docs':[]}}" + "]}}");
    // test adding in scores
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id,score", "rows", "2", "group.limit", "2", "indent", "off"), "/grouped/" + f + "/groups==" + "[" + "{'groupValue':1,'doclist':{'numFound':3,'start':0,numFoundExact:true,'maxScore':10.0,'docs':[{'id':'8','score':10.0},{'id':'10','score':3.0}]}}," + "{'groupValue':3,'doclist':{'numFound':2,'start':0,numFoundExact:true,'maxScore':7.0,'docs':[{'id':'3','score':7.0},{'id':'6','score':2.0}]}}" + "]");
    // test function (functions are currently all float - this may change)
