    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.func", func, "fl", "id", "rows", "2"), "/grouped=={'" + func + "':{'matches':10,'groups':[" + "{'groupValue':2.0,'doclist':{'numFound':3,'start':0,numFoundExact:true,'docs':[{'id':'8'}]}}," + "{'groupValue':6.0,'doclist':{'numFound':2,'start':0,numFoundExact:true,'docs':[{'id':'3'}]}}" + "]}}");
