    assertEquals(client0.getById("5000") + " and " + client1.getById("5000"), "mytitle", client1.getById("5000").getFirstValue("title"));
    // a DBQ with value
    delQ(client0, params(DISTRIB_UPDATE_PARAM, FROM_LEADER, "_version_", "5005"), // current val is 2, so this should not delete anything
    "val_i_dvo:1");
    assertSync(client1, numVersions, true, shardsArr[0]);
    add(client0, seenLeader, // full update
    sdoc("id", "5000", "val_i_dvo", 0, "title", "mytitle", "_version_", 5000));
    docsAdded.add(5000);
    assertSync(client1, numVersions, true, shardsArr[0]);
    inPlaceParams.set(DistributedUpdateProcessor.DISTRIB_INPLACE_PREVVERSION, "5004");
    add(client0, inPlaceParams, sdoc("id", 5000, "val_i_dvo", 3, "_version_", 5006));
    assertSync(client1, numVersions, true, shardsArr[0]);
    // verify the in-place updated document (id=5000) has correct fields
    assertEquals(3, client1.getById("5000").get("val_i_dvo"));
    assertEquals(client0.getById("5000") + " and " + client1.getById("5000"), "mytitle", client1.getById("5000").getFirstValue("title"));
    validateDocs(docsAdded, client0, client1);
    del(client0, params(DISTRIB_UPDATE_PARAM, FROM_LEADER, "_version_", "5007"), 5000);
    docsAdded.remove(5000);
    assertSync(client1, numVersions, true, shardsArr[0]);
    validateDocs(docsAdded, client0, client1);
    // if doc with id=6000 is deleted, further in-place-updates should fail
    add(client0, seenLeader, // full update
    sdoc("id", "6000", "val_i_dvo", 6, "title", "mytitle", "_version_", 6000));
    delQ(client0, params(DISTRIB_UPDATE_PARAM, FROM_LEADER, "_version_", "6004"), // current val is 6000, this will delete id=6000
    "val_i_dvo:6");
    assertSync(client1, numVersions, true, shardsArr[0]);
    SolrException ex = expectThrows(SolrException.class, () -> {
        inPlaceParams.set(DistributedUpdateProcessor.DISTRIB_INPLACE_PREVVERSION, "6000");
        add(client0, inPlaceParams, sdoc("id", 6000, "val_i_dvo", 6003, "_version_", 5007));
    });
    assertEquals(ex.toString(), SolrException.ErrorCode.SERVER_ERROR.code, ex.code());
    assertThat(ex.getMessage(), containsString("Can't find document with id=6000"));
    // Reordered DBQ with Child-nodes (SOLR-10114)
    docsAdded.clear();
    // Reordered full delete should not delete child-docs
    // add with later version
    add(client0, seenLeader, sdocWithChildren(7001, "7001", 2));
    docsAdded.add(7001);
    docsAdded.add(7001001);
    docsAdded.add(7001002);
    delQ(client0, params(DISTRIB_UPDATE_PARAM, FROM_LEADER, "_version_", "7000"), // reordered delete
    "id:*");
    assertSync(client1, numVersions, true, shardsArr[0]);
    validateDocs(docsAdded, client0, client1);
    // Reordered DBQ should not affect update
    // add with later version
    add(client0, seenLeader, sdocWithChildren(8000, "8000", 5));
    delQ(client0, params(DISTRIB_UPDATE_PARAM, FROM_LEADER, "_version_", "8002"), // not found, arrives earlier
    "id:8500");
    // update with two childs
    add(client0, seenLeader, sdocWithChildren(8000, "8001", 2));
    docsAdded.add(8000);
    docsAdded.add(8000001);
    docsAdded.add(8000002);
    assertSync(client1, numVersions, true, shardsArr[0]);
    validateDocs(docsAdded, client0, client1);
    assertNotEquals(PeerSync.SHARD_REQUEST_PURPOSE_GET_UPDATES, PeerSync.SHARD_REQUEST_PURPOSE_GET_VERSIONS);
    handleVersionsWithRangesTests();
}

@Test
@ShardsFixed(num = 3)
public void test() throws Exception {
    Set<Integer> docsAdded = new LinkedHashSet<>();
    handle.clear();
    handle.put("timestamp", SKIPVAL);
    handle.put("score", SKIPVAL);
    handle.put("maxScore", SKIPVAL);
    SolrClient client0 = clients.get(0);
    SolrClient client1 = clients.get(1);
    long v = 0;
    // add some context
    for (int i = 1; i <= 10; i++) {
        add(client0, seenLeader, sdoc("id", String.valueOf(i), "_version_", ++v));
        add(client1, seenLeader, sdoc("id", String.valueOf(i), "_version_", v));
    }
    // jetty1 was down
    for (int i = 11; i <= 15; i++) {
        add(client0, seenLeader, sdoc("id", String.valueOf(i), "_version_", ++v));
    }
    // it restarted and must do PeerSync
    SolrCore jetty1Core = jettys.get(1).getCoreContainer().getCores().iterator().next();
    jetty1Core.getUpdateHandler().getUpdateLog().bufferUpdates();
    for (int i = 16; i <= 20; i++) {
        add(client0, seenLeader, sdoc("id", String.valueOf(i), "_version_", ++v));
        add(client1, seenLeader, sdoc("id", String.valueOf(i), "_version_", v));
    }
    // some updates are on-wire
    add(client0, seenLeader, sdoc("id", "21", "_version_", ++v));
    add(client0, seenLeader, sdoc("id", "22", "_version_", ++v));
    // this will make a gap in buffer tlog
    add(client0, seenLeader, sdoc("id", "23", "_version_", ++v));
    add(client1, seenLeader, sdoc("id", "23", "_version_", v));
    // client1 should be able to sync
    assertSync(client1, numVersions, shardsArr[0]);
    // on-wire updates arrived at jetty1
    add(client1, seenLeader, sdoc("id", "21", "_version_", v - 2));
    add(client1, seenLeader, sdoc("id", "22", "_version_", v - 1));
    log.info("Apply buffered updates");
    jetty1Core.getUpdateHandler().getUpdateLog().applyBufferedUpdates().get();
    for (int i = 1; i <= 23; i++) docsAdded.add(i);
    validateDocs(docsAdded, client0, client1);
    // random test
    v = 2000;
    if (random().nextBoolean()) {
        for (int i = 24; i <= 30; i++) {
            add(client0, seenLeader, sdoc("id", String.valueOf(i), "_version_", ++v));
            add(client1, seenLeader, sdoc("id", String.valueOf(i), "_version_", v));
        }
    }
    log.info("After buffer updates");
    jetty1Core.getUpdateHandler().getUpdateLog().bufferUpdates();
    Set<Integer> docIds = new HashSet<>();
    for (int i = 0; i <= 50; i++) {
        int kindOfUpdate = random().nextInt(100);
        if (docIds.size() < 10)
            kindOfUpdate = 0;
        // TODO test atomic update
        if (kindOfUpdate <= 50) {
            // add a new document update, may be duplicate with the current one
            int val = random().nextInt(1000);
            int docId = random().nextInt(10000);
            docIds.add(docId);
            SolrInputDocument doc = sdoc("id", docId, "val_i_dvo", val, "_version_", ++v);
            add(client0, seenLeader, doc);
            if (random().nextBoolean()) {
                add(client1, seenLeader, doc);
            }
        } else if (kindOfUpdate <= 65) {
            // delete by query
            ArrayList<Integer> ids = new ArrayList<>(docIds);
            int docId1 = ids.get(random().nextInt(ids.size()));
            int docId2 = ids.get(random().nextInt(ids.size()));
            String query = "id:" + docId1 + " OR id:" + docId2;
            String version = Long.toString(-++v);
            delQ(client0, params(DISTRIB_UPDATE_PARAM, FROM_LEADER, "_version_", version), query);
            if (random().nextBoolean()) {
                delQ(client1, params(DISTRIB_UPDATE_PARAM, FROM_LEADER, "_version_", version), query);
            }
        } else {
            // delete by id
            ArrayList<Integer> ids = new ArrayList<>(docIds);
            String docId = ids.get(random().nextInt(ids.size())) + "";
            String version = Long.toString(-++v);
            del(client0, params(DISTRIB_UPDATE_PARAM, FROM_LEADER, "_version_", version), docId);
            if (random().nextBoolean()) {
                del(client1, params(DISTRIB_UPDATE_PARAM, FROM_LEADER, "_version_", version), docId);
            }
        }
    }
    // with many gaps, client1 should be able to sync
    assertSync(client1, numVersions, shardsArr[0]);
}

