@Test
public void testRemoveregex() {
    SolrInputDocument doc;
    doc = new SolrInputDocument();
    doc.setField("id", "1");
    doc.setField("cat", new String[] { "aaa", "bbb", "ccc", "ccc", "ddd" });
    assertU(adoc(doc));
    doc = new SolrInputDocument();
    doc.setField("id", "2");
    doc.setField("cat", new String[] { "aaa", "bbb", "bbb", "ccc", "ddd" });
    assertU(adoc(doc));
    doc = new SolrInputDocument();
    doc.setField("id", "20");
    doc.setField("cat", new String[] { "aaa", "ccc", "ddd" });
    assertU(adoc(doc));
    doc = new SolrInputDocument();
    doc.setField("id", "21");
    doc.setField("cat", new String[] { "aaa", "bbb", "ddd" });
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '4']");
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '3']");
    assertQ(req("q", "cat:ccc", "indent", "true"), "//result[@numFound = '3']");
    doc = new SolrInputDocument();
    doc.setField("id", "1");
    List<String> removeList = new ArrayList<>();
    removeList.add(".b.");
    removeList.add("c+c");
    // behavior when hitting Solr through ZK
    doc.setField("cat", Map.of("removeregex", removeList));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '4']");
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '2']");
    assertQ(req("q", "cat:ccc", "indent", "true"), // removeregex does remove all occurrences
    "//result[@numFound = '2']");
    doc = new SolrInputDocument();
    doc.setField("id", "21");
    removeList = new ArrayList<>();
    removeList.add("bb*");
    removeList.add("cc+");
    // behavior when hitting Solr through ZK
    doc.setField("cat", Map.of("removeregex", removeList));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '4']");
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '1']");
    doc = new SolrInputDocument();
    doc.setField("id", "1");
    // behavior when hitting Solr directly
    doc.setField("cat", Map.of("removeregex", "a.a"));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '4']");
    assertQ(req("q", "cat:aaa", "indent", "true"), "//result[@numFound = '3']");
}

@Test
public void testRemoveregexMustMatchWholeValue() {
    SolrInputDocument doc;
    doc = new SolrInputDocument();
    doc.setField("id", "1");
    doc.setField("cat", new String[] { "aaa", "bbb", "ccc", "ccc", "ddd" });
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '1']");
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '1']");
    doc = new SolrInputDocument();
    doc.setField("id", "1");
    List<String> removeList = new ArrayList<>();
    removeList.add("bb");
    // behavior when hitting Solr through ZK
    doc.setField("cat", Map.of("removeregex", removeList));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '1']");
    assertQ(req("q", "cat:bbb", "indent", "true"), // Was not removed - regex didn't match whole value
    "//result[@numFound = '1']");
    doc = new SolrInputDocument();
    doc.setField("id", "1");
    removeList = new ArrayList<>();
    removeList.add("bbb");
    // behavior when hitting Solr through ZK
    doc.setField("cat", Map.of("removeregex", removeList));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '1']");
    assertQ(req("q", "cat:bbb", "indent", "true"), // Was removed now - regex matches
    "//result[@numFound = '0']");
}

@Test
public void testAdd() {
    SolrInputDocument doc = new SolrInputDocument();
    doc.setField("id", "3");
