    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '2']");
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '0']");
    doc = new SolrInputDocument();
    doc.setField("id", "3");
    doc.setField("cat", Map.of("add-distinct", "bbb"));
    doc.setField("atomic_is", Map.of("add-distinct", 10));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '2']");
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '1']");
    assertQ(req("q", "cat:bbb", "indent", "true"), "//doc/arr[@name='cat'][count(str)=3]", "//doc/arr[@name='atomic_is'][count(int)=1]");
    doc = new SolrInputDocument();
    doc.setField("id", "3");
    doc.setField("cat", Map.of("add-distinct", Arrays.asList("bbb", "bbb")));
    doc.setField("atomic_is", Map.of("add-distinct", Arrays.asList(10, 34)));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '2']");
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '1']");
    assertQ(req("q", "cat:bbb", "indent", "true"), // 'bbb' already present will not be added again
    "//doc/arr[@name='cat'][count(str)=3]", "//doc/arr[@name='atomic_is'][count(int)=2]");
    doc = new SolrInputDocument();
    doc.setField("id", "5");
    doc.setField("cat", Map.of("add-distinct", "bbb"));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '3']");
    assertQ(req("q", "cat:bbb", "indent", "true"), // 'cat' field not present, do 'add' atomic operation
    "//result[@numFound = '2']");
}

