    addDocsAndCommit(false, newDoc("calico", "2019-07-04T00:00:00Z"), newDoc("tabby", "2019-07-01T00:00:00Z"), newDoc("tabby", "2019-07-01T23:00:00Z"), newDoc("calico", "2019-07-03T23:00:00Z"));
    assertCatTimeInvariants(ap(catTimeDraColFor("calico", "2019-07-01"), catTimeDraColFor("calico", "2019-07-02"), catTimeDraColFor("calico", "2019-07-03"), catTimeDraColFor("calico", "2019-07-04"), catTimeDraColFor("tabby", "2019-07-01"), catTimeDraColFor("tabby", "2019-07-02")), ap("tabby", "calico"));
    // now test with async pre-create.
    CollectionAdminRequest.setAliasProperty(getAlias()).addProperty("router.1.preemptiveCreateMath", "30MINUTE").process(solrClient);
    addDocsAndCommit(false, // create 2 sync 1 async
    newDoc("shorthair", "2019-07-02T23:40:00Z"), // does not create
    newDoc("calico", "2019-07-03T23:00:00Z"));
    waitColAndAlias(getAlias(), "", CRA + "shorthair" + TRA + "2019-07-03", 2);
    assertCatTimeInvariants(ap(catTimeDraColFor("calico", "2019-07-01"), catTimeDraColFor("calico", "2019-07-02"), catTimeDraColFor("calico", "2019-07-03"), catTimeDraColFor("calico", "2019-07-04"), catTimeDraColFor("shorthair", "2019-07-01"), catTimeDraColFor("shorthair", "2019-07-02"), catTimeDraColFor("shorthair", "2019-07-03"), catTimeDraColFor("tabby", "2019-07-01"), catTimeDraColFor("tabby", "2019-07-02")), ap("shorthair", "tabby", "calico"));
    addDocsAndCommit(false, // should be no change
    newDoc("shorthair", "2019-07-02T23:40:00Z"), newDoc("calico", "2019-07-03T23:00:00Z"));
    /*
     Here we need to be testing that something that should not be created (extra preemptive async collections)
     didn't get created (a bug that actually got killed during development, and caused later asserts to
     fail due to wrong number of collections). There's no way to set a watch for something that doesn't and
     should never exist... Thus, the only choice is to sleep and make sure nothing appeared while we were asleep.
    */
    Thread.sleep(5000);
    assertCatTimeInvariants(ap(catTimeDraColFor("calico", "2019-07-01"), catTimeDraColFor("calico", "2019-07-02"), catTimeDraColFor("calico", "2019-07-03"), catTimeDraColFor("calico", "2019-07-04"), catTimeDraColFor("shorthair", "2019-07-01"), catTimeDraColFor("shorthair", "2019-07-02"), catTimeDraColFor("shorthair", "2019-07-03"), catTimeDraColFor("tabby", "2019-07-01"), catTimeDraColFor("tabby", "2019-07-02")), ap("shorthair", "tabby", "calico"));
    // now test with auto-delete.
    CollectionAdminRequest.setAliasProperty(getAlias()).addProperty("router.1.autoDeleteAge", "/DAY-5DAY").process(solrClient);
    // this one should not yet cause deletion
    addDocsAndCommit(false, // no effect expected
    newDoc("shorthair", "2019-07-02T23:00:00Z"), // create 1
    newDoc("calico", "2019-07-05T23:00:00Z"));
    assertCatTimeInvariants(ap(catTimeDraColFor("calico", "2019-07-01"), catTimeDraColFor("calico", "2019-07-02"), catTimeDraColFor("calico", "2019-07-03"), catTimeDraColFor("calico", "2019-07-04"), catTimeDraColFor("calico", "2019-07-05"), catTimeDraColFor("shorthair", "2019-07-01"), catTimeDraColFor("shorthair", "2019-07-02"), catTimeDraColFor("shorthair", "2019-07-03"), catTimeDraColFor("tabby", "2019-07-01"), catTimeDraColFor("tabby", "2019-07-02")), ap("shorthair", "tabby", "calico"));
    addDocsAndCommit(true, // no effect expected
    newDoc("shorthair", "2019-07-02T23:00:00Z"), // create July 6, delete July 1
    newDoc("calico", "2019-07-06T00:00:00Z"));
    waitCoreCount(getAlias() + CRA + "calico" + TRA + "2019-07-01", 0);
    assertCatTimeInvariants(ap(catTimeDraColFor("calico", "2019-07-02"), catTimeDraColFor("calico", "2019-07-03"), catTimeDraColFor("calico", "2019-07-04"), catTimeDraColFor("calico", "2019-07-05"), catTimeDraColFor("calico", "2019-07-06"), // note that other categories are unaffected
    catTimeDraColFor("shorthair", "2019-07-01"), catTimeDraColFor("shorthair", "2019-07-02"), catTimeDraColFor("shorthair", "2019-07-03"), catTimeDraColFor("tabby", "2019-07-01"), catTimeDraColFor("tabby", "2019-07-02")), ap("shorthair", "tabby", "calico"));
    // verify that all the documents ended up in the right collections.
    QueryResponse resp = solrClient.query(getAlias(), params("q", "*:*", "rows", "100", "fl", "*,[shard]", "sort", "id asc"));
    SolrDocumentList results = resp.getResults();
    assertEquals(18, results.getNumFound());
    for (SolrDocument result : results) {
        String shard = String.valueOf(result.getFieldValue("[shard]"));
        String cat = String.valueOf(result.getFieldValue("cat_s"));
        Date date = (Date) result.getFieldValue("timestamp_dt");
        String day = date.toInstant().toString().split("T")[0];
        assertTrue(shard.contains(cat));
        assertTrue(shard.contains(day));
    }
}

@Test
public void testShouldBufferUpdateZk() throws IOException {
    SolrQueryRequest req = new LocalSolrQueryRequest(h.getCore(), new ModifiableSolrParams());
    try (DistributedUpdateProcessor processor = new DistributedUpdateProcessor(req, null, null, null)) {
        AddUpdateCommand cmd = new AddUpdateCommand(req);
        // applying buffer updates, isReplayOrPeerSync flag doesn't matter
        assertFalse(processor.shouldBufferUpdate(cmd, false, UpdateLog.State.APPLYING_BUFFERED));
        assertFalse(processor.shouldBufferUpdate(cmd, true, UpdateLog.State.APPLYING_BUFFERED));
        assertTrue(processor.shouldBufferUpdate(cmd, false, UpdateLog.State.BUFFERING));
        // this is not a buffering update, and it depends on other updates
        cmd.prevVersion = 10;
        assertTrue(processor.shouldBufferUpdate(cmd, false, UpdateLog.State.APPLYING_BUFFERED));
    }
}

@Test
public void testVersionAdd() throws IOException {
    SolrQueryRequest req = new LocalSolrQueryRequest(h.getCore(), new ModifiableSolrParams());
    int threads = 5;
    Function<DistributedUpdateProcessor, Boolean> versionAddFunc = (DistributedUpdateProcessor process) -> {
        try {
            AddUpdateCommand cmd = new AddUpdateCommand(req);
            cmd.solrDoc = new SolrInputDocument();
            cmd.solrDoc.setField("notid", "10");
            return process.versionAdd(cmd);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    };
    int succeeded = runCommands(threads, 1000, req, versionAddFunc);
    // only one should succeed
    assertThat(succeeded, is(1));
    succeeded = runCommands(threads, -1, req, versionAddFunc);
    // all should succeed
    assertThat(succeeded, is(threads));
}

