@Test
public void testBlockAtomicInplaceUpdates() throws Exception {
    SolrInputDocument doc = sdoc("id", "1", "string_s", "root");
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "id:1", "fl", "*"), "//*[@numFound='1']", "//doc[1]/str[@name='id']=1");
    List<SolrInputDocument> docs = IntStream.range(10, 20).mapToObj(x -> sdoc("id", String.valueOf(x), "string_s", "child", "inplace_updatable_int", "0")).collect(Collectors.toList());
    doc = sdoc("id", "1", "_root_", "1", "children", Collections.singletonMap("add", docs));
    addAndGetVersion(doc, null);
    assertU(commit());
    assertQ(req("q", "_root_:1", "fl", "*", "rows", "11"), "//*[@numFound='11']");
    assertQ(req("q", "string_s:child", "fl", "*"), "//*[@numFound='10']", "*[count(//str[@name='string_s'][.='child'])=10]");
    for (int i = 10; i < 20; ++i) {
        doc = sdoc("id", String.valueOf(i), "_root_", "1", "inplace_updatable_int", Collections.singletonMap("inc", "1"));
        addAndGetVersion(doc, null);
        assertU(commit());
    }
    for (int i = 10; i < 20; ++i) {
        doc = sdoc("id", String.valueOf(i), "_root_", "1", "inplace_updatable_int", Collections.singletonMap("inc", "1"));
        addAndGetVersion(doc, null);
        assertU(commit());
    }
    // ensure updates work when block has more than 10 children
    for (int i = 10; i < 20; ++i) {
        docs = IntStream.range(i * 10, (i * 10) + 5).mapToObj(x -> sdoc("id", String.valueOf(x), "string_s", "grandChild")).collect(Collectors.toList());
        doc = sdoc("id", String.valueOf(i), "_root_", "1", "grandChildren", Collections.singletonMap("add", docs));
        addAndGetVersion(doc, null);
        assertU(commit());
    }
    for (int i = 10; i < 20; ++i) {
        doc = sdoc("id", String.valueOf(i), "_root_", "1", "inplace_updatable_int", Collections.singletonMap("inc", "1"));
        addAndGetVersion(doc, null);
        assertU(commit());
    }
    assertQ(req("q", "-_root_:*", "fl", "*"), "//*[@numFound='0']");
    assertQ(req("q", "string_s:grandChild", "fl", "*", "rows", "50"), "//*[@numFound='50']");
    assertQ(req("q", "string_s:child", "fl", "*"), "//*[@numFound='10']", "*[count(//str[@name='string_s'][.='child'])=10]");
    assertJQ(req("q", "id:1", "fl", "*,[child limit=-1]"), "/response/docs/[0]/id=='1'", "/response/docs/[0]/children/[0]/id=='10'", "/response/docs/[0]/children/[0]/inplace_updatable_int==3", "/response/docs/[0]/children/[0]/grandChildren/[0]/id=='100'", "/response/docs/[0]/children/[0]/grandChildren/[4]/id=='104'", "/response/docs/[0]/children/[9]/id=='19'");
}

