@Test
@LogLevel("org.apache.solr.update.processor.TimeRoutedAlias=DEBUG;org.apache.solr.cloud=DEBUG")
public void test() throws Exception {
    String configName = getSaferTestName();
    createConfigSet(configName);
    // Start with one collection manually created (and use higher numShards & replicas than we'll
    // use for others) This tests we may pre-create the collection, and it's acceptable.
    final String col23rd = alias + TRA + "2017-10-23";
    CollectionAdminRequest.createCollection(col23rd, configName, 2, 2).withProperty(ROUTED_ALIAS_NAME_CORE_PROP, alias).process(solrClient);
    cluster.waitForActiveCollection(col23rd, 2, 4);
    List<String> retrievedConfigSetNames = new ConfigSetAdminRequest.List().process(solrClient).getConfigSets();
    List<String> expectedConfigSetNames = Arrays.asList("_default", configName);
    // config sets leak between tests, so we can't be any more specific than this on the next 2
    // asserts
    assertTrue("We expect at least 2 configSets", retrievedConfigSetNames.size() >= expectedConfigSetNames.size());
    assertTrue("ConfigNames should include :" + expectedConfigSetNames, retrievedConfigSetNames.containsAll(expectedConfigSetNames));
    CollectionAdminRequest.createTimeRoutedAlias(alias, "2017-10-23T00:00:00Z", "+1DAY", getTimeField(), CollectionAdminRequest.createCollection("_unused_", configName, 1, 1)).process(solrClient);
    // now we index a document
    assertUpdateResponse(solrClient.add(alias, newDoc(Instant.parse("2017-10-23T00:00:00Z"))));
    solrClient.commit(alias);
    // assertDocRoutedToCol(lastDocId, col23rd);
    assertInvariants(col23rd);
    // a document that is too old
    testFailedDocument(Instant.parse("2017-10-01T00:00:00Z"), "couldn't be routed");
    // a document which is too far into the future
    testFailedDocument(Instant.now().plus(30, ChronoUnit.MINUTES), "too far in the future");
    // add another collection with the precise name we expect, but don't add to alias explicitly.
    // When we add a document destined for this collection, Solr will see it already exists and add
    // it to the alias.
    final String col24th = alias + TRA + "2017-10-24";
    CollectionAdminRequest.createCollection(col24th, configName, 1, // more shards and replicas now
    1).withProperty(ROUTED_ALIAS_NAME_CORE_PROP, alias).process(solrClient);
    // index 3 documents in a random fashion
    addDocsAndCommit(// send these to alias & collections
    false, newDoc(Instant.parse("2017-10-23T00:00:00Z")), newDoc(Instant.parse("2017-10-24T01:00:00Z")), newDoc(Instant.parse("2017-10-24T02:00:00Z")));
    //    System.out.println(cluster.getRandomJetty(random()).getBaseUrl());
    //    Thread.sleep(1000000);
    assertInvariants(col24th, col23rd);
    // assert that the IncrementURP has updated all '0' to '1'
    final SolrDocumentList checkIncResults = solrClient.query(alias, params("q", "NOT " + getIntField() + ":1")).getResults();
    assertEquals(checkIncResults.toString(), 0, checkIncResults.getNumFound());
    // delete a random document id; ensure we don't find it
    int idToDelete = 1 + random().nextInt(lastDocId);
    if (idToDelete == 2 || idToDelete == 3) {
        // these didn't make it
        idToDelete = 4;
    }
    assertUpdateResponse(solrClient.deleteById(alias, Integer.toString(idToDelete)));
    assertUpdateResponse(solrClient.commit(alias));
    numDocsDeletedOrFailed++;
    assertInvariants(col24th, col23rd);
    // delete the Oct23rd (save memory)...
    //   make sure we track that we are effectively deleting docs there
    numDocsDeletedOrFailed += solrClient.query(col23rd, params("q", "*:*", "rows", "0")).getResults().getNumFound();
    //   remove from the alias
    CollectionAdminRequest.createAlias(alias, col24th).process(solrClient);
    //   delete the collection
    CollectionAdminRequest.deleteCollection(col23rd).process(solrClient);
    // now we're going to add documents that will trigger more collections to be created
    //   for 25th & 26th
    addDocsAndCommit(// send these to alias & collections
    false, newDoc(Instant.parse("2017-10-24T03:00:00Z")), newDoc(Instant.parse("2017-10-25T04:00:00Z")), newDoc(Instant.parse("2017-10-26T05:00:00Z")), newDoc(Instant.parse("2017-10-26T06:00:00Z")));
    assertInvariants(alias + TRA + "2017-10-26", alias + TRA + "2017-10-25", col24th);
    // verify that collection properties are set when the collections are created. Note: first 2
    // collections in this test have a core property instead, of a collection property but that MUST
    // continue to work as well for back compatibility's reasons.
    Thread.sleep(1000);
    byte[] data = cluster.getZkClient().getData(COLLECTIONS_ZKNODE + "/" + alias + TRA + "2017-10-26" + "/" + COLLECTION_PROPS_ZKNODE, null, null, true);
    assertNotNull(data);
    assertTrue(data.length > 0);
    @SuppressWarnings("unchecked")
    Map<String, String> props = (Map<String, String>) Utils.fromJSON(data);
    assertTrue(props.containsKey(ROUTED_ALIAS_NAME_CORE_PROP));
    assertEquals(alias, props.get(ROUTED_ALIAS_NAME_CORE_PROP));
    // update metadata to auto-delete oldest collections
    CollectionAdminRequest.setAliasProperty(alias).addProperty(TimeRoutedAlias.ROUTER_AUTO_DELETE_AGE, // thus, usually keep 2 collections of a day size
    "-1DAY").process(solrClient);
    // add more docs, creating one new collection, but trigger ones prior to
    int numDocsToBeAutoDeleted = queryNumDocs(getTimeField() + ":[* TO \"2017-10-26T00:00:00Z\"}");
    addDocsAndCommit(// send these to alias only
    true, // existing
    newDoc(Instant.parse("2017-10-26T07:00:00Z")), // new
    newDoc(Instant.parse("2017-10-27T08:00:00Z")));
    numDocsDeletedOrFailed += numDocsToBeAutoDeleted;
    assertInvariants(alias + TRA + "2017-10-27", alias + TRA + "2017-10-26");
}

/**
 * Test that the Update Processor Factory routes documents to leader shards and thus avoids the
 * possibility of introducing an extra hop to find the leader.
 *
 * @throws Exception when it blows up unexpectedly :)
 */
@Test
@LogLevel("org.apache.solr.update.processor.TrackingUpdateProcessorFactory=DEBUG")
public void testSliceRouting() throws Exception {
    String configName = getSaferTestName();
    createConfigSet(configName);
    // each collection has 4 shards with 3 replicas for 12 possible destinations
    // 4 of which are leaders, and 8 of which should fail this test.
    final int numShards = 1 + random().nextInt(4);
    final int numReplicas = 1 + random().nextInt(3);
    CollectionAdminRequest.createTimeRoutedAlias(alias, "2017-10-23T00:00:00Z", "+1DAY", getTimeField(), CollectionAdminRequest.createCollection("_unused_", configName, numShards, numReplicas)).process(solrClient);
    // cause some collections to be created
    assertUpdateResponse(solrClient.add(alias, new SolrInputDocument("id", "1", "timestamp_dt", "2017-10-25T00:00:00Z")));
    assertUpdateResponse(solrClient.commit(alias));
    // wait for all the collections to exist...
    waitColAndAlias(alias, TRA, "2017-10-23", numShards);
    waitColAndAlias(alias, TRA, "2017-10-24", numShards);
    waitColAndAlias(alias, TRA, "2017-10-25", numShards);
    // at this point we now have 3 collections with 4 shards each, and 3 replicas per shard for a
    // total of 36 total replicas, 1/3 of which are leaders. We will add 3 docs and each has a 33%
    // chance of hitting a leader randomly and not causing a failure if the code is broken, but as a
    // whole this test will therefore only have about a 3.6% false positive rate (0.33^3). If that's
    // not good enough, add more docs or more replicas per shard :).
    final String trackGroupName = getTrackUpdatesGroupName();
    final List<UpdateCommand> updateCommands;
    try {
        TrackingUpdateProcessorFactory.startRecording(trackGroupName);
        // cause some collections to be created
        ModifiableSolrParams params = params("post-processor", "tracking-" + trackGroupName);
        assertUpdateResponse(add(alias, Arrays.asList(sdoc("id", "2", "timestamp_dt", "2017-10-24T00:00:00Z"), sdoc("id", "3", "timestamp_dt", "2017-10-25T00:00:00Z"), sdoc("id", "4", "timestamp_dt", "2017-10-23T00:00:00Z")), params));
    } finally {
        updateCommands = TrackingUpdateProcessorFactory.stopRecording(trackGroupName);
    }
    assertRouting(numShards, updateCommands);
}

@Test
public void testPreemptiveCreation() throws Exception {
    String configName = getSaferTestName();
    createConfigSet(configName);
    final int numShards = 1;
    final int numReplicas = 1;
    CollectionAdminRequest.createTimeRoutedAlias(alias, "2017-10-23T00:00:00Z", "+1DAY", getTimeField(), CollectionAdminRequest.createCollection("_unused_", configName, numShards, numReplicas)).setPreemptiveCreateWindow("3HOUR").process(solrClient);
    // needed to verify that preemptive creation in one alias doesn't inhibit preemptive creation in
    // another
    CollectionAdminRequest.createTimeRoutedAlias(alias2, "2017-10-23T00:00:00Z", "+1DAY", getTimeField(), CollectionAdminRequest.createCollection("_unused_", configName, numShards, numReplicas)).setPreemptiveCreateWindow("3HOUR").process(solrClient);
    addOneDocSyncCreation(numShards, alias);
    addOneDocSyncCreation(numShards, alias2);
    List<String> cols;
    ModifiableSolrParams params = params();
    // Using threads to ensure that two TRA's  are simultaneously preemptively creating and don't
    // interfere with each other
    ExecutorService executorService = ExecutorUtil.newMDCAwareCachedThreadPool("TimeRoutedAliasProcessorTestx-testPreemptiveCreation");
    Exception[] threadExceptions = new Exception[2];
    boolean[] threadStarted = new boolean[2];
    boolean[] threadFinished = new boolean[2];
    try {
        CountDownLatch starter = new CountDownLatch(1);
        executorService.execute(() -> {
            threadStarted[0] = true;
            try {
                starter.await();
                concurrentUpdates(params, alias);
            } catch (Exception e) {
                threadExceptions[0] = e;
            }
            threadFinished[0] = true;
        });
        executorService.execute(() -> {
            threadStarted[1] = true;
            try {
                starter.await();
                concurrentUpdates(params, alias2);
            } catch (Exception e) {
                threadExceptions[1] = e;
            }
            threadFinished[1] = true;
        });
        starter.countDown();
    } finally {
        ExecutorUtil.shutdownAndAwaitTermination(executorService);
    }
    // threads are known to be terminated by now, check for exceptions
    for (Exception threadException : threadExceptions) {
        if (threadException != null) {
            // avoid spurious fails due to TRA thread not done yet
            Thread.sleep(5000);
            throw threadException;
        }
    }
    // just for confidence that there's nothing dodgy about how the threads executed.
    assertTrue(threadStarted[0]);
    assertTrue(threadStarted[1]);
    assertTrue(threadFinished[0]);
    assertTrue(threadFinished[1]);
    // if one of these times out then the test has failed due to interference between aliases
    waitColAndAlias(alias, TRA, "2017-10-26", numShards);
    waitColAndAlias(alias2, TRA, "2017-10-26", numShards);
    // these next checks will be checking that a collection DID NOT get created asynchronously,
    // there's no way to wait for something that should never exist to not exist... so all we can do
    // is sleep a good while before checking
    Thread.sleep(5000);
    // after this we can ignore alias2
    checkPreemptiveCase1(alias);
    checkPreemptiveCase1(alias2);
    // Some designs contemplated with close hooks were not properly restricted to the core and would
    // have failed after other cores with other TRAs were stopped. Make sure that we don't fall into
    // that trap in the future. The basic problem with a close hook solution is that one either
    // winds up putting the executor on the TRAUP where it's duplicated/initiated for every request,
    // or putting it at the class level in which case the hook will remove it for all TRA's which
    // can pass a single TRA test nicely but is not safe where multiple TRA's might come and go.
    //
    // Start and stop some cores that have TRA's... 2x2 used to ensure every jetty gets at least one
    CollectionAdminRequest.createTimeRoutedAlias(getSaferTestName() + "foo", "2017-10-23T00:00:00Z", "+1DAY", getTimeField(), CollectionAdminRequest.createCollection("_unused_", configName, 2, 2)).setPreemptiveCreateWindow("3HOUR").process(solrClient);
    waitColAndAlias(getSaferTestName() + "foo", TRA, "2017-10-23", 2);
    waitCoreCount(getSaferTestName() + "foo" + TRA + "2017-10-23", // prove this works, for confidence in deletion checking below.
    4);
    assertUpdateResponse(solrClient.add(getSaferTestName() + "foo", sdoc("id", "1", "timestamp_dt", // no extra collections should be created
    "2017-10-23T00:00:00Z")));
    assertUpdateResponse(solrClient.commit(getSaferTestName() + "foo"));
    List<String> foo = solrClient.getClusterStateProvider().resolveAlias(getSaferTestName() + "foo");
    CollectionAdminRequest.deleteAlias(getSaferTestName() + "foo").process(solrClient);
    for (String colName : foo) {
        CollectionAdminRequest.deleteCollection(colName).process(solrClient);
        waitCoreCount(colName, 0);
    }
    // if the design for terminating our executor is correct create/delete above will not cause
    // failures below continue testing...
    cols = new CollectionAdminRequest.ListAliases().process(solrClient).getAliasesAsLists().get(alias);
    // only one created in async case
    assertEquals(4, cols.size());
    // now test with pre-create window longer than time slice, only one creation per request
    CollectionAdminRequest.setAliasProperty(alias).addProperty(TimeRoutedAlias.ROUTER_PREEMPTIVE_CREATE_MATH, "3DAY").process(solrClient);
    assertUpdateResponse(add(alias, Arrays.asList(sdoc("id", "7", "timestamp_dt", // should cause preemptive creation of 10-27 now
    "2017-10-25T23:01:00Z"), sdoc("id", "71", "timestamp_dt", // should not cause preemptive creation of 10-28 now
    "2017-10-25T23:02:00Z")), params));
    assertUpdateResponse(solrClient.commit(alias));
    waitColAndAlias(alias, TRA, "2017-10-27", numShards);
    cols = new CollectionAdminRequest.ListAliases().process(solrClient).getAliasesAsLists().get(alias);
    // only one created in async case
    assertEquals(5, cols.size());
    assertNumDocs("2017-10-23", 1, alias);
    assertNumDocs("2017-10-24", 1, alias);
    assertNumDocs("2017-10-25", 6, alias);
    assertNumDocs("2017-10-26", 0, alias);
    assertNumDocs("2017-10-27", 0, alias);
    assertUpdateResponse(add(alias, Collections.singletonList(sdoc("id", "8", "timestamp_dt", // should cause preemptive creation of 10-28 now
    "2017-10-25T23:01:00Z")), params));
    assertUpdateResponse(solrClient.commit(alias));
    waitColAndAlias(alias, TRA, "2017-10-28", numShards);
    cols = new CollectionAdminRequest.ListAliases().process(solrClient).getAliasesAsLists().get(alias);
    assertEquals(6, cols.size());
    assertNumDocs("2017-10-23", 1, alias);
    assertNumDocs("2017-10-24", 1, alias);
    assertNumDocs("2017-10-25", 7, alias);
    assertNumDocs("2017-10-26", 0, alias);
    assertNumDocs("2017-10-27", 0, alias);
    assertNumDocs("2017-10-28", 0, alias);
    QueryResponse resp;
    resp = solrClient.query(alias, params("q", "*:*", "rows", "10"));
    assertEquals(9, resp.getResults().getNumFound());
    assertUpdateResponse(add(alias, Arrays.asList(sdoc("id", "9", "timestamp_dt", // should cause preemptive creation
    "2017-10-27T23:01:00Z"), // If these are not ignored properly this test will fail during cleanup with a
    // message about router.name being required. This happens because the test finishes
    // while overseer threads are still trying to invoke maintain after the @After
    // method has deleted collections and emptied out the aliases.... this leaves the
    // maintain command cloning alias properties Aliases.EMPTY and thus not getting a
    // value from router.name (normally router.name == 'time') The check for non-blank
    // router.name  happens to be the first validation. There is a small chance this
    // could slip through without a fail occasionally, but it was 100% with just one of
    // these.
    sdoc("id", "10", "timestamp_dt", // should be ignored due to in progress creation
    "2017-10-28T23:01:00Z"), sdoc("id", "11", "timestamp_dt", // should be ignored due to in progress creation
    "2017-10-28T23:02:00Z"), sdoc("id", "12", "timestamp_dt", // should be ignored due to in progress creation
    "2017-10-28T23:03:00Z")), params));
    assertUpdateResponse(solrClient.commit(alias));
    waitColAndAlias(alias, TRA, "2017-10-29", numShards);
    cols = new CollectionAdminRequest.ListAliases().process(solrClient).getAliasesAsLists().get(alias);
    assertEquals(7, cols.size());
    assertNumDocs("2017-10-23", 1, alias);
    assertNumDocs("2017-10-24", 1, alias);
    assertNumDocs("2017-10-25", 7, alias);
    assertNumDocs("2017-10-26", 0, alias);
    assertNumDocs("2017-10-27", 1, alias);
    assertNumDocs("2017-10-28", 3, // should get through even though preemptive creation ignored it.
    alias);
    assertNumDocs("2017-10-29", 0, alias);
    resp = solrClient.query(alias, params("q", "*:*", "rows", "0"));
    assertEquals(13, resp.getResults().getNumFound());
    // Sync creation with an interval longer than the time slice for the alias...
    assertUpdateResponse(add(alias, Collections.singletonList(// lucky?
    sdoc("id", "13", "timestamp_dt", "2017-10-30T23:03:00Z")), params));
    assertUpdateResponse(solrClient.commit(alias));
    waitColAndAlias(alias, TRA, "2017-10-30", numShards);
    // removed support for this case because it created a LOT of complexity for the benefit of
    // attempting to (maybe) not pause again after already hitting a synchronous creation (but only
    // if async gets it done first), otherwise we have a race... not enough benefit to justify the
    // support/complexity.
    //
    // Now we just let the next doc take care of it...
    //
    // waitColAndAlias(alias, TRA, "2017-10-31", numShards); // spooky! async case arising in middle
    // of sync creation!!
    cols = new CollectionAdminRequest.ListAliases().process(solrClient).getAliasesAsLists().get(alias);
    assertEquals(8, cols.size());
    assertNumDocs("2017-10-23", 1, alias);
    assertNumDocs("2017-10-24", 1, alias);
    assertNumDocs("2017-10-25", 7, alias);
    assertNumDocs("2017-10-26", 0, alias);
    assertNumDocs("2017-10-27", 1, alias);
    assertNumDocs("2017-10-28", 3, // should get through even though preemptive creation ignored it.
    alias);
    assertNumDocs("2017-10-29", 0, alias);
    assertNumDocs("2017-10-30", 1, alias);
    resp = solrClient.query(alias, params("q", "*:*", "rows", "0"));
    assertEquals(14, resp.getResults().getNumFound());
    assertUpdateResponse(add(alias, Collections.singletonList(sdoc("id", "14", "timestamp_dt", // should cause preemptive creation 10-31
    "2017-10-30T23:01:00Z")), params));
    waitColAndAlias(alias, TRA, "2017-10-31", numShards);
    assertUpdateResponse(add(alias, Collections.singletonList(sdoc("id", "15", "timestamp_dt", // should cause preemptive creation 11-01
    "2017-10-30T23:01:00Z")), params));
    waitColAndAlias(alias, TRA, "2017-11-01", numShards);
    assertUpdateResponse(add(alias, Collections.singletonList(sdoc("id", "16", "timestamp_dt", // should cause preemptive creation 11-02
    "2017-10-30T23:01:00Z")), params));
    waitColAndAlias(alias, TRA, "2017-11-02", numShards);
    assertUpdateResponse(add(alias, Collections.singletonList(sdoc("id", "17", "timestamp_dt", // should NOT cause preemptive creation 11-03
    "2017-10-30T23:01:00Z")), params));
    cols = new CollectionAdminRequest.ListAliases().process(solrClient).getAliasesAsLists().get(alias);
    assertFalse(cols.contains("myalias" + TRA + "2017-11-03"));
    assertUpdateResponse(add(alias, Collections.singletonList(sdoc("id", "18", "timestamp_dt", // should cause preemptive creation 11-03
    "2017-10-31T23:01:00Z")), params));
    waitColAndAlias(alias, TRA, "2017-11-03", numShards);
}

