@Test
public void testExceededMaxTermLength() {
    // problematic field
    final String longFieldName = "cat";
    final String longFieldValue = TestUtil.randomSimpleString(random(), minTestTermLength, maxTestTermLength);
    final String okayFieldName = // Dynamic field
    TestUtil.randomSimpleString(random(), 1, 50) + "_sS";
    final String okayFieldValue = TestUtil.randomSimpleString(random(), minTestTermLength, maxTestTermLength);
    boolean includeOkayFields = random().nextBoolean();
    if (random().nextBoolean()) {
        // Use XML
        String doc;
        if (includeOkayFields) {
            doc = adoc("id", "1", longFieldName, longFieldValue, okayFieldName, okayFieldValue);
        } else {
            doc = adoc("id", "1", longFieldName, longFieldValue);
        }
        assertFailedU(doc);
    } else {
        // Use JSON
        final String jsonStr;
        if (includeOkayFields) {
            String format = "[{'id':'1','%s':'%s', '%s': '%s'}]";
            jsonStr = String.format(Locale.ROOT, format, longFieldName, longFieldValue, okayFieldName, okayFieldValue);
        } else {
            String format = "[{'id':'1','%s':'%s'}]";
            jsonStr = String.format(Locale.ROOT, format, longFieldName, longFieldValue);
        }
        Exception e = assertThrows(Exception.class, () -> updateJ(json(jsonStr), null));
        assertNotNull(e.getCause());
        assertTrue(e.getCause().getMessage().contains("one immense term in field=\"cat\""));
    }
    assertU(commit());
    assertQ(req("q", "*:*"), "//*[@numFound='0']");
}

