        List<String> longLabels = longSummaries.get(i).getLabels();
        assertEquals(shortLabels.size(), longLabels.size());
        for (int j = 0; j < shortLabels.size(); j++) {
            assertThat("Shorter summary is longer than longer summary?", shortLabels.get(j).length(), Matchers.lessThanOrEqualTo(longLabels.get(j).length()));
        }
    }
}

