@Test
public void embeddedQueryAsSubQuery() throws Exception {
    final String solrQuery = "*:* AND {!knn_text_to_vector model=dummy-1 f=vector topK=5 v='hello world'}";
    final SolrQuery query = new SolrQuery();
    query.setQuery(solrQuery);
    query.setFilterQueries("id:(2 4 7 9 8 20 3)");
    query.add("fl", "id");
    // When knn parser is a subquery, it should not pre-filter on any global fq params
    // topK -> 1,4,2,10,3 -> fq -> 4,2,3
    assertJQ("/query" + query.toQueryString(), "/response/numFound==3]", "/response/docs/[0]/id=='4'", "/response/docs/[1]/id=='2'", "/response/docs/[2]/id=='3'");
}

