@Test
public void testFilterFeatureScorerOverridesScorerMethods() {
    final Class<?> ffsClass = Feature.FeatureWeight.FilterFeatureScorer.class;
    for (final Method scorerClassMethod : Scorer.class.getDeclaredMethods()) {
        try {
            // the FilterFeatureScorer may simply inherit Scorer's default implementation
            if (scorerClassMethod.getName().equals("twoPhaseIterator"))
                continue;
            // the FilterFeatureScorer may simply inherit Scorer's default implementation
            if (scorerClassMethod.getName().equals("smoothingScore"))
                continue;
            // the FilterFeatureScorer's implementation does not influence its parent Weight
            if (scorerClassMethod.getName().equals("getWeight"))
                continue;
            final Method ffsClassMethod = ffsClass.getDeclaredMethod(scorerClassMethod.getName(), scorerClassMethod.getParameterTypes());
            assertEquals("getReturnType() difference", scorerClassMethod.getReturnType(), ffsClassMethod.getReturnType());
        } catch (NoSuchMethodException e) {
            fail(ffsClass + " needs to override '" + scorerClassMethod + "'");
        }
    }
}

