public void testSparseDenseFeatures() throws Exception {
    loadFeature("match", SolrFeature.class.getName(), "test4", "{\"q\":\"{!terms f=title}different\"}");
    loadFeature("c4", ValueFeature.class.getName(), "test4", "{\"value\":1.0}");
