    loadFeature("defaultStoreFeature1", ValueFeature.class.getName(), FeatureStore.DEFAULT_FEATURE_STORE_NAME, "{\"value\":1.0}");
    loadFeature("defaultStoreFeature2", ValueFeature.class.getName(), FeatureStore.DEFAULT_FEATURE_STORE_NAME, "{\"value\":4.0}");
    loadFeature("storeAFeature1", ValueFeature.class.getName(), "storeA", "{\"value\":2.0}");
    loadFeature("storeAFeature2", ValueFeature.class.getName(), "storeA", "{\"value\":6.0}");
    loadModel("modelA", LinearModel.class.getName(), new String[] { "storeAFeature2" }, "storeA", "{\"weights\":{\"storeAFeature2\":6.0}}");
    // Store specified, used store for logging
    // No logAll specified, use default: logAll=false since we pass the same store as the model
    // store
    final SolrQuery query = new SolrQuery();
    query.setQuery("id:7");
    query.add("rows", "1");
    query.add("fl", "fv:[fv store=storeA]");
    query.add("rq", "{!ltr reRankDocs=3 model=modelA}");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[0]/=={'fv':'" + FeatureLoggerTestUtils.toFeatureVector("storeAFeature2", "6.0") + "'}");
}

