    {
        LTRScoringModel wrappedModel = createMockWrappedModel(FeatureStore.DEFAULT_FEATURE_STORE_NAME, Arrays.asList(new ValueFeature("v1", Collections.emptyMap()), new ValueFeature("v2", Collections.emptyMap())), Collections.emptyList());
        e = expectThrows(ModelException.class, () -> wrapperModel.updateModel(wrappedModel));
        assertEquals("counted 2 features and 0 norms in model testModel", e.getMessage());
    }
}

