    new UpdateRequest().add("id", "1", "text_t", "XXXX XXXX", "str_s", "a", "field_i", "1").add("id", "2", "text_t", "XXXX XXXX", "str_s", "b", "field_i", "2").add("id", "3", "text_t", "XXXX XXXX", "str_s", "a", "field_i", "20").add("id", "4", "text_t", "XXXX XXXX", "str_s", "b", "field_i", "2").add("id", "5", "text_t", "XXXX XXXX", "str_s", "c", "field_i", "30").add("id", "6", "text_t", "XXXX XXXX", "str_s", "c", "field_i", "30").add("id", "7", "text_t", "XXXX XXXX", "str_s", "c", "field_i", "50").add("id", "8", "text_t", "XXXX XXXX", "str_s", "c", "field_i", "60").commit(cluster.getSolrClient(), COLLECTIONORALIAS);
    String baseUrl = cluster.getJettySolrRunners().get(0).getBaseUrl().toString() + "/" + COLLECTIONORALIAS;
    SolrParams sParams = params(CommonParams.QT, "/sql", "numWorkers", "2", "aggregationMode", "map_reduce", "stmt", "select distinct str_s, field_i from collection1 order by str_s asc, field_i asc");
    List<Tuple> tuples = getTuples(sParams, baseUrl);
    assertEquals(6, tuples.size());
    Tuple tuple;
    tuple = tuples.get(0);
    assertEquals("a", tuple.get("str_s"));
    assertEquals(1, tuple.getLong("field_i").longValue());
    tuple = tuples.get(1);
    assertEquals("a", tuple.get("str_s"));
    assertEquals(20, tuple.getLong("field_i").longValue());
    tuple = tuples.get(2);
    assertEquals("b", tuple.get("str_s"));
    assertEquals(2, tuple.getLong("field_i").longValue());
    tuple = tuples.get(3);
    assertEquals("c", tuple.get("str_s"));
    assertEquals(30, tuple.getLong("field_i").longValue());
    tuple = tuples.get(4);
    assertEquals("c", tuple.get("str_s"));
    assertEquals(50, tuple.getLong("field_i").longValue());
    tuple = tuples.get(5);
    assertEquals("c", tuple.get("str_s"));
    assertEquals(60, tuple.getLong("field_i").longValue());
    // reverse the sort
    sParams = params(CommonParams.QT, "/sql", "numWorkers", "2", "aggregationMode", "map_reduce", "stmt", "select distinct str_s, field_i from collection1 order by str_s desc, field_i desc");
    tuples = getTuples(sParams, baseUrl);
    assertEquals(6, tuples.size());
    tuple = tuples.get(0);
    assertEquals("c", tuple.get("str_s"));
    assertEquals(60, tuple.getLong("field_i").longValue());
    tuple = tuples.get(1);
    assertEquals("c", tuple.get("str_s"));
    assertEquals(50, tuple.getLong("field_i").longValue());
    tuple = tuples.get(2);
    assertEquals("c", tuple.get("str_s"));
    assertEquals(30, tuple.getLong("field_i").longValue());
    tuple = tuples.get(3);
    assertEquals("b", tuple.get("str_s"));
    assertEquals(2, tuple.getLong("field_i").longValue());
    tuple = tuples.get(4);
    assertEquals("a", tuple.get("str_s"));
    assertEquals(20, tuple.getLong("field_i").longValue());
    tuple = tuples.get(5);
    assertEquals("a", tuple.get("str_s"));
    assertEquals(1, tuple.getLong("field_i").longValue());
    // reverse the sort
    sParams = params(CommonParams.QT, "/sql", "numWorkers", "2", "aggregationMode", "map_reduce", "stmt", "select distinct str_s as myString, field_i from collection1 order by myString desc, field_i desc");
    tuples = getTuples(sParams, baseUrl);
    assertEquals(6, tuples.size());
    tuple = tuples.get(0);
    assertEquals("c", tuple.get("myString"));
    assertEquals(60, tuple.getLong("field_i").longValue());
    tuple = tuples.get(1);
    assertEquals("c", tuple.get("myString"));
    assertEquals(50, tuple.getLong("field_i").longValue());
    tuple = tuples.get(2);
    assertEquals("c", tuple.get("myString"));
    assertEquals(30, tuple.getLong("field_i").longValue());
    tuple = tuples.get(3);
    assertEquals("b", tuple.get("myString"));
    assertEquals(2, tuple.getLong("field_i").longValue());
    tuple = tuples.get(4);
    assertEquals("a", tuple.get("myString"));
    assertEquals(20, tuple.getLong("field_i").longValue());
    tuple = tuples.get(5);
    assertEquals("a", tuple.get("myString"));
    assertEquals(1, tuple.getLong("field_i").longValue());
    // test with limit
    sParams = params(CommonParams.QT, "/sql", "numWorkers", "2", "aggregationMode", "map_reduce", "stmt", "select distinct str_s, field_i from collection1 order by str_s desc, field_i desc limit 2");
    tuples = getTuples(sParams, baseUrl);
    assertEquals(2, tuples.size());
    tuple = tuples.get(0);
    assertEquals("c", tuple.get("str_s"));
    assertEquals(60, tuple.getLong("field_i").longValue());
    tuple = tuples.get(1);
    assertEquals("c", tuple.get("str_s"));
    assertEquals(50, tuple.getLong("field_i").longValue());
    // Test without a sort. Sort should be asc by default.
    sParams = params(CommonParams.QT, "/sql", "numWorkers", "2", "aggregationMode", "map_reduce", "stmt", "select distinct str_s, field_i from collection1");
    tuples = getTuples(sParams, baseUrl);
    assertEquals(6, tuples.size());
    tuple = tuples.get(0);
    assertEquals("a", tuple.get("str_s"));
    assertEquals(1, tuple.getLong("field_i").longValue());
    tuple = tuples.get(1);
    assertEquals("a", tuple.get("str_s"));
    assertEquals(20, tuple.getLong("field_i").longValue());
    tuple = tuples.get(2);
    assertEquals("b", tuple.get("str_s"));
    assertEquals(2, tuple.getLong("field_i").longValue());
    tuple = tuples.get(3);
    assertEquals("c", tuple.get("str_s"));
    assertEquals(30, tuple.getLong("field_i").longValue());
    tuple = tuples.get(4);
    assertEquals("c", tuple.get("str_s"));
    assertEquals(50, tuple.getLong("field_i").longValue());
    tuple = tuples.get(5);
    assertEquals("c", tuple.get("str_s"));
    assertEquals(60, tuple.getLong("field_i").longValue());
    // Test with a predicate.
    sParams = params(CommonParams.QT, "/sql", "numWorkers", "2", "aggregationMode", "map_reduce", "stmt", "select distinct str_s, field_i from collection1 where str_s = 'a'");
    tuples = getTuples(sParams, baseUrl);
    assertEquals(2, tuples.size());
    tuple = tuples.get(0);
    assertEquals("a", tuple.get("str_s"));
    assertEquals(1, tuple.getLong("field_i").longValue());
    tuple = tuples.get(1);
    assertEquals("a", tuple.get("str_s"));
    assertEquals(20, tuple.getLong("field_i").longValue());
}

