@Test
public void testAggregatesWithoutGrouping() throws Exception {
    new UpdateRequest().add(id, "0", "a_s", "hello0", "a_i", "0", "a_f", "1").add(id, "2", "a_s", "hello0", "a_i", "2", "a_f", "2").add(id, "3", "a_s", "hello3", "a_i", "3", "a_f", "3").add(id, "4", "a_s", "hello4", "a_i", "4", "a_f", "4").add(id, "1", "a_s", "hello0", "a_i", "1", "a_f", "5").add(id, "5", "a_s", "hello3", "a_i", "10", "a_f", "6").add(id, "6", "a_s", "hello4", "a_i", "11", "a_f", "7").add(id, "7", "a_s", "hello3", "a_i", "12", "a_f", "8").add(id, "8", "a_s", "hello3", "a_i", "13", "a_f", "9").add(id, "9", "a_s", "hello0", "a_i", "14", "a_f", "10").commit(cluster.getSolrClient(), COLLECTIONORALIAS);
    String baseUrl = cluster.getJettySolrRunners().get(0).getBaseUrl().toString() + "/" + COLLECTIONORALIAS;
    SolrParams sParams = params(CommonParams.QT, "/sql", "stmt", "select count(*), sum(a_i), min(a_i), max(a_i), cast(avg(1.0 * a_i) as float), sum(a_f), " + "min(a_f), max(a_f), avg(a_f) from collection1");
    List<Tuple> tuples = getTuples(sParams, baseUrl);
    assertEquals(1, tuples.size());
    // Test Long and Double Sums
    Tuple tuple = tuples.get(0);
    // count(*)
    Double count = tuple.getDouble("EXPR$0");
    // sum(a_i)
    Double sumi = tuple.getDouble("EXPR$1");
    // min(a_i)
    Double mini = tuple.getDouble("EXPR$2");
    // max(a_i)
    Double maxi = tuple.getDouble("EXPR$3");
    // avg(a_i)
