    assertEquals(1.0D, minf, 0.0);
    assertEquals(10.0D, maxf, 0.0);
    assertEquals(5.5D, avgf, 0.0);
    // Test where clause hits
    sParams = params(CommonParams.QT, "/sql", "stmt", "select count(*), sum(a_i), min(a_i), max(a_i), cast(avg(1.0 * a_i) as float), sum(a_f), " + "min(a_f), max(a_f), avg(a_f) from collection1 where id = 2");
