            docs.add(doc);
        }

        @Override
        public void streamDocListInfo(long numFound, long start, Float maxScore) {
        }
    });
    assertEquals(1, docs.size());
    parentDoc = docs.get(0);
    assertEquals(1, parentDoc.getChildDocumentCount());
}

