@Test
public void testConcurrentUpdate() throws Exception {
    ConcurrentUpdateSolrClientTest.TestServlet.clear();
    String serverUrl = getBaseUrl() + "/cuss/foo";
    int cussThreadCount = 2;
    int cussQueueSize = 100;
    // for tracking callbacks from CUSS
    final AtomicInteger successCounter = new AtomicInteger(0);
    final AtomicInteger errorCounter = new AtomicInteger(0);
    final StringBuilder errors = new StringBuilder();
    try (Http2SolrClient http2Client = new Http2SolrClient.Builder().build();
        ConcurrentUpdateHttp2SolrClient concurrentClient = new OutcomeCountingConcurrentUpdateSolrClient.Builder(serverUrl, http2Client, successCounter, errorCounter, errors).withQueueSize(cussQueueSize).withThreadCount(cussThreadCount).setPollQueueTime(0, TimeUnit.MILLISECONDS).build()) {
        // ensure it doesn't block where there's nothing to do yet
        concurrentClient.blockUntilFinished();
        int poolSize = 5;
        ExecutorService threadPool = ExecutorUtil.newMDCAwareFixedThreadPool(poolSize, new SolrNamedThreadFactory("testCUSS"));
        int numDocs = 100;
        int numRunnables = 5;
        for (int r = 0; r < numRunnables; r++) threadPool.execute(new ConcurrentUpdateSolrClientTest.SendDocsRunnable(String.valueOf(r), numDocs, concurrentClient));
        // ensure all docs are sent
        threadPool.awaitTermination(5, TimeUnit.SECONDS);
        threadPool.shutdown();
        // wait until all requests are processed by CUSS
        concurrentClient.blockUntilFinished();
        concurrentClient.shutdownNow();
        assertEquals("post", ConcurrentUpdateSolrClientTest.TestServlet.lastMethod);
        // expect all requests to be successful
        int expectedSuccesses = ConcurrentUpdateSolrClientTest.TestServlet.numReqsRcvd.get();
        // at least one request must have been sent
        assertTrue(expectedSuccesses > 0);
        assertEquals("Expected no errors but got " + errorCounter.get() + ", due to: " + errors.toString(), 0, errorCounter.get());
        assertEquals("Expected " + expectedSuccesses + " successes, but got " + successCounter.get(), successCounter.get(), expectedSuccesses);
        int expectedDocs = numDocs * numRunnables;
        assertEquals("Expected CUSS to send " + expectedDocs + " but got " + ConcurrentUpdateSolrClientTest.TestServlet.numDocsRcvd.get(), ConcurrentUpdateSolrClientTest.TestServlet.numDocsRcvd.get(), expectedDocs);
    }
}

