@Test
public void testProxyWithHttpSolrClientJdkImpl() throws Exception {
    assertNotNull(proxy);
    var builder = new HttpJdkSolrClient.Builder(url).withProxyConfiguration(host, proxy.getListenPort(), false, false);
    try (HttpJdkSolrClient client = builder.build()) {
        testProxy(client);
    }
    // This is a workaround for java.net.http.HttpClient not implementing closeable/autocloseable
    // until Java 21.
    Thread[] threads = new Thread[Thread.currentThread().getThreadGroup().activeCount()];
    Thread.currentThread().getThreadGroup().enumerate(threads);
    Set<Thread> tSet = Arrays.stream(threads).filter(Objects::nonNull).filter(t -> t.getName().startsWith("HttpClient-")).collect(Collectors.toSet());
    for (Thread t : tSet) {
        t.interrupt();
    }
    System.gc();
}

