@Test
public void testRedirectSwapping() throws Exception {
    final String clientUrl = getBaseUrl() + REDIRECT_SERVLET_PATH;
    SolrQuery q = new SolrQuery("*:*");
    // default for follow redirects is false
    try (Http2SolrClient client = new Http2SolrClient.Builder(clientUrl).withDefaultCollection(DEFAULT_CORE).build()) {
        SolrServerException e = expectThrows(SolrServerException.class, () -> client.query(q));
        assertTrue(e.getMessage().contains("redirect"));
    }
    try (Http2SolrClient client = new Http2SolrClient.Builder(clientUrl).withDefaultCollection(DEFAULT_CORE).withFollowRedirects(true).build()) {
        // shouldn't throw an exception
        client.query(q);
    }
    // set explicit false for following redirects
    try (Http2SolrClient client = new Http2SolrClient.Builder(clientUrl).withDefaultCollection(DEFAULT_CORE).withFollowRedirects(false).build()) {
        SolrServerException e = expectThrows(SolrServerException.class, () -> client.query(q));
        assertTrue(e.getMessage().contains("redirect"));
    }
}

