public void testBuilder() {
    try (Http2SolrClient seed = new Http2SolrClient.Builder("baseSolrUrl").withBasicAuthCredentials("testu", "testp").build()) {
        try (Http2SolrClient clone1 = new Http2SolrClient.Builder("baseSolrUrl").withHttpClient(seed).build()) {
