        // test overwrite seed value, order of builder method calls reversed
        try (Http2SolrClient clone3 = new Http2SolrClient.Builder("baseSolrUrl").withBasicAuthCredentials("testu3", "testp3").withHttpClient(seed).build()) {
            String expected3 = Http2SolrClient.basicAuthCredentialsToAuthorizationString("testu3", "testp3");
