        }
    }
}

@Test
public void testIdleTimeoutWithHttpClient() {
    try (Http2SolrClient oldClient = new Http2SolrClient.Builder("baseSolrUrl").withIdleTimeout(5000, TimeUnit.MILLISECONDS).build()) {
        try (Http2SolrClient onlyBaseUrlChangedClient = new Http2SolrClient.Builder("newBaseSolrUrl").withHttpClient(oldClient).build()) {
            assertEquals(oldClient.getIdleTimeout(), onlyBaseUrlChangedClient.getIdleTimeout());
            assertEquals(oldClient.getHttpClient(), onlyBaseUrlChangedClient.getHttpClient());
        }
        try (Http2SolrClient idleTimeoutChangedClient = new Http2SolrClient.Builder("baseSolrUrl").withHttpClient(oldClient).withIdleTimeout(3000, TimeUnit.MILLISECONDS).build()) {
            assertFalse(oldClient.getIdleTimeout() == idleTimeoutChangedClient.getIdleTimeout());
            assertEquals(3000, idleTimeoutChangedClient.getIdleTimeout());
        }
    }
}

