@Test
public void testNonRepeatableMalformedGzipEntityAutoClosed() throws IOException {
    HttpEntity baseEntity = new InputStreamEntity(new ByteArrayInputStream("this is not compressed".getBytes(StandardCharsets.UTF_8)));
    HttpClientUtil.GzipDecompressingEntity gzipDecompressingEntity = new HttpClientUtil.GzipDecompressingEntity(baseEntity);
    Throwable error = expectThrows(IOException.class, "An IOException wrapping a ZIPException should be thrown when loading a malformed GZIP Entity Content", gzipDecompressingEntity::getContent);
    assertEquals("IOException should be caused by a ZipException", ZipException.class, error.getCause() == null ? null : error.getCause().getClass());
    assertNull("The second time getContent is called, null should be returned since the underlying entity is non-repeatable", gzipDecompressingEntity.getContent());
    assertEquals("No more content should be available after the GZIP Entity failed to load", 0, baseEntity.getContent().available());
}

@Test
public void testRepeatableMalformedGzipEntity() throws IOException {
    HttpEntity baseEntity = new StringEntity("this is not compressed");
    HttpClientUtil.GzipDecompressingEntity gzipDecompressingEntity = new HttpClientUtil.GzipDecompressingEntity(baseEntity);
    Throwable error = expectThrows(IOException.class, "An IOException wrapping a ZIPException should be thrown when loading a malformed GZIP Entity Content", gzipDecompressingEntity::getContent);
    assertEquals("IOException should be caused by a ZipException", ZipException.class, error.getCause() == null ? null : error.getCause().getClass());
    error = expectThrows(IOException.class, "An IOException should be thrown again when re-loading a repeatable malformed GZIP Entity Content", gzipDecompressingEntity::getContent);
    assertEquals("IOException should be caused by a ZipException", ZipException.class, error.getCause() == null ? null : error.getCause().getClass());
}

@Test
public void testRepeatableGzipEntity() throws IOException {
    String testString = "this is compressed";
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    try (GZIPOutputStream gzipOutputStream = new GZIPOutputStream(baos)) {
        gzipOutputStream.write(testString.getBytes(StandardCharsets.UTF_8));
    }
    // Use an ByteArrayEntity because it is repeatable
    HttpEntity baseEntity = new ByteArrayEntity(baos.toByteArray());
    HttpClientUtil.GzipDecompressingEntity gzipDecompressingEntity = new HttpClientUtil.GzipDecompressingEntity(baseEntity);
    try (InputStream stream = gzipDecompressingEntity.getContent()) {
        assertEquals("Entity incorrect after decompression", testString, new String(stream.readAllBytes(), StandardCharsets.UTF_8));
    }
    try (InputStream stream = gzipDecompressingEntity.getContent()) {
        assertEquals("Entity incorrect after decompression after repeating", testString, new String(stream.readAllBytes(), StandardCharsets.UTF_8));
    }
}

@Test
public void testNonRepeatableGzipEntity() throws IOException {
    String testString = "this is compressed";
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    try (GZIPOutputStream gzipOutputStream = new GZIPOutputStream(baos)) {
        gzipOutputStream.write(testString.getBytes(StandardCharsets.UTF_8));
    }
    // Use an InputStreamEntity because it is non-repeatable
    HttpEntity baseEntity = new InputStreamEntity(new ByteArrayInputStream(baos.toByteArray()));
    HttpClientUtil.GzipDecompressingEntity gzipDecompressingEntity = new HttpClientUtil.GzipDecompressingEntity(baseEntity);
    try (InputStream stream = gzipDecompressingEntity.getContent()) {
        assertEquals("Entity incorrect after decompression", testString, new String(stream.readAllBytes(), StandardCharsets.UTF_8));
    }
    try (InputStream stream = gzipDecompressingEntity.getContent()) {
        expectThrows(IOException.class, "Entity Content should already be closed since the input is non-repeatable", stream::available);
    }
}

@Test
@SuppressWarnings("unchecked")
public void testHttpClusterStateWithSSL() throws Exception {
    URL url0 = cluster.getJettySolrRunner(0).getBaseUrl();
    assertEquals("https", url0.getProtocol());
    final String collectionId = "test-https-cluster-state";
    final int numShards = 3;
    final int rf = 2;
    final int expectedReplicas = numShards * rf;
    CollectionAdminRequest.createCollection(collectionId, "conf", numShards, rf).setPerReplicaState(false).process(cluster.getSolrClient());
    cluster.waitForActiveCollection(collectionId, numShards, numShards * rf);
    // verify the base_url is actually stored with https in it on the server-side
    byte[] stateJsonBytes = cluster.getZkClient().getData(DocCollection.getCollectionPath(collectionId), null, null, true);
    assertNotNull(stateJsonBytes);
    Map<String, Object> replicasMap = (Map<String, Object>) Utils.getObjectByPath(Utils.fromJSON(stateJsonBytes), false, "/" + collectionId + "/shards/shard1/replicas");
    assertEquals(2, replicasMap.size());
    for (Object replicaObj : replicasMap.values()) {
        Map<String, Object> replicaData = (Map<String, Object>) replicaObj;
        String baseUrl = (String) replicaData.get("base_url");
        assertTrue(baseUrl != null && baseUrl.startsWith("https://"));
    }
    // verify the http derived cluster state (on the client side) agrees with what the server stored
    try (CloudSolrClient httpBasedCloudSolrClient = new CloudSolrClient.Builder(Collections.singletonList(url0.toExternalForm())).build()) {
        ClusterStateProvider csp = httpBasedCloudSolrClient.getClusterStateProvider();
        assertTrue(csp instanceof Http2ClusterStateProvider);
        verifyUrlSchemeInClusterState(csp.getCollection(collectionId), expectedReplicas);
    }
    // http2
    try (CloudSolrClient http2BasedClient = new CloudHttp2SolrClient.Builder(Collections.singletonList(url0.toExternalForm())).build()) {
        ClusterStateProvider csp = http2BasedClient.getClusterStateProvider();
        assertTrue(csp instanceof Http2ClusterStateProvider);
        verifyUrlSchemeInClusterState(csp.getCollection(collectionId), expectedReplicas);
    }
    // Zk cluster state now
    ClusterStateProvider csp = cluster.getSolrClient().getClusterStateProvider();
    assertTrue(csp instanceof ZkClientClusterStateProvider);
    verifyUrlSchemeInClusterState(csp.getCollection(collectionId), expectedReplicas);
}

