    ModifiableSolrParams params = new ModifiableSolrParams();
    List<Replica> replicas = getBasicReplicaList();
    // Add a replica so that sorting by replicaType:TLOG can cause a tie
    replicas.add(new Replica("node4", Map.of(ZkStateReader.NODE_NAME_PROP, "node4:8983_solr", ZkStateReader.BASE_URL_PROP, Utils.getBaseUrlForNodeName("node4:8983_solr", "https"), ZkStateReader.CORE_NAME_PROP, "collection1", ZkStateReader.REPLICA_TYPE, "TLOG"), "c1", "s1"));
