public void testCommitWithinOnDelete() throws Exception {
    // make sure it is empty...
    SolrClient client = getSolrClient();
    // delete everything!
    client.deleteByQuery("*:*");
    client.commit();
    QueryResponse rsp = client.query(new SolrQuery("*:*"));
    assertEquals(0, rsp.getResults().getNumFound());
    // Now add one document...
    SolrInputDocument doc3 = new SolrInputDocument();
    doc3.addField("id", "id3");
    doc3.addField("name", "doc3");
    doc3.addField("price", 10);
    client.add(doc3);
    client.commit();
    // now check that it comes out...
    rsp = client.query(new SolrQuery("id:id3"));
    assertEquals(1, rsp.getResults().getNumFound());
    // now test commitWithin on a delete operation
    UpdateRequest up = new UpdateRequest();
    up.setCommitWithin(1000);
    up.deleteById("id3");
    up.process(client);
    // the document should still be there
    rsp = client.query(new SolrQuery("id:id3"));
    assertEquals(1, rsp.getResults().getNumFound());
    // check if the doc has been deleted every 250 ms for 30 seconds
    TimeOut timeout = new TimeOut(30, TimeUnit.SECONDS, TimeSource.NANO_TIME);
    do {
        // wait 250 ms
        Thread.sleep(250);
        rsp = client.query(new SolrQuery("id:id3"));
        if (rsp.getResults().getNumFound() == 0) {
            return;
        }
    } while (!timeout.hasTimedOut());
    fail("commitWithin failed to commit");
}

@Test
public void testAddDelete() throws Exception {
    SolrClient client = getSolrClient();
    // Empty the database...
    // delete everything!
    client.deleteByQuery("*:*");
    SolrInputDocument[] doc = new SolrInputDocument[3];
    for (int i = 0; i < 3; i++) {
        doc[i] = new SolrInputDocument();
        doc[i].setField("id", i + " & 222");
    }
    String id = (String) doc[0].getField("id").getFirstValue();
    client.add(doc[0]);
    client.commit();
    // make sure it got in
    assertNumFound("*:*", 1);
    // make sure it got in there
    client.deleteById(id);
    client.commit();
    // make sure it got out
    assertNumFound("*:*", 0);
    // add it back
    client.add(doc[0]);
    client.commit();
    // make sure it got in
    assertNumFound("*:*", 1);
    client.deleteByQuery("id:\"" + ClientUtils.escapeQueryChars(id) + "\"");
    client.commit();
    // make sure it got out
    assertNumFound("*:*", 0);
    // Add two documents
    for (SolrInputDocument d : doc) {
        client.add(d);
    }
    client.commit();
    // make sure it got in
    assertNumFound("*:*", 3);
    // should be able to handle multiple delete commands in a single go
    List<String> ids = new ArrayList<>();
    for (SolrInputDocument d : doc) {
        ids.add(d.getFieldValue("id").toString());
    }
    client.deleteById(ids);
    client.commit();
    // make sure it got out
    assertNumFound("*:*", 0);
}

