/**
 * Test that if there is a non interruptable thread that awaitTermination eventually returns.
 */
@Test
// Must prevent runaway failures so limit this to short timeframe in case of failure
@Timeout(millis = 5_000)
public void testExecutorUtilAwaitsTerminationWhenTaskIgnoresInterupt() throws Exception {
    final Worker w = new Worker(false);
    final ExecutorService executorService = ExecutorUtil.newMDCAwareSingleThreadExecutor(new SolrNamedThreadFactory(this.getClass().getSimpleName() + "non-interruptable"));
    try {
        final Future<Boolean> f = executorService.submit(w);
        assertTrue("Worker didn't start in a sane amount of time", w.awaitWorkerStart());
        executorService.shutdownNow();
        assertTrue("Worker not interupted by shutdown in a sane amount of time", w.awaitWorkerInteruptedAtLeastOnce());
        assertThrows(RuntimeException.class, () -> ExecutorUtil.awaitTermination(executorService, MAX_AWAIT_TERMINATION_ARG_MS, TimeUnit.MILLISECONDS));
        assertFalse("Worker should not finish due to shutdown or awaitTermination", f.isDone());
        assertTrue("test sanity check: WTF? how did we get here?", w.getNumberOfInterupts() > 0);
        // Worker should finish if we let it
        w.tellWorkerToFinish();
        assertTrue(f.get(MAX_SANE_WAIT_DURATION_MS, TimeUnit.MILLISECONDS));
    } finally {
        w.tellWorkerToFinish();
        ExecutorUtil.shutdownNowAndAwaitTermination(executorService);
    }
}

/**
 * Test that if there is an interruptable thread that awaitTermination forcefully returns.
 */
@Test
// Must prevent runaway failures so limit this to short timeframe in case of failure
@Timeout(millis = 5_000)
public void testExecutorUtilAwaitsTerminationWhenTaskRespectsInterupt() throws Exception {
    final Worker w = new Worker(true);
    final ExecutorService executorService = ExecutorUtil.newMDCAwareSingleThreadExecutor(new SolrNamedThreadFactory(this.getClass().getSimpleName() + "interruptable"));
    try {
        final Future<Boolean> f = executorService.submit(w);
        assertTrue("Worker didn't start in a sane amount of time", w.awaitWorkerStart());
        executorService.shutdownNow();
        ExecutorUtil.awaitTermination(executorService, MAX_AWAIT_TERMINATION_ARG_MS, TimeUnit.MILLISECONDS);
        // Worker should finish on its own after the interupt
        assertTrue("Worker not interupted in a sane amount of time", w.awaitWorkerInteruptedAtLeastOnce());
        assertFalse(f.get(MAX_SANE_WAIT_DURATION_MS, TimeUnit.MILLISECONDS));
        assertTrue("test sanity check: WTF? how did we get here?", w.getNumberOfInterupts() > 0);
    } finally {
        w.tellWorkerToFinish();
        ExecutorUtil.shutdownNowAndAwaitTermination(executorService);
    }
}

@Test
public void testCMDCAwareCachedThreadPool() throws Exception {
    // 5 threads max, unbounded queue
    ExecutorService executor = ExecutorUtil.newMDCAwareCachedThreadPool(5, Integer.MAX_VALUE, new NamedThreadFactory("test"));
    AtomicInteger concurrentTasks = new AtomicInteger();
    AtomicInteger maxConcurrentTasks = new AtomicInteger();
    int taskCount = 5 + random().nextInt(100);
    CountDownLatch latch = new CountDownLatch(5);
    List<Future<Void>> futures = new ArrayList<>();
    for (int i = 0; i < taskCount; i++) {
        String core = "id_" + random().nextLong();
        Callable<Void> task = () -> {
            // ensure we never have too many concurrent tasks
            int concurrent = concurrentTasks.incrementAndGet();
            assertTrue(concurrent <= 5);
            maxConcurrentTasks.getAndAccumulate(concurrent, Math::max);
            // assert MDC context is copied from the parent thread that submitted the task
            assertEquals(core, MDC.get("core"));
            // The first 4 tasks to be executed will wait on the latch, and the 5th will
            // release all the threads.
            latch.countDown();
            latch.await(1, TimeUnit.SECONDS);
            concurrentTasks.decrementAndGet();
            return null;
        };
        MDCLoggingContext.setCoreName(core);
        futures.add(executor.submit(task));
    }
    ExecutorUtil.shutdownAndAwaitTermination(executor);
    for (Future<Void> future : futures) {
        // Throws an exception (and make the test fail) if an assertion failed
        // in the subtask
        future.get();
    }
    // assert the pool was actually multithreaded. Since we submitted many tasks,
    // all the threads should have been started
    assertEquals(5, maxConcurrentTasks.get());
}

@Test
public void submitAllTest() throws IOException {
    AtomicLong idx = new AtomicLong();
    Callable<Long> c = () -> idx.getAndIncrement();
    List<Long> results = new ArrayList<>();
    ExecutorService service = ExecutorUtil.newMDCAwareCachedThreadPool(new SolrNamedThreadFactory("test"));
    try {
        List<Callable<Long>> tasks = List.of(c, c, c, c, c);
        results.addAll(ExecutorUtil.submitAllAndAwaitAggregatingExceptions(service, tasks));
    } finally {
        ExecutorUtil.shutdownNowAndAwaitTermination(service);
    }
    Collections.sort(results);
    List<Long> expected = List.of(0l, 1l, 2l, 3l, 4l);
