    assertEquals("sam", tuples.get(5).getString("node"));
    assertEquals(1L, tuples.get(5).getLong("level").longValue());
    assertEquals("steve", tuples.get(6).getString("node"));
    assertEquals(2L, tuples.get(6).getLong("level").longValue());
    cache.close();
}

@Test
public void testGraphHandler() throws Exception {
    new UpdateRequest().add(id, "0", "from_s", "bill", "to_s", "jim", "message_t", "Hello jim").add(id, "1", "from_s", "bill", "to_s", "sam", "message_t", "Hello sam").add(id, "2", "from_s", "bill", "to_s", "max", "message_t", "Hello max").add(id, "3", "from_s", "max", "to_s", "kip", "message_t", "Hello kip").add(id, "4", "from_s", "sam", "to_s", "steve", "message_t", "Hello steve").add(id, "5", "from_s", "jim", "to_s", "ann", "message_t", "Hello steve").commit(cluster.getSolrClient(), COLLECTION);
    commit();
    List<JettySolrRunner> runners = cluster.getJettySolrRunners();
    JettySolrRunner runner = runners.get(0);
    String url = runner.getBaseUrl().toString();
    SolrClient client = getHttpSolrClient(url);
    ModifiableSolrParams params = new ModifiableSolrParams();
    String expr = "sort(by=\"node asc\", gatherNodes(collection1, " + "walk=\"bill->from_s\"," + "trackTraversal=\"true\"," + "gather=\"to_s\"))";
    params.add("expr", expr);
    QueryRequest query = new QueryRequest(params);
    query.setPath("/collection1/graph");
    query.setResponseParser(new InputStreamResponseParser("xml"));
    query.setMethod(SolrRequest.METHOD.POST);
    NamedList<Object> genericResponse = client.request(query);
    InputStream stream = (InputStream) genericResponse.get(InputStreamResponseParser.STREAM_KEY);
    InputStreamReader reader = new InputStreamReader(stream, StandardCharsets.UTF_8);
    String xml = readString(reader);
    // Validate the nodes
    String error = BaseTestHarness.validateXPath(xml, "//graph/node[1][@id ='jim']", "//graph/node[2][@id ='max']", "//graph/node[3][@id ='sam']");
    if (error != null) {
        throw new Exception(error);
    }
    // Validate the edges
    error = BaseTestHarness.validateXPath(xml, "//graph/edge[1][@source ='bill']", "//graph/edge[1][@target ='jim']", "//graph/edge[2][@source ='bill']", "//graph/edge[2][@target ='max']", "//graph/edge[3][@source ='bill']", "//graph/edge[3][@target ='sam']");
    if (error != null) {
        throw new Exception(error);
    }
    client.close();
}

@Test
public void testShortestPathStream() throws Exception {
    new UpdateRequest().add(id, "0", "from_s", "jim", "to_s", "mike", "predicate_s", "knows").add(id, "1", "from_s", "jim", "to_s", "dave", "predicate_s", "knows").add(id, "2", "from_s", "jim", "to_s", "stan", "predicate_s", "knows").add(id, "3", "from_s", "dave", "to_s", "stan", "predicate_s", "knows").add(id, "4", "from_s", "dave", "to_s", "bill", "predicate_s", "knows").add(id, "5", "from_s", "dave", "to_s", "mike", "predicate_s", "knows").add(id, "20", "from_s", "dave", "to_s", "alex", "predicate_s", "knows").add(id, "21", "from_s", "alex", "to_s", "steve", "predicate_s", "knows").add(id, "6", "from_s", "stan", "to_s", "alice", "predicate_s", "knows").add(id, "7", "from_s", "stan", "to_s", "mary", "predicate_s", "knows").add(id, "8", "from_s", "stan", "to_s", "dave", "predicate_s", "knows").add(id, "10", "from_s", "mary", "to_s", "mike", "predicate_s", "knows").add(id, "11", "from_s", "mary", "to_s", "max", "predicate_s", "knows").add(id, "12", "from_s", "mary", "to_s", "jim", "predicate_s", "knows").add(id, "13", "from_s", "mary", "to_s", "steve", "predicate_s", "knows").commit(cluster.getSolrClient(), COLLECTION);
    List<Tuple> tuples = null;
    Set<String> paths = null;
    ShortestPathStream stream = null;
    String zkHost = cluster.getZkServer().getZkAddress();
    StreamContext context = new StreamContext();
    SolrClientCache cache = new SolrClientCache();
    context.setSolrClientCache(cache);
    SolrParams sParams = params("fq", "predicate_s:knows");
    stream = new ShortestPathStream(zkHost, "collection1", "jim", "steve", "from_s", "to_s", sParams, 20, 3, 6);
    stream.setStreamContext(context);
    paths = new HashSet<>();
    tuples = getTuples(stream);
    assertEquals(2, tuples.size());
    for (Tuple tuple : tuples) {
        paths.add(tuple.get("path").toString());
    }
    assertTrue(paths.contains("[jim, dave, alex, steve]"));
    assertTrue(paths.contains("[jim, stan, mary, steve]"));
    // Test with batch size of 1
    sParams = params("fq", "predicate_s:knows");
    stream = new ShortestPathStream(zkHost, "collection1", "jim", "steve", "from_s", "to_s", sParams, 1, 3, 6);
    stream.setStreamContext(context);
    paths = new HashSet<>();
    tuples = getTuples(stream);
    assertEquals(2, tuples.size());
    for (Tuple tuple : tuples) {
        paths.add(tuple.get("path").toString());
    }
    assertTrue(paths.contains("[jim, dave, alex, steve]"));
    assertTrue(paths.contains("[jim, stan, mary, steve]"));
    // Test with bad predicate
    sParams = params("fq", "predicate_s:crap");
    stream = new ShortestPathStream(zkHost, "collection1", "jim", "steve", "from_s", "to_s", sParams, 1, 3, 6);
    stream.setStreamContext(context);
    tuples = getTuples(stream);
    assertEquals(0, tuples.size());
    // Test with depth 2
    sParams = params("fq", "predicate_s:knows");
    stream = new ShortestPathStream(zkHost, "collection1", "jim", "steve", "from_s", "to_s", sParams, 1, 3, 2);
    stream.setStreamContext(context);
    tuples = getTuples(stream);
    assertEquals(0, tuples.size());
    // Take out alex
    sParams = params("fq", "predicate_s:knows NOT to_s:alex");
    stream = new ShortestPathStream(zkHost, "collection1", "jim", "steve", "from_s", "to_s", sParams, 10, 3, 6);
    stream.setStreamContext(context);
    paths = new HashSet<>();
    tuples = getTuples(stream);
    assertEquals(1, tuples.size());
    for (Tuple tuple : tuples) {
        paths.add(tuple.get("path").toString());
    }
    assertTrue(paths.contains("[jim, stan, mary, steve]"));
    cache.close();
}

