@Test
@SuppressWarnings({ "unchecked", "rawtypes" })
public void testZplot() throws Exception {
    String url = cluster.getJettySolrRunners().get(0).getBaseUrl().toString() + "/" + COLLECTIONORALIAS;
    String cexpr = "let(a=array(1,2,3,4)," + "        b=array(10,11,12,13)," + "        zplot(x=a, y=b))";
    ModifiableSolrParams paramsLoc = new ModifiableSolrParams();
    paramsLoc.set("expr", cexpr);
    paramsLoc.set("qt", "/stream");
    TupleStream solrStream = new SolrStream(url, paramsLoc);
    StreamContext context = new StreamContext();
    solrStream.setStreamContext(context);
    List<Tuple> tuples = getTuples(solrStream);
    assertEquals(4, tuples.size());
    Tuple out = tuples.get(0);
    assertEquals(out.getDouble("x"), 1.0, 0.0);
    assertEquals(out.getDouble("y"), 10.0, 0.0);
    out = tuples.get(1);
    assertEquals(out.getDouble("x"), 2.0, 0.0);
    assertEquals(out.getDouble("y"), 11.0, 0.0);
    out = tuples.get(2);
    assertEquals(out.getDouble("x"), 3.0, 0.0);
    assertEquals(out.getDouble("y"), 12.0, 0.0);
    out = tuples.get(3);
    assertEquals(out.getDouble("x"), 4.0, 0.0);
    assertEquals(out.getDouble("y"), 13.0, 0.0);
    cexpr = "let(b=array(10,11,12,13)," + "        zplot(y=b))";
    paramsLoc = new ModifiableSolrParams();
    paramsLoc.set("expr", cexpr);
    paramsLoc.set("qt", "/stream");
    solrStream = new SolrStream(url, paramsLoc);
    context = new StreamContext();
    solrStream.setStreamContext(context);
    tuples = getTuples(solrStream);
    assertEquals(4, tuples.size());
    out = tuples.get(0);
    assertEquals(out.getDouble("x"), 0.0, 0.0);
    assertEquals(out.getDouble("y"), 10.0, 0.0);
    out = tuples.get(1);
    assertEquals(out.getDouble("x"), 1.0, 0.0);
    assertEquals(out.getDouble("y"), 11.0, 0.0);
    out = tuples.get(2);
    assertEquals(out.getDouble("x"), 2.0, 0.0);
    assertEquals(out.getDouble("y"), 12.0, 0.0);
    out = tuples.get(3);
    assertEquals(out.getDouble("x"), 3.0, 0.0);
    assertEquals(out.getDouble("y"), 13.0, 0.0);
    cexpr = "zplot(dist=binomialDistribution(10, .50))";
    paramsLoc = new ModifiableSolrParams();
    paramsLoc.set("expr", cexpr);
    paramsLoc.set("qt", "/stream");
    solrStream = new SolrStream(url, paramsLoc);
    context = new StreamContext();
    solrStream.setStreamContext(context);
    tuples = getTuples(solrStream);
    assertEquals(tuples.size(), 11);
    long x = tuples.get(5).getLong("x");
    double y = tuples.get(5).getDouble("y");
    assertEquals(x, 5);
    assertEquals(y, 0.24609375000000003, 0);
    // Due to random errors (bugs) in Apache Commons Math EmpiricalDistribution
    // there are times when tuples are discarded because
    // they contain values with NaN values. This will occur
    // only on the very end of the tails of the normal distribution or other
    // real distributions and doesn't affect the visual quality of the curve very much.
    // But it does affect the reliability of tests.
    // For this reason the loop below is in place to run the test N times looking
    // for the correct number of tuples before asserting the mean.
    int n = 0;
    int limit = 15;
    while (true) {
        cexpr = "zplot(dist=normalDistribution(100, 10))";
        paramsLoc = new ModifiableSolrParams();
        paramsLoc.set("expr", cexpr);
        paramsLoc.set("qt", "/stream");
        solrStream = new SolrStream(url, paramsLoc);
        context = new StreamContext();
        solrStream.setStreamContext(context);
        tuples = getTuples(solrStream);
        // Assert the mean
        if (tuples.size() == 32) {
            double x1 = tuples.get(15).getDouble("x");
            double y1 = tuples.get(15).getDouble("y");
            assertEquals(x1, 100, 10);
            assertEquals(y1, .039, .02);
            break;
        } else {
