    Number prediction = (Number) tuples.get(0).get("g");
    assertEquals(prediction.doubleValue(), 85.09999847, 0);
    // Test robust. Take the median rather then average
    cexpr = "let(echo=true, a=array(8.5, 12.89999962, 5.199999809, 10.69999981, 3.099999905, 3.5, 9.199999809, 9, 8.10000038, 8.19999981), " + "b=array(5.099999905, 5.800000191, 2.099999905, 8.399998665, 2.900000095, 1.200000048, 3.700000048, 5.599999905, 5.699999809, 4.5)," + "c=array(4.699999809, 8.800000191, 15.10000038, 12.19999981, 10.60000038, 3.5, 9.699999809, 5.900000095, 4.79999924, 4.900000095)," + "d=array(85.09999847, 106.3000031, 50.20000076, 130.6000061, 54.79999924, 30.29999924, 79.40000153, 91, 135.3999939, 89.30000305)," + "e=transpose(matrix(a, b, c))," + "f=knnRegress(e, d, 3, scale=true, robust=true)," + "g=predict(f, array(8, 5, 4)))";
