@Test
public void mergeTest() {
    final Map<String, Object> commonFields = new HashMap<>();
    commonFields.put("field-one", new Object());
    commonFields.put("field-two", new Object());
    commonFields.put("field-three", new Object());
    commonFields.put(StreamParams.EXCEPTION, "exception");
    commonFields.put(StreamParams.EOF, true);
    final Tuple tupleOne = new Tuple();
    tupleOne.putAll(commonFields);
    tupleOne.setFieldNames(new ArrayList<>(Arrays.asList("field-one-name", "field-two-name", "field-three-name")));
    tupleOne.setFieldLabels(new HashMap<>(Map.ofEntries(Map.entry("field-one-name", "field-one"), Map.entry("field-two-name", "field-two"), Map.entry("field-three-name", "field-three"))));
    final Tuple tupleTwo = new Tuple();
    tupleTwo.putAll(commonFields);
    tupleTwo.put("field-four", new Object());
    tupleTwo.put("new-field-two", new Object());
    tupleTwo.setFieldNames(new ArrayList<>(Arrays.asList("field-one-name", "field-two-name", "field-four-name")));
    tupleTwo.setFieldLabels(new HashMap<>(Map.ofEntries(Map.entry("field-one-name", "field-one"), Map.entry("field-two-name", "new-field-two"), Map.entry("field-four-name", "field-four"))));
    tupleOne.merge(tupleTwo);
    assertEquals(7, tupleOne.getFields().size());
    // fieldNames should contain no duplicates
    assertEquals(4, tupleOne.getFieldNames().size());
    assertEquals(4, tupleOne.getFieldLabels().size());
    assertEquals("new-field-two", tupleOne.getFieldLabels().get("field-two-name"));
    assertTrue(tupleOne.EOF);
    assertTrue(tupleOne.EXCEPTION);
}

@Test
public void writeMapTest() throws IOException {
    final Map<String, Object> commonFields = new HashMap<>();
    commonFields.put("field a", "1");
    commonFields.put("field b", "2");
    commonFields.put("field c", "3");
    final Tuple tupleOne = new Tuple(commonFields);
    // label all fields
    tupleOne.setFieldLabels(new HashMap<>(Map.ofEntries(Map.entry("field-one", "field a"), Map.entry("field-two", "field b"), Map.entry("field-three", "field c"))));
    // then choose a subset for serialisation
    tupleOne.setFieldNames(new ArrayList<>(Arrays.asList("field-two", "field-three")));
    {
        final TupleEntryWriter writer = new TupleEntryWriter();
        tupleOne.writeMap(writer);
        assertEquals(2, writer.tuple.getFields().size());
        // field-two
        assertEquals("2", writer.tuple.get("field b"));
        // field-three
        assertEquals("3", writer.tuple.get("field c"));
    }
    final Tuple tupleTwo = new Tuple(commonFields);
    tupleTwo.put("field d", "4");
    // label most fields (3 of 4)
    tupleTwo.setFieldLabels(new HashMap<>(Map.ofEntries(Map.entry("field-one", "field b"), Map.entry("field-two", "field a"), Map.entry("field-four", "field d"))));
    // then choose a subset for serialisation
    tupleTwo.setFieldNames(new ArrayList<>(Arrays.asList("field-two", "field-four")));
    {
        final TupleEntryWriter writer = new TupleEntryWriter();
        tupleTwo.writeMap(writer);
        assertEquals(2, writer.tuple.getFields().size());
        // field-two
        assertEquals("1", writer.tuple.get("field a"));
        // field-four
        assertEquals("4", writer.tuple.get("field d"));
    }
    // clone and merge
    final Tuple tupleThree = tupleOne.clone();
    tupleThree.merge(tupleTwo);
    assertEquals(4, tupleThree.getFieldLabels().size());
    assertEquals(3, tupleThree.getFieldNames().size());
    // serialise merged tuples
    {
        final TupleEntryWriter writer = new TupleEntryWriter();
        tupleThree.writeMap(writer);
        assertEquals(3, writer.tuple.getFields().size());
        // field-two label in tupleTwo replaced field-two label from tupleOne
        assertEquals("1", writer.tuple.get("field a"));
        // field-three label from tupleOne
        assertEquals("3", writer.tuple.get("field c"));
        // field-four label from tupleTwo
        assertEquals("4", writer.tuple.get("field d"));
    }
    tupleThree.setFieldNames(null);
    // full serialisation
    {
        final TupleEntryWriter writer = new TupleEntryWriter();
        tupleThree.writeMap(writer);
        assertEquals(4, writer.tuple.getFields().size());
        assertEquals("1", writer.tuple.get("field a"));
        assertEquals("2", writer.tuple.get("field b"));
        assertEquals("3", writer.tuple.get("field c"));
        assertEquals("4", writer.tuple.get("field d"));
    }
}

@Test
public void testGetTags() throws Exception {
    try (var cloudHttp2SolrClient = new CloudHttp2SolrClient.Builder(Collections.singletonList(cluster.getZkServer().getZkAddress()), Optional.empty()).build()) {
        int totalCores = 0;
        // Sum all the cores of the collection by fetching tags of all nodes.
        // We should get same number than when we created the collection
        for (JettySolrRunner runner : cluster.getJettySolrRunners()) {
            String node = runner.getNodeName();
            RemoteCallCtx ctx = new RemoteCallCtx(node, cloudHttp2SolrClient);
            NodeValueFetcher fetcher = new NodeValueFetcher();
            Set<String> requestedTags = Set.of("cores");
            fetcher.getTags(requestedTags, ctx);
            // make sure we only get the tag we asked
            assertEquals(1, ctx.tags.size());
            int coresOnNode = (Integer) ctx.tags.get("cores");
            totalCores += coresOnNode;
        }
        assertEquals(numShards * numReplicas, totalCores);
    }
}

@Test
public void testSimpleUpdateACLs() throws KeeperException, InterruptedException {
    assertTrue("Initial create was in secure mode; please check the test", canRead(defaultClient, PATH));
    assertTrue("Credentialed client should always be able to read", canRead(credentialsClient, PATH));
    // convert to secure
    aclClient.updateACLs(ROOT);
    assertFalse("Default client should not be able to read root in secure mode", canRead(defaultClient, ROOT));
    assertFalse("Default client should not be able to read children in secure mode", canRead(defaultClient, PATH));
