    CollectionAdminRequest.Create create = isImplicit ? // NOTE: use shard list with same # of shards as NUM_SHARDS; we assume this later
    CollectionAdminRequest.createCollectionWithImplicitRouter(getCollectionName(), "conf1", "shard1,shard2", replFactor, numTlogReplicas, numPullReplicas) : CollectionAdminRequest.createCollection(getCollectionName(), "conf1", NUM_SHARDS, replFactor, numTlogReplicas, numPullReplicas);
    Properties coreProps = new Properties();
