@Test
public void addReplicaTest() throws Exception {
    String collectionName = "addReplicaColl";
    CollectionAdminRequest.createCollection(collectionName, "conf", 2, 2).process(cluster.getSolrClient());
    cluster.waitForActiveCollection(collectionName, 2, 4);
    ArrayList<String> nodeList = new ArrayList<>(cluster.getSolrClient().getClusterState().getLiveNodes());
    Collections.shuffle(nodeList, random());
    CollectionAdminResponse response = CollectionAdminRequest.addReplicaToShard(collectionName, "shard1").setNode(nodeList.get(0)).process(cluster.getSolrClient());
    Replica newReplica = grabNewReplica(response, getCollectionState(collectionName));
    assertEquals("Replica should be created on the right node", cluster.getZkStateReader().getBaseUrlForNodeName(nodeList.get(0)), newReplica.getBaseUrl());
    Path instancePath = createTempDir();
    response = CollectionAdminRequest.addReplicaToShard(collectionName, "shard1").withProperty(CoreAdminParams.INSTANCE_DIR, instancePath.toString()).process(cluster.getSolrClient());
    newReplica = grabNewReplica(response, getCollectionState(collectionName));
    assertNotNull(newReplica);
    try (SolrClient coreclient = getHttpSolrClient(newReplica.getBaseUrl())) {
        CoreAdminResponse status = CoreAdminRequest.getStatus(newReplica.getStr("core"), coreclient);
        final var coreStatus = status.getCoreStatus(newReplica.getStr("core"));
        String instanceDirStr = coreStatus.instanceDir;
        assertEquals(instanceDirStr, instancePath.toString());
    }
    // Test to make sure we can't create another replica with an existing core_name of that
    // collection
    String coreName = newReplica.getStr(CORE_NAME_PROP);
    SolrException e = expectThrows(SolrException.class, () -> {
        ModifiableSolrParams params = new ModifiableSolrParams();
        params.set("action", "addreplica");
        params.set("collection", collectionName);
        params.set("shard", "shard1");
        params.set("name", coreName);
        var request = new GenericSolrRequest(METHOD.GET, "/admin/collections", SolrRequestType.ADMIN, params);
        cluster.getSolrClient().request(request);
    });
    assertTrue(e.getMessage().contains("Another replica with the same core name already exists for this collection"));
    // Check that specifying property.name works. DO NOT remove this when the "name" property is
    // deprecated
    // for ADDREPLICA, this is "property.name". See SOLR-7132
    response = CollectionAdminRequest.addReplicaToShard(collectionName, "shard1").withProperty(CoreAdminParams.NAME, "propertyDotName").process(cluster.getSolrClient());
    newReplica = grabNewReplica(response, getCollectionState(collectionName));
    assertEquals("'core' should be 'propertyDotName' ", "propertyDotName", newReplica.getStr("core"));
}

@Test
public void testSimple() throws Exception {
    setTestSuffix("testbackupincsimple");
    final String backupCollectionName = getCollectionName();
    final String restoreCollectionName = backupCollectionName + "_restore";
    final int randomizedNumShards = rarely() ? LARGE_NUM_SHARDS : NUM_SHARDS;
    CloudSolrClient solrClient = cluster.getSolrClient();
    CollectionAdminRequest.createCollection(backupCollectionName, "conf1", randomizedNumShards, 1).process(solrClient);
    int totalIndexedDocs = indexDocs(backupCollectionName, true);
    String backupName = BACKUPNAME_PREFIX + testSuffix;
    try (BackupRepository repository = cluster.getJettySolrRunner(0).getCoreContainer().newBackupRepository(BACKUP_REPO_NAME)) {
        String backupLocation = repository.getBackupLocation(getBackupLocation());
        long t = System.nanoTime();
        int expectedDocsForFirstBackup = totalIndexedDocs;
        CollectionAdminRequest.backupCollection(backupCollectionName, backupName).setLocation(backupLocation).setIncremental(true).setRepositoryName(BACKUP_REPO_NAME).processAndWait(cluster.getSolrClient(), 100);
        long timeTaken = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - t);
        log.info("Created backup with {} docs, took {}ms", totalIndexedDocs, timeTaken);
        totalIndexedDocs += indexDocs(backupCollectionName, true);
        t = System.nanoTime();
        CollectionAdminRequest.backupCollection(backupCollectionName, backupName).setLocation(backupLocation).setIncremental(true).setRepositoryName(BACKUP_REPO_NAME).processAndWait(cluster.getSolrClient(), 100);
        timeTaken = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - t);
        long numFound = cluster.getSolrClient().query(backupCollectionName, new SolrQuery("*:*")).getResults().getNumFound();
        log.info("Created backup with {} docs, took {}ms", numFound, timeTaken);
        t = System.nanoTime();
        randomlyPrecreateRestoreCollection(restoreCollectionName, "conf1", randomizedNumShards, 1);
        CollectionAdminRequest.restoreCollection(restoreCollectionName, backupName).setBackupId(0).setLocation(backupLocation).setRepositoryName(BACKUP_REPO_NAME).processAndWait(solrClient, 500);
        timeTaken = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - t);
        log.info("Restored from backup, took {}ms", timeTaken);
        t = System.nanoTime();
        AbstractDistribZkTestBase.waitForRecoveriesToFinish(restoreCollectionName, ZkStateReader.from(solrClient), log.isDebugEnabled(), false, 3);
        timeTaken = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - t);
        log.info("Restored collection healthy, took {}ms", timeTaken);
        numFound = cluster.getSolrClient().query(restoreCollectionName, new SolrQuery("*:*")).getResults().getNumFound();
        assertEquals(expectedDocsForFirstBackup, numFound);
    }
}

@Test
public void testRestoreToOriginalCollection() throws Exception {
    setTestSuffix("testbackuprestoretooriginal");
    final String backupCollectionName = getCollectionName();
    final String backupName = BACKUPNAME_PREFIX + testSuffix;
    // Bootstrap the backup collection with seed docs
    CollectionAdminRequest.createCollection(backupCollectionName, "conf1", NUM_SHARDS, REPL_FACTOR).process(cluster.getSolrClient());
    final int firstBatchNumDocs = indexDocs(backupCollectionName, true);
    // Backup and immediately add more docs to the collection
    try (BackupRepository repository = cluster.getJettySolrRunner(0).getCoreContainer().newBackupRepository(BACKUP_REPO_NAME)) {
        final String backupLocation = repository.getBackupLocation(getBackupLocation());
        final RequestStatusState result = CollectionAdminRequest.backupCollection(backupCollectionName, backupName).setLocation(backupLocation).setRepositoryName(BACKUP_REPO_NAME).processAndWait(cluster.getSolrClient(), 20);
        assertEquals(RequestStatusState.COMPLETED, result);
    }
    final int secondBatchNumDocs = indexDocs(backupCollectionName, true);
    final int maxDocs = secondBatchNumDocs + firstBatchNumDocs;
    assertEquals(maxDocs, getNumDocsInCollection(backupCollectionName));
    // Restore original docs and validate that doc count is correct
    try (BackupRepository repository = cluster.getJettySolrRunner(0).getCoreContainer().newBackupRepository(BACKUP_REPO_NAME)) {
        final String backupLocation = repository.getBackupLocation(getBackupLocation());
        final RequestStatusState result = CollectionAdminRequest.restoreCollection(backupCollectionName, backupName).setLocation(backupLocation).setRepositoryName(BACKUP_REPO_NAME).processAndWait(cluster.getSolrClient(), 30);
        assertEquals(RequestStatusState.COMPLETED, result);
    }
    assertEquals(firstBatchNumDocs, getNumDocsInCollection(backupCollectionName));
}

@SuppressWarnings("unchecked")
@Test
@Nightly
public void testBackupIncremental() throws Exception {
    setTestSuffix("testbackupinc");
    CloudSolrClient solrClient = cluster.getSolrClient();
    CollectionAdminRequest.createCollection(getCollectionName(), "conf1", NUM_SHARDS, REPL_FACTOR).process(solrClient);
    indexDocs(getCollectionName(), false);
    String backupName = BACKUPNAME_PREFIX + testSuffix;
    try (BackupRepository repository = cluster.getJettySolrRunner(0).getCoreContainer().newBackupRepository(BACKUP_REPO_NAME)) {
        String backupLocation = repository.getBackupLocation(getBackupLocation());
        URI fullBackupLocationURI = repository.resolveDirectory(repository.createDirectoryURI(backupLocation), backupName, getCollectionName());
        BackupFilePaths backupPaths = new BackupFilePaths(repository, fullBackupLocationURI);
        IncrementalBackupVerifier verifier = new IncrementalBackupVerifier(repository, backupLocation, backupName, getCollectionName(), 3);
        backupRestoreThenCheck(solrClient, verifier);
        indexDocs(getCollectionName(), false);
        backupRestoreThenCheck(solrClient, verifier);
        // adding more commits to trigger merging segments
        for (int i = 0; i < 15; i++) {
            indexDocs(getCollectionName(), 5, false);
        }
        backupRestoreThenCheck(solrClient, verifier);
        indexDocs(getCollectionName(), false);
        backupRestoreThenCheck(solrClient, verifier);
        // test list backups
        CollectionAdminResponse resp = CollectionAdminRequest.listBackup(backupName).setBackupLocation(backupLocation).setBackupRepository(BACKUP_REPO_NAME).process(cluster.getSolrClient());
        List<?> backups = (List<?>) resp.getResponse().get("backups");
        assertEquals(3, backups.size());
        // test delete backups
        resp = CollectionAdminRequest.deleteBackupByRecency(backupName, 4).setRepositoryName(BACKUP_REPO_NAME).setLocation(backupLocation).process(cluster.getSolrClient());
        assertNull(resp.getResponse().get("deleted"));
        resp = CollectionAdminRequest.deleteBackupByRecency(backupName, 3).setRepositoryName(BACKUP_REPO_NAME).setLocation(backupLocation).process(cluster.getSolrClient());
        assertNull(resp.getResponse().get("deleted"));
        resp = CollectionAdminRequest.deleteBackupByRecency(backupName, 2).setRepositoryName(BACKUP_REPO_NAME).setLocation(backupLocation).process(cluster.getSolrClient());
        assertEquals(1, resp.getResponse()._get("deleted[0]/backupId", null));
        resp = CollectionAdminRequest.deleteBackupById(backupName, 3).setRepositoryName(BACKUP_REPO_NAME).setLocation(backupLocation).process(cluster.getSolrClient());
        assertEquals(3, resp.getResponse()._get("deleted[0]/backupId", null));
        simpleRestoreAndCheckDocCount(solrClient, backupLocation, backupName);
        // test purge backups
        // purging first since there may corrupted files were uploaded
        resp = CollectionAdminRequest.deleteBackupPurgeUnusedFiles(backupName).setRepositoryName(BACKUP_REPO_NAME).setLocation(backupLocation).process(cluster.getSolrClient());
        addDummyFileToIndex(repository, backupPaths.getIndexDir(), "dummy-files-1");
        addDummyFileToIndex(repository, backupPaths.getIndexDir(), "dummy-files-2");
        resp = CollectionAdminRequest.deleteBackupPurgeUnusedFiles(backupName).setRepositoryName(BACKUP_REPO_NAME).setLocation(backupLocation).process(cluster.getSolrClient());
        assertEquals(2, ((Map<String, Object>) resp.getResponse().get("deleted")).get("numIndexFiles"));
        new UpdateRequest().deleteByQuery("*:*").commit(cluster.getSolrClient(), getCollectionName());
        indexDocs(getCollectionName(), false);
        // corrupt index files
        corruptIndexFiles();
        try {
            log.info("Create backup after corrupt index files");
            CollectionAdminRequest.Backup backup = CollectionAdminRequest.backupCollection(getCollectionName(), backupName).setLocation(backupLocation).setIncremental(true).setMaxNumberBackupPoints(3).setRepositoryName(BACKUP_REPO_NAME);
            if (random().nextBoolean()) {
                RequestStatusState state = backup.processAndWait(cluster.getSolrClient(), 1000);
                if (state != RequestStatusState.FAILED) {
                    fail("This backup should be failed");
                }
            } else {
                CollectionAdminResponse rsp = backup.process(cluster.getSolrClient());
                fail("This backup should be failed");
            }
        } catch (Exception e) {
            log.error("expected", e);
        }
    }
}

@Test
public void testSkipConfigset() throws Exception {
    setTestSuffix("testskipconfigset");
    final String backupCollectionName = getCollectionName();
    final String restoreCollectionName = backupCollectionName + "-restore";
    CloudSolrClient solrClient = cluster.getSolrClient();
    CollectionAdminRequest.createCollection(backupCollectionName, "conf1", NUM_SHARDS, 1).process(solrClient);
    int numDocs = indexDocs(backupCollectionName, true);
    String backupName = BACKUPNAME_PREFIX + testSuffix;
    try (BackupRepository repository = cluster.getJettySolrRunner(0).getCoreContainer().newBackupRepository(BACKUP_REPO_NAME)) {
        String backupLocation = repository.getBackupLocation(getBackupLocation());
        CollectionAdminRequest.backupCollection(backupCollectionName, backupName).setLocation(backupLocation).setBackupConfigset(false).setRepositoryName(BACKUP_REPO_NAME).processAndWait(cluster.getSolrClient(), 100);
        assertFalse("Configset shouldn't be part of the backup but found:\n" + TrackingBackupRepository.directoriesCreated().stream().map(URI::toString).collect(Collectors.joining("\n")), TrackingBackupRepository.directoriesCreated().stream().anyMatch(f -> f.getPath().contains("configs/conf1")));
        assertFalse("Configset shouldn't be part of the backup but found:\n" + TrackingBackupRepository.outputsCreated().stream().map(URI::toString).collect(Collectors.joining("\n")), TrackingBackupRepository.outputsCreated().stream().anyMatch(f -> f.getPath().contains("configs/conf1")));
        assertFalse("solrconfig.xml shouldn't be part of the backup but found:\n" + TrackingBackupRepository.outputsCreated().stream().map(URI::toString).collect(Collectors.joining("\n")), TrackingBackupRepository.outputsCreated().stream().anyMatch(f -> f.getPath().contains("solrconfig.xml")));
        assertFalse("schema.xml shouldn't be part of the backup but found:\n" + TrackingBackupRepository.outputsCreated().stream().map(URI::toString).collect(Collectors.joining("\n")), TrackingBackupRepository.outputsCreated().stream().anyMatch(f -> f.getPath().contains("schema.xml")));
        CollectionAdminRequest.restoreCollection(restoreCollectionName, backupName).setLocation(backupLocation).setRepositoryName(BACKUP_REPO_NAME).processAndWait(solrClient, 500);
        AbstractDistribZkTestBase.waitForRecoveriesToFinish(restoreCollectionName, ZkStateReader.from(solrClient), log.isDebugEnabled(), false, 3);
        assertEquals(numDocs, cluster.getSolrClient().query(restoreCollectionName, new SolrQuery("*:*")).getResults().getNumFound());
    }
    TrackingBackupRepository.clear();
    try (BackupRepository repository = cluster.getJettySolrRunner(0).getCoreContainer().newBackupRepository(BACKUP_REPO_NAME)) {
        String backupLocation = repository.getBackupLocation(getBackupLocation());
        CollectionAdminRequest.backupCollection(backupCollectionName, backupName).setLocation(backupLocation).setBackupConfigset(true).setRepositoryName(BACKUP_REPO_NAME).processAndWait(cluster.getSolrClient(), 100);
        assertTrue("Configset should be part of the backup but not found:\n" + TrackingBackupRepository.directoriesCreated().stream().map(URI::toString).collect(Collectors.joining("\n")), TrackingBackupRepository.directoriesCreated().stream().anyMatch(f -> f.getPath().contains("configs/conf1")));
        assertTrue("Configset should be part of the backup but not found:\n" + TrackingBackupRepository.outputsCreated().stream().map(URI::toString).collect(Collectors.joining("\n")), TrackingBackupRepository.outputsCreated().stream().anyMatch(f -> f.getPath().contains("configs/conf1")));
        assertTrue("solrconfig.xml should be part of the backup but not found:\n" + TrackingBackupRepository.outputsCreated().stream().map(URI::toString).collect(Collectors.joining("\n")), TrackingBackupRepository.outputsCreated().stream().anyMatch(f -> f.getPath().contains("solrconfig.xml")));
        assertTrue("schema.xml should be part of the backup but not found:\n" + TrackingBackupRepository.outputsCreated().stream().map(URI::toString).collect(Collectors.joining("\n")), TrackingBackupRepository.outputsCreated().stream().anyMatch(f -> f.getPath().contains("schema.xml")));
    }
}

